	private static readonly Lazy<ConnectionMultiplexer> s_redis = new Lazy<ConnectionMultiplexer>(() =>
	{
		ConfigurationOptions configurationOptions = ConfigurationOptions.Parse(FConvert.GetRedisServer() ?? throw new InvalidOperationException("Redis connection string is null"));
		configurationOptions.AbortOnConnectFail = false;
		configurationOptions.ConnectRetry = 3;
		configurationOptions.ConnectTimeout = 5000;
		configurationOptions.KeepAlive = 180;
		ConnectionMultiplexer connectionMultiplexer = ConnectionMultiplexer.Connect(configurationOptions);
		connectionMultiplexer.ConnectionFailed += (object s, ConnectionFailedEventArgs e) =>
		{
			ProngHorn.LogError(0, 1, 1, "Redis connection failed ", e.Exception.Message);
		};
		connectionMultiplexer.ConnectionRestored += (object s, ConnectionFailedEventArgs e) =>
		{
			ProngHorn.LogError(0, 1, 1, "Redis connection restored ", "");
		};
		return connectionMultiplexer;
	});

