	public ReportMatrix GetAnalyzeData(RepRecord objRec, int iCompanyId)
	{
		m_iCompanyId = iCompanyId;
		if (IsSortingApply(objRec))
		{
			return GetAnalyzeDataSort(objRec, iCompanyId);
		}
		ReportMatrix reportMatrix = null;
		string[] arrLastValue = null;
		object[] arrReportTotal = null;
		object[] arrOverAllTotal = null;
		List<object[]> arrGroupTotal = null;
		int iCurrentRowIndex = 0;
		bool flag = IsRowGrouping(objRec);
		AnalyzeData analyzeData = null;
		IdNamePair oCurrentLevel = null;
		string text = null;
		List<string[]> list = null;
		List<int> list2 = null;
		List<IdDecimalPair> arrFormulaTotal = null;
		List<IdDecimalPair> arrFormulaGrandTotal = null;
		List<int> list3 = null;
		List<FieldData> list4 = null;
		List<IdNamePair> list5 = null;
		LineData[] array = null;
		List<IdNamePair> list6 = null;
		if (m_oConversion == null)
		{
			m_oConversion = new RDConversion(m_objCalType);
			m_oConversion.RDPreferenceData.IsPrintZeroValueAsNumeric = _focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Print, 8) > 0;
			m_oConversion.RDPreferenceData.IsNumericSeparator = _focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Misc, 12) > 0;
		}
		m_defaultFont = FConvert.GetDefaultFont();
		m_defaultFont.FontWeight = 2;
		text = (string.IsNullOrEmpty(objRec.UniqueId) ? Guid.NewGuid().ToString() : objRec.UniqueId);
		analyzeData = new AnalyzeData();
		analyzeData.KeyValue = text;
		analyzeData.SessionId = objRec.SessionId;
		if (!ContainsKey(ref analyzeData))
		{
			analyzeData.Data = GetAllData(objRec, iCompanyId);
			m_arrAnalyzeData.Add(analyzeData);
		}
		reportMatrix = new ReportMatrix();
		if ((objRec.ReportCustomize.DataSourceType == DataSourceType.Query && objRec.ReportCustomize.ReportType == ReportType.Detail) || (objRec.ReportCustomize.DataSourceType == DataSourceType.Reports && objRec.ReportCustomize.ReportType == ReportType.Cubes) || (objRec.ReportCustomize.DataSourceType == DataSourceType.Standard && objRec.ReportCustomize.ReportType == ReportType.Standard))
		{
			m_bAnalyze = true;
		}
		GetParticularValue(objRec.ReportCustomize.Layout.ExtraValues);
		m_bDetailDocField = isDetailDocNoField(objRec.ReportCustomize);
		try
		{
			if (analyzeData.Data.Error)
			{
				reportMatrix = analyzeData.Data;
			}
			else
			{
				if (objRec.CurrentPage == 0)
				{
					objRec.Outputs = ClearPreviousBalanceData(-9, objRec.Outputs);
					list2 = new List<int>();
					list3 = new List<int>();
					list4 = new List<FieldData>();
					list5 = new List<IdNamePair>();
					list = new List<string[]>();
					analyzeData.OrderBy = GetAnalyzeOrderBy(objRec, ref list3, ref list4, ref list5, ref list2);
					analyzeData.ColumnMeasures = list4.Select((FieldData p) => new DualIdPair(p.ParentId, p.Miscellaneous, p.FieldOrder)).ToArray();
					analyzeData.DontShowTotalColumnMeasures = list2.ToArray();
					analyzeData.ColumnGrouping = list3.ToArray();
					analyzeData.ExtraMasterColumns = list5.ToArray();
					analyzeData.DataColumns = null;
					if (analyzeData.OrderBy.Length != 0)
					{
						analyzeData.SortedIndex = GetAnalyzeSortData(analyzeData, objRec, iCompanyId, ref list);
						if (list.Count > 0)
						{
							analyzeData.DataColumns = GetColumnGroupingColumns(analyzeData, list4, list, objRec);
						}
					}
					else
					{
						analyzeData.SortedIndex = new int[0];
					}
					list6 = GetDataColumns(analyzeData, objRec, flag);
					arrOverAllTotal = CalculateOverallTotal(analyzeData, flag);
				}
				else
				{
					iCurrentRowIndex = FConvert.GetInputValue(objRec.Outputs, -10);
					if (FConvert.GetInputObject(objRec.Outputs, -11) != null)
					{
						arrLastValue = (string[])FConvert.GetInputObject(objRec.Outputs, -11);
					}
					if (FConvert.GetInputObject(objRec.Outputs, -12) != null)
					{
						arrReportTotal = (object[])FConvert.GetInputObject(objRec.Outputs, -12);
					}
					if (FConvert.GetInputObject(objRec.Outputs, -13) != null)
					{
						arrGroupTotal = (List<object[]>)FConvert.GetInputObject(objRec.Outputs, -13);
					}
					if (FConvert.GetInputObject(objRec.Outputs, -14) != null)
					{
						arrOverAllTotal = (object[])FConvert.GetInputObject(objRec.Outputs, -14);
					}
					if (FConvert.GetInputObject(objRec.Outputs, -15) != null)
					{
						oCurrentLevel = (IdNamePair)FConvert.GetInputObject(objRec.Outputs, -15);
					}
					if (FConvert.GetInputObject(objRec.Outputs, -16) != null)
					{
						arrFormulaTotal = (List<IdDecimalPair>)FConvert.GetInputObject(objRec.Outputs, -16);
					}
					if (FConvert.GetInputObject(objRec.Outputs, -17) != null)
					{
						arrFormulaGrandTotal = (List<IdDecimalPair>)FConvert.GetInputObject(objRec.Outputs, -17);
					}
				}
				array = UpdateRowGrouping(analyzeData, objRec, flag, ref arrLastValue, ref arrGroupTotal, ref iCurrentRowIndex, ref arrReportTotal, ref oCurrentLevel);
				reportMatrix.BalanceValues = SetOutputValuesAll(objRec.Outputs, -10, iCurrentRowIndex, arrLastValue, arrGroupTotal, arrReportTotal, arrOverAllTotal, oCurrentLevel);
				reportMatrix.UniqueId = text;
				reportMatrix.ExtraColumns = objRec.ExtraColumns;
				reportMatrix.TotalRow = ((analyzeData.SortedIndex != null) ? analyzeData.SortedIndex.Length : analyzeData.Data.ColumnData.Length);
				reportMatrix.TotalRow = ((array.Length > reportMatrix.TotalRow) ? array.Length : reportMatrix.TotalRow);
				reportMatrix.Columns = ((list6 != null && list6.Count > 0) ? list6.ToArray() : analyzeData.Data.Columns);
				reportMatrix.EndOfFile = iCurrentRowIndex >= reportMatrix.TotalRow || array.Length == 0 || iCurrentRowIndex >= analyzeData.SortedIndex.Length;
				if (reportMatrix.EndOfFile)
				{
					if (objRec.ReportCustomize.Groupings.Length != 0 && GroupingOptions(objRec.ReportCustomize.Groupings[0].MiscellaneousOptions, GroupingOption.SKIP_PAGE_AT_END))
					{
						List<LineData> list7 = new List<LineData>();
						list7.AddRange(array);
						if (list7.Count > 0)
						{
							list7.Add(GetSpecialLine(list7[0].CellData.Length, ReportRowType.PageBreak));
						}
						array = list7.ToArray();
					}
					AddReportTotal(ref array, arrReportTotal, analyzeData, objRec.ReportCustomize, flag);
					reportMatrix.TotalRow = array.Length;
				}
				reportMatrix.ColumnData = array;
				if (IsFinalCalculationFormula(objRec))
				{
					int[] mandatoryColumns = GetMandatoryColumns(objRec, bParticularColumn: true, analyzeData.Data.ExtraColumns, bFinalColumnOnly: true);
					CheckFormula(ref reportMatrix, objRec, iCompanyId, 0, bCallingFromAnalyze: true, arrOverAllTotal);
					try
					{
						UpdateFormulaTotal(ref reportMatrix, ref arrFormulaTotal, ref arrFormulaGrandTotal, ref arrReportTotal, analyzeData, mandatoryColumns, objRec.ReportCustomize.ReportLevel);
						IdValuePair[] arrInputs = reportMatrix.BalanceValues;
						FConvert.SetInputValue(ref arrInputs, -12, arrReportTotal);
						reportMatrix.BalanceValues = arrInputs;
						if (FConvert.GetInputObject(reportMatrix.BalanceValues, -16) == null)
						{
							List<IdValuePair> list8 = reportMatrix.BalanceValues.ToList();
							list8.Add(new IdValuePair(-16, arrFormulaTotal));
							reportMatrix.BalanceValues = list8.ToArray();
						}
						else
						{
							arrInputs = reportMatrix.BalanceValues;
							FConvert.SetInputValue(ref arrInputs, -16, arrFormulaTotal);
							reportMatrix.BalanceValues = arrInputs;
						}
						if (FConvert.GetInputObject(reportMatrix.BalanceValues, -17) == null)
						{
							List<IdValuePair> list9 = reportMatrix.BalanceValues.ToList();
							list9.Add(new IdValuePair(-17, arrFormulaGrandTotal));
							reportMatrix.BalanceValues = list9.ToArray();
						}
						else
						{
							arrInputs = reportMatrix.BalanceValues;
							FConvert.SetInputValue(ref arrInputs, -17, arrFormulaGrandTotal);
							reportMatrix.BalanceValues = arrInputs;
						}
					}
					catch
					{
					}
					List<LineData> list10 = new List<LineData>();
					if (mandatoryColumns != null && mandatoryColumns.Length != 0 && reportMatrix.ColumnData.Length != 0)
					{
						for (int num = 0; num < reportMatrix.ColumnData.Length; num++)
						{
							if ((reportMatrix.ColumnData[num].CellData[0] as ReportRowHeader).RowType == ReportRowType.Total || CheckMandatoryValue(reportMatrix.ColumnData[num], mandatoryColumns))
							{
								list10.Add(reportMatrix.ColumnData[num]);
							}
						}
					}
					else
					{
						list10.AddRange(reportMatrix.ColumnData);
					}
					reportMatrix.ColumnData = ApplySetting(list10, analyzeData, objRec.ReportCustomize, flag, FormulaOnly: true);
				}
				if (reportMatrix.EndOfFile && (objRec.ReportCustomize.DataSourceType != DataSourceType.Standard || objRec.ReportCustomize.ReportType != ReportType.Standard))
				{
					objRec.Outputs = ClearPreviousBalanceData(-9, objRec.Outputs);
					_focus.company(m_iCompanyId).clearBuffer(reportMatrix.UniqueId);
					RemoveKey(analyzeData);
				}
			}
		}
		catch (Exception ex)
		{
			ReportMatrix reportMatrix2 = reportMatrix;
			bool endOfFile = (reportMatrix.Error = true);
			reportMatrix2.EndOfFile = endOfFile;
			reportMatrix.Message = ex.Message;
		}
		return reportMatrix;
	}

