	{
		m_iCompanyId = iCompanyId;
		ReportMatrix reportMatrix = null;
		string[] arrLastValue = null;
		object[] arrReportTotal = null;
		object[] arrRowTotalData = null;
		List<object[]> arrGroupTotal = null;
