			m_oConversion = new RDConversion(m_objCalType);
			m_oConversion.RDPreferenceData.IsPrintZeroValueAsNumeric = _focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Print, 8) > 0;
			m_oConversion.RDPreferenceData.IsNumericSeparator = _focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Misc, 12) > 0;
		}
		text = (string.IsNullOrEmpty(objRec.UniqueId) ? Guid.NewGuid().ToString() : objRec.UniqueId);
		analyzeData = new AnalyzeData();
		analyzeData.KeyValue = text;
