		{
			analyzeData.Data = GetAllData(objRec, iCompanyId);
			m_arrAnalyzeData.Add(analyzeData);
		}
		reportMatrix = new ReportMatrix();
		if ((objRec.ReportCustomize.DataSourceType == DataSourceType.Query && objRec.ReportCustomize.ReportType == ReportType.Detail) || (objRec.ReportCustomize.DataSourceType == DataSourceType.Reports && objRec.ReportCustomize.ReportType == ReportType.Cubes) || (objRec.ReportCustomize.DataSourceType == DataSourceType.Standard && objRec.ReportCustomize.ReportType == ReportType.Standard))
		{
			m_bAnalyze = true;
		}
		GetParticularValue(objRec.ReportCustomize.Layout.ExtraValues);
		try
		{
			if (analyzeData.Data.Error)
			{
				reportMatrix = analyzeData.Data;
			}
			else
			{
				if (objRec.CurrentPage == 0)
				{
					objRec.Outputs = ClearPreviousBalanceData(-9, objRec.Outputs);
					list2 = new List<int>();
					list3 = new List<int>();
					list4 = new List<FieldData>();
					list5 = new List<IdNamePair>();
					list = new List<string[]>();
					analyzeData.OrderBy = GetAnalyzeOrderBy(objRec, ref list3, ref list4, ref list5, ref list2);
					analyzeData.ColumnMeasures = list4.Select((FieldData p) => new DualIdPair(p.ParentId, p.Miscellaneous, p.FieldOrder)).ToArray();
					analyzeData.DontShowTotalColumnMeasures = list2.ToArray();
					analyzeData.ColumnGrouping = list3.ToArray();
					analyzeData.ExtraMasterColumns = list5.ToArray();
					analyzeData.DataColumns = null;
					if (analyzeData.OrderBy.Length != 0)
					{
						analyzeData.SortedIndex = GetAnalyzeSortData(analyzeData, objRec, iCompanyId, ref list);
						if (list.Count > 0)
						{
							analyzeData.DataColumns = GetColumnGroupingColumns(analyzeData, list4, list, objRec);
						}
					}
					else
					{
						analyzeData.SortedIndex = new int[0];
					}
					list6 = GetDataColumns(analyzeData, objRec, flag);
					if (m_bAnalyze)
					{
						arrRowTotalData = CalculateOverallTotal(analyzeData, flag);
					}
					else
					{
						CheckCustomSorting(objRec, flag, ref analyzeData, ref arrRowTotalData);
					}
				}
				else
				{
					iCurrentRowIndex = FConvert.GetInputValue(objRec.Outputs, -10);
