				}
				array = (m_bAnalyze ? UpdateRowGrouping(analyzeData, objRec, flag, ref arrLastValue, ref arrGroupTotal, ref iCurrentRowIndex, ref arrReportTotal, ref oCurrentLevel) : GetRowGroupingData(analyzeData, objRec, flag, ref iCurrentRowIndex));
				reportMatrix.BalanceValues = SetOutputValuesAll(objRec.Outputs, -10, iCurrentRowIndex, arrLastValue, arrGroupTotal, arrReportTotal, arrRowTotalData, oCurrentLevel);
