	private List<IdValuePair> GetMeasureColumnCustomize(AnalyzeData objAnalyzeData, _Reports objReportCustomize, bool bRowGrouping)
	{
		bool flag = false;
		int num = 0;
		int num2 = 0;
		List<IdValuePair> list = null;
		list = new List<IdValuePair>();
		if (bRowGrouping)
		{
			for (num2 = 0; num2 < objReportCustomize.Layout.Columns.Length; num2++)
			{
				list.Add(new IdValuePair(6, objReportCustomize.Layout.Columns[num2]));
			}
		}
		else
		{
			for (num = 0; num < objReportCustomize.Groupings.Length; num++)
			{
				if (objReportCustomize.Groupings[num].GroupingType != _GroupingType.Column)
				{
					continue;
				}
				flag = true;
				if (!objReportCustomize.Groupings[num].IsAscending)
				{
					continue;
				}
				for (num2 = 1; num2 < objReportCustomize.Layout.Columns.Length; num2++)
				{
					if (objReportCustomize.Groupings[num].FieldId == objReportCustomize.Layout.Columns[num2].FieldId && objReportCustomize.Groupings[num].SubParentId == objReportCustomize.Layout.Columns[num2].SubParentId)
					{
						list.Add(new IdValuePair(6, objReportCustomize.Layout.Columns[num2]));
						break;
					}
				}
			}
			for (num = 0; num < objAnalyzeData.ExtraMasterColumns.Length; num++)
			{
				for (num2 = 0; num2 < objReportCustomize.Layout.Columns.Length; num2++)
				{
					if (m_bAnalyze && objAnalyzeData.ExtraMasterColumns[num].Tag != null && objAnalyzeData.ExtraMasterColumns[num].Tag.GetType() == typeof(FieldData))
					{
						if (((FieldData)objAnalyzeData.ExtraMasterColumns[num].Tag).FieldId == objReportCustomize.Layout.Columns[num2].FieldId && ((FieldData)objAnalyzeData.ExtraMasterColumns[num].Tag).SubParentId == objReportCustomize.Layout.Columns[num2].SubParentId)
						{
							list.Add(new IdValuePair(0, objReportCustomize.Layout.Columns[num2]));
							break;
						}
					}
					else if (objAnalyzeData.ExtraMasterColumns[num].ID - 1 == num2)
					{
						list.Add(new IdValuePair(0, objReportCustomize.Layout.Columns[num2]));
						break;
					}
				}
				if (num2 == objReportCustomize.Layout.Columns.Length && !string.IsNullOrEmpty(objAnalyzeData.ExtraMasterColumns[num].Name) && objAnalyzeData.ExtraMasterColumns[num].Name.StartsWith("^"))
				{
					list.Add(new IdValuePair(0, null));
				}
			}
			if (!flag)
			{
				for (num2 = 0; num2 < objReportCustomize.Layout.Columns.Length; num2++)
				{
					if (objReportCustomize.Layout.Columns[num2].DataTypeId == MasterDataType.Fraction)
					{
						list.Add(new IdValuePair(6, objReportCustomize.Layout.Columns[num2]));
					}
				}
			}
		}
		return list;
	}

	private void GetColumnGroupValue(AnalyzeData objAnalyzeData, RepRecord objRec, int iTotalExtraMasters, int iSortRowIndex, int iColumnTotalCount, ref LineData objLineData, ref List<IdDecimalPair> arrTotal)
	{
		bool flag = true;
		decimal num = 0m;
		int num2 = 0;
		int iColumnIndex = 0;
		int num3 = 0;
		string text = null;
		IdNamePair[] array = null;
		for (iColumnIndex = 2 + iTotalExtraMasters; iColumnIndex < objLineData.CellData.Length - iColumnTotalCount; iColumnIndex++)
		{
			if (objAnalyzeData.DataColumns == null || objAnalyzeData.DataColumns.Length == 0 || iColumnTotalCount <= 0)
			{
				continue;
			}
			array = (IdNamePair[])objAnalyzeData.DataColumns[iColumnIndex - (2 + iTotalExtraMasters)].Tag;
			flag = true;
			for (num3 = 0; num3 < array.Length - 1; num3++)
			{
				if (array[num3] != null && array[num3].ID < objAnalyzeData.Data.ColumnData[iSortRowIndex].CellData.Length)
				{
					text = Convert.ToString(objAnalyzeData.Data.ColumnData[iSortRowIndex].CellData[array[num3].ID]);
					text = ConvertTo(text, array[num3].ID, objRec, num3, _GroupingType.Column);
					if (array[num3] != null && text != array[num3].Name)
					{
						flag = false;
						break;
					}
				}
			}
			if (flag && array.Length > 1)
			{
				string value = Convert.ToString(objAnalyzeData.Data.ColumnData[iSortRowIndex].CellData[array[array.Length - 1].ID]);
				if (!string.IsNullOrEmpty(value))
				{
					num = Convert.ToDecimal(value);
				}
				num2 = ((num2 < objAnalyzeData.ColumnMeasures.Length) ? num2 : 0);
				switch ((AggregateFunction)Convert.ToInt32(objAnalyzeData.ColumnMeasures[num2].Value))
				{
				default:
					objLineData.CellData[iColumnIndex] = Convert.ToDecimal(objLineData.CellData[iColumnIndex]) + num;
					break;
				case AggregateFunction.Average:
				{
					if (num != 0m)
					{
						arrTotal.Add(new IdDecimalPair(iColumnIndex, num));
					}
					int num4 = (from p in arrTotal
						where p.ID == iColumnIndex
						select p.ID).Count();
					if (num4 > 0)
					{
						decimal num5 = (from p in arrTotal
							where p.ID == iColumnIndex
							select p.Value).Sum();
						objLineData.CellData[iColumnIndex] = num5 / (decimal)num4;
					}
					break;
				}
				case AggregateFunction.Count:
					objLineData.CellData[iColumnIndex] = Convert.ToInt32(objLineData.CellData[iColumnIndex]) + ((num != 0m) ? 1 : 0);
					break;
				case AggregateFunction.Maximum:
					objLineData.CellData[iColumnIndex] = ((Convert.ToDecimal(objLineData.CellData[iColumnIndex]) > num) ? Convert.ToDecimal(objLineData.CellData[iColumnIndex]) : num);
					break;
				case AggregateFunction.Minimum:
					objLineData.CellData[iColumnIndex] = ((Convert.ToDecimal(objLineData.CellData[iColumnIndex]) < num) ? Convert.ToDecimal(objLineData.CellData[iColumnIndex]) : num);
					break;
				}
			}
			num2++;
		}
		for (num3 = 0; num3 < iColumnTotalCount; num3++)
		{
			num = 0m;
			num2 = ((num3 < objAnalyzeData.ColumnMeasures.Length) ? num3 : 0);
			for (iColumnIndex = 2 + iTotalExtraMasters + num3; iColumnIndex < objLineData.CellData.Length - iColumnTotalCount; iColumnIndex += iColumnTotalCount)
			{
				decimal num6 = Convert.ToDecimal(objLineData.CellData[iColumnIndex]);
				switch ((AggregateFunction)Convert.ToInt32(objAnalyzeData.ColumnMeasures[num2].Value))
				{
				default:
					num += num6;
					break;
				case AggregateFunction.Average:
				{
					int count = arrTotal.Count;
					if (count > 0)
					{
						num = arrTotal.Select((IdDecimalPair p) => p.Value).Sum() / (decimal)count;
					}
					break;
				}
				case AggregateFunction.Count:
					num = Convert.ToInt32(objLineData.CellData[iColumnIndex]) + ((num6 != 0m) ? 1 : 0);
					break;
				case AggregateFunction.Maximum:
					num = ((Convert.ToDecimal(objLineData.CellData[iColumnIndex]) > num6) ? Convert.ToDecimal(objLineData.CellData[iColumnIndex]) : num6);
					break;
				case AggregateFunction.Minimum:
					num = ((Convert.ToDecimal(objLineData.CellData[iColumnIndex]) < num6) ? Convert.ToDecimal(objLineData.CellData[iColumnIndex]) : num6);
					break;
				}
			}
			objLineData.CellData[objLineData.CellData.Length - iColumnTotalCount + num3] = num;
		}
	}

	private void ApplySettingOnTotal(ref LineData objLineData, AnalyzeData objAnalyzeData, _Reports objReportCustomize, bool bRowGrouping)
