						{
							reportRowHeader.Image = format.LabelImage;
						}
						reportRowHeader.SetColumnId = format.SetColumnId;
						reportRowHeader.IsSetOnColumnOnlly = format.IsApplyOnColumn;
						reportRowHeader.RowType = ReportRowType.Formatting;
						arrLineData[num2].CellData[0] = reportRowHeader;
