						}
					}
				}
			}
			else
			{
				_Column[] array2 = (from p in m_arrMeasureColumns
					where p.ID == 0
					select (_Column)p.Value).ToArray();
				_Column[] array3 = (from p in m_arrMeasureColumns
					where p.ID == 6
					select (_Column)p.Value).ToArray();
				for (num = 2; num < arrLineData[0].CellData.Length; num++)
				{
					column = null;
					if (num >= array2.Length + 2 && array3.Length != 0)
					{
						num3 = ((!flag2) ? (num - (array2.Length + 2)) : ((num - array2.Length + 2) % array3.Length));
						if (num3 > -1 && num3 < array3.Length)
						{
							column = array3[num3];
						}
					}
					else if (array2.Length != 0 && num - 2 < array2.Length)
					{
						column = array2[num - 2];
					}
					if (column == null)
					{
						continue;
					}
					for (num2 = 0; num2 < arrLineData.Count; num2++)
					{
						reportRowHeader = (ReportRowHeader)arrLineData[num2].CellData[0];
						if (reportRowHeader != null && !m_bAnalyze)
						{
							if (((column.Miscelleneous >> 7) & 1) == 1 && (reportRowHeader.RowType == ReportRowType.Total || (reportRowHeader.TreeData != null && reportRowHeader.TreeData.IsGroup)))
							{
								arrLineData[num2].CellData[num] = 0;
							}
							else if (objAnalyzeData.DontShowTotalColumnMeasures != null && objAnalyzeData.DontShowTotalColumnMeasures.Length != 0)
							{
								for (int num5 = 0; num5 < objAnalyzeData.DontShowTotalColumnMeasures.Length; num5++)
								{
									if (num == objAnalyzeData.DontShowTotalColumnMeasures[num5] - 1 && ((reportRowHeader.TreeData != null && reportRowHeader.TreeData.IsGroup) || reportRowHeader.RowType == ReportRowType.Total))
									{
										arrLineData[num2].CellData[num] = 0;
										break;
									}
								}
							}
						}
						if (column.DataTypeId == MasterDataType.Fraction || column.DataTypeId == MasterDataType.Date || column.DataTypeId == MasterDataType.Time || column.DataTypeId == MasterDataType.DateTime || column.DataTypeId == MasterDataType.Shamsi || column.DataTypeId == MasterDataType.Hijri || column.DataTypeId == MasterDataType.Boolean)
						{
							arrLineData[num2].CellData[num] = m_oConversion.ApplySettingOnData(arrLineData[num2].CellData[num], column);
						}
						else if (column.DataTypeId == MasterDataType.Picture && RDCommon.GetRowSpan(column.ColumnAlignment) > 0 && Convert.ToString(arrLineData[num2].CellData[num]).Length > 10 && ((ReportRowHeader)arrLineData[num2].CellData[0]).ExtraInfo == null)
						{
