				}
			}
		}
		return arrLineData.ToArray();
	}

	private void UpdateFormulaTotal(ref ReportMatrix objReprotData, ref List<IdDecimalPair> arrFormulaTotal, ref List<IdDecimalPair> arrFormulaGrandTotal, ref object[] arrRowTotalData, AnalyzeData objAnalyzeData, int[] arrMandatoryColumns, int iReportLevel)
	{
		int num = 0;
		int num2 = 0;
		int iCurIndex = 0;
		int num3 = 0;
		decimal num4 = 0m;
		bool flag = false;
		ReportRowHeader reportRowHeader = null;
		List<DualIdPair> list = new List<DualIdPair>();
		if (arrFormulaTotal == null)
		{
			arrFormulaTotal = new List<IdDecimalPair>();
		}
		if (arrFormulaGrandTotal == null)
		{
			arrFormulaGrandTotal = new List<IdDecimalPair>();
		}
		for (num2 = 0; num2 < objAnalyzeData.ColumnMeasures.Length; num2++)
		{
			if (RDCommon.GetMiscValue(objAnalyzeData.ColumnMeasures[num2].SubId, MiscFields.FinalCalculation))
			{
				if (RDCommon.GetMiscValue(objAnalyzeData.ColumnMeasures[num2].SubId, MiscFields.ApplyFormulaOnTotal))
				{
					list.Add(new DualIdPair(objAnalyzeData.ColumnMeasures[num2].Id + 1, 1, objAnalyzeData.ColumnMeasures[num2].Value));
				}
				else
				{
					list.Add(new DualIdPair(objAnalyzeData.ColumnMeasures[num2].Id + 1, 0, objAnalyzeData.ColumnMeasures[num2].Value));
				}
			}
		}
		for (num = 0; num < objReprotData.ColumnData.Length; num++)
		{
			reportRowHeader = objReprotData.ColumnData[num].CellData[0] as ReportRowHeader;
			flag = Convert.ToString(objReprotData.ColumnData[num].CellData[1]) == "Sub Total";
			if (reportRowHeader.RowType != ReportRowType.Total && !CheckMandatoryValue(objReprotData.ColumnData[num], arrMandatoryColumns))
			{
				continue;
			}
			switch (reportRowHeader.RowType)
			{
			case ReportRowType.Total:
				for (num2 = 0; num2 < list.Count; num2++)
				{
					iCurIndex = list[num2].Id;
					if (list[num2].SubId != 0)
					{
						continue;
					}
					if (((flag || arrFormulaGrandTotal.Count == 0) && arrFormulaTotal.Where((IdDecimalPair p) => p.ID == iCurIndex).Count() > 0) || arrFormulaGrandTotal.Where((IdDecimalPair p) => p.ID == iCurIndex).Count() > 0)
					{
						switch ((AggregateFunction)Convert.ToInt32(list[num2].Value))
						{
						case AggregateFunction.Sum:
							num4 = ((!flag && arrFormulaGrandTotal.Count != 0) ? (from p in arrFormulaGrandTotal
								where p.ID == iCurIndex
								select p.Value).Sum() : (from p in arrFormulaTotal
								where p.ID == iCurIndex
								select p.Value).Sum());
							break;
						case AggregateFunction.Average:
							if (flag || arrFormulaGrandTotal.Count == 0)
							{
								num4 = (from p in arrFormulaTotal
									where p.ID == iCurIndex
									select p.Value).Sum();
								num3 = (from p in arrFormulaTotal
									where p.ID == iCurIndex
									select p.ID).Count();
							}
							else
							{
								num4 = (from p in arrFormulaGrandTotal
									where p.ID == iCurIndex
									select p.Value).Sum();
								num3 = (from p in arrFormulaGrandTotal
									where p.ID == iCurIndex
									select p.ID).Count();
							}
							if (num3 > 0)
							{
								num4 /= (decimal)num3;
							}
							break;
						case AggregateFunction.Count:
							num4 = ((!flag && arrFormulaGrandTotal.Count != 0) ? ((decimal)(from p in arrFormulaGrandTotal
								where p.ID == iCurIndex
								select p.ID).Count()) : ((decimal)(from p in arrFormulaTotal
								where p.ID == iCurIndex
								select p.ID).Count()));
							break;
						case AggregateFunction.Maximum:
							num4 = ((!flag && arrFormulaGrandTotal.Count != 0) ? (from p in arrFormulaGrandTotal
								where p.ID == iCurIndex
								select p.Value).Max() : (from p in arrFormulaTotal
								where p.ID == iCurIndex
								select p.Value).Max());
							break;
						case AggregateFunction.Minimum:
							num4 = ((!flag && arrFormulaGrandTotal.Count != 0) ? (from p in arrFormulaGrandTotal
								where p.ID == iCurIndex
								select p.Value).Min() : (from p in arrFormulaTotal
								where p.ID == iCurIndex
								select p.Value).Min());
							break;
						}
					}
					objReprotData.ColumnData[num].CellData[iCurIndex] = num4;
					if (flag)
					{
						arrRowTotalData[iCurIndex] = RemoveDrCr(Convert.ToString(arrRowTotalData[iCurIndex]));
						arrRowTotalData[iCurIndex] = Convert.ToDecimal(arrRowTotalData[iCurIndex]) + num4;
					}
					else
					{
						arrRowTotalData[iCurIndex] = num4;
					}
					num4 = 0m;
				}
				arrFormulaGrandTotal.AddRange(arrFormulaTotal);
				arrFormulaTotal.Clear();
				break;
			case ReportRowType.Normal:
			case ReportRowType.Formatting:
			case ReportRowType.TreeGroup:
				if (reportRowHeader.RowType != ReportRowType.Normal && reportRowHeader.RowType != ReportRowType.Formatting && (reportRowHeader.RowType != ReportRowType.TreeGroup || reportRowHeader.TreeData == null || iReportLevel - 1 != reportRowHeader.TreeData.GroupLevel))
				{
					break;
				}
				for (num2 = 0; num2 < list.Count; num2++)
				{
					iCurIndex = list[num2].Id;
					if (!string.IsNullOrEmpty(Convert.ToString(objReprotData.ColumnData[num].CellData[iCurIndex])))
					{
						num4 = Convert.ToDecimal(objReprotData.ColumnData[num].CellData[iCurIndex]);
						if (num4 != 0m)
						{
							arrFormulaTotal.Add(new IdDecimalPair(iCurIndex, num4));
						}
					}
				}
				break;
			}
		}
	}

	private decimal RemoveDrCr(string sValue)
	{
		decimal result = 0m;
		if (!string.IsNullOrEmpty(sValue))
		{
			sValue = sValue.Replace(",", string.Empty);
			bool flag = sValue.Contains(" Dr");
			sValue = sValue.Replace(" Dr", string.Empty);
			sValue = sValue.Replace(" Cr", string.Empty);
			return (!FConvert.IsNumeric(sValue)) ? 0m : (Convert.ToDecimal(sValue) * (decimal)((!flag) ? 1 : (-1)));
		}
		return result;
	}

	private IdIntPair[] GetAnalyzeOrderBy(RepRecord objRec, ref List<int> lstColumnGrouping, ref List<FieldData> lstColumnMeasures, ref List<IdNamePair> lstMasterExtraColumns, ref List<int> lstDontShowTotalMeasures)
	{
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		int num5 = -1;
		List<IdIntPair> list = new List<IdIntPair>();
		for (num = 0; num < objRec.ReportCustomize.Groupings.Length; num++)
		{
			for (num2 = 1; num2 < objRec.ExtraColumns.Length; num2++)
			{
				num3 = objRec.ReportCustomize.Groupings[num].FieldId;
				num4 = objRec.ReportCustomize.Groupings[num].SubParentId;
				if (objRec.ExtraColumns[num2].DataType == MasterDataType.Date)
				{
					RDCommon.GetSubFieldId(ref num3);
				}
				if (num3 != objRec.ExtraColumns[num2].FieldId || (num4 >= 0 && num4 != objRec.ExtraColumns[num2].SubParentId))
				{
					continue;
				}
				num5++;
				switch (objRec.ReportCustomize.Groupings[num].GroupingType)
				{
				case _GroupingType.Row:
					list.Add(new IdIntPair(num2, objRec.ReportCustomize.Groupings[num].IsAscending ? 1 : 0));
					break;
				case _GroupingType.Column:
					if (objRec.ReportCustomize.Groupings[num].IsAscending)
					{
						lstColumnMeasures.Add(new FieldData
						{
							FieldId = objRec.ReportCustomize.Groupings[num].FieldId,
							SubParentId = objRec.ReportCustomize.Groupings[num].SubParentId,
							FieldOrder = objRec.ReportCustomize.Groupings[num].OrderBy,
							ParentId = num2,
							Miscellaneous = objRec.ExtraColumns[num2].Miscellaneous
						});
					}
					else
					{
						lstColumnGrouping.Add(num2);
					}
					break;
				}
				break;
			}
		}
		for (num2 = 1; num2 < objRec.ExtraColumns.Length; num2++)
		{
			if (objRec.ExtraColumns[num2].DataType != MasterDataType.Fraction && objRec.ExtraColumns[num2].DataType != MasterDataType.Number)
			{
				string columnMeasureName = GetColumnMeasureName(objRec.ExtraColumns[num2], objRec.ReportCustomize.Layout.Columns);
				lstMasterExtraColumns.Add(new IdNamePair(num2, columnMeasureName, objRec.ExtraColumns[num2]));
			}
		}
		if (list.Count > 0 && lstColumnMeasures.Count == 0 && lstColumnGrouping.Count == 0)
		{
			num5 = ((num5 >= 0) ? num5 : 0);
			for (num2 = 2; num2 < objRec.ExtraColumns.Length; num2++)
			{
				if (objRec.ExtraColumns[num2].FieldId != -5 && (objRec.ExtraColumns[num2].DataType == MasterDataType.Fraction || objRec.ExtraColumns[num2].DataType == MasterDataType.Number))
				{
					if (!m_bAnalyze && ((objRec.ExtraColumns[num2].Miscellaneous >> 7) & 1) == 1)
					{
						lstDontShowTotalMeasures.Add(num2 - num5);
					}
					lstColumnMeasures.Add(new FieldData
					{
						FieldId = objRec.ExtraColumns[num2].FieldId,
						SubParentId = objRec.ExtraColumns[num2].SubParentId,
						FieldOrder = GetFunctionOnColumn(objRec.ExtraColumns[num2].FieldId, objRec.ExtraColumns[num2].SubParentId, objRec.ExtraColumns[num2].ColumnId, objRec.ReportCustomize.Layout.Columns),
						ParentId = num2,
						Miscellaneous = objRec.ExtraColumns[num2].Miscellaneous
					});
				}
			}
		}
		return list.ToArray();
	}

	private int GetFunctionOnColumn(int iFieldId, int iSubParentId, int iColumnId, _Column[] arrColumns)
	{
		for (int i = 0; i < arrColumns.Length; i++)
		{
			if (arrColumns[i].ColumnFunction == null || arrColumns[i].ColumnFunction.Function <= AggregateFunction.Sum)
			{
				continue;
			}
			bool flag = false;
			if (iColumnId > 0)
			{
				if (arrColumns[i].ColumnId == iColumnId)
				{
					flag = true;
				}
			}
			else if (arrColumns[i].FieldId == iFieldId)
			{
				if (iSubParentId > 0)
				{
					if (arrColumns[i].SubParentId == iSubParentId)
					{
						flag = true;
					}
				}
				else
				{
					flag = true;
				}
			}
			if (flag)
			{
				return (int)arrColumns[i].ColumnFunction.Function;
			}
		}
		return 1;
	}

	private void CheckCustomSorting(RepRecord objRec, bool bRowGrouping, ref AnalyzeData objAnalyzeData, ref object[] arrRowTotalData)
	{
		bool flag = false;
		int iCurrentRowIndex = 0;
		int num = 0;
		bool flag2 = false;
		string text = null;
		ReportRowHeader reportRowHeader = null;
		IdNamePair oCurrentLevel = null;
		string[] arrLastValue = null;
		List<object[]> arrGroupTotal = null;
		RowData rowData = null;
		IdValuePair idValuePair = null;
		List<RowData> list = null;
		if (!objAnalyzeData.IsDataReady)
		{
			num = objRec.RowsPerPage;
			objRec.RowsPerPage = int.MaxValue;
			objAnalyzeData.Data.ColumnData = UpdateRowGrouping(objAnalyzeData, objRec, bRowGrouping, ref arrLastValue, ref arrGroupTotal, ref iCurrentRowIndex, ref arrRowTotalData, ref oCurrentLevel);
			objRec.RowsPerPage = num;
			objAnalyzeData.IsDataReady = true;
		}
		for (iCurrentRowIndex = 0; iCurrentRowIndex < objRec.ReportCustomize.Layout.Columns.Length; iCurrentRowIndex++)
		{
			flag2 = objRec.ReportCustomize.Layout.Columns[iCurrentRowIndex].DataTypeId == MasterDataType.Fraction;
			if (objRec.ColumnSort != null && objRec.ColumnSort.OrderId != 0)
			{
				if (objRec.ColumnSort.OrderId == -3)
				{
					idValuePair = new IdValuePair(1, objRec.ColumnSort.IsAscending);
					break;
				}
				if (objRec.ReportCustomize.Layout.Columns[iCurrentRowIndex].FieldId == objRec.ColumnSort.OrderId)
				{
					idValuePair = new IdValuePair(iCurrentRowIndex + 1 + (bRowGrouping ? 1 : 0), objRec.ColumnSort.IsAscending);
					if (objRec.ReportCustomize.Layout.Columns[iCurrentRowIndex].DataTypeId == MasterDataType.Date)
					{
						flag = true;
					}
					break;
				}
			}
			else if (objRec.ReportCustomize.Layout.Columns[iCurrentRowIndex].ColumnOrder != null)
			{
				idValuePair = new IdValuePair(iCurrentRowIndex + 1 + (bRowGrouping ? 1 : 0), objRec.ReportCustomize.Layout.Columns[iCurrentRowIndex].ColumnOrder.IsAscending);
				break;
			}
		}
		list = new List<RowData>();
		num = -1;
		for (iCurrentRowIndex = 0; iCurrentRowIndex < objAnalyzeData.Data.ColumnData.Length; iCurrentRowIndex++)
		{
			rowData = new RowData();
			rowData.RowIndex = iCurrentRowIndex;
			if (idValuePair != null)
			{
				reportRowHeader = objAnalyzeData.Data.ColumnData[iCurrentRowIndex].CellData[0] as ReportRowHeader;
				if (reportRowHeader.TreeData == null || !reportRowHeader.TreeData.IsGroup)
				{
					num = (rowData.RowIndex = ((num == -1) ? iCurrentRowIndex : num));
				}
				else
