						string.IsNullOrEmpty(text) ? 0m : Convert.ToDecimal(text.Replace(",", ""))
					};
				}
				else
				{
					rowData.Values = new decimal[2] { rowData.RowIndex, 0m };
					rowData.Data = new string[1] { text };
				}
				rowData.RowIndex = iCurrentRowIndex;
			}
			list.Add(rowData);
		}
		if (idValuePair != null)
		{
			if (flag2)
			{
				if (Convert.ToBoolean(idValuePair.Value))
				{
					objAnalyzeData.SortedIndex = (from c in list
						orderby c.Values[0], c.Values[1]
						select c.RowIndex).ToArray();
				}
				else
				{
					objAnalyzeData.SortedIndex = (from c in list
						orderby c.Values[0], c.Values[1] descending
						select c.RowIndex).ToArray();
				}
			}
			else if (flag)
			{
				objAnalyzeData.SortedIndex = (from c in list
					orderby c.RowIndex
					select c.RowIndex).ToArray();
			}
			else if (Convert.ToBoolean(idValuePair.Value))
			{
				objAnalyzeData.SortedIndex = (from c in list
					orderby c.Values[0], c.Data[0]
					select c.RowIndex).ToArray();
			}
			else
			{
				objAnalyzeData.SortedIndex = (from c in list
					orderby c.Values[0], c.Data[0] descending
					select c.RowIndex).ToArray();
			}
		}
		else
		{
			objAnalyzeData.SortedIndex = (from c in list
				orderby c.RowIndex
				select c.RowIndex).ToArray();
		}
	}

