	private List<masterTree> getMasterWithSequence(int iTypeId, int iCompanyId)
	{
		IDataReader dataReader = null;
		List<masterTree> list = new List<masterTree>();
		try
		{
			if (ProngHorn.USESOCKET(iCompanyId) && ProngHorn.GetSocketFlag(iCompanyId).MastersEnabled)
			{
				list = (from p in ProngHorn.GetTreeSequence(1, 0, 0, iCompanyId)
					select new masterTree
					{
						code = p.Code,
						id = p.iMasterId,
						level = p.Level,
						name = p.Name,
						sequence = p.iSeq
					}).ToList();
			}
			else
			{
				Database database = DatabaseWrapper.GetDatabase2(iCompanyId);
				string text = $"SELECT iMasterId,sName,sCode,iSeq FROM dbo.fCore_GetAccountTreeSequence(0,0) WHERE bGroup=0 ORDER BY iSeq";
				using (DbCommand command = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text))
				{
					dataReader = database.ExecuteReader(command);
					while (dataReader.Read())
					{
						masterTree masterTree2 = new masterTree();
						masterTree2.id = Convert.ToInt32(dataReader["iMasterId"]);
						masterTree2.sequence = Convert.ToInt32(dataReader["iSeq"]);
						masterTree2.name = Convert.ToString(dataReader["sName"]);
						masterTree2.code = Convert.ToString(dataReader["sCode"]);
						list.Add(masterTree2);
					}
					dataReader.Close();
				}
				database = null;
				dataReader = null;
			}
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
		}
		return list;
	}

	private ReportMatrix GetAllData(RepRecord objRec, int iCompId)
	{
		ReportMatrix reportMatrix = null;
		RDReport rDReport = null;
		DataSourceType dataSourceType = DataSourceType.Default;
		List<LineData> list = null;
		try
		{
			rDReport = new RDReport();
			rDReport.m_objCalType = m_objCalType;
			rDReport.m_bCallingFromBI = true;
			list = new List<LineData>();
			objRec.IsStartOfReport = false;
			int rowsPerPage = objRec.RowsPerPage;
			objRec.RowsPerPage = int.MaxValue;
			objRec.FetchAllData = true;
			objRec.ReportCustomize.DelayFetch = false;
			do
			{
				reportMatrix = rDReport.GetPagewiseData(objRec, iCompId, ref dataSourceType);
				if (reportMatrix.ColumnData != null)
				{
					list.AddRange(reportMatrix.ColumnData);
				}
				objRec.UniqueId = reportMatrix.UniqueId;
			}
			while (!reportMatrix.EndOfFile && reportMatrix.ColumnData != null);
			reportMatrix.ColumnData = list.ToArray();
			objRec.RowsPerPage = rowsPerPage;
			objRec.FetchAllData = false;
			if (objRec.SourceType == DataSourceType.Reports && dataSourceType != DataSourceType.Query)
			{
				objRec.ReportQuery = null;
			}
		}
		catch (Exception ex)
		{
			ReportMatrix reportMatrix2 = reportMatrix;
			bool endOfFile = (reportMatrix.EndOfFile = true);
			reportMatrix2.EndOfFile = endOfFile;
			reportMatrix.Message = ex.Message;
		}
		return reportMatrix;
	}

	private IdValuePair[] SetOutputValues(IdValuePair[] arrValuePair, int iId, int iCurrentRowIndex, object[] arrOverAllTotal)
	{
		int num = 0;
		bool[] array = new bool[2];
		List<IdValuePair> list = new List<IdValuePair>();
		if (arrValuePair != null)
		{
			list.AddRange(arrValuePair);
		}
		for (num = 0; num < list.Count; num++)
		{
			if (list[num].ID == -10)
			{
				list[num].Value = iCurrentRowIndex;
				array[0] = true;
			}
			if (list[num].ID == -11 && arrOverAllTotal != null)
			{
				list[num].Value = arrOverAllTotal;
				array[1] = true;
			}
		}
		if (!array[0])
		{
			list.Add(new IdValuePair(-10, iCurrentRowIndex));
