	private IdValuePair[] SetOutputValuesAll(IdValuePair[] arrValuePair, int iId, int iCurrentRowIndex, string[] arrLastValue, List<object[]> arrGroupTotal, object[] arrReprotTotal, object[] arrOverAllTotal, IdNamePair oCurrentLevel)
	{
		bool flag = false;
		if (arrValuePair == null)
		{
			arrValuePair = new IdValuePair[0];
		}
		for (int i = 0; i < arrValuePair.Length; i++)
		{
			if (arrValuePair[i].ID == iId)
			{
				arrValuePair[i].Value = iCurrentRowIndex;
				flag = true;
			}
			if (arrValuePair[i].ID == iId - 1)
			{
				arrValuePair[i].Value = arrLastValue;
				flag = true;
			}
			if (arrValuePair[i].ID == iId - 2)
			{
				arrValuePair[i].Value = arrReprotTotal;
				flag = true;
			}
			if (arrValuePair[i].ID == iId - 3)
			{
				arrValuePair[i].Value = arrGroupTotal;
				flag = true;
			}
			if (arrValuePair[i].ID == iId - 4)
			{
				arrValuePair[i].Value = arrOverAllTotal;
				flag = true;
			}
			if (arrValuePair[i].ID == iId - 5)
			{
				arrValuePair[i].Value = oCurrentLevel;
				flag = true;
			}
		}
		if (!flag)
		{
			Array.Resize(ref arrValuePair, arrValuePair.Length + 6);
			arrValuePair[arrValuePair.Length - 6] = new IdValuePair(iId--, iCurrentRowIndex);
			arrValuePair[arrValuePair.Length - 5] = new IdValuePair(iId--, arrLastValue);
			arrValuePair[arrValuePair.Length - 4] = new IdValuePair(iId--, arrReprotTotal);
			arrValuePair[arrValuePair.Length - 3] = new IdValuePair(iId--, arrGroupTotal);
			arrValuePair[arrValuePair.Length - 2] = new IdValuePair(iId--, arrOverAllTotal);
			arrValuePair[arrValuePair.Length - 1] = new IdValuePair(iId, oCurrentLevel);
		}
		return arrValuePair;
	}

	private bool ContainsKey(ref AnalyzeData objSet)
	{
		int num = 0;
		if (m_arrAnalyzeData != null && m_arrAnalyzeData.Count > 0)
		{
			for (num = 0; num < m_arrAnalyzeData.Count; num++)
			{
				if (m_arrAnalyzeData[num].KeyValue == objSet.KeyValue)
				{
					objSet = m_arrAnalyzeData[num];
					return true;
				}
			}
		}
		return false;
	}

	private bool RemoveKey(AnalyzeData objSet)
	{
		int num = 0;
		if (m_arrAnalyzeData != null)
		{
			for (num = 0; num < m_arrAnalyzeData.Count; num++)
			{
				if (m_arrAnalyzeData[num].KeyValue == objSet.KeyValue)
				{
					m_arrAnalyzeData[num].ColumnGrouping = null;
					m_arrAnalyzeData[num].ColumnMeasures = null;
					m_arrAnalyzeData[num].Data = null;
					m_arrAnalyzeData[num].DontShowTotalColumnMeasures = null;
					m_arrAnalyzeData[num].OrderBy = null;
					m_arrAnalyzeData[num].KeyValue = null;
					m_arrAnalyzeData[num].SortedIndex = null;
					m_arrAnalyzeData.RemoveAt(num);
					break;
				}
			}
		}
		return false;
	}

	private string ConvertTo(string strValue, int iColumn, RepRecord objRec, int iCurrentGroup)
	{
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		if (objRec.ExtraColumns != null && iColumn > -1 && iColumn < objRec.ExtraColumns.Length && !string.IsNullOrEmpty(strValue))
		{
			if (objRec.ExtraColumns[iColumn].DataType == MasterDataType.Date)
			{
				goto IL_0088;
			}
			if (objRec.ReportCustomize.DataSourceType != DataSourceType.Query && objRec.ExtraColumns[iColumn].SubParentId == 2)
			{
				string fieldName = objRec.ExtraColumns[iColumn].FieldName;
				if (fieldName != null && !fieldName.EndsWith("sCode"))
				{
					goto IL_0088;
				}
			}
			if (objRec.ExtraColumns[iColumn].DataType == MasterDataType.DateTime)
			{
				for (num3 = iCurrentGroup; num3 < objRec.ReportCustomize.Groupings.Length; num3++)
				{
					num2 = objRec.ReportCustomize.Groupings[num3].FieldId;
					num = RDCommon.GetSubFieldId(ref num2);
					if (num2 == objRec.ExtraColumns[iColumn].FieldId && (num2 & 0xFF0000) >> 16 != 128)
					{
						strValue = ConvertToDateTime(strValue, num, objRec.DateFormat);
						break;
					}
				}
			}
			else if (m_bDetailDocField && iCurrentGroup < objRec.ReportCustomize.Groupings.Length - 1)
			{
				for (num3 = iCurrentGroup; num3 < objRec.ReportCustomize.Groupings.Length - 1; num3++)
				{
					if (objRec.ReportCustomize.Groupings[num3].FieldId == 187)
					{
						num3 = strValue.LastIndexOf('~');
						if (num3 > 0 && num3 < strValue.Length)
						{
							strValue = strValue.Remove(num3, strValue.Length - num3);
						}
						break;
					}
				}
			}
		}
		goto IL_01ed;
		IL_01ed:
		return strValue;
		IL_0088:
		for (num3 = iCurrentGroup; num3 < objRec.ReportCustomize.Groupings.Length; num3++)
		{
			num2 = objRec.ReportCustomize.Groupings[num3].FieldId;
			num = RDCommon.GetSubFieldId(ref num2);
			if (num2 == objRec.ExtraColumns[iColumn].FieldId && (num2 & 0xFF0000) >> 16 != 128)
			{
				strValue = ConvertTo(strValue, num, objRec.DateFormat);
				break;
			}
		}
		goto IL_01ed;
	}

	private string ConvertTo(string strValue, int iColumn, RepRecord objRec, int iCurrentGroup, _GroupingType oGroupingType)
	{
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		if (objRec.ExtraColumns != null && iColumn > -1 && iColumn < objRec.ExtraColumns.Length && strValue != null && strValue.Length > 0 && objRec.ReportCustomize.DataSourceType != DataSourceType.Query)
		{
			for (num3 = 0; num3 < objRec.ReportCustomize.Groupings.Length; num3++)
			{
				num2 = objRec.ReportCustomize.Groupings[num3].FieldId;
				num = RDCommon.GetSubFieldId(ref num2);
				if (objRec.ReportCustomize.Groupings[num3].GroupingType == oGroupingType && (objRec.ExtraColumns[iColumn].DataType == MasterDataType.Date || num2 == 2))
				{
					if (num2 == objRec.ExtraColumns[iColumn].FieldId && num4 >= iCurrentGroup)
					{
						strValue = ConvertTo(strValue, num, objRec.DateFormat);
						break;
					}
					num4++;
				}
			}
		}
		return strValue;
	}

	private string ConvertTo(string strValue, int iSubFieldId, string strDateFormat, _Column oColumn = null)
	{
		if (strValue == "0")
		{
			return string.Empty;
		}
		switch ((DatePart)iSubFieldId)
		{
		case DatePart.Year:
			strValue = new Date(Convert.ToInt32(strValue), m_objCalType).Year.ToString();
			break;
		case DatePart.Month:
			strValue = new Date(Convert.ToInt32(strValue), m_objCalType).GetMonthName();
			break;
		case DatePart.WeekDay:
			strValue = new Date(m_objCalType).IntToDate(Convert.ToInt32(strValue)).ToString("dddd");
			break;
		case DatePart.Day:
			strValue = Convert.ToString(new Date(Convert.ToInt32(strValue), m_objCalType).Day);
			break;
		case DatePart.DayOfYear:
			strValue = Convert.ToString(new Date(m_objCalType).IntToDate(Convert.ToInt32(strValue)).DayOfYear);
			break;
		case DatePart.Week:
			strValue = (new Date(m_objCalType).IntToDate(Convert.ToInt32(strValue)).DayOfYear / 7 + 1).ToString();
			break;
		default:
			if (oColumn != null)
			{
				if (string.IsNullOrEmpty(m_oConversion.DateFormat) && !string.IsNullOrEmpty(strDateFormat))
				{
					m_oConversion.DateFormat = strDateFormat;
				}
				strValue = Convert.ToString(m_oConversion.ApplySettingOnData(strValue, oColumn));
			}
			else if (!string.IsNullOrEmpty(strValue) && FConvert.IsNumeric(strValue))
			{
				Date date = new Date(m_objCalType);
				date.Value = Convert.ToInt32(strValue);
				strValue = (string.IsNullOrEmpty(strDateFormat) ? date.ToString() : date.FormatMethod(date.Day, date.Month, date.Year, strDateFormat));
			}
			break;
		}
		return strValue;
	}

	private string ConvertToDateTime(string strValue, int iSubFieldId, string strDateFormat, _Column oColumn = null)
	{
		if (strValue == "0")
		{
			return string.Empty;
		}
		DateTime dateTime = DateTime.Now;
		new Date(m_objCalType).GetToday(m_objCalType);
		if (FConvert.IsNumeric(strValue))
		{
			dateTime = new FDateTime(Convert.ToInt64(strValue), m_objCalType).DateTime;
		}
		strValue = (DateTimePart)iSubFieldId switch
		{
			DateTimePart.Year => dateTime.Year.ToString(), 
			DateTimePart.Quarter => dateTime.Month.ToString(), 
			DateTimePart.Month => new Date(dateTime.Year, dateTime.Month, dateTime.Day, m_objCalType).GetMonthName(), 
			DateTimePart.DayOfYear => dateTime.DayOfYear.ToString(), 
			DateTimePart.Day => dateTime.Day.ToString(), 
			DateTimePart.Week => (dateTime.DayOfYear / 7 + 1).ToString(), 
			DateTimePart.WeekDay => new Date(dateTime.Year, dateTime.Month, dateTime.Day, m_objCalType).ToString("dddd"), 
			DateTimePart.Hour => dateTime.Hour.ToString(), 
			DateTimePart.Minute => dateTime.Minute.ToString(), 
			DateTimePart.Second => dateTime.Second.ToString(), 
			DateTimePart.MilliSecond => dateTime.Millisecond.ToString(), 
			_ => dateTime.ToString(), 
		};
		return strValue;
	}

	private string GetValidColumnName(string strColumn)
	{
		if (!string.IsNullOrEmpty(strColumn))
		{
			strColumn = strColumn.Replace("Report Specific.", string.Empty);
			strColumn = strColumn.Replace("Transaction Fields.", string.Empty);
		}
		return strColumn;
	}

