	private void SortDatePart(DatePart iDatePart, ref string[] arrDistinctColumnGroup, int StartingDate)
	{
		IdNamePair[] array = null;
		switch (iDatePart)
		{
		case DatePart.WeekDay:
			array = new IdNamePair[7]
			{
				new IdNamePair(1, "Sunday"),
				new IdNamePair(2, "Monday"),
				new IdNamePair(3, "Tuesday"),
				new IdNamePair(4, "Wednesday"),
				new IdNamePair(5, "Thursday"),
				new IdNamePair(6, "Friday"),
				new IdNamePair(7, "Saturday")
			};
			break;
		case DatePart.Day:
		{
			List<IdNamePair> list2 = new List<IdNamePair>();
			for (int num = 1; num <= 31; num++)
			{
				list2.Add(new IdNamePair(num.ToString(), num));
			}
			array = list2.ToArray();
			break;
		}
		default:
		{
			array = new IdNamePair[12]
			{
				new IdNamePair(1, "January"),
				new IdNamePair(2, "February"),
				new IdNamePair(3, "March"),
				new IdNamePair(4, "April"),
				new IdNamePair(5, "May"),
				new IdNamePair(6, "June"),
				new IdNamePair(7, "July"),
				new IdNamePair(8, "August"),
				new IdNamePair(9, "September"),
				new IdNamePair(10, "October"),
				new IdNamePair(11, "November"),
				new IdNamePair(12, "December")
			};
			if (StartingDate != 0 || _focus.company(m_iCompanyId).accountingDate <= 0)
			{
				break;
			}
			Date date = new Date(m_objCalType);
			date.Value = _focus.company(m_iCompanyId).accountingDate;
			if (date.Month <= 1)
			{
				break;
			}
			List<IdNamePair> list = new List<IdNamePair>();
			int iMonth = 0;
			int iCurMonth = date.Month;
			while (iMonth < 12)
			{
				list.Add((from p in array
					where p.ID == iCurMonth
					select new IdNamePair(iMonth + 1, p.Name)).FirstOrDefault());
				if (iCurMonth == 12)
				{
					iCurMonth = 0;
				}
				iMonth++;
				iCurMonth++;
			}
			array = list.ToArray();
			break;
		}
		}
		arrDistinctColumnGroup = (from p in arrDistinctColumnGroup
			join q in array on p equals q.Name
			orderby q.ID
			select p).ToArray();
	}

	private void SortMonthYearPart(ref string[] arrDistinctColumnGroup)
	{
		IdNamePair[] array = null;
		List<string> list = new List<string>();
		list.AddRange(arrDistinctColumnGroup);
		array = new IdNamePair[12]
		{
			new IdNamePair(1, "January"),
			new IdNamePair(2, "February"),
			new IdNamePair(3, "March"),
			new IdNamePair(4, "April"),
			new IdNamePair(5, "May"),
			new IdNamePair(6, "June"),
			new IdNamePair(7, "July"),
			new IdNamePair(8, "August"),
			new IdNamePair(9, "September"),
			new IdNamePair(10, "October"),
			new IdNamePair(11, "November"),
			new IdNamePair(12, "December")
		};
		for (int i = 0; i < list.Count; i++)
		{
			for (int j = 0; j < array.Length; j++)
			{
				if (list[i] != null && list[i].Contains(array[j].Name))
				{
					list[i] = list[i].Replace(array[j].Name, $"{array[j].ID:00}");
					break;
				}
			}
		}
		list = list.OrderBy((string p) => p).ToList();
		for (int num = 0; num < list.Count; num++)
		{
			for (int num2 = 0; num2 < array.Length; num2++)
			{
				if (list[num] != null && list[num].Contains($" {array[num2].ID:00}"))
				{
					list[num] = list[num].Replace($" {array[num2].ID:00}", $" {array[num2].Name}");
					break;
				}
			}
		}
		arrDistinctColumnGroup = list.ToArray();
	}

	private void SortTimePart(ref string[] arrDistinctColumnGroup)
	{
		int num = 0;
		string text = null;
		List<IdNamePair> list = new List<IdNamePair>();
		for (int i = 0; i < arrDistinctColumnGroup.Length; i++)
		{
			text = arrDistinctColumnGroup[i];
			if (text.Length >= 3)
			{
				num = Convert.ToInt32(text.Substring(0, 2));
			}
			if (text.Contains("PM"))
			{
				num += 12;
			}
			list.Add(new IdNamePair(num, text));
		}
		arrDistinctColumnGroup = (from p in arrDistinctColumnGroup
			join q in list on p equals q.Name
			orderby q.ID
			select p).ToArray();
	}

	private bool isDetailDocNoField(_Reports oData)
	{
		bool flag = false;
		if (oData != null && oData.Groupings != null && oData.Groupings.Length != 0)
		{
			for (int i = 0; i < oData.Groupings.Length; i++)
			{
				if (!oData.Groupings[i].IsAscending && oData.Groupings[i].FieldId == 187)
				{
					flag = !flag;
				}
			}
		}
		return flag;
	}

