              SET @Query = 'SELECT @BodyDiscount = ' + @BodyDiscountFlds + ' FROM tCore_IndtaBodyScreenData{suffix} HScreen\r\n\t\t\t                      INNER JOIN tCore_Data{suffix} D ON D.iBodyId = HScreen.iBodyId AND D.iType = 0\r\n\t\t\t                      INNER JOIN tCore_Header{suffix} H ON H.iHeaderId = D.iHeaderId AND H.iDate BETWEEN ' + CONVERT(VARCHAR(50), @iStartDate) + ' AND ' + CONVERT(VARCHAR(50), @iEndDate)\r\n                    EXEC sp_executesql @Query, N'@BodyDiscount DECIMAL(18,7) OUTPUT', @BodyDiscount = @BodyDiscount OUTPUT;\r\n                    \r\n                    SET @Query = 'SELECT @FooterDiscount = ' + @FooterDiscountFlds + ' FROM tCore_IndtaFooterScreenData{suffix} HScreen\r\n\t\t\t                      INNER JOIN tCore_Header{suffix} H ON H.iHeaderId = HScreen.iHeaderId AND H.iDate Between ' + CONVERT(VARCHAR(50), @iStartDate) + ' AND ' + CONVERT(VARCHAR(50), @iEndDate)\r\n                    EXEC sp_executesql @Query, N'@FooterDiscount DECIMAL(18,7) OUTPUT', @FooterDiscount = @FooterDiscount OUTPUT;\r\n\r\n                    SELECT ISNULL(@BodyDiscount, 0) + ISNULL(@FooterDiscount, 0)";
