ELECT sAbbr FROM cCore_Vouchers{0} WHERE iVoucherType = {2}) +'%' AND fDrCardAmount is not null\r\n                    GROUP BY mPos_BankCardType.iMasterId, mPos_BankCardType.sName\r\n                    UNION ALL\r\n\t                --Preorder DiscountVoucher\r\n\t                SELECT 0[iMasterId], 'P_Disc Voucher', SUM(fDVTotRedeemedValue)[Amount],0[Type] FROM \r\n\t                tCore_Header{0} \r\n\t                JOIN tCore_HeaderData{1}{0} ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n\t                WHERE iDate BETWEEN {4} AND {5} AND iShift = {6} {8} AND tCore_HeaderData{1}{0}.sBillReferenceNo LIKE \r\n\t                (SELECT sAbbr FROM cCore_Vouchers{0} WHERE iVoucherType = {2}) +'%' AND fDVTotRedeemedValue is not null\r\n                    UNION ALL\r\n                    --Walk in sales CASH\r\n                    SELECT 0[iMasterId],'Cash'[sName], sum(fCashPaid)[Amount],1[Type] FROM \r\n                    tCore_Header{0} JOIN tCore_HeaderData{1}{0} ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                    WHERE iDate BETWEEN {4} AND {5} AND iShift = {6} {8} AND tCore_HeaderData{1}{0}.sBillReferenceNo LIKE \r\n                    (SELECT sAbbr FROM cCore_Vouchers{0} WHERE iVoucherType = {3}) +'%'\r\n                    UNION ALL\r\n                    ----Walk in sales Credit card\r\n                    SELECT mPos_BankCardType.iMasterId, mPos_BankCardType.sName, SUM(fCrCardAmount)[Amount],1[Type] FROM \r\n                    tCore_Header{0} \r\n                    JOIN tCore_HeaderData{1}{0} ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                    JOIN mPos_BankCardType ON mPos_BankCardType.iMasterId = tCore_HeaderData{1}{0}.iCrCardType\r\n                    WHERE iDate BETWEEN {4} AND {5} AND iShift = {6} {8} AND tCore_HeaderData{1}{0}.sBillReferenceNo LIKE \r\n                    (SELECT sAbbr FROM cCore_Vouchers{0} WHERE iVoucherType = {3}) +'%'\r\n                    GROUP BY mPos_BankCardType.iMasterId, mPos_BankCardType.sName    \r\n                    UNION ALL\r\n                    ----Walk in sales Debit card\r\n                    SELECT mPos_BankCardType.iMasterId, mPos_BankCardType.sName, SUM(fDrCardAmount)[Amount],1[Type] FROM \r\n                    tCore_Header{0} \r\n                    JOIN tCore_HeaderData{1}{0} ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                    JOIN mPos_BankCardType ON mPos_BankCardType.iMasterId = tCore_HeaderData{1}{0}.iDrCardType\r\n                    WHERE iDate BETWEEN {4} AND {5} AND iShift = {6} {8} AND tCore_HeaderData{1}{0}.sBillReferenceNo LIKE \r\n                    (SELECT sAbbr FROM cCore_Vouchers{0} WHERE iVoucherType = {3}) +'%' AND fDrCardAmount IS NOT NULL\r\n                    GROUP BY mPos_BankCardType.iMasterId, mPos_BankCardType.sName   \r\n                    UNION ALL\r\n\t                --Walkin DiscountVoucher\r\n\t                SELECT 0[iMasterId], 'Disc Voucher', SUM(fDVExternal)[Amount],1[Type] FROM \r\n\t                tCore_Header{0} \r\n\t                JOIN tCore_HeaderData{1}{0} ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                    LEFT JOIN vPos_GVDVValues ON vPos_GVDVValues.iHeaderId  = tCore_Header{0}.iHeaderId\r\n\t                WHERE iDate BETWEEN {4} AND {5} AND iShift = {6} {8} AND tCore_HeaderData{1}{0}.sBillReferenceNo LIKE \r\n\t                (SELECT sAbbr FROM cCore_Vouchers{0} WHERE iVoucherType = {3}) +'%' AND fDVExternal is not null\r\n                    union ALL\r\n                    SELECT 0[iMasterId], 'Disc Voucher int', -SUM(fDVInternal)[Amount],1[Type] FROM \r\n\t                tCore_Header{0} \r\n\t                JOIN tCore_HeaderData{1}{0} ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                    LEFT JOIN vPos_GVDVValues ON vPos_GVDVValues.iHeaderId  = tCore_Header{0}.iHeaderId\r\n\t                WHERE iDate BETWEEN {4} AND {5} AND iShift = {6} {8} AND tCore_HeaderData{1}{0}.sBillReferenceNo LIKE \r\n\t                (SELECT sAbbr FROM cCore_Vouchers{0} WHERE iVoucherType = {3}) +'%' AND fDVInternal is not null\r\n\r\n                    {7}\r\n                    UNION ALL\r\n\t                SELECT 0[iMasterId],'Gift voucher external', SUM(fGVExternal)[Amount],1[Type] \r\n\t                FROM tCore_Header{0} \r\n\t                JOIN tCore_HeaderData{1}{0} ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                    LEFT JOIN vPos_GVDVValues ON vPos_GVDVValues.iHeaderId  = tCore_Header{0}.iHeaderId\r\n\t                WHERE iDate BETWEEN {4} AND {5} AND iShift = {6} {8} AND tCore_HeaderData{1}{0}.sBillReferenceNo LIKE \r\n\t                (SELECT sAbbr FROM cCore_Vouchers{0} WHERE iVoucherType = {3}) +'%' AND fGVExternal is not null\r\n                    UNION ALL\r\n\t                SELECT 0[iMasterId],'Gift voucher internal', -SUM(fGVInternal)[Amount],1[Type] \r\n\t                FROM tCore_Header{0} \r\n\t                JOIN tCore_HeaderData{1}{0} ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                    LEFT JOIN vPos_GVDVValues ON vPos_GVDVValues.iHeaderId  = tCore_Header{0}.iHeaderId\r\n\t                WHERE iDate BETWEEN {4} AND {5} AND iShift = {6} {8} AND tCore_HeaderData{1}{0}.sBillReferenceNo LIKE \r\n\t                (SELECT sAbbr FROM cCore_Vouchers{0} WHERE iVoucherType = {3}) +'%' AND fGVInternal is not null\r\n\r\n\t                UNION ALL\r\n\t                SELECT 0[iMasterId],'Cheque payment', SUM(fChqValue)[Amount],1[Type] \r\n\t                FROM tCore_Header{0} \r\n\t                JOIN tCore_HeaderData{1}{0} ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n\t                WHERE iDate BETWEEN {4} AND {5} AND iShift = {6} {8} AND tCore_HeaderData{1}{0}.sBillReferenceNo LIKE \r\n\t                (SELECT sAbbr FROM cCore_Vouchers{0} WHERE iVoucherType = {3}) +'%'\r\n\r\n                    )SubTable WHERE Amount <> 0 GROUP BY iMasterId, sName, Type ORDER BY Type", FConvert.GetSuffix(iCompId), 4096, 5632, 3331, objHeader.FromDate, objHeader.EndDate, objHeader.Shift, text, text2);
				dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
				dataReader = database.ExecuteReader(dbCommand);
				list = new List<IdNamePair>();
				list2 = new List<IdNamePair>();
				while (dataReader.Read())
				{
					idNamePair = new IdNamePair();
					idNamePair.ID = Convert.ToInt32(dataReader["iMasterId"]);
					idNamePair.Name = Convert.ToString(dataReader["sName"]);
					idNamePair.Tag = dataReader["Amount"];
					if (Convert.ToByte(dataReader["Type"]) == 0)
					{
						list.Add(idNamePair);
					}
					else if (Convert.ToDecimal(idNamePair.Tag) > 0m)
					{
						list2.Add(idNamePair);
						wISSubTotal += Convert.ToDecimal(idNamePair.Tag);
					}
				}
				dataReader.Close();
				posXReading.PROSPayments = list.ToArray();
				posXReading.WISPayments = list2.ToArray();
				posXReading.PROSSubTotal = list.Sum((IdNamePair p) => Convert.ToDecimal(p.Tag));
				posXReading.WISSubTotal = wISSubTotal;
				posXReading.TotalforSGD = posXReading.PROSSubTotal + posXReading.WISSubTotal;
			}
			catch (Exception ex22)
			{
				posXReading.ErrorMsg += $"Payment Type: {ex22.Message}\\r\\n";
			}
		}
		return posXReading;
	}

	public POSPrinterDetails LoadPOSPrintDetailsWithPrinter(POSSocketInput oData, int iCompanyId)
	{
		POSPrinterDetails pOSPrinterDetails = LoadPOSPrintDetails(oData.BodyIds, oData.Type, oData.KOTId, oData.Counter, oData.OrderType, oData.LoginId, iCompanyId, oData.OutletId);
		if (oData.Type == 1 && oData.ItemPrinters != null && oData.ItemPrinters.Length != 0 && pOSPrinterDetails.PrinterConfigurations != null && pOSPrinterDetails.PrinterConfigurations.Length != 0)
		{
			for (int i = 0; i < oData.ItemPrinters.Length; i++)
			{
				if (string.IsNullOrEmpty(oData.ItemPrinters[i].Name))
				{
					continue;
				}
				for (int j = 0; j < pOSPrinterDetails.PrinterConfigurations.Length; j++)
				{
					if (pOSPrinterDetails.PrinterConfigurations[j].Products == null || pOSPrinterDetails.PrinterConfigurations[j].Products.Length == 0)
					{
						continue;
					}
					for (int k = 0; k < pOSPrinterDetails.PrinterConfigurations[j].Products.Length; k++)
					{
						if (string.IsNullOrEmpty(oData.ItemPrinters[i].Name) || Convert.ToInt32(pOSPrinterDetails.PrinterConfigurations[j].Products[k].Tag) != oData.ItemPrinters[i].ID || !(pOSPrinterDetails.PrinterConfigurations[j].DefaultPrinter != oData.ItemPrinters[i].Name))
						{
							continue;
						}
						bool flag = false;
						for (int l = 0; l < pOSPrinterDetails.PrinterConfigurations.Length; l++)
						{
							if (oData.ItemPrinters[i].Name == pOSPrinterDetails.PrinterConfigurations[l].DefaultPrinter)
							{
								flag = true;
								List<IdNamePair> list = new List<IdNamePair>();
								list = pOSPrinterDetails.PrinterConfigurations[l].Products.ToList();
								list.Add(pOSPrinterDetails.PrinterConfigurations[j].Products[k]);
								pOSPrinterDetails.PrinterConfigurations[l].Products = list.ToArray();
								list = new List<IdNamePair>();
								list = pOSPrinterDetails.PrinterConfigurations[j].Products.ToList();
								list.RemoveAt(k);
								pOSPrinterDetails.PrinterConfigurations[j].Products = list.ToArray();
								break;
							}
						}
						if (!flag)
						{
							List<POSRestaurentPrinter> list2 = new List<POSRestaurentPrinter>();
							list2 = pOSPrinterDetails.PrinterConfigurations.ToList();
							POSRestaurentPrinter pOSRestaurentPrinter = new POSRestaurentPrinter();
							pOSRestaurentPrinter.DefaultPrinter = oData.ItemPrinters[i].Name;
							pOSRestaurentPrinter.AlternatePrinter = pOSPrinterDetails.PrinterConfigurations[j].AlternatePrinter;
							pOSRestaurentPrinter.LayoutId = pOSPrinterDetails.PrinterConfigurations[j].LayoutId;
							List<IdNamePair> list3 = new List<IdNamePair>();
							list3.Add(pOSPrinterDetails.PrinterConfigurations[j].Products[k]);
							pOSRestaurentPrinter.Products = list3.ToArray();
							list2.Add(pOSRestaurentPrinter);
							list3 = new List<IdNamePair>();
							list3 = pOSPrinterDetails.PrinterConfigurations[j].Products.ToList();
							list3.RemoveAt(k);
							pOSPrinterDetails.PrinterConfigurations[j].Products = list3.ToArray();
							pOSPrinterDetails.PrinterConfigurations = list2.ToArray();
						}
						break;
					}
				}
			}
		}
		return pOSPrinterDetails;
	}

