	public IdNamePair[] GetSpecificDocFields(IdNamePair[] arrDefaultFields, LayoutInformation[] arrLayouts)
	{
		List<IdNamePair> lstDocFields = new List<IdNamePair>();
		for (int i = 0; i < arrLayouts.Length; i++)
		{
			for (int j = 0; j < arrLayouts[i].Pages.Length; j++)
			{
				for (int k = 0; k < arrLayouts[i].Pages[j].PageHeader.Length; k++)
				{
					if (arrLayouts[i].Pages[j].PageHeader[k].Type == ControlType.BodyCanvas)
					{
						for (int l = 0; l < arrLayouts[i].Pages[j].PageHeader[k].PageBody.Length; l++)
						{
							string[] array = arrLayouts[i].Pages[j].PageHeader[k].PageBody[l].Column.Split('.');
							if (array.Length > 1)
							{
								GetDocField(arrDefaultFields, array, ref lstDocFields);
							}
						}
					}
					else
					{
						string[] array = arrLayouts[i].Pages[j].PageHeader[k].Text.Split('.');
						if (array.Length > 1)
						{
							GetDocField(arrDefaultFields, array, ref lstDocFields);
						}
					}
				}
			}
		}
		return lstDocFields.ToArray();
	}

	private void GetDocField(IdNamePair[] arrDefaultFields, string[] arrData, ref List<IdNamePair> lstDocFields)
	{
		string text = "";
		bool flag = false;
		for (int i = 0; i < arrDefaultFields.Length; i++)
		{
			text = "Body";
			if (!(arrDefaultFields[i].Tag as TranMasterInfo).IsBodyField)
			{
				text = "Header";
			}
			if (text.ToLower() == arrData[0].ToLower() && arrDefaultFields[i].Name.ToLower() == arrData[1].ToLower())
			{
				lstDocFields.Add(arrDefaultFields[i]);
				flag = true;
				break;
			}
			if (!flag && arrDefaultFields[i].Name.ToLower() == arrData[0].ToLower())
			{
				lstDocFields.Add(arrDefaultFields[i]);
				break;
			}
		}
	}

