		IDataReader dataReader = null;
		if (arrProducts.Count > 0)
		{
			Database database = DatabaseWrapper.GetDatabase2(iCompanyId);
			text = string.Format("SELECT iMasterId FROM vmCore_Product WHERE iMasterId IN ({0}) AND iTreeId = 0 AND bDonotPrintInBill = 1 ", string.Join(",", arrProducts.Select((IdNamePair p) => p.ID.ToString()).ToArray()));
			dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				for (num = 0; num < arrProducts.Count; num++)
