	private int GetPrintLayout(int iOutlet, int iOrderType, Database objDb, int iCompanyId)
	{
		IDataReader dataReader = null;
		int result = 0;
		int num = 0;
		string value = ((iOrderType == 0) ? "PFBBSE" : "PFKITN");
		string text = null;
		string text2 = null;
		string[] array = null;
		text = string.Format("SELECT sPrefType, sSetting FROM mPos_OutletPreferences{1} WITH (READUNCOMMITTED) WHERE iOutletId = {0} AND sPrefType = 'PRNT'", iOutlet, FConvert.GetSuffix(iCompanyId));
		dataReader = objDb.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		if (dataReader.Read())
		{
			text2 = Convert.ToString(dataReader["sSetting"]);
			num = text2.IndexOf(value) + 6;
			if (num > 5)
			{
				array = text2.Substring(num + 1, text2.IndexOf("@", num) - num - 2).Split('~');
				if (array.Length != 0)
				{
					result = int.Parse(array[0].Split('#')[1]);
				}
			}
		}
		dataReader.Close();
		return result;
	}

