	private void ArrangeGroupingData(Transaction objTrans, LayoutInformation oLayoutInfo, ref IdNamePair[] arrGroupData, ref byte iGroupingType, ref PageBodyClass objLayoutBody, Database objDb, int iCompanyId)
	{
		bool isDontClubIfRateDifferent = false;
		bool flag = false;
		IdNamePair[] array = null;
		List<int> list = null;
		List<int> list2 = null;
		int voucherType = objTrans.Header.VoucherType;
		if (oLayoutInfo != null && oLayoutInfo.Pages != null && oLayoutInfo.Pages.Length != 0 && oLayoutInfo.Pages[0].PageHeader != null && oLayoutInfo.Pages[0].PageHeader.Length != 0)
		{
			PageHeader[] pageHeader = oLayoutInfo.Pages[0].PageHeader;
			foreach (PageHeader pageHeader2 in pageHeader)
			{
				if (pageHeader2.UID > 2000 || pageHeader2.PageBodyClass == null)
				{
					continue;
				}
				objLayoutBody = pageHeader2.PageBodyClass;
				IdNamePair[] orderBy;
				if (pageHeader2.PageBodyClass.OrderBy != null && pageHeader2.PageBodyClass.OrderBy.Length != 0)
				{
					iGroupingType = 0;
					list = new List<int>();
					orderBy = pageHeader2.PageBodyClass.OrderBy;
					foreach (IdNamePair idNamePair in orderBy)
					{
						if (idNamePair.ID == 101)
						{
							flag = true;
						}
						list.Add(idNamePair.ID);
					}
				}
				if (pageHeader2.PageBodyClass.GroupByOption != null && pageHeader2.PageBodyClass.GroupByOption.GroupBy != null && pageHeader2.PageBodyClass.GroupByOption.GroupBy.Length != 0)
				{
					iGroupingType = 1;
					list = new List<int>();
					orderBy = pageHeader2.PageBodyClass.GroupByOption.GroupBy;
					foreach (IdNamePair idNamePair2 in orderBy)
					{
						if (idNamePair2.ID == 101)
						{
							flag = true;
						}
						list.Add(idNamePair2.ID);
					}
				}
				if (pageHeader2.PageBodyClass.ClubByOption == null || pageHeader2.PageBodyClass.ClubByOption.ClubBy == null || pageHeader2.PageBodyClass.ClubByOption.ClubBy.Length == 0)
				{
					break;
				}
				iGroupingType = 2;
				list = new List<int>();
				orderBy = pageHeader2.PageBodyClass.ClubByOption.ClubBy;
				foreach (IdNamePair idNamePair3 in orderBy)
				{
					if (idNamePair3.ID == 101)
					{
						flag = true;
					}
					list.Add(idNamePair3.ID);
				}
				break;
			}
		}
		if (objTrans != null && objTrans.BodyData != null && objTrans.BodyData.Length != 0)
		{
			list2 = new List<int>();
			if (FConvert.IsItSales(voucherType))
			{
				TransBody[] bodyData = objTrans.BodyData;
				foreach (TransBody transBody in bodyData)
				{
					if (transBody.Sales != null && transBody.Sales.Product > 0)
					{
						list2.Add(transBody.Sales.Product);
					}
				}
			}
			else
			{
				TransBody[] bodyData = objTrans.BodyData;
				foreach (TransBody transBody2 in bodyData)
				{
					if (transBody2.Code > 0)
					{
						list2.Add(transBody2.Code);
					}
				}
			}
		}
		if (list2 != null && list2.Count > 0 && list != null && list.Count > 0)
		{
			array = ((!flag) ? new Focus.Transactions.BL.Transactions().GetLevelWiseMasters((!FConvert.IsItSales(voucherType)) ? 1 : 2, list2.ToArray(), list.ToArray(), iCompanyId) : GetMenus(list2.ToArray(), objDb, iCompanyId));
		}
		switch (iGroupingType)
		{
		case 0:
			if (array != null && array.Length != 0)
			{
				OrderByData(array, ref objTrans, isDontClubIfRateDifferent, iGroupingType);
			}
			break;
		case 1:
		case 2:
			if (array != null && array.Length != 0)
			{
				isDontClubIfRateDifferent = objLayoutBody != null && objLayoutBody.ClubByOption != null && FConvert.IsItSales(voucherType) && objLayoutBody.ClubByOption.IsDontClubIfRateDifferent;
				arrGroupData = OrderByData(array, ref objTrans, isDontClubIfRateDifferent, iGroupingType);
			}
			break;
		}
	}

	private IdNamePair[] OrderByData(IdNamePair[] arrOrderByData, ref Transaction objTranData, bool IsDontClubIfRateDifferent, byte iGroupingType)
	{
		string text = null;
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		int voucherType = objTranData.Header.VoucherType;
		List<IdNamePair> list = null;
		List<TransBody> list2 = null;
		list = new List<IdNamePair>();
		if (arrOrderByData != null && objTranData != null)
		{
			list2 = new List<TransBody>();
			arrOrderByData = arrOrderByData.OrderBy((IdNamePair p) => p.Name).ToArray();
			for (num = 0; num < arrOrderByData.Length; num++)
			{
				for (num2 = 0; num2 < objTranData.BodyData.Length; num2++)
				{
					if (objTranData.BodyData[num2].RowType != _RowType.Default)
					{
						continue;
					}
					num3 = (FConvert.IsItSales(voucherType) ? objTranData.BodyData[num2].Sales.Product : objTranData.BodyData[num2].Code);
					if (arrOrderByData[num].ID == num3)
					{
						if (text != arrOrderByData[num].Name)
						{
							list.Add(new IdNamePair(list2.Count, arrOrderByData[num].Name));
							text = arrOrderByData[num].Name;
						}
						else if (IsDontClubIfRateDifferent && list.Count > 0 && list2.Count > 0 && objTranData.BodyData[num2].Sales.Rate != list2[list2.Count - 1].Sales.Rate)
						{
							list.Add(new IdNamePair(list2.Count, arrOrderByData[num].Name));
						}
						list2.Add(objTranData.BodyData[num2]);
						if (iGroupingType == 1)
						{
							break;
						}
					}
				}
			}
			if (list2.Count > 0)
			{
				objTranData.BodyData = list2.ToArray();
			}
		}
		return list.ToArray();
	}

	private IdNamePair[] GetMenus(int[] arrMasters, Database objDb, int iComanyId)
	{
		List<IdNamePair> list = new List<IdNamePair>();
		string text = null;
		string text2 = null;
		try
		{
			for (int i = 0; i < arrMasters.Length; i++)
			{
				text = $"SELECT TOP 1 sName FROM cPos_RestMenuItem\r\n                    JOIN cPos_RestMenu ON cPos_RestMenuItem.iRestMenuId = cPos_RestMenu.iRestMenuId\r\n                    WHERE iProductId = {arrMasters[i]}";
				text2 = Convert.ToString(objDb.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
				if (!string.IsNullOrEmpty(text2))
				{
					list.Add(new IdNamePair(arrMasters[i], text2));
				}
				else if (list.Count > 0)
				{
					list.Add(new IdNamePair(arrMasters[i], list[list.Count - 1].Name));
				}
			}
		}
		catch
		{
		}
		return list.ToArray();
	}

	private List<HeaderGroup> GetVoucherFields(Transaction objTran, IdNamePair[] arrDefaultFields, string sHeader, InvoiceFieldType iGroupIdType, int iCompanyId, LayoutInformation oLayoutInfo, IdNamePair[] arrOrderedData = null, PageBodyClass objLayoutBody = null, byte iGroupingType = 0, bool bDontIncludeSuspendAmount = false)
	{
		bool IsDontConvertField = false;
		bool flag = false;
		HeaderGroup headerGroup = null;
		TemplateFields templateFields = null;
		TranMasterInfo tranMasterInfo = null;
		List<HeaderGroup> list = null;
		List<TemplateFields> list2 = null;
		List<object> list3 = null;
		List<object> arrRateValues = null;
		int voucherType = objTran.Header.VoucherType;
		bool flag2 = false;
		int num = 0;
		list = new List<HeaderGroup>();
		if (arrDefaultFields == null)
		{
			for (num = 0; num < arrDefaultFields.Length; num++)
			{
				if ((voucherType == 4096 || voucherType == 3840) && arrDefaultFields[num].ID == 4 && ((TranMasterInfo)arrDefaultFields[num].Tag).MasterType == 1)
				{
					arrDefaultFields[num].Name = ((voucherType == 4096) ? "Cr Account" : "Dr Account");
				}
				if (arrDefaultFields[num].ID == 13 && !FConvert.IsItInwardVoucher(voucherType))
				{
					flag = true;
				}
			}
			if (arrDefaultFields != null && arrDefaultFields.Length != 0)
			{
				Array.Resize(ref arrDefaultFields, arrDefaultFields.Length + 5 + (flag ? 2 : 0));
				arrDefaultFields[arrDefaultFields.Length - 5] = new IdNamePair(75, "Net", new TranMasterInfo
				{
					IsBodyField = true,
					DataType = 6,
					MasterType = 0,
					Filter = string.Empty
				});
				arrDefaultFields[arrDefaultFields.Length - 4] = new IdNamePair(75, "Net (base currency)", new TranMasterInfo
				{
					IsBodyField = true,
					DataType = 6,
					MasterType = -1,
					Filter = string.Empty
				});
				arrDefaultFields[arrDefaultFields.Length - 3] = new IdNamePair(75, "Net (local currency)", new TranMasterInfo
				{
					IsBodyField = true,
					DataType = 6,
					MasterType = -2,
					Filter = string.Empty
				});
				arrDefaultFields[arrDefaultFields.Length - 2] = new IdNamePair(116, "Print count", new TranMasterInfo
				{
					IsBodyField = false,
					DataType = 1,
					MasterType = 0,
					Filter = string.Empty
				});
				arrDefaultFields[arrDefaultFields.Length - 1] = new IdNamePair(117, "Revision number", new TranMasterInfo
				{
					IsBodyField = false,
					DataType = 1,
					MasterType = 0,
					Filter = string.Empty
				});
				if (flag)
				{
					arrDefaultFields[arrDefaultFields.Length - 6] = new IdNamePair(36, "Manufacturing date", new TranMasterInfo
					{
						IsBodyField = true,
						DataType = 0,
						MasterType = 0,
						Filter = string.Empty
					});
					arrDefaultFields[arrDefaultFields.Length - 7] = new IdNamePair(37, "Expiry date", new TranMasterInfo
					{
						IsBodyField = true,
						DataType = 0,
						MasterType = 0,
						Filter = string.Empty
					});
				}
				List<IdNamePair> list4 = new List<IdNamePair>();
				list4.AddRange(arrDefaultFields);
				list4.Add(new IdNamePair(166, "Email count", new TranMasterInfo
				{
					IsBodyField = false,
					DataType = 1,
					MasterType = 0,
					Filter = string.Empty
				}));
				arrDefaultFields = list4.ToArray();
				list4.Clear();
			}
		}
		headerGroup = new HeaderGroup();
		headerGroup.MasterId = (int)iGroupIdType;
		headerGroup.GroupName = sHeader;
		list2 = new List<TemplateFields>();
		switch (iGroupIdType)
		{
		case InvoiceFieldType.User:
			if (objTran != null)
			{
				UserContactDetails[] array = null;
				array = new InvoiceLayout().GetUsersContactDetails(objTran.Header.HeaderId, CurrentData.get().UserId, iCompanyId);
				IdNamePair[] userSpecificFields = GetUserSpecificFields(array != null && array.Length > 1);
				foreach (IdNamePair idNamePair in userSpecificFields)
				{
					templateFields = new TemplateFields();
					templateFields.FieldId = idNamePair.ID;
					templateFields.Name = idNamePair.Name;
					templateFields.Values = GetUserSpecificValues(idNamePair.ID, array);
					list2.Add(templateFields);
				}
			}
			break;
		case InvoiceFieldType.POS:
		{
			IdNamePair[] userSpecificFields = GetVoucherSpecificFields();
			foreach (IdNamePair idNamePair3 in userSpecificFields)
			{
				templateFields = new TemplateFields();
				templateFields.FieldId = idNamePair3.ID;
				templateFields.Name = idNamePair3.Name;
				templateFields.Values = GetVoucherSpecificValues(objTran, idNamePair3.ID, iCompanyId, oLayoutInfo, arrOrderedData, iGroupingType);
				list2.Add(templateFields);
			}
			break;
		}
		case InvoiceFieldType.Reference:
			if (objTran != null && objTran.Header != null && objTran.Header.Flags != null && objTran.Header.Flags.UpdateFA)
			{
				IdNamePair[] userSpecificFields = GetReferenceFields();
				foreach (IdNamePair idNamePair2 in userSpecificFields)
				{
					templateFields = new TemplateFields();
					templateFields.FieldId = idNamePair2.ID;
					templateFields.Name = idNamePair2.Name;
					templateFields.DataType = (MasterDataType)idNamePair2.Tag;
					templateFields.Values = GetReferenceValues(objTran, idNamePair2.ID, iCompanyId, ref IsDontConvertField);
					list2.Add(templateFields);
				}
				break;
			}
			return null;
		case InvoiceFieldType.Header:
		case InvoiceFieldType.Body:
			for (num = 0; num < arrDefaultFields.Length; num++)
			{
				list3 = new List<object>();
				templateFields = new TemplateFields();
				templateFields.FieldId = arrDefaultFields[num].ID;
				templateFields.Name = arrDefaultFields[num].Name;
				tranMasterInfo = (TranMasterInfo)arrDefaultFields[num].Tag;
				templateFields.DataType = (MasterDataType)tranMasterInfo.DataType;
				templateFields.MasterType = tranMasterInfo.MasterType;
				if (templateFields.DataType == MasterDataType.Master && templateFields.MasterType > 1)
				{
					_ = templateFields.FieldId;
					_ = 5000;
				}
				if (!tranMasterInfo.IsBodyField && iGroupIdType == InvoiceFieldType.Header)
				{
					if (objTran != null)
					{
						list3.Add(GetHeaderValue(templateFields.FieldId, templateFields.DataType, templateFields.MasterType, objTran, iCompanyId, IsDontConvertField));
					}
					else
					{
						list3.Add("0");
					}
					templateFields.Values = list3.ToArray();
					list2.Add(templateFields);
				}
				else
				{
					if (!tranMasterInfo.IsBodyField || iGroupIdType != InvoiceFieldType.Body)
					{
						continue;
					}
					double num2 = 0.0;
					if (objTran != null && objTran.BodyData != null && objTran.BodyData.Length != 0)
					{
						for (int i = 0; i < objTran.BodyData.Length; i++)
						{
							if (objTran.BodyData[i].RowType != _RowType.Default && (objTran.BodyData[i].RowType != _RowType.AccountToPost || templateFields.FieldId != 75))
							{
								continue;
							}
							if (objTran.BodyData[i].RowType == _RowType.AccountToPost)
							{
								num2 += Convert.ToDouble(GetBodyValue(templateFields.FieldId, templateFields.DataType, templateFields.MasterType, objTran, i, iCompanyId, IsDontConvertField));
							}
							if ((templateFields.FieldId == 75 || templateFields.FieldId == 28) && objTran.BodyData[i].Flags.SuspendFA && objTran.BodyData[i].AuthStatus == _AuthStatus.Authorized)
							{
								list3.Add(0);
							}
							else if (templateFields.FieldId == 75 && objTran.BodyData[0].Book != objTran.BodyData[i].Book)
							{
								list3.Add(0);
							}
							else if (templateFields.FieldId == 23 && !IsPrintModiferProduct(objTran.BodyData[i].Sales.POSData, oLayoutInfo, objTran.BodyData[i].Sales.Rate))
							{
								list3.Add(string.Empty);
							}
							else
							{
								if (FConvert.IsItTransfer(objTran.Header.VoucherType) && i >= objTran.BodyData.Length / 2)
								{
									continue;
								}
								if (objTran.BodyData[i].Sales != null && !IsPrintModiferProduct(objTran.BodyData[i].Sales.POSData, oLayoutInfo, objTran.BodyData[i].Sales.Rate))
								{
									list3.Add(0);
								}
								else if ((objTran.BodyData[i].Flags.SuspendFA & bDontIncludeSuspendAmount) && templateFields.FieldId == 75)
								{
									list3.Add(0);
								}
								else if (arrDefaultFields[num].ID == 26 && objTran.BodyData[i].Sales.POSData != null && objTran.BodyData[i].Sales.POSData.ModifierId > 0)
								{
									if (oLayoutInfo != null && objTran.BodyData[i].Sales.POSData != null && !oLayoutInfo.IsDonotPrintQuantityforModifiers)
									{
										list3.Add(GetBodyValue(templateFields.FieldId, templateFields.DataType, templateFields.MasterType, objTran, i, iCompanyId, IsDontConvertField));
									}
									else
									{
										list3.Add(string.Empty);
									}
								}
								else
								{
									list3.Add(GetBodyValue(templateFields.FieldId, templateFields.DataType, templateFields.MasterType, objTran, i, iCompanyId, IsDontConvertField));
								}
							}
						}
						if (templateFields.FieldId == 75 && list3.Count > 0)
						{
							num2 += Convert.ToDouble(list3[0]);
							list3[0] = num2;
						}
					}
					else
					{
						list3.Add("0");
					}
					if (arrOrderedData != null)
					{
						if (iGroupingType == 1)
						{
							ArrangeGroupByData(arrOrderedData, objLayoutBody, templateFields.FieldId, templateFields.DataType, ref list3);
						}
						else
						{
							ArrangeClubByData(arrOrderedData, objLayoutBody, templateFields.FieldId, templateFields.DataType, arrRateValues, ref list3);
						}
					}
					templateFields.Values = list3.ToArray();
					list2.Add(templateFields);
				}
			}
			break;
		}
		headerGroup.Fields = list2.ToArray();
		list.Add(headerGroup);
		return list;
	}

	private IdNamePair[] GetUserSpecificFields(bool bNextUSer)
