	private object[] GetUserSpecificValues(int iFieldId, UserContactDetails[] arrUserDetails)
	{
		int num = 0;
		UserContactDetails userContactDetails = null;
		List<object> list = null;
		list = new List<object>();
		if (iFieldId < 10)
		{
			for (num = 0; num < arrUserDetails.Length; num++)
			{
				if (arrUserDetails[num].UserId == CurrentData.get().UserId)
				{
					userContactDetails = arrUserDetails[num];
					break;
				}
			}
			if (userContactDetails != null)
			{
				switch (iFieldId)
				{
				case 0:
					list.Add(userContactDetails.UserName);
					break;
				case 1:
					list.Add(userContactDetails.MobileNumber);
					break;
				case 2:
					list.Add(userContactDetails.PhoneNumber);
					break;
				case 3:
					list.Add(userContactDetails.EmailId);
					break;
				}
			}
		}
		else
		{
			for (num = 0; num < arrUserDetails.Length; num++)
			{
				if (arrUserDetails[num].UserId != CurrentData.get().UserId)
				{
					switch (iFieldId)
					{
					case 10:
						list.Add(arrUserDetails[num].UserName);
						break;
					case 11:
						list.Add(arrUserDetails[num].MobileNumber);
						break;
					case 12:
						list.Add(arrUserDetails[num].PhoneNumber);
						break;
					case 13:
						list.Add(arrUserDetails[num].EmailId);
						break;
					}
				}
			}
		}
		if (list.Count == 0)
		{
			list.Add("0");
		}
		return list.ToArray();
	}

	private void ArrangeGroupByData(IdNamePair[] arrOrderedData, PageBodyClass objBodyClass, int iFieldId, MasterDataType objType, ref List<object> arrValues)
	{
		double[] array = null;
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		if (objBodyClass.GroupByOption == null || (!objBodyClass.GroupByOption.IsPrintGroupHeading && !objBodyClass.GroupByOption.IsPrintSubTotal))
		{
			return;
		}
		if (objType == MasterDataType.Fraction && objBodyClass.GroupByOption.IsPrintSubTotal)
		{
			array = new double[arrOrderedData.Length];
			for (num = 0; num < arrOrderedData.Length; num++)
			{
				if (iFieldId != 27)
				{
					num3 = ((num < arrOrderedData.Length - 1) ? arrOrderedData[num + 1].ID : arrValues.Count);
					for (num2 = arrOrderedData[num].ID; num2 < num3; num2++)
					{
						array[num] += Convert.ToDouble(arrValues[num2]);
					}
				}
			}
		}
		for (num = 0; num < arrOrderedData.Length; num++)
		{
			if (objType == MasterDataType.Fraction)
			{
				if (objBodyClass.GroupByOption.IsPrintSubTotal && array[num] != 0.0)
				{
					arrValues.Insert(arrOrderedData[num].ID + num, array[num]);
				}
				else
				{
					arrValues.Insert(arrOrderedData[num].ID + num, 0);
				}
			}
			else if (objBodyClass.GroupByOption.IsPrintGroupHeading && arrOrderedData[num].ID + num < arrValues.Count && iFieldId == 23)
			{
				if (!string.IsNullOrEmpty(Convert.ToString(arrValues[arrOrderedData[num].ID + num])))
				{
					arrValues.Insert(arrOrderedData[num].ID + num, $"<B>{arrOrderedData[num].Name}~{arrValues[arrOrderedData[num].ID + num]}");
				}
				else
				{
					arrValues.Insert(arrOrderedData[num].ID + num, string.Empty);
				}
			}
			else
			{
				arrValues.Insert(arrOrderedData[num].ID + num, string.Empty);
			}
		}
	}

	private void ArrangeClubByData(IdNamePair[] arrOrderedData, PageBodyClass objBodyClass, int iFieldId, MasterDataType objType, List<object> arrRateValues, ref List<object> arrValues)
	{
		double[] array = null;
		string[] array2 = null;
		double num = 0.0;
		List<IdValuePair> list = null;
		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		int num5 = 0;
		if (objBodyClass.ClubByOption == null)
		{
			return;
		}
		if (objType == MasterDataType.Fraction)
		{
			array = new double[arrOrderedData.Length];
			for (num2 = 0; num2 < arrOrderedData.Length; num2++)
			{
				num = 0.0;
				num5 = 0;
				num4 = ((num2 < arrOrderedData.Length - 1) ? arrOrderedData[num2 + 1].ID : arrValues.Count);
				for (num3 = arrOrderedData[num2].ID; num3 < num4; num3++)
				{
					if (iFieldId == 27)
					{
						num += Convert.ToDouble(arrValues[num3]);
						num5++;
					}
					else
					{
						array[num2] += Convert.ToDouble(arrValues[num3]);
					}
				}
				if (iFieldId == 27 && num5 > 0)
				{
					array[num2] = num / (double)num5;
				}
			}
		}
		else if (iFieldId == 13)
		{
			array2 = new string[arrOrderedData.Length];
			for (num2 = 0; num2 < arrOrderedData.Length; num2++)
			{
				List<string> list2 = new List<string>();
				num4 = ((num2 < arrOrderedData.Length - 1) ? arrOrderedData[num2 + 1].ID : arrValues.Count);
				for (num3 = arrOrderedData[num2].ID; num3 < num4; num3++)
				{
					list2.Add(Convert.ToString(arrValues[num3]));
				}
				array2[num2] = string.Join(",", list2.Distinct().ToArray());
			}
		}
		list = new List<IdValuePair>();
		for (num2 = 0; num2 < arrOrderedData.Length; num2++)
		{
			if (objType == MasterDataType.Fraction)
			{
				list.Add(new IdValuePair(arrOrderedData[num2].ID, array[num2]));
				continue;
			}
			if (iFieldId == 23)
			{
				if (Convert.ToString(arrValues[arrOrderedData[num2].ID]) != string.Empty)
				{
					list.Add(new IdValuePair(arrOrderedData[num2].ID, $"<B>{arrOrderedData[num2].Name}~{arrValues[arrOrderedData[num2].ID]}"));
				}
				else
				{
					list.Add(new IdValuePair(arrOrderedData[num2].ID, ""));
				}
			}
			switch (iFieldId)
			{
			case 24:
				list.Add(new IdValuePair(arrOrderedData[num2].ID, $"{arrValues[arrOrderedData[num2].ID]}"));
				continue;
			case 13:
				if (array2 != null && num2 < array2.Length)
				{
					list.Add(new IdValuePair(arrOrderedData[num2].ID, array2[num2]));
					continue;
				}
				break;
			}
			if (objType == MasterDataType.Text && num2 < arrValues.Count)
			{
				list.Add(new IdValuePair(arrOrderedData[num2].ID, arrValues[num2]));
			}
		}
		arrValues = list.Select((IdValuePair p) => p.Value).ToList();
	}

	private object[] GetVoucherSpecificValues(Transaction objTran, int iFieldId, int iCompId, LayoutInformation oLayoutInfo, IdNamePair[] arrOrderData, byte iGroupingType)
	{
		List<object> list = new List<object>();
		if (objTran != null)
		{
			for (int i = 0; i < objTran.BodyData.Length; i++)
			{
				if (objTran.BodyData[i].Sales != null && IsPrintModiferProduct(objTran.BodyData[i].Sales.POSData, oLayoutInfo, objTran.BodyData[i].Sales.Rate))
				{
					switch (iFieldId)
					{
					case 0:
						if (objTran.BodyData[i].Sales.POSData == null || (objTran.BodyData[i].Sales.POSData != null && objTran.BodyData[i].Sales.POSData.ModifierId == 0))
						{
							list.Add(GetMasterValue(2, objTran.BodyData[i].Sales.Product, iCompId));
						}
						else
						{
							list.Add(string.Empty);
						}
						break;
					case 1:
						if (objTran.BodyData[i].Sales.POSData != null && objTran.BodyData[i].Sales.POSData.ModifierId > 0)
						{
							list.Add("<I>" + GetMasterValue(2, objTran.BodyData[i].Sales.Product, iCompId));
						}
						else
						{
							list.Add(string.Empty);
						}
						break;
					case 3:
						if (objTran.BodyData[i].Sales != null && objTran.BodyData[i].Sales.Product > 0)
						{
							list.Add(GetMasterValue(-8, objTran.BodyData[i].Sales.Product, iCompId, IsDontConvertField: true));
						}
						else
						{
							list.Add(string.Empty);
						}
						break;
					case 2:
						if (objTran.BodyData[i].Sales.Product > 0)
						{
							bool flag = true;
							if (arrOrderData != null && arrOrderData.Length != 0)
							{
								flag = false;
								for (int j = 0; j < arrOrderData.Length; j++)
								{
									if (arrOrderData[j].ID == i)
									{
										flag = true;
										break;
									}
								}
							}
							if (flag || iGroupingType == 1)
							{
								int alternateLanguage = GetAlternateLanguage(iCompId);
								if (objTran.BodyData[i].Sales.POSData != null && objTran.BodyData[i].Sales.POSData.ModifierId > 0)
								{
									list.Add(GetMasterCode(2, objTran.BodyData[i].Sales.Product, alternateLanguage, iCompId));
								}
								else
								{
									list.Add(GetMasterCode(2, objTran.BodyData[i].Sales.Product, alternateLanguage, iCompId));
								}
							}
						}
						else
						{
							list.Add(string.Empty);
						}
						break;
					}
				}
				else
				{
					list.Add(string.Empty);
				}
			}
			if (arrOrderData != null && iFieldId == 2 && iGroupingType == 1)
			{
				for (int k = 0; k < arrOrderData.Length; k++)
				{
					list.Insert(arrOrderData[k].ID + k, null);
				}
			}
		}
		else
		{
			list.Add("0");
		}
		return list.ToArray();
	}

	private IdNamePair[] GetReferenceFields()
	{
