			new IdNamePair(2, "Balance amount", MasterDataType.Text),
			new IdNamePair(3, "Due date", MasterDataType.Date),
			new IdNamePair(4, "Reference", MasterDataType.Text),
			new IdNamePair(6, "Doc number", MasterDataType.Text),
			new IdNamePair(7, "Date", MasterDataType.Text),
			new IdNamePair(5, "Account", MasterDataType.Text)
		};
	}

	private object[] GetReferenceValues(Transaction objTran, int iFieldId, int iCompanyId, ref bool IsDontConvertField)
	{
		string text = null;
		decimal num = 0m;
		int num2 = 0;
		int num3 = 0;
		List<string> list = new List<string>();
		List<string> list2 = null;
		list2 = new List<string>();
		if (objTran != null && objTran.BodyData != null && objTran.BodyData.Length != 0)
		{
			for (int i = 0; i < objTran.BodyData.Length; i++)
			{
				list2.Clear();
				if (objTran.BodyData[i].BillwiseData == null)
				{
					continue;
				}
				for (int j = 0; j < objTran.BodyData[i].BillwiseData.Length; j++)
				{
					switch (iFieldId)
					{
					case 0:
						num = objTran.BodyData[i].BillwiseData[j].BillBaseInfo.OrginalTransactionAmount;
						list2.Add(num.AddDecimalInColumn(2));
						break;
					case 1:
						num = objTran.BodyData[i].BillwiseData[j].mAAIDInvoiceCurrency;
						list2.Add(num.AddDecimalInColumn(2));
						break;
					case 2:
						num = objTran.BodyData[i].BillwiseData[j].BillBaseInfo.BalanceTransactionAmount - objTran.BodyData[i].BillwiseData[j].mAAIDInvoiceCurrency;
						list2.Add(num.AddDecimalInColumn(2));
						break;
					case 4:
						list2.Add(objTran.BodyData[i].BillwiseData[j].sReference);
						break;
					case 6:
						if (objTran.BodyData[i].BillwiseData[j].sReference != null)
						{
							num2 = objTran.BodyData[i].BillwiseData[j].sReference.IndexOf(" : ");
							if (num2 > 0)
							{
								list2.Add(objTran.BodyData[i].BillwiseData[j].sReference.Substring(0, num2));
							}
						}
						break;
					case 7:
						if (objTran.BodyData[i].BillwiseData[j].sReference != null)
						{
							num2 = objTran.BodyData[i].BillwiseData[j].sReference.IndexOf(" : ") + 3;
							num3 = objTran.BodyData[i].BillwiseData[j].sReference.Length;
							if (num2 > 0 && num3 > num2)
							{
								list2.Add(objTran.BodyData[i].BillwiseData[j].sReference.Substring(num2, num3 - num2));
							}
						}
						break;
					case 5:
						IsDontConvertField = false;
						list2.Add(GetMasterValue(1, objTran.BodyData[i].BillwiseData[j].iCode, iCompanyId, IsDontConvertField));
						IsDontConvertField = true;
						break;
					}
				}
				text = string.Join(", ", list2.ToArray());
				list.Add(text);
			}
		}
		else
		{
			list.Add("0");
		}
		return list.ToArray();
	}

