			new IdNamePair(2, "Alias"),
			new IdNamePair(3, "Product Category")
		};
	}

	private bool IsPrintModiferProduct(TransPOS oPosData, LayoutInformation objLayoutInfo, decimal dRate)
	{
		bool result = true;
		if (objLayoutInfo != null && oPosData != null && oPosData.ModifierId > 0)
		{
			switch (objLayoutInfo.ModifierOption)
			{
			case ModifierPrintOption.Print:
				result = true;
				break;
			case ModifierPrintOption.PrintItemWithPrice:
				result = dRate > 0m;
				break;
			}
		}
		return result;
	}

	public object GetHeaderValue(int iFieldId, MasterDataType objType, int iMasterType, Transaction objTran, int iCompanyId, bool IsDontConvertField = false)
	{
		int iIndex = 0;
		switch ((VTFIELDID)iFieldId)
		{
		case VTFIELDID.FDF_PRINTCOUNT:
			return objTran.Header.PrintCount;
		case VTFIELDID.FDF_EMAILCOUNT:
			return objTran.Header.EmailCount;
		case VTFIELDID.FDF_REVISION_NO:
			return (objTran.Header.Versions != null && objTran.Header.Versions.Length != 0) ? objTran.Header.Versions.Length : 0;
		case VTFIELDID.FDF_DOCUMENTNO:
			return objTran.Header.DocNo;
		case VTFIELDID.FDF_DATE:
			return ConvertValue(objTran.Header.Date, objType, iMasterType, iCompanyId, IsDontConvertField);
		case VTFIELDID.FDF_TIME:
			return ConvertValue(objTran.Header.ModifiedTime, objType, iMasterType, iCompanyId, IsDontConvertField);
		case VTFIELDID.FDF_BOOKNO:
			return GetMasterValue(1, objTran.BodyData[iIndex].Book, iCompanyId, IsDontConvertField);
		case VTFIELDID.FDF_CODE:
			return GetMasterValue(1, objTran.BodyData[iIndex].Code, iCompanyId, IsDontConvertField);
		case VTFIELDID.FDF_AGAINSTINVOIVENO:
			return objTran.BodyData[iIndex].InvTag;
		case VTFIELDID.FDF_DUEDATE:
			return objTran.BodyData[iIndex].DueDate;
		case VTFIELDID.FDF_HEADERCURRENCY:
			return objTran.BodyData[iIndex].CurrencyId;
		case VTFIELDID.FDF_EXCHANGERATE:
			return objTran.BodyData[iIndex].ExchangeRate;
		case VTFIELDID.FDF_UPDATESTOCKS:
			return ConvertValue(objTran.Header.Flags.UpdateInv, objType, iMasterType, iCompanyId, IsDontConvertField);
		case VTFIELDID.FDF_UPDATEFA:
			return ConvertValue(objTran.Header.Flags.UpdateFA, objType, iMasterType, iCompanyId, IsDontConvertField);
		case VTFIELDID.FDF_LCNUMBER:
			return GetMasterValue(-2, objTran.Header.LC, iCompanyId, IsDontConvertField);
		case VTFIELDID.FDF_PMTTERMS:
			return objTran.Header.PmtTerm;
		case VTFIELDID.FDF_HEADERINVTAG:
			return GetMasterValue(_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Tag, 1), objTran.BodyData[iIndex].InvTag, iCompanyId, IsDontConvertField);
		case VTFIELDID.FDF_BODYINVTAG:
			return GetMasterValue(_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Tag, 1), (iIndex + 1 < objTran.BodyData.Length) ? objTran.BodyData[iIndex + 1].InvTag : objTran.BodyData[iIndex].InvTag, iCompanyId, IsDontConvertField);
		case VTFIELDID.FDF_RCTISSUESELECTION:
			if (!(objTran.BodyData[iIndex].Sales.Quantity < 0m))
			{
				return "Receipts";
			}
			return "Issues";
		default:
			if ((iFieldId & 0x10000000) > 0)
			{
				if (_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Tag, 1) == (iFieldId & 0xFFFFFF))
				{
					return GetMasterValue(iFieldId & 0xFFFFFF, objTran.BodyData[iIndex].InvTag, iCompanyId, IsDontConvertField);
				}
				if (_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Tag, 0) == (iFieldId & 0xFFFFFF))
				{
					return GetMasterValue(iFieldId & 0xFFFFFF, objTran.BodyData[iIndex].FATag, iCompanyId, IsDontConvertField);
				}
				if (objTran.BodyData[0].Tags != null && objTran.BodyData[0].Tags.Length != 0)
				{
					for (iIndex = 0; iIndex < objTran.BodyData[0].Tags.Length; iIndex++)
					{
						if (objTran.BodyData[0].Tags[iIndex].ID == (iFieldId & 0xFFFFFF))
						{
							return GetMasterValue(iFieldId & 0xFFFFFF, (int)objTran.BodyData[0].Tags[iIndex].Tag, iCompanyId, IsDontConvertField);
						}
					}
				}
			}
			if (objTran.HeaderExtra != null)
			{
				for (iIndex = 0; iIndex < objTran.HeaderExtra.Length; iIndex++)
				{
					if (objTran.HeaderExtra[iIndex].ID == iFieldId)
					{
						return ConvertValue(objTran.HeaderExtra[iIndex].Tag, objType, (iMasterType == -1) ? (iFieldId & 0xFFFFFF) : iMasterType, iCompanyId, IsDontConvertField);
					}
				}
			}
			if (objTran.Footer != null)
			{
				for (iIndex = 0; iIndex < objTran.Footer.Length; iIndex++)
				{
					if (objTran.Footer[iIndex].FieldId == (iFieldId & 0xFFFFFF))
					{
						double num = Convert.ToDouble(objTran.Footer[iIndex].Value);
						return ConvertValue(num, objType, iMasterType, iCompanyId, IsDontConvertField);
					}
					if ((iFieldId & Convert.ToInt32(VTFIELDFLAG.SCR_FTR)) == Convert.ToInt32(VTFIELDFLAG.SCR_FTR) && (iFieldId & 0xFFFFFF) - 1001 == iIndex)
					{
						FooterData[] array = objTran.Footer.Where((FooterData p) => p.ColMap == objTran.Footer[iIndex].ColMap).ToArray();
						if (array.Length != 0 && array[0].Account1 > 0)
						{
							return GetMasterValue(1, array[0].Account1, iCompanyId, IsDontConvertField);
						}
					}
				}
			}
			return null;
		}
	}

	public object GetBodyValue(int iFieldId, MasterDataType objType, int iMasterType, Transaction objTran, int iRowIndex, int iCompanyId, bool IsDontConvertField = false)
	{
		int num = 0;
		string text = null;
		if (objTran.BodyData != null && iRowIndex < objTran.BodyData.Length)
		{
			switch ((VTFIELDID)iFieldId)
			{
			case VTFIELDID.FDF_CODE:
			case VTFIELDID.FDF_BODYCODE:
				return GetMasterValue(1, objTran.BodyData[iRowIndex].Code, iCompanyId, IsDontConvertField);
			case VTFIELDID.FDF_BOOKNO:
			case VTFIELDID.FDF_BODYBOOKNO:
				return GetMasterValue(1, objTran.BodyData[iRowIndex].Book, iCompanyId, IsDontConvertField);
			case VTFIELDID.FDF_BODYDUEDATE:
				return ConvertValue(objTran.BodyData[iRowIndex].DueDate, objType, iMasterType, iCompanyId, IsDontConvertField);
			case VTFIELDID.FDF_EXCHANGERATE:
				return objTran.BodyData[iRowIndex].ExchangeRate;
			case VTFIELDID.FDF_BODYBATCHNO:
				if (objTran.BodyData[iRowIndex].Sales != null && objTran.BodyData[iRowIndex].Sales.BatchNo != null)
				{
					return objTran.BodyData[iRowIndex].Sales.BatchNo.BatchNo;
				}
				break;
			case VTFIELDID.FDF_BODYCURRENCY:
				return GetMasterValue(-1, objTran.BodyData[iRowIndex].CurrencyId, iCompanyId, IsDontConvertField);
			case VTFIELDID.FDF_BODYEXCHANGERATE:
				return objTran.BodyData[iRowIndex].ExchangeRate;
			case VTFIELDID.FDF_BODYAMOUNT:
				return objTran.BodyData[iRowIndex].OriginalAmounts[1];
			case VTFIELDID.FDF_BODYNET:
				switch (iMasterType)
				{
				case -1:
					return objTran.BodyData[iRowIndex].Amounts[1];
				case -2:
					if (objTran.BodyData[iRowIndex].LocalCurrencyData != null)
					{
						return objTran.BodyData[iRowIndex].LocalCurrencyData.Amounts[1];
					}
					return 0;
				default:
					return objTran.BodyData[iRowIndex].OriginalAmounts[1];
				}
			case VTFIELDID.FDF_CREDITDAYSBASEDDISCOUNT:
			case VTFIELDID.FDF_BODYJRNDEBIT:
				if (objTran.BodyData[iRowIndex].Amounts != null && objTran.BodyData[iRowIndex].Amounts.Length > 1)
				{
					if (objTran.BodyData[iRowIndex].Amounts[0] < 0m)
					{
						return objTran.BodyData[iRowIndex].Amounts[1];
					}
					return 0;
				}
				break;
			case VTFIELDID.FDF_BODYJRNCREDIT:
				if (objTran.BodyData[iRowIndex].Amounts != null && objTran.BodyData[iRowIndex].Amounts.Length > 1)
				{
					if (objTran.BodyData[iRowIndex].Amounts[1] < 0m)
					{
						return objTran.BodyData[iRowIndex].Amounts[0];
					}
					return 0;
				}
				break;
			case VTFIELDID.FDF_RESERVEQUANTITY:
				if (objTran.BodyData[iRowIndex].Sales != null && objTran.BodyData[iRowIndex].Sales.Reservation != null)
				{
					return PrintReservationDetails(objTran.BodyData[iRowIndex].Sales.Reservation);
				}
				break;
			case VTFIELDID.FDF_MAXQTYRELEASE:
				if (objTran.BodyData[iRowIndex].Sales != null && objTran.BodyData[iRowIndex].Sales.StockToRelease != null)
				{
					return objTran.BodyData[iRowIndex].Sales.StockToRelease.Quantity;
				}
				break;
			case VTFIELDID.FDF_BODYPRODUCT:
				if (objTran.BodyData[iRowIndex].Sales != null)
				{
					return GetMasterValue(2, objTran.BodyData[iRowIndex].Sales.Product, iCompanyId);
				}
				break;
			case VTFIELDID.FDF_BODYUNITS:
				if (objTran.BodyData[iRowIndex].Sales != null)
				{
					return GetMasterValue(11, objTran.BodyData[iRowIndex].Sales.Unit, iCompanyId, IsDontConvertField, bConvert: true);
				}
				break;
			case VTFIELDID.FDF_BODYQUANTITY:
				if (objTran.BodyData[iRowIndex].Sales != null)
				{
					return objTran.BodyData[iRowIndex].Sales.Quantity;
				}
				break;
			case VTFIELDID.FDF_BODYALTQUANTITY:
				if (objTran.BodyData[iRowIndex].Sales != null)
				{
					return objTran.BodyData[iRowIndex].Sales.AlternateQuantity;
				}
				break;
			case VTFIELDID.FDF_LINK:
				text = string.Empty;
				if (objTran.BodyData[iRowIndex].Links != null && objTran.BodyData[iRowIndex].Links.Length != 0)
				{
					for (num = 0; num < objTran.BodyData[iRowIndex].Links.Length; num++)
					{
						if ((iMasterType & 0xFFFF) == objTran.BodyData[iRowIndex].Links[num].VoucherType)
						{
							text = objTran.BodyData[iRowIndex].Links[num].VoucherNo;
							break;
						}
					}
				}
				return text;
			case VTFIELDID.FDF_MFGDATE:
				if (objTran.BodyData[iRowIndex].Sales != null && objTran.BodyData[iRowIndex].Sales.BatchNo != null)
				{
					return objTran.BodyData[iRowIndex].Sales.BatchNo.MfgDate.ToString();
				}
				break;
			case VTFIELDID.FDF_EXPDATE:
				if (objTran.BodyData[iRowIndex].Sales != null && objTran.BodyData[iRowIndex].Sales.BatchNo != null)
				{
					return objTran.BodyData[iRowIndex].Sales.BatchNo.ExpDate.ToString();
				}
				break;
			case VTFIELDID.FDF_RMANO:
				if (objTran.BodyData[iRowIndex].Sales != null && objTran.BodyData[iRowIndex].Sales.RMANos != null)
				{
					return string.Join(",", objTran.BodyData[iRowIndex].Sales.RMANos);
				}
				break;
			case VTFIELDID.FDF_BODYGROSS:
				if (objTran.BodyData[iRowIndex].Sales != null)
				{
					return objTran.BodyData[iRowIndex].Sales.OrigGross;
				}
				break;
			case VTFIELDID.FDF_BODYRATE:
				if (objTran.BodyData[iRowIndex].Sales != null)
				{
					return objTran.BodyData[iRowIndex].Sales.OrigRate;
				}
				break;
			case VTFIELDID.FDF_REFERENCE:
				if (objTran.BodyData[iRowIndex].BillwiseData != null)
				{
					List<string> list = new List<string>();
					for (num = 0; num < objTran.BodyData[iRowIndex].BillwiseData.Length; num++)
					{
						list.Add($"{objTran.BodyData[iRowIndex].BillwiseData[num].sReference} {objTran.BodyData[iRowIndex].BillwiseData[num].mAAIDInvoiceCurrency.AddDecimalInColumn(2)}");
					}
					return string.Join(", ", list.ToArray());
				}
				break;
			case VTFIELDID.FDF_BINS:
				if (objTran.BodyData[iRowIndex].Sales == null || objTran.BodyData[iRowIndex].Sales.BinsData == null)
				{
					break;
				}
				text = string.Empty;
				for (num = 0; num < objTran.BodyData[iRowIndex].Sales.BinsData.Length; num++)
				{
					if (num > 0)
					{
						text += ",";
					}
					text = GetMasterValue(12, objTran.BodyData[iRowIndex].Sales.BinsData[num].BinId, iCompanyId, IsDontConvertField);
				}
				return text;
			case VTFIELDID.FDF_BODYINVTAG:
				if (FConvert.IsItTransfer(objTran.Header.VoucherType))
				{
					iRowIndex = objTran.BodyData.Length / 2 + iRowIndex;
					if (iRowIndex >= objTran.BodyData.Length)
					{
						iRowIndex = 0;
					}
					return GetMasterValue(_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Tag, 1), objTran.BodyData[iRowIndex].InvTag, iCompanyId, IsDontConvertField);
				}
				return GetMasterValue(_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Tag, 1), objTran.BodyData[iRowIndex].InvTag, iCompanyId, IsDontConvertField);
			default:
			{
				if ((iFieldId & 0x20000000) > 0)
				{
					if (_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Tag, 1) == (iFieldId & 0xFFFFFF))
					{
						return GetMasterValue(iFieldId & 0xFFFFFF, objTran.BodyData[iRowIndex].InvTag, iCompanyId, IsDontConvertField);
					}
					if (_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Tag, 0) == (iFieldId & 0xFFFFFF))
					{
						return GetMasterValue(iFieldId & 0xFFFFFF, objTran.BodyData[iRowIndex].FATag, iCompanyId, IsDontConvertField);
					}
					if (objTran.BodyData[iRowIndex].Tags != null && objTran.BodyData[iRowIndex].Tags.Length != 0)
					{
						for (num = 0; num < objTran.BodyData[iRowIndex].Tags.Length; num++)
						{
							if (objTran.BodyData[iRowIndex].Tags[num].ID == (iFieldId & 0xFFFFFF) || objTran.BodyData[iRowIndex].Tags[num].ID == iFieldId)
							{
								return GetMasterValue(iFieldId & 0xFFFFFF, (int)objTran.BodyData[iRowIndex].Tags[num].Tag, iCompanyId, IsDontConvertField);
							}
						}
					}
				}
				if (objTran.BodyData[iRowIndex].BodyExtra != null)
				{
					for (num = 0; num < objTran.BodyData[iRowIndex].BodyExtra.Length; num++)
					{
						if (objTran.BodyData[iRowIndex].BodyExtra[num].ID == iFieldId)
						{
							if (objTran.BodyData[iRowIndex].BodyExtra[num].Name == "sLineNarration")
							{
								return "<I>" + ConvertValue(objTran.BodyData[iRowIndex].BodyExtra[num].Tag, objType, (iMasterType == -1) ? (iFieldId & 0xFFFFFF) : iMasterType, iCompanyId, IsDontConvertField);
							}
							return ConvertValue(objTran.BodyData[iRowIndex].BodyExtra[num].Tag, objType, (iMasterType == -1) ? (iFieldId & 0xFFFFFF) : iMasterType, iCompanyId, IsDontConvertField);
						}
					}
				}
				if (objTran.BodyData[iRowIndex].Sales == null || objTran.BodyData[iRowIndex].Sales.ScreenData == null)
				{
					break;
				}
				int num2 = iFieldId;
				for (num = 0; num < objTran.BodyData[iRowIndex].Sales.ScreenData.Length; num++)
				{
					if (num2 < 0)
					{
						iFieldId = num2 * -1;
						if (objTran.BodyData[iRowIndex].Sales.ScreenData[num].FieldId == (iFieldId & 0xFFFFFF) || objTran.BodyData[iRowIndex].Sales.ScreenData[num].FieldId == iFieldId)
						{
							return ConvertValue(objTran.BodyData[iRowIndex].Sales.ScreenData[num].Value, objType, iMasterType, iCompanyId, IsDontConvertField);
						}
						iFieldId = num2;
					}
					else if (objTran.BodyData[iRowIndex].Sales.ScreenData[num].FieldId == (iFieldId & 0xFFFFFF) || objTran.BodyData[iRowIndex].Sales.ScreenData[num].FieldId == iFieldId)
					{
						return ConvertValue(objTran.BodyData[iRowIndex].Sales.ScreenData[num].Input, objType, iMasterType, iCompanyId, IsDontConvertField);
					}
				}
				break;
			}
			}
		}
		return null;
	}

	private string PrintReservationDetails(Reservations objReservations)
	{
		if (objReservations.ReserveType == 2)
		{
			if (((StockReservationList)objReservations).StockList.Count > 0)
			{
				return string.Format("Stock:" + ((StockReservationList)objReservations).StockList.Sum((StockReservationDetails p) => p.ReserveQty));
			}
		}
		else if (objReservations.ReserveType == 3)
		{
			if (objReservations.ReserveByBatch)
			{
				if (objReservations.ReserveByBin)
				{
					if (objReservations.ReserveByRMA)
					{
						_ = ((BatchReservationList)objReservations).BatchList.Count;
						_ = 0;
						return string.Empty;
					}
					if (((BatchReservationList)objReservations).BatchList.Count > 0)
					{
						StringBuilder stringBuilder = new StringBuilder();
						stringBuilder.Append("Batch-Bin:");
						for (int num = 0; num < ((BatchReservationList)objReservations).BatchList.Count; num++)
						{
							if (((BatchReservationList)objReservations).BatchList[num].ReserveQty > 0m)
							{
								if (num > 0)
								{
									stringBuilder.Append(",");
								}
								stringBuilder.Append(((BatchReservationList)objReservations).BatchList[num].BatchNo + "-");
								stringBuilder.Append(((BatchReservationList)objReservations).BatchList[num].Bins + ":");
								stringBuilder.Append(((BatchReservationList)objReservations).BatchList[num].ReserveQty);
							}
						}
						return stringBuilder.ToString();
					}
				}
				else if (((BatchReservationList)objReservations).BatchList.Count > 0)
				{
					StringBuilder stringBuilder2 = new StringBuilder();
					stringBuilder2.Append("Batch:");
					for (int num2 = 0; num2 < ((BatchReservationList)objReservations).BatchList.Count; num2++)
					{
						if (((BatchReservationList)objReservations).BatchList[num2].ReserveQty > 0m)
						{
							if (num2 > 0)
							{
								stringBuilder2.Append(",");
							}
							stringBuilder2.Append(((BatchReservationList)objReservations).BatchList[num2].BatchNo + ":");
							stringBuilder2.Append(((BatchReservationList)objReservations).BatchList[num2].ReserveQty);
						}
					}
					return stringBuilder2.ToString();
				}
			}
			else if (objReservations.ReserveByBin)
			{
				if (objReservations.ReserveByRMA)
				{
					return string.Empty;
				}
				if (((BinReservationList)objReservations).BinList.Count > 0)
				{
					StringBuilder stringBuilder3 = new StringBuilder();
					stringBuilder3.Append("Bin:");
					for (int num3 = 0; num3 < ((BinReservationList)objReservations).BinList.Count; num3++)
					{
						if (((BinReservationList)objReservations).BinList[num3].ReserveQty > 0m)
						{
							if (num3 > 0)
							{
								stringBuilder3.Append(",");
							}
							stringBuilder3.Append(((BinReservationList)objReservations).BinList[num3].Bins + ":");
							stringBuilder3.Append(((BinReservationList)objReservations).BinList[num3].ReserveQty);
						}
					}
					return stringBuilder3.ToString();
				}
			}
			else if (((RMAReservationList)objReservations).RMAList.Count > 0)
			{
				StringBuilder stringBuilder4 = new StringBuilder();
				stringBuilder4.Append("Bin:");
				for (int num4 = 0; num4 < ((RMAReservationList)objReservations).RMAList.Count; num4++)
				{
					if (((RMAReservationList)objReservations).RMAList[num4].Selected)
					{
						if (num4 > 0)
						{
							stringBuilder4.Append(",");
						}
						stringBuilder4.Append(((RMAReservationList)objReservations).RMAList[num4].RMANo);
					}
				}
				return stringBuilder4.ToString();
			}
		}
		return string.Empty;
	}

	private object ConvertValue(object oValue, MasterDataType oDataType, int iMasterType, int iCompanyId, bool IsDontConvertField = false)
	{
		bool flag = false;
		if (IsDontConvertField)
		{
			return oValue;
		}
		try
		{
			switch (oDataType)
			{
			case MasterDataType.Date:
				oValue = new Date(Convert.ToInt32(oValue), m_objCalType).ToString();
				break;
			case MasterDataType.Time:
				oValue = FConvert.IntToStringTime(Convert.ToInt32(oValue));
				break;
			case MasterDataType.DateTime:
				oValue = new FDateTime(Convert.ToInt64(oValue), m_objCalType);
				break;
			case MasterDataType.Master:
				oValue = GetMasterValue(iMasterType, Convert.ToInt32(oValue), iCompanyId);
				break;
			case MasterDataType.NumberList:
			{
				string[] array = GetMasterValue(-3, iMasterType, iCompanyId).Split(',');
				foreach (string text in array)
				{
					if (flag)
					{
						oValue = text;
						break;
					}
					if (text == Convert.ToString(oValue))
					{
						flag = true;
					}
				}
				break;
			}
			case MasterDataType.Boolean:
				FConvert.PrintBooleanAs(_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Print, 26), ref oValue);
				break;
			case MasterDataType.Fraction:
			case MasterDataType.Picture:
			case MasterDataType.StringList:
			case MasterDataType.DocumentViewer:
			case MasterDataType.UpdatedTime:
				break;
			}
		}
		catch
		{
		}
		return oValue;
	}

	private string GetMasterValue(int iMasterTypeId, int iMasterId, int iCompanyId, bool IsDontConvertField = false, bool bConvert = false)
	{
		if (IsDontConvertField && !bConvert)
		{
			return Convert.ToString(iMasterId);
		}
		return new Focus.Transactions.BL.Transactions().GetMasterFieldName(iMasterId, iMasterTypeId, 0, iCompanyId).Name;
	}

	private string GetMasterCode(int iMasterTypeId, int iMasterId, int iLanguageId, int iCompanyId)
	{
		IdNamePair idNamePair = new IdNamePair();
		idNamePair = new Focus.Transactions.BL.Transactions().GetMasterFieldName(iMasterId, iMasterTypeId, iLanguageId, iCompanyId);
		if (iLanguageId > 0)
		{
			return idNamePair.Name;
		}
		return Convert.ToString(idNamePair.Tag);
	}

