	private string GetGroupsOrCategoryOfProduct(ref IdNamePair objProductGroup, bool IsCategory, Database objDb, int iCompId)
	{
		int num = -1;
		IDataReader dataReader = null;
		List<string> list = null;
		string text = null;
		list = new List<string>();
		try
		{
			if (IsCategory)
			{
				if (!string.IsNullOrEmpty(objProductGroup.Name))
				{
					num = Convert.ToInt32(objProductGroup.Name);
				}
				text = $"with RecursionCTE(iRestMenuId, iParentId)\r\n                    as\r\n                    (\r\n\t                    select iRestMenuId, iParentId from cPos_RestMenu \r\n\t                    where iRestMenuId in(select iRestMenuId from cPos_RestMenuItem where iProductId = {((num > 0) ? num : objProductGroup.ID)} AND ISNULL(iStatus,0) <> 5)\r\n\t                    union all \r\n\t                    select R1.iRestMenuId, R1.iParentId from cPos_RestMenu R1\r\n\t                    join RecursionCTE R2 on R2.iParentId = R1.iRestMenuId\r\n                    )\r\n                    select iRestMenuId from RecursionCTE";
			}
			else
			{
				text = string.Format("with RecursionCTE (iMasterId, sName, iParentId)  \r\n                    as  \r\n                    (  \r\n                        select iMasterId, sName, iParentId\r\n                        from vmCore_Product{0}\r\n                        where iMasterId = {1} and iTreeId = 0\r\n                        union all  \r\n                        select R1.iMasterId, R1.sName, R1.iParentId\r\n                        from vmCore_Product{0} as R1\r\n                        join RecursionCTE as R2 on R2.iParentId = R1.iMasterId\r\n                    )\r\n                    select iMasterId, sName from RecursionCTE where iMasterId > 0", FConvert.GetSuffix(iCompId), objProductGroup.ID);
			}
			dataReader = objDb.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				list.Add(Convert.ToString(dataReader[0]));
			}
			dataReader.Close();
		}
		catch
		{
		}
		return string.Join(",", list.ToArray());
	}

	private List<HeaderGroup> SetMiscellaneousFields(int iLoginId, Database objDb, int iCompanyId)
	{
		int num = 0;
		HeaderGroup headerGroup = null;
		TemplateFields templateFields = null;
		IdNamePair[] array = null;
		List<TemplateFields> list = null;
