	private object[] GetMiscValue(int iFieldId, int iLoginId, int iCompanyId, Database objDb)
	{
		DbCommand dbCommand = null;
		List<object> list = null;
		list = new List<object>();
		switch ((INVOICE_FIELD)iFieldId)
		{
		case INVOICE_FIELD.INV_PRINT_DATE:
			list.Add(new Date().GetToday(m_objCalType));
			break;
		case INVOICE_FIELD.INV_LOGIN_NAME:
			dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre($"select sLoginName from mSec_Users where iUserId={iLoginId}") : $"select sLoginName from mSec_Users where iUserId={iLoginId}");
