			break;
		}
		return list.ToArray();
	}

	public MemberOutput[] GetMemberStatus(MemberInput objValue, int iCompId)
	{
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		Database database = DatabaseWrapper.GetDatabase2(iCompId);
		string suffix = FConvert.GetSuffix(iCompId);
		string empty = string.Empty;
		MemberOutput memberOutput = null;
		List<MemberOutput> list = new List<MemberOutput>();
		using (database.CreateConnection())
		{
			try
			{
				empty = string.Format(" SELECT DISTINCT tCore_Header{0}.iHeaderId, tCore_Header{0}.sVoucherNo, \r\n                                                CASE tCore_HeaderData{1}{0}.iDeliveryType WHEN 1 THEN (CASE ISNULL(mPos_HomeDelivery.iMemberId, 0) WHEN 0 THEN mPos_HomeDelivery.sNonMemName ELSE vmPos_Member.sName END)\r\n                                                ELSE (CASE ISNULL(tCore_HeaderData{1}{0}.sNonMemberName, '') WHEN '' THEN vmPos_Member.sName ELSE tCore_HeaderData{1}{0}.sNonMemberName END) END sName,\r\n                                                tCore_HeaderData{1}{0}.iCollectionDate[DeliveryDate], dbo.fCore_IntToTime(tCore_HeaderData{1}{0}.iCollectionTime)[DeliveryTime], \r\n                                                CASE ISNULL(mPos_HomeDelivery.sAlternativeAddress, '') WHEN '' THEN ISNULL(vmPos_Member.sAddress1, '') + ' ' +  ISNULL(vmPos_Member.sAddress2, '') \r\n                                                ELSE mPos_HomeDelivery.sAlternativeAddress END DeliveryAddress,\r\n                                                CASE tCore_HeaderData{1}{0}.iDeliveryType WHEN 1 THEN  (CASE  ISNULL(mPos_HomeDelivery.iMemberId, 0) WHEN 0 THEN CAST(mPos_HomeDelivery.iPhone AS VARCHAR(15)) ELSE CAST(vmPos_Member.iMobile AS VARCHAR(15)) END)\r\n                                                ELSE (CASE ISNULL(tCore_HeaderData{1}{0}.sPhoneNumber, '') WHEN '' THEN CAST(vmPos_Member.iMobile AS VARCHAR(15)) ELSE tCore_HeaderData{1}{0}.sPhoneNumber END) END PhoneNumber,\r\n                                                (CASE tCore_HeaderData{1}{0}.iStatus WHEN 1 THEN 'New' WHEN 2 THEN 'Deposit' WHEN 3 THEN 'FinalPayment' WHEN 4 THEN 'Collected' WHEN 5 THEN 'Cancelled' END) POStatus \r\n                                                FROM tCore_Header{0} \r\n                                                JOIN tCore_HeaderData{1}{0} ON tCore_HeaderData{1}{0}.iHeaderId = tCore_Header{0}.iHeaderId \r\n                                                JOIN tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId \r\n                                                LEFT JOIN tCore_Data_Tags{0} ON tCore_Data_Tags{0}.iBodyId = tCore_Data{0}.iBodyId \r\n                                                LEFT JOIN vmPos_Member ON vmPos_Member.iMasterId = tCore_Data_Tags{0}.iTag1106 \r\n                                                LEFT JOIN mPos_HomeDelivery ON mPos_HomeDelivery.iTransactionId = tCore_Data{0}.iTransactionId \r\n                                                WHERE tCore_Header{0}.iVoucherType = {1} AND (tCore_Header{0}.iDate BETWEEN {2} AND {3}) AND iSerialNo = 0 ", suffix, 5632, objValue.FromDate, objValue.ToDate);
				if (!string.IsNullOrEmpty(objValue.OrderNo))
				{
					empty = empty + " AND tCore_Header" + suffix + ".sVoucherNo = N'" + objValue.OrderNo + "'";
				}
				if (objValue.MobileNumber > 0)
				{
					empty += $" AND vmPos_Member.iMobile = {objValue.MobileNumber}";
				}
				if (objValue.PreOrder)
				{
					empty += $" AND tCore_HeaderData{5632}{suffix}.iStatus < 4";
				}
				empty = empty + " ORDER BY tCore_Header" + suffix + ".iHeaderId DESC";
				dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
				dataReader = database.ExecuteReader(dbCommand);
				while (dataReader.Read())
				{
					memberOutput = new MemberOutput();
					memberOutput.Id = Convert.ToInt32(dataReader["iHeaderId"]);
					memberOutput.OrderNo = Convert.ToString(dataReader["sVoucherNo"]);
					memberOutput.MemberName = Convert.ToString(dataReader["sName"]);
					memberOutput.Date = Convert.ToString(dataReader["DeliveryDate"]);
					memberOutput.Time = Convert.ToString(dataReader["DeliveryTime"]);
					memberOutput.Address = Convert.ToString(dataReader["DeliveryAddress"]);
					memberOutput.PhoneNumber = Convert.ToString(dataReader["PhoneNumber"]);
					memberOutput.Status = Convert.ToString(dataReader["POStatus"]);
					list.Add(memberOutput);
				}
				dataReader.Close();
			}
			catch (Exception ex)
			{
				memberOutput = new MemberOutput();
				memberOutput.Id = -1;
				memberOutput.OrderNo = ex.Message;
				list.Add(memberOutput);
			}
		}
		return list.ToArray();
	}

