                        FROM \r\n                                tCore_Header{0} \r\n                                JOIN tCore_HeaderData{1}{0} WITH (READUNCOMMITTED) ON tCore_HeaderData{1}{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                                JOIN tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                                JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId\r\n                                JOIN vmCore_Product ON vmCore_Product.iMasterId = tCore_Indta{0}.iProduct\r\n                                LEFT JOIN tCore_Data_Tags{0} ON tCore_Data_Tags{0}.iBodyId = tCore_Data{0}.iBodyId  \r\n                                LEFT JOIN vmPos_Member WITH (READUNCOMMITTED) ON vmPos_Member.iMasterId = tCore_Data_Tags{0}.iTag1106 \r\n                                LEFT JOIN mPos_HomeDelivery WITH (READUNCOMMITTED) ON mPos_HomeDelivery.iTransactionId = tCore_Data{0}.iTransactionId\r\n                                WHERE tCore_Header{0}.iVoucherType = {1}\r\n                                and tCore_HeaderData{1}{0}.iOrderType = 2 and tCore_HeaderData{1}{0}.iStatus < 2 and (mPos_HomeDelivery.bDelivered is null or mPos_HomeDelivery.bDelivered = 0)\r\n                                GROUP BY sVoucherNo,\r\n                                mPos_HomeDelivery.bPaymentOnDelivery, mPos_HomeDelivery.iDeliveryDate, mPos_HomeDelivery.iCreatedDate, mPos_HomeDelivery.sRemarks, vmCore_Product.sName, tCore_Indta{0}.fQuantity,\r\n                                                                \r\n                                mPos_HomeDelivery.iMemberId, mPos_HomeDelivery.sAlternativeAddress, vmPos_Member.sAddress1, vmPos_Member.sAddress2, mPos_HomeDelivery.iPhone, vmPos_Member.iMobile\r\n\r\n                                ORDER BY mPos_HomeDelivery.iDeliveryDate DESC\r\n                                ", suffix, 3331);
				dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
				dataReader = database.ExecuteReader(dbCommand);
