						openOrders = new OpenOrders();
					}
					if (text != text2)
					{
						list2.Clear();
						openOrders.OrderNo = Convert.ToString(dataReader["sVoucherNo"]);
						openOrders.NetAmount = Convert.ToDecimal(dataReader["NetAmount"]);
						openOrders.NetAmount *= -1m;
						text = openOrders.OrderNo;
						openOrders.DeliveryDateTime = Convert.ToInt64(dataReader["iDeliveryDate"]);
						openOrders.DeliveryDate = Convert.ToString(dataReader["sDeliveryDate"]);
						openOrders.DeliveryTime = Convert.ToString(dataReader["sDeliveryTime"]);
						openOrders.OrderDateTime = Convert.ToInt64(dataReader["iCreatedDate"]);
						openOrders.OrderDate = Convert.ToString(dataReader["sCreatedyDate"]);
						openOrders.OrderTime = Convert.ToString(dataReader["sCreatedTime"]);
						openOrders.Remarks = Convert.ToString(dataReader["sRemarks"]);
						openOrders.Status = Convert.ToBoolean(dataReader["bPaymentOnDelivery"]);
						openOrders.DeliveryAddress = Convert.ToString(dataReader["Address"]);
						openOrders.PhoneNo = Convert.ToInt64(dataReader["Phoneno"]);
						idNamePair = new IdNamePair();
						idNamePair.Name = Convert.ToString(dataReader["Item"]);
						idNamePair.Tag = Convert.ToInt32(dataReader["Quantity"]);
						idNamePair.Tag = Convert.ToInt32(idNamePair.Tag) * -1;
						list2.Add(idNamePair);
						openOrders.BodyData = list2.ToArray();
					}
					else
					{
						idNamePair = new IdNamePair();
						idNamePair.Name = Convert.ToString(dataReader["Item"]);
						idNamePair.Tag = Convert.ToInt32(dataReader["Quantity"]);
						idNamePair.Tag = Convert.ToInt32(idNamePair.Tag) * -1;
						list2.Add(idNamePair);
					}
				}
				openOrders.BodyData = list2.ToArray();
				list.Add(openOrders);
				dataReader.Close();
			}
			catch (Exception ex)
			{
				m_sError = ex.Message;
			}
		}
		return list.ToArray();
	}

