actionId\r\n\r\n                                WHERE tCore_Header{0}.iVoucherType = {1}\r\n                                and tCore_HeaderData{1}{0}.iOrderType = 2 and tCore_HeaderData{1}{0}.iStatus <= 2 \r\n                                and mPos_HomeDelivery.iCreatedDate BETWEEN {2} AND {3}\r\n\r\n                                GROUP BY sVoucherNo, mPos_HomeDelivery.iCreatedDate, \r\n                                \r\n                                mPos_HomeDelivery.iMemberId, mPos_HomeDelivery.sAlternativeAddress, vmPos_Member.sAddress1, vmPos_Member.sAddress2, mPos_HomeDelivery.sNonMemName, vmPos_Member.sName\r\n\r\n                                ", suffix, 3331, iFromDate, iToDate);
