	public bool UpdateStatus(int iCompId, string sVoucherNo)
	{
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		Database database = DatabaseWrapper.GetDatabase2(iCompId);
		string suffix = FConvert.GetSuffix(iCompId);
		string empty = string.Empty;
		int num = 0;
		int num2 = 0;
		using (database.CreateConnection())
		{
			try
			{
				empty = $" SELECT iHeaderId FROM tCore_Header{suffix} WHERE iVoucherType = {3331} and sVoucherNo = '{sVoucherNo}' ";
				dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
				num = Convert.ToInt32(database.ExecuteScalar(dbCommand));
				if (num > 0)
				{
					empty = string.Format(" Update tCore_HeaderData{1}{0} SET iStatus = 2 WHERE iHeaderId = {2} ", suffix, 3331, num);
					dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
					database.ExecuteNonQuery(dbCommand);
					empty = $" select iTransactionId from tCore_Data{suffix} where iHeaderId = {num} ";
					dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
					dataReader = database.ExecuteReader(dbCommand);
					while (dataReader.Read())
					{
						num2 = Convert.ToInt32(dataReader["iTransactionId"]);
						if (num2 > 0)
						{
							empty = $" Update mPos_HomeDelivery set bDelivered = 1 WHERE iTransactionId = {num2} ";
							dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
							database.ExecuteNonQuery(dbCommand);
						}
					}
					dataReader.Close();
				}
			}
			catch (Exception ex)
			{
				m_sError = ex.Message;
				return false;
			}
		}
		return true;
	}

	public string SaveNonMemberValue(NonMemberData objNonMember, int iCompId)
	{
		DbCommand dbCommand = null;
		Database database = null;
		string text = null;
		string result = string.Empty;
		database = DatabaseWrapper.GetDatabase2(iCompId);
