		{
			text = $"INSERT INTO mPos_HomeDelivery \r\n                        (iTransactionId, iMemberId, sNonMemName, sAlternativeAddress, iPhone, iDeliveryDate, sRemarks, iDeliveryOutletId)\r\n                        VALUES( {objNonMember.TransactionId}, {objNonMember.MemberId}, '{objNonMember.NonMemberName}', '{objNonMember.NonMemberAddress}', {objNonMember.PhoneNo}, {objNonMember.DeliveryDate}, '{objNonMember.Remarks}', {objNonMember.DeliveryOutletId})";
