	private decimal GetLedgerBalanceForGroupFromDictionary(int[] arrMasterId, int iMasterId, LedgerBalanceType oType, ref Dictionary<int, LedgerBalanceData> arrOpBalData, ref decimal dOpBalLocal, ref decimal dOpBalBase)
