		{
			for (int i = 0; i < arrMasterId.Length; i++)
			{
				num += GetLedgerBalanceFromDictionary(arrMasterId[i], oType, ref arrOpBalData, ref dOpBalLocal2, ref dOpBalBase2);
				dOpBalLocal += dOpBalLocal2;
				dOpBalBase += dOpBalBase2;
				dOpBalBase2 = 0m;
				dOpBalLocal2 = dOpBalBase2;
			}
		}
		if (num == 0m)
		{
			num = GetLedgerBalanceFromDictionary(iMasterId, oType, ref arrOpBalData, ref dOpBalLocal, ref dOpBalBase);
		}
		return num;
	}

	private decimal GetLedgerBalanceFromDictionary(int iMasterId, LedgerBalanceType oType, ref Dictionary<int, LedgerBalanceData> arrOpBalData, ref decimal dOpBalLocal, ref decimal dOpBalBase)
	{
		decimal result = 0m;
		LedgerBalanceData value = null;
		if (arrOpBalData != null)
		{
			arrOpBalData.TryGetValue(iMasterId, out value);
			if (value != null)
			{
				switch (oType)
				{
				case LedgerBalanceType.OpeningBalance:
					if (value.OpeningBalance != null)
					{
						dOpBalBase = value.OpeningBalance[0];
						dOpBalLocal = value.OpeningBalance[1];
						result = value.OpeningBalance[2];
						value.OpeningBalance = null;
					}
					break;
				case LedgerBalanceType.PDCBalance:
					if (value.PDCBalance != null)
					{
						dOpBalBase = value.PDCBalance[0];
						dOpBalLocal = value.PDCBalance[1];
						result = value.PDCBalance[2];
						value.PDCBalance = null;
					}
					break;
				case LedgerBalanceType.UnauthoriseBalance:
					if (value.UnauthorisedBalance != null)
					{
						dOpBalBase = value.UnauthorisedBalance[0];
						dOpBalLocal = value.UnauthorisedBalance[1];
						result = value.UnauthorisedBalance[2];
						value.UnauthorisedBalance = null;
					}
					break;
				case LedgerBalanceType.UnadjustedBalance:
					if (value.UnadjustedBalance != null)
					{
						dOpBalBase = value.UnadjustedBalance[0];
						dOpBalLocal = value.UnadjustedBalance[1];
						result = value.UnadjustedBalance[2];
						value.UnadjustedBalance = null;
					}
					break;
				case LedgerBalanceType.ForeignExchenge:
					if (value.ForexBalance != null)
					{
						dOpBalBase = value.ForexBalance[0];
						dOpBalLocal = value.ForexBalance[1];
						result = value.ForexBalance[2];
						value.ForexBalance = null;
					}
					break;
				}
				arrOpBalData[iMasterId] = value;
			}
		}
		return result;
	}

