o ORDER BY mCore_Account_Props.iParentId asc)  iRowNo, Hier.iMasterId iMasterId ,mCore_Account_Props.iParentId\r\n                                                    from (SELECT T.c.value('./@ID', 'int') as iMasterId, T.c.value('./@P', 'int') as iParentId , T.c.value('./@iR', 'int') as iRowNo\r\n\t\t\t\t\t\t\t\t\t\t\t\t\tFROM @SplitStringListWithIndex.nodes('/R') T(c) \r\n\t\t\t\t\t\t\t\t\t\t\t\t\t) R\r\n                                                    cross apply dbo.fCore_Get" + text2 + "HierarchyForClubbing(isnull(cast(R.iMasterId as int),0),0) Hier \r\n                                                    join #AccountClubBy mCore_Account_Props on Hier.iMasterId=mCore_Account_Props.iMasterId or Hier.iMasterId=mCore_Account_Props.iParentId\r\n                                                    where Hier.iMasterId not in(Select iMasterId from #MasterIdTable )\r\n                                                    declare @iCount int =0\r\n\t\t\t\t\t\t\t\t\t\t\t\t\tSelect @iCount=count(*) from #MasterIdTable\r\n\t\t\t\t\t\t\t\t\t\t\t\t\tif (@iCount=1)\r\n\t\t\t\t\t\t\t\t\t\t\t\t\tbegin\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t    delete from #MasterIdTable\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t    insert into #MasterIdTable\r\n                                                        Select case when isnull(mCore_Account_Props.iParentId,0)<>A.iMasterId then ROW_NUMBER() OVER(ORDER BY mCore_Account_Props.iParentId asc)  else ROW_NUMBER() OVER(ORDER BY A.iMasterId DESC)  end  iRowNo, \r\n                                                        cast(A.iMasterId as int) iMasterId ,isnull(mCore_Account_Props.iParentId,0) iParentId\r\n                                                        from dbo.fCore_Get" + text2 + "Hierarchy(cast('" + General.GetMasters(objRec.Masters) + "' as int),0) A \r\n                                                        left join #AccountClubBy mCore_Account_Props on A.iMasterId=mCore_Account_Props.iMasterId\r\n\r\n\t\t\t\t\t\t\t\t\t\t\t\t\tend\r\n                                                    Update #AccountClubBy set iParentId= iMasterId\r\n                                                     from #AccountClubBy where iParentId not in(\r\n                                                    Select iMasterId from #AccountClubBy\r\n                                                    where iParentId in (Select iMasterId from #MasterIdTable))\r\n                                                    and iMasterId<>iParentId\r\n                                                    \r\n                                                    Update #MasterIdTable set iParentId= #AccountClubBy.iParentId\r\n\t\t\t\t\t\t\t\t\t\t\t\t\tfrom #MasterIdTable \r\n\t\t\t\t\t\t\t\t\t\t\t\t\tinner join #AccountClubBy on #MasterIdTable.iMasterId=#AccountClubBy.iMasterId\r\n                                                    /*\r\n                                                    insert into #AccountClubByData(iRowSeq ,iMasterId , iParentId)\r\n                                                    Select A.iRowSeq, A.iMasterId, B.iParentId \r\n\t\t\t\t\t\t\t\t\t\t\t\t\tfrom #MasterIdTable A \r\n\t\t\t\t\t\t\t\t\t\t\t\t\tinner join  #AccountClubBy B on A.iMasterId= B.iMasterId\r\n                                                    */\r\n                                                    /*\r\n                                                    declare @AccountClubBy as xml\r\n\t\t\t\t\t\t\t\t\t\t\t\t\tset @AccountClubBy= (Select iR,ID, P from(\r\n\t\t\t\t\t\t\t\t\t\t\t\t\tSELECT A.iRowSeq iR, A.iMasterId ID, B.iParentId P from #MasterIdTable A \r\n\t\t\t\t\t\t\t\t\t\t\t\t\tinner join  #AccountClubBy B on A.iMasterId= B.iMasterId) R\r\n\t\t\t\t\t\t\t\t\t\t\t\t\tFOR XML Auto) \r\n                                                    */\r\n                                                    Update #MasterIdTable set iRowSeq= NewiRowSeq\r\n\t\t\t\t\t\t\t\t\t\t\t\t\tfrom #MasterIdTable\r\n\t\t\t\t\t\t\t\t\t\t\t\t\tInner join(\r\n\t\t\t\t\t\t\t\t\t\t\t\