	private bool IsGroupChange(int iMasterId, int iGroupId, object[] arrCellData, List<LedgerAccountProperties> arrAccountProperties, ref int iReportSorting, string sPrevValue, ref LedgerAccountProperties oCurrentProperties, ref int iRefColumn)
	{
		int num = 0;
		string empty = string.Empty;
		if (iMasterId != iGroupId || oCurrentProperties == null)
		{
			oCurrentProperties = null;
			if (arrAccountProperties != null)
			{
				for (num = 0; num < arrAccountProperties.Count; num++)
				{
					if (iMasterId == arrAccountProperties[num].MasterId)
					{
						oCurrentProperties = arrAccountProperties[num];
						break;
					}
				}
			}
		}
		switch (iReportSorting)
		{
		case 0:
			if (oCurrentProperties == null)
			{
				break;
			}
			oCurrentProperties.DisplayCreditTotal = ((oCurrentProperties.DisplayCreditTotal != AccountTotal.Monthly && oCurrentProperties.DisplayCreditTotal != AccountTotal.Daily && oCurrentProperties.DisplayCreditTotal != AccountTotal.Summary) ? oCurrentProperties.DisplayCreditTotal : AccountTotal.None);
			if (oCurrentProperties.IsGenerateLedgerByCurrency && (sPrevValue != Convert.ToString(arrCellData[14]) || iMasterId != iGroupId))
			{
				iRefColumn = 14;
				return true;
			}
			switch (oCurrentProperties.DisplayCreditTotal)
			{
			case AccountTotal.Monthly:
				empty = new Date(m_objCalType)
				{
					Value = Convert.ToInt32(arrCellData[2])
				}.GetMonthName();
				if (sPrevValue != empty || iMasterId != iGroupId)
				{
					iRefColumn = 2;
					return true;
				}
				break;
			case AccountTotal.Daily:
				empty = Convert.ToInt32(arrCellData[2]).ToString();
				if (sPrevValue != empty || iMasterId != iGroupId)
				{
					iRefColumn = 2;
					return true;
				}
				break;
			}
			break;
		case 1:
			if (sPrevValue != Convert.ToString(arrCellData[14]) || iMasterId != iGroupId)
			{
				iRefColumn = 14;
				return true;
			}
			break;
		case 2:
			empty = Convert.ToInt32(arrCellData[2]).ToString();
			if (sPrevValue != empty || iMasterId != iGroupId)
			{
				iRefColumn = 2;
				return true;
			}
			break;
		case 3:
			if (sPrevValue != Convert.ToString(arrCellData[17]) || iMasterId != iGroupId)
			{
				iRefColumn = 17;
				return true;
			}
			break;
		}
		return false;
	}

	private void GetLedgerAccountProperties(RepRecord objRec, ref Dictionary<int, LedgerBalanceData> arrOpBalance)
	{
		string text = null;
		IDataReader dataReader = null;
		DbCommand dbCommand = null;
		LedgerBalanceData ledgerBalanceData = null;
		try
		{
			text = "SELECT iMasterId, iDisplayCreditTotal, bDisplayUnRealizeGainLossInLedger, bGenerateLedgerByCurrency \r\n                FROM mCore_Account_Props WHERE (iDisplayCreditTotal <> 0 OR bDisplayUnRealizeGainLossInLedger = 1 OR bGenerateLedgerByCurrency = 1)";
			text = ((!SINGLE_MASTER || objRec.Masters == null || objRec.Masters.Length != 1) ? (text + " AND iMasterId > 0") : (text + $" AND iMasterId = {objRec.Masters[0].ID}"));
			dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dbCommand.CommandTimeout = 0;
			dataReader = m_objDatabase.ExecuteReader(dbCommand);
			while (dataReader.Read())
			{
				ledgerBalanceData = null;
				arrOpBalance.TryGetValue(Convert.ToInt32(dataReader["iMasterId"]), out ledgerBalanceData);
				if (ledgerBalanceData != null)
				{
					ledgerBalanceData.DisplayCreditTotal = (AccountTotal)Convert.ToInt32(dataReader["iDisplayCreditTotal"]);
					ledgerBalanceData.IsDisplayUnRealizeGainLossInLedger = Convert.ToBoolean(dataReader["bDisplayUnRealizeGainLossInLedger"]);
					ledgerBalanceData.IsGenerateLedgerByCurrency = Convert.ToBoolean(dataReader["bGenerateLedgerByCurrency"]);
					arrOpBalance[Convert.ToInt32(dataReader["iMasterId"])] = ledgerBalanceData;
				}
				else
				{
					ledgerBalanceData = new LedgerBalanceData();
					ledgerBalanceData.DisplayCreditTotal = (AccountTotal)Convert.ToInt32(dataReader["iDisplayCreditTotal"]);
					ledgerBalanceData.IsDisplayUnRealizeGainLossInLedger = Convert.ToBoolean(dataReader["bDisplayUnRealizeGainLossInLedger"]);
					ledgerBalanceData.IsGenerateLedgerByCurrency = Convert.ToBoolean(dataReader["bGenerateLedgerByCurrency"]);
					arrOpBalance.Add(Convert.ToInt32(dataReader["iMasterId"]), ledgerBalanceData);
				}
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			m_sError = $"GetLedgerAccountProperties: {ex.Message}";
		}
	}

	private void GetLedgerAccountType(RepRecord objRec, ref Dictionary<int, LedgerBalanceData> arrOpBalance)
	{
		string text = null;
		IDataReader dataReader = null;
		DbCommand dbCommand = null;
		LedgerBalanceData ledgerBalanceData = null;
		try
		{
			text = "SELECT iMasterId,iAccountType FROM mCore_Account WHERE iStatus <> 5";
			if (SINGLE_MASTER && objRec.Masters != null && objRec.Masters.Length == 1)
			{
				text += $" WHERE iMasterId = {objRec.Masters[0].ID}";
			}
			dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dbCommand.CommandTimeout = 0;
			dataReader = m_objDatabase.ExecuteReader(dbCommand);
			while (dataReader.Read())
			{
				ledgerBalanceData = null;
				arrOpBalance.TryGetValue(Convert.ToInt32(dataReader["iMasterId"]), out ledgerBalanceData);
				if (ledgerBalanceData != null)
				{
					ledgerBalanceData.AccountType = (AccountTypes)Convert.ToInt32(dataReader["iAccountType"]);
					arrOpBalance[Convert.ToInt32(dataReader["iMasterId"])] = ledgerBalanceData;
				}
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			m_sError = $"GetLedgerAccountType : {ex.Message}";
		}
	}

	private List<LedgerAccountProperties> GetLedgerAccountPropertiesFromDictionary(ComboData[] arrMasters, int iCode, Dictionary<int, LedgerBalanceData> arrOpBalData)
	{
		LedgerBalanceData value = null;
		List<LedgerAccountProperties> list = new List<LedgerAccountProperties>();
		if (arrOpBalData != null)
		{
			int num = ((iCode > 0) ? iCode : ((arrMasters != null && arrMasters.Length != 0) ? arrMasters[0].ID : 0));
			arrOpBalData.TryGetValue(num, out value);
			if (value != null)
			{
				list.Add(new LedgerAccountProperties
				{
					DisplayCreditTotal = value.DisplayCreditTotal,
					IsDisplayUnRealizeGainLossInLedger = value.IsDisplayUnRealizeGainLossInLedger,
					IsGenerateLedgerByCurrency = value.IsGenerateLedgerByCurrency,
					MasterId = num
				});
			}
		}
		return list;
	}

	private LineData GetSortingLineData(string sGroupValue, int iLength, int iGroupColumn, int iGroupId, int iTextCol, object[] arrReportTotal = null)
	{
		LineData lineData = new LineData();
		if (arrReportTotal != null)
		{
			lineData.CellData = arrReportTotal;
			lineData.CellData[0] = new ReportRowHeader();
			(lineData.CellData[0] as ReportRowHeader).RowType = ReportRowType.Total;
		}
		else
		{
			lineData.CellData = new object[iLength];
			lineData.CellData[0] = new ReportRowHeader();
			(lineData.CellData[0] as ReportRowHeader).RowType = ReportRowType.HighLight;
		}
		lineData.CellData[iGroupColumn] = iGroupId;
		lineData.CellData[iTextCol] = sGroupValue;
		return lineData;
	}

	private LineData[] ArrangeBRSBalance(RepRecord objRec, LineData[] arrLineData, bool bEndOfFile, int iCompId, int iFieldCount)
	{
		int num = 0;
		int num2 = 6;
		int num3 = 10;
		int num4 = 14;
		int firstTextColumn = GetFirstTextColumn(objRec.Columns, 3);
		decimal dPDCValue = 0m;
		decimal dPDCVal = 0m;
		decimal dPDCVal2 = 0m;
		decimal num5 = 0m;
		decimal num6 = 0m;
		decimal num7 = 0m;
		decimal num8 = 0m;
		decimal num9 = 0m;
		decimal num10 = 0m;
		LineData lineData = null;
		List<LineData> list = null;
		if (objRec.Outputs == null)
		{
			objRec.Outputs = new IdValuePair[6];
			objRec.Outputs[0] = new IdValuePair(0, 0);
			objRec.Outputs[1] = new IdValuePair(1, 0);
			objRec.Outputs[2] = new IdValuePair(2, 0);
			objRec.Outputs[3] = new IdValuePair(3, 0);
			objRec.Outputs[4] = new IdValuePair(4, 0);
			objRec.Outputs[5] = new IdValuePair(5, 0);
		}
		num6 = Convert.ToDecimal(objRec.Outputs[0].Value);
		num8 = Convert.ToDecimal(objRec.Outputs[1].Value);
		num10 = Convert.ToDecimal(objRec.Outputs[2].Value);
		num5 = Convert.ToDecimal(objRec.Outputs[3].Value);
		num7 = Convert.ToDecimal(objRec.Outputs[4].Value);
		num9 = Convert.ToDecimal(objRec.Outputs[5].Value);
		list = new List<LineData>();
		if (num == 0 && objRec.CurrentPage == 0 && objRec.Code > 0)
		{
			num5 = GetBalanceAsPerBook(objRec, bBrs: false, ref num7, ref num9);
			if (num5 != 0m || num7 != 0m || num9 != 0m)
			{
				list.Add(GetBRSOpeningBalanceRow(iFieldCount, firstTextColumn, "Balance as per Books", num5, num7, num9));
			}
		}
		if (objRec.CurrentPage == 0)
		{
			num6 += num5;
			num10 += num9;
			num8 += num7;
		}
		for (num = 0; num < arrLineData.Length; num++)
		{
			num6 -= Convert.ToDecimal(arrLineData[num].CellData[num3 - 2]) + Convert.ToDecimal(arrLineData[num].CellData[num3 - 1]);
			arrLineData[num].CellData[num3] = num6;
			arrLineData[num].CellData[num3 + 1] = num5 - num6;
			num8 -= Convert.ToDecimal(arrLineData[num].CellData[num2 - 2]) + Convert.ToDecimal(arrLineData[num].CellData[num2 - 1]);
			arrLineData[num].CellData[num2] = num8;
			arrLineData[num].CellData[num2 + 1] = num7 - num8;
			num10 -= Convert.ToDecimal(arrLineData[num].CellData[num4 - 2]) + Convert.ToDecimal(arrLineData[num].CellData[num4 - 1]);
			arrLineData[num].CellData[num4] = num10;
			arrLineData[num].CellData[num4 + 1] = num9 - num10;
			list.Add(arrLineData[num]);
		}
		if (bEndOfFile)
		{
			if (FConvert.GetInputValue(objRec.Inputs, 1) == 2 || FConvert.GetInputValue(objRec.Inputs, 1) == 3)
			{
				GetSummaryPDC(objRec.Code, objRec, ref dPDCValue, ref dPDCVal, ref dPDCVal2, iCompId, ref m_objDatabase, _focus.company(m_iCompanyId).faTagId);
				if (dPDCValue != 0m || dPDCVal != 0m || dPDCVal2 != 0m)
				{
					lineData = GetSpecialLine(arrLineData[0].CellData.Length, 3, "Unmatured PDC", 4, dPDCVal, ReportRowType.UnmaturedPDC);
					lineData.CellData[5] = ((dPDCValue > 0m) ? dPDCValue : 0m);
					list.Add(lineData);
				}
			}
			list.Add(GetBRSOpeningBalanceRow(iFieldCount, firstTextColumn, "Balance as per Bank", num6, num8, num10));
		}
		objRec.Outputs[0].Value = num6;
