	private DualIdPair[] GetAccountDayWiseBalance(RepRecord objRec, bool bAccountFilter, int iCompId)
	{
		string suffix = FConvert.GetSuffix(iCompId);
		string text = null;
		string text2 = string.Empty;
		_ = string.Empty;
		IDataReader dataReader = null;
		DualIdPair dualIdPair = null;
		List<DualIdPair> list = null;
		if (m_objDatabase == null)
		{
			m_objDatabase = DatabaseWrapper.GetDatabase2(iCompId);
		}
		if (objRec.FilterSource != null && objRec.FilterSource.Length != 0)
		{
			string financeFilter = _focus.company(m_iCompanyId).getFinanceFilter(objRec.FilterSource);
			if (!string.IsNullOrEmpty(financeFilter))
			{
				text2 = $" AND iFaTag IN({financeFilter})";
			}
		}
		text = string.Format("SELECT iMasterId, iDate,SUM(Debit+Credit)[Balance]\r\n            FROM\r\n            (\r\n\t            SELECT iDate,iBookNo[iMasterId],\r\n\t            CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t            CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit\r\n\t            FROM tCore_Header{0}\r\n\t            JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n\t            WHERE {3} <= {2} AND tCore_Data{0}.bUpdateFA = 1 \r\n                AND tCore_Data{0}.bSuspendUpdateFA <> 1 AND tCore_Header{0}.bSuspended = 0 {4}\r\n\t            UNION ALL\r\n\t            SELECT iDate,iCode[iMasterId],\r\n\t            CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n\t            CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit\r\n\t            FROM tCore_Header{0} \r\n\t            JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n\t            WHERE {3} <= {2} AND tCore_Data{0}.bUpdateFA = 1 \r\n                AND tCore_Data{0}.bSuspendUpdateFA <> 1 AND tCore_Header{0}.bSuspended = 0 {4}\r\n            )Temp {1}\r\n            GROUP BY iMasterId, iDate \r\n            HAVING SUM(Debit+Credit) <> 0\r\n            ORDER BY iMasterId, iDate", suffix, (bAccountFilter && objRec.Code > 0) ? $"WHERE iMasterId = {objRec.Code}" : string.Empty, objRec.EndingDate, (objRec.SubReportId == 1) ? $"tCore_Header{suffix}.iDate" : $"tCore_Data{suffix}.iDueDate", text2);
		dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		list = new List<DualIdPair>();
		while (dataReader.Read())
		{
			dualIdPair = new DualIdPair();
			dualIdPair.Id = Convert.ToInt32(dataReader["iMasterId"]);
			dualIdPair.SubId = Convert.ToInt32(dataReader["iDate"]);
			dualIdPair.Value = Convert.ToDecimal(dataReader["Balance"]);
			list.Add(dualIdPair);
		}
		dataReader.Close();
		return list.ToArray();
	}

	private decimal GetAccountInterestRate(int iMasterId, int iCompId)
	{
		string text = null;
		if (m_objDatabase == null)
