	private LineData[] ArrangeAdvanceCashFlow(LineData[] arrLineData, ref RepRecord objRec, bool bEndOfReport, string sUniqueId, int iCompId)
	{
		decimal dDr = 0m;
		decimal dCr = 0m;
		decimal num = 0m;
		decimal num2 = 0m;
		LineData lineData = null;
		List<LineData> list = null;
		Dictionary<int, AccountingData> dictionary = null;
		list = new List<LineData>();
		list.AddRange(arrLineData);
		if (_focus.company(iCompId).getBuffer(sUniqueId) != null)
		{
			dictionary = (Dictionary<int, AccountingData>)_focus.company(iCompId).getBuffer(sUniqueId);
		}
		else
		{
			dictionary = GetDebitCreditBalance(objRec, m_objDatabase);
			_focus.company(iCompId).setBuffer(sUniqueId, dictionary);
		}
		if (objRec.IsStartOfReport)
		{
			num2 = GetProfitAndLoss(objRec, m_objDatabase, iCompId);
			lineData = GetSpecialLine(5, 1, "Net Income", 2, num2, ReportRowType.Normal);
			list.Insert(0, lineData);
		}
		if (objRec.Outputs != null && objRec.Outputs.Length != 0)
		{
			num = Convert.ToDecimal(objRec.Outputs[0].Value);
		}
		for (int i = 0; i < list.Count; i++)
		{
			if ((list[i].CellData[0] as ReportRowHeader).Id > 0)
			{
				GetDebitCreditForGroup((list[i].CellData[0] as ReportRowHeader).Id, m_objDatabase, dictionary, ref dDr, ref dCr);
				num = dDr + dCr;
				num *= (decimal)((!(num < 0m)) ? 1 : (-1));
				if (Convert.ToBoolean(list[i].CellData[3]))
				{
					num *= -1m;
				}
				num2 += num;
				list[i].CellData[2] = num;
			}
		}
		if (bEndOfReport)
		{
			decimal dOpBalLocal = 0m;
			decimal dOpBalBase = 0m;
			GetCashAndBankOpeningBalance(objRec, objRec.StartingDate, iCompId, ref dOpBalLocal, ref dOpBalBase);
			num = dOpBalBase;
			lineData = GetSpecialLine(5, 1, "Begining Cash Balance", 2, num, ReportRowType.Total);
			list.Add(lineData);
			lineData = GetSpecialLine(5, 1, "Total Change in Cash", 2, num2, ReportRowType.Total);
			list.Add(lineData);
			num2 += num;
			lineData = GetSpecialLine(5, 1, "Ending Cash Balance", 2, num2, ReportRowType.Total);
			list.Add(lineData);
			_focus.company(iCompId).clearBuffer(sUniqueId);
		}
		else
		{
			if (objRec.Outputs == null)
			{
				objRec.Outputs = new IdValuePair[1];
			}
			objRec.Outputs[0] = new IdValuePair(1, num);
		}
		arrLineData = list.ToArray();
		return arrLineData;
	}

