	private string GetAuditFolderPath()
	{
		string text = null;
		Database database = DatabaseWrapper.GetDatabase2(-2);
		text = Convert.ToString(database.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre("SELECT sAuditPath from cCore_Instances") : "SELECT sAuditPath from cCore_Instances"));
		if (string.IsNullOrEmpty(text))
		{
			text = "D:\\AuditLogs\\";
			database.ExecuteNonQuery(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre("UPDATE cCore_Instances SET sAuditPath = '" + text + "'") : ("UPDATE cCore_Instances SET sAuditPath = '" + text + "'"));
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text);
			}
		}
		return text;
	}

