	private LineData GetLoginLogoutRow(int iLength, int iId, string sText, int iDate, int iTime, string[] arrData, bool bLogout, bool bFailed = false)
	{
		FontClass defaultFont = FConvert.GetDefaultFont();
		defaultFont.FontWeight = 1;
		defaultFont.Foreground = (bFailed ? (-65536) : (-16777216));
		LineData lineData = new LineData();
		ReportRowHeader reportRowHeader = new ReportRowHeader();
		reportRowHeader.RowType = ReportRowType.Formatting;
		reportRowHeader.Id = iId;
		reportRowHeader.Font = defaultFont;
		lineData.CellData = new object[iLength];
		lineData.CellData[0] = reportRowHeader;
		lineData.CellData[1] = string.Format("{0}{1}", bFailed ? "Failed " : string.Empty, sText);
		if (m_dClientOffet != 0.0)
		{
			FConvert.TranslateTimeZone(ref iDate, ref iTime, m_dClientOffet, m_objCalType);
		}
		if (!bLogout)
		{
			lineData.CellData[2] = iDate;
			lineData.CellData[3] = iTime;
		}
		else
		{
			lineData.CellData[4] = iDate;
			lineData.CellData[5] = iTime;
		}
		lineData.CellData[10] = arrData[0];
		lineData.CellData[11] = arrData[1];
		lineData.CellData[12] = arrData[2];
		lineData.CellData[13] = arrData[3];
		return lineData;
	}

	private void ArrangeAuditReport(ref ReportMatrix objData, RepRecord objRec, int iFieldCount, int iCompId)
	{
		iFieldCount = ((iFieldCount > 8) ? iFieldCount : 8);
		LineData lineData = null;
		string auditFolderPath = GetAuditFolderPath();
		string text = null;
		auditFolderPath = FConvert.GetCompAuditFolder(auditFolderPath, iCompId);
		RDConversion rDConversion = new RDConversion(m_objCalType);
		rDConversion.DateFormat = objRec.DateFormat;
		BackupLogDB backupLogDB = new BackupLogDB(auditFolderPath);
		List<LineData> list = new List<LineData>();
		List<IdNamePair> list2 = new List<IdNamePair>();
		try
		{
			BackupLogStruct[] arrAuditLog = backupLogDB.LoadData(objRec.StartingDate, objRec.EndingDate, iCompId);
			if (arrAuditLog != null && arrAuditLog.Length != 0)
			{
				int iIndex;
				for (iIndex = 0; iIndex < arrAuditLog.Length; iIndex++)
				{
					lineData = new LineData();
					lineData.CellData = new object[iFieldCount];
					lineData.CellData[0] = new ReportRowHeader();
					lineData.CellData[1] = (arrAuditLog[iIndex].bIsManual ? "Manual" : "Scheduler");
					if (arrAuditLog[iIndex].iUserId > 1)
					{
						if (list2.Where((IdNamePair p) => p.ID == arrAuditLog[iIndex].iUserId).Count() > 0)
						{
							text = (from p in list2
								where p.ID == arrAuditLog[iIndex].iUserId
								select p.Name).FirstOrDefault();
						}
						else
						{
							text = _focus.company(m_iCompanyId).getUserName(arrAuditLog[iIndex].iUserId);
							list2.Add(new IdNamePair(arrAuditLog[iIndex].iUserId, text));
						}
					}
					ref object reference = ref lineData.CellData[2];
					string text2;
					if (arrAuditLog[iIndex].iUserId <= 0)
					{
						text2 = "N/A";
					}
					else
					{
						text2 = ((arrAuditLog[iIndex].iUserId == 1) ? "SU" : text);
					}
					reference = text2;
					lineData.CellData[3] = $"{rDConversion.SetDateFormat(StandardDataFormat.Default, arrAuditLog[iIndex].iBackupDate, null)} {FConvert.IntToStringTime(arrAuditLog[iIndex].iBackupTime)}";
					if (arrAuditLog[iIndex].iTimeTakenInSecs > 3600)
					{
						lineData.CellData[4] = string.Format("{0} Hours {0} Minutes {1} Seconds", arrAuditLog[iIndex].iTimeTakenInSecs / 3600, arrAuditLog[iIndex].iTimeTakenInSecs % 3600, arrAuditLog[iIndex].iTimeTakenInSecs % 60);
					}
					else if (arrAuditLog[iIndex].iTimeTakenInSecs > 60)
					{
						lineData.CellData[4] = $"{arrAuditLog[iIndex].iTimeTakenInSecs / 60} Minutes {arrAuditLog[iIndex].iTimeTakenInSecs % 60} Seconds";
					}
					else
					{
						lineData.CellData[4] = $"{arrAuditLog[iIndex].iTimeTakenInSecs} Seconds";
					}
					lineData.CellData[5] = (arrAuditLog[iIndex].bSuccess ? "Successful" : "Failed");
					lineData.CellData[6] = arrAuditLog[iIndex].strFailedReason;
					lineData.CellData[7] = arrAuditLog[iIndex].strOutput;
					list.Add(lineData);
				}
			}
			else
			{
				objData.Error = true;
				objData.Message = $"Backup log file does not exists : {auditFolderPath}";
			}
		}
		catch (Exception ex)
		{
			m_sError = $"ArrangeAuditReport : {ex.Message}";
			objData.Error = true;
			objData.Message = ex.Message;
		}
		objData.EndOfFile = true;
		objData.ColumnData = list.ToArray();
	}

