	private LineData[] ArrangeDayBook(RepRecord objRec, LineData[] arrLineData, int iCompId)
	{
		int index = 0;
		decimal num = 0m;
		decimal num2 = 0m;
		decimal num3 = 0m;
		decimal num4 = 0m;
		decimal num5 = 0m;
		List<LineData> list = null;
		list = new List<LineData>();
		list.AddRange(arrLineData);
		if (objRec.IsStartOfReport)
		{
			foreach (KeyValuePair<int, LedgerBalanceData> item in GetLedgerOpeningBalance(objRec, bLoadAccountProperty: false, bLoadAccountType: true))
			{
				if (item.Key != 2)
				{
					num5 += item.Value.OpeningBalance[0];
					num3 += item.Value.OpeningBalance[1];
					num4 += item.Value.OpeningBalance[2];
					switch (item.Value.AccountType)
					{
					case AccountTypes.Cash:
						num += item.Value.OpeningBalance[0];
