	private int[] GetAccountInGroupBasedOnType(int iAccountGroup, int iAccountType)
	{
		IDataReader dataReader = null;
		string text = null;
		List<int> list = new List<int>();
		text = $"WITH RecursionCTE (iMasterId, iParentId, bGroup)  AS  \r\n                            (   SELECT iMasterId, iParentId, bGroup\r\n                                FROM vmCore_Account \r\n                                WHERE iMasterId = {iAccountGroup} AND iTreeId = 0 AND iAccountType = {iAccountType}\r\n                                UNION ALL  \r\n                                SELECT R1.iMasterId, R1.iParentId, R1.bGroup\r\n                                FROM vmCore_Account AS R1 \r\n                                JOIN RecursionCTE AS R2 ON R1.iParentId = R2.iMasterId\r\n                            )SELECT iMasterId  FROM RecursionCTE WHERE bGroup = 0 ";
		dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		while (dataReader.Read())
		{
			list.Add(Convert.ToInt32(dataReader["iMasterId"]));
		}
		dataReader.Close();
		if (list.Count == 0)
		{
			list.Add(iAccountGroup);
		}
		return list.ToArray();
	}

