			text2 = text6 + "\r\n                    SELECT TempTable.[iMasterId], SUM(Debit)+SUM(Credit)[Base], SUM(TranDr)+SUM(TranCr)[FX], SUM(LocalDr)+SUM(LocalCr)[Local] \r\n                    FROM\r\n                    --@XML.nodes('/Master/r') T(c) \r\n                    --JOIN\r\n                    (\r\n\t                    SELECT iBookNo[iMasterId],\r\n\t                    CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t                    CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit,\r\n\t                    CASE WHEN ISNULL(mFxAmount2,mAmount2) < 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranDr, \r\n\t                    CASE WHEN ISNULL(mFxAmount2,mAmount2) > 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranCr,\r\n\t                    CASE WHEN ISNULL(fLocalAmount2,0) < 0 THEN ISNULL(fLocalAmount2,0) ELSE 0 END LocalDr, \r\n\t                    CASE WHEN ISNULL(fLocalAmount2,0) > 0 THEN ISNULL(fLocalAmount2,0) ELSE 0 END LocalCr\r\n\t                    FROM tCore_Header" + m_strSuffix + " \r\n\t                    JOIN tCore_Data" + m_strSuffix + " ON tCore_Data" + m_strSuffix + ".iHeaderId = tCore_Header" + m_strSuffix + ".iHeaderId " + text7 + "\r\n\t                    LEFT JOIN tCore_Data_FX" + m_strSuffix + " ON tCore_Data_FX" + m_strSuffix + ".iBodyId = tCore_Data" + m_strSuffix + ".iBodyId \r\n                        " + sTagJoinTable + "\r\n                        WHERE tCore_Data" + m_strSuffix + ".bUpdateFA = 1 AND tCore_Data" + m_strSuffix + ".bSuspendUpdateFA = 0 AND tCore_Header" + m_strSuffix + ".bSuspended = 0 \r\n                        AND tCore_Data" + m_strSuffix + ".iAuthStatus < 2 AND " + text3 + "\r\n\t                    UNION ALL\r\n\t                    SELECT iCode[iMasterId],\r\n\t                    CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n\t                    CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit,\r\n\t                    CASE WHEN ISNULL(mFXAmount1,mAmount1) < 0