						value.OpeningBalance[2] += Convert.ToDecimal(dataReader["FX"]);
						dictionary[Convert.ToInt32(dataReader["iMasterId"])] = value;
					}
				}
				if (value == null)
				{
					value = new LedgerBalanceData();
					value.OpeningBalance = new decimal[3];
					value.OpeningBalance[0] = Convert.ToDecimal(dataReader["Base"]);
					value.OpeningBalance[1] = Convert.ToDecimal(dataReader["Local"]);
					value.OpeningBalance[2] = Convert.ToDecimal(dataReader["FX"]);
					dictionary.Add(Convert.ToInt32(dataReader["iMasterId"]), value);
					value = null;
				}
			}
			dataReader.Close();
			if (FConvert.GetInputValue(objRec.Inputs, 1) == 2 || FConvert.GetInputValue(objRec.Inputs, 1) == 3)
			{
				GetLedgerPDCBalance(objRec, ref dictionary);
			}
			if (FConvert.GetInputValue(objRec.Inputs, 10) == 2 || FConvert.GetInputValue(objRec.Inputs, 10) == 3)
			{
				GetLedgerUnauthoriseBalance(objRec, ref dictionary);
			}
			if (bLoadAccountProperty)
			{
				GetLedgerAccountProperties(objRec, ref dictionary);
			}
			if (bLoadAccountType)
			{
				GetLedgerAccountType(objRec, ref dictionary);
			}
		}
		catch (Exception ex)
		{
			m_sError = $"GetLedgerOpeningBalance : {ex.Message}";
		}
		if (SELECTED_MASTERS != null && SELECTED_MASTERS.Length != 0)
		{
			Dictionary<int, LedgerBalanceData> dictionary2 = new Dictionary<int, LedgerBalanceData>();
			num = 0;
			while (num < SELECTED_MASTERS.Length)
			{
				dictionary.TryGetValue(SELECTED_MASTERS[num].ID, out value);
				if (value != null)
				{
					dictionary2.Add(SELECTED_MASTERS[num].ID, value);
				}
				num++;
				value = null;
			}
			dictionary = dictionary2;
		}
		return dictionary;
	}

	private string GetVoucherTagFilter(int iUserId, ref bool bTagJoin)
	{
		bool flag = false;
		string text = string.Empty;
		string text2 = null;
		List<MasterRights> list = null;
		List<FieldData> arrMasterField = null;
		if (_focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Print, 36) == 0)
		{
			if (_focus.company(m_iCompanyId).user(iUserId).RoleMasters == null)
			{
				list = new COptionbase().CheckRoleMasters(iUserId, "2,3,6,7", ref arrMasterField, m_objDatabase, m_iCompanyId);
				_focus.company(m_iCompanyId).user(iUserId).RoleMasters = new UserRoleField(list, arrMasterField);
			}
			list = _focus.company(m_iCompanyId).user(iUserId).RoleMasters.masterRestrictions;
			if (list != null && list.Count > 0)
			{
				for (int i = 0; i < list.Count; i++)
				{
					text2 = list[i].Tag;
					flag = list[i].Exclude;
					if (!string.IsNullOrEmpty(text2) && list[i].ID > 2)
					{
						if ((from p in text2.Split(',')
							where p == "0"
							select p).Count() == 0)
						{
							text2 += ",0";
						}
						if (list[i].ID == _focus.company(m_iCompanyId).faTagId)
						{
							text += string.Format(" AND iFaTag {0}IN ({1})", flag ? "NOT " : string.Empty, text2);
							continue;
						}
						if (list[i].ID == _focus.company(m_iCompanyId).invTagId)
						{
							text += string.Format(" AND iInvTag {0}IN ({1})", flag ? "NOT " : string.Empty, text2);
							continue;
						}
						text = ((!flag) ? (text + $" AND ISNULL(tCore_Data_Tags{m_strSuffix}.iTag{list[i].ID},0) IN ({text2})") : (text + string.Format(" AND (ISNULL(tCore_Data_Tags{0}.iTag{1},0) {2}IN ({3}) OR tCore_Data_Tags{0}.iTag{1} IS NULL)", m_strSuffix, list[i].ID, flag ? "NOT " : string.Empty, text2)));
						bTagJoin = true;
					}
				}
			}
		}
		return text;
	}

