	private void GetFutureAndForexAdjustments(int iCompId, bool IsCompanyClosedFlag, RepRecord objRec, ref Dictionary<int, LedgerBalanceData> arrOpBalData, string strMasterName, ref Database objDB, string strMasterXML)
