			string text = "";
			text = string.Format(" {3} \r\n                                        Select isnull(mCore_Account_Props.iParentId,mCore_Account_Props.iMasterId) iMasterId, sum(case when mBaseAmount<0 then\r\n\t\t\t\t                        (abs(mBaseAmount)+isnull(mExchangeDiff,0)) * sign(mBaseAmount) \r\n\t\t\t\t                        else (abs(mBaseAmount)-isnull(mExchangeDiff,0)) * sign(mBaseAmount)  end) mBaseAmount, sum(mAmount) mAmount, \r\n\t\t\t\t\t\t\t\t\t\tsum(case when mLocalAmount<0 then\r\n\t\t\t\t                        (abs(mLocalAmount)+isnull(mLocalExchangeDiff,0)) * sign(mLocalAmount) \r\n\t\t\t\t                        else (abs(mLocalAmount)-isnull(mLocalExchangeDiff,0)) * sign(mLocalAmount)  end ) mLocalAmount \r\n                                        from tCore_Refrn_{0} a WITH (READUNCOMMITTED)\r\n                                        inner join tCore_Data_{0} b on a.iBodyId= b.iBodyId\r\n\t\t\t\t\t\t\t\t\t\tinner join tCore_Header_{0} c on b.iHeaderId= c.iHeaderId\r\n\t\t\t\t\t\t\t\t\t\tjoin #MasterIdTable mCore_Account_Props on isnull(a.iCode,0)=mCore_Account_Props.iMasterId\r\n                                        join #MasterIdTable MasterIdTable on  mCore_Account_Props.iMasterId=MasterIdTable.iMasterId                \r\n                    \t\t\t\t\tinner join \r\n\t\t\t\t\t (Select iRef from tCore_Refrn_{0} a WITH (READUNCOMMITTED)\r\n                                        inner join tCore_Data_{0} b on a.iBodyId= b.iBodyId\r\n\t\t\t\t\t\t\t\t\t\tinner join tCore_Header_{0} c on b.iHeaderId= c.iHeaderId\r\n\t\t\t\t\t\t\t\t\t\t where c.iDate>{1} and iRefType=0 and b.bUpdateFA = 1 AND b.bSuspendUpdateFA <> 1 \r\n                        AND c.bSuspended = 0) FutureFef on a.iRef=FutureFef.iRef\r\n\t\t\t\t\t where c.iDate<={1} and iRefType=2 and b.bUpdateFA = 1 AND b.bSuspendUpdateFA <> 1 \r\n                        AND c.bSuspended = 0\r\n                     group by isnull(mCore_Account_Props.iParentId,mCore_Account_Props.iMasterId) ", yearId, objRec.EndingDate, strMasterName, strMasterXML);
			text = string.Format("  {3}\r\n                                        Select  isnull(mCore_Account_Props.iParentId,mCore_Account_Props.iMasterId) iMasterId, sum(mAmount1) mBaseAmount, 0 mAmount, 0 mLocalAmount \r\n                                        from tCore_Data_{0} b \r\n\t\t\t\t\t\t\t\t\t\tinner join tCore_Header_{0} c on b.iHeaderId= c.iHeaderId\r\n\t\t\t\t\t\t\t\t\t\tjoin #MasterIdTable mCore_Account_Props on isnull(b.iCode,0)=mCore_Account_Props.iMasterId\r\n\t\t\t\t\t\t\t\t\t\tjoin #MasterIdTable MasterIdTable on  mCore_Account_Props.iMasterId=MasterIdTable.iMasterId                \r\n                    \t\t\t\t\tjoin mCore_{2} mCore_Account on isnull(b.iCode,0)= mCore_Account.iMasterId and iAccountType in(5,6,7)\r\n                                        \r\n                     where c.iDate<={1} and bForexFlux =1 and b.bSuspendUpdateFA <> 1 AND c.bSuspended = 0 AND b.iAuthStatus < 2 \r\n                     group by  isnull(mCore_Account_Props.iParentId,mCore_Account_Props.iMasterId)   \r\n                    having sum(mAmount1)<>0", yearId, objRec.EndingDate, strMasterName, text);
