					arrOpBalData[Convert.ToInt32(dataReader["iMasterId"])] = ledgerBalanceData;
				}
				else
				{
					ledgerBalanceData = new LedgerBalanceData();
					ledgerBalanceData.ForexBalance = new decimal[3];
