		{
			text3 = $" AND iMasterId = {objRec.Masters[0].ID}";
		}
		if (objRec.FilterSource != null && objRec.FilterSource.Length != 0)
		{
			text2 = _focus.company(m_iCompanyId).getFinanceFilter(objRec.FilterSource);
			if (!string.IsNullOrEmpty(text2))
			{
				text3 += $" AND iFaTag IN({text2})";
			}
		}
		if (objRec.UserId > 1 && _focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Print, 36) == 0)
		{
			bool bExclude = false;
