nCr,\r\n\t                CASE WHEN ISNULL(fLocalAmount1,0) < 0 THEN ISNULL(fLocalAmount1,0) ELSE 0 END LocalDr, \r\n\t                CASE WHEN ISNULL(fLocalAmount1,0) > 0 THEN ISNULL(fLocalAmount1,0) ELSE 0 END LocalCr\r\n\t                FROM tCore_Data" + m_strSuffix + " \r\n\t                JOIN tCore_Header" + m_strSuffix + " ON tCore_Data" + m_strSuffix + ".iHeaderId = tCore_Header" + m_strSuffix + ".iHeaderId\r\n\t                LEFT JOIN tCore_Data_FX" + m_strSuffix + " ON tCore_Data_FX" + m_strSuffix + ".iBodyId = tCore_Data" + m_strSuffix + ".iBodyId\r\n                    " + sTagJoinTable + "\r\n                    WHERE tCore_Data" + m_strSuffix + ".bUpdateFA = 1 AND tCore_Data" + m_strSuffix + ".bSuspendUpdateFA <> 1 AND tCore_Header" + m_strSuffix + ".bSuspended = 0 \r\n                    AND tCore_Data" + m_strSuffix + ".iAuthStatus < 2 AND " + text3 + "\r\n                )TempTable \r\n                JOIN mCore_Currency ON mCore_Currency.iCurrencyId=TempTable.iCurrencyId\r\n                " + text4 + " GROUP BY [iMasterId], mCore_Currency.sName";
