			text2 = "SELECT TempTable.[iMasterId], vrCore_SubLedger.sName[Subledger], SUM(Debit)+SUM(Credit)[Base], SUM(TranDr)+SUM(TranCr)[FX], SUM(LocalDr)+SUM(LocalCr)[Local] \r\n                FROM\r\n                (\r\n\t                SELECT iBookNo[iMasterId],iTag50,\r\n\t                CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t                CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit,\r\n\t                CASE WHEN ISNULL(mFxAmount2,mAmount2) < 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranDr, \r\n\t                CASE WHEN ISNULL(mFxAmount2,mAmount2) > 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranCr,\r\n\t                CASE WHEN ISNULL(fLocalAmount2,0) < 0 THEN ISNULL(fLocalAmount2,0) ELSE 0 END LocalDr, \r\n\t                CASE WHEN ISNULL(fLocalAmount2,0) > 0 THEN ISNULL(fLocalAmount2,0) ELSE 0 END LocalCr\r\n\t                FROM tCore_Data" + m_strSuffix + " \r\n\t                JOIN tCore_Header" + m_strSuffix + " ON tCore_Data" + m_strSuffix + ".iHeaderId = tCore_Header" + m_strSuffix + ".iHeaderId\r\n\t                LEFT JOIN tCore_Data_FX" + m_strSuffix + " ON tCore_Data_FX" + m_strSuffix + ".iBodyId = tCore_Data" + m_strSuffix + ".iBodyId \r\n                    " + sTagJoinTable + "\r\n                    WHERE tCore_Data" + m_strSuffix + ".bUpdateFA = 1 AND tCore_Data" + m_strSuffix + ".bSuspendUpdateFA <> 1 AND tCore_Header" + m_strSuffix + ".bSuspended = 0 \r\n                    AND tCore_Data" + m_strSuffix + ".iAuthStatus < 2 AND " + text3 + "\r\n\t                UNION ALL\r\n\t                SELECT iCode[iMasterId],iTag50,\r\n\t                CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n\t                CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit,\r\n\t                CASE WHEN ISNULL(mFXAmount1,mAmount1) < 0 THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END TranDr, \r\n\t                CASE WHEN ISNULL(mFXAmount1,mAmount1) > 0 THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END TranCr,\r\n\t                CASE WHEN ISNULL(fLocalAmount1,0) < 0 THEN ISNULL(fLocalAmount1,0) ELSE 0 END LocalDr, \r\n\t                CASE WHEN ISNULL(fLocalAmount1,0) > 0 THEN ISNULL(fLocalAmount1,0) ELSE 0 END LocalCr\r\n\t                FROM tCore_Data" + m_strSuffix + " \r\n\t                JOIN tCore_Header" + m_strSuffix + " ON tCore_Data" + m_strSuffix + ".iHeaderId = tCore_Header" + m_strSuffix + ".iHeaderId\r\n\t                LEFT JOIN tCore_Data_FX" + m_strSuffix + " ON tCore_Data_FX" + m_strSuffix + ".iBodyId = tCore_Data" + m_strSuffix + ".iBodyId\r\n                    " + sTagJoinTable + "\r\n                    WHERE tCore_Data" + m_strSuffix + ".bUpdateFA = 1 AND tCore_Data" + m_strSuffix + ".bSuspendUpdateFA <> 1 AND tCore_Header" + m_strSuffix + ".bSuspended = 0 \r\n                    AND tCore_Data" + m_strSuffix + ".iAuthStatus < 2 AND " + text3 + "\r\n                )TempTable \r\n                LEFT JOIN vrCore_SubLedger ON vrCore_SubLedger.iMasterId = TempTable.iTag50 AND vrCore_SubLedger.iTreeId=0 \r\n                " + text4 + " GROUP BY TempTable.[iMasterId], vrCore_SubLedger.sName";
			dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text2) : text2);
			while (dataReader.Read())
			{
				bool flag = false;
				if (m_bClosed)
				{
					for (num = 0; num < list.Count; num++)
					{
						if (list[num].ID == Convert.ToInt32(dataReader["iMasterId"]) && list[num].Name == Convert.ToString(dataReader["Subledger"]))
						{
							(list[num].Tag as decimal[])[0] += Convert.ToDecimal(dataReader["Base"]);
							(list[num].Tag as decimal[])[1] += Convert.ToDecimal(dataReader["FX"]);
							(list[num].Tag as decimal[])[2] += Convert.ToDecimal(dataReader["Local"]);
							flag = true;
							break;
						}
					}
				}
				if (!flag)
				{
					list.Add(new IdNamePair(Convert.ToInt32(dataReader["iMasterId"]), Convert.ToString(dataReader["Subledger"]), new decimal[3]
					{
						Convert.ToDecimal(dataReader["Base"]),
						Convert.ToDecimal(dataReader["FX"]),
						Convert.ToDecimal(dataReader["Local"])
					}));
				}
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			m_sError = $"GetSubledgerWiseOpeningBalance : {ex.Message}";
		}
		return list;
	}

	private decimal GetBalanceAsPerBook(RepRecord objRec, bool bBrs, ref decimal dTranAmount, ref decimal dLocalAmount)
	{
		string text = null;
		string text2 = null;
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		decimal result = 0m;
		text = _focus.company(m_iCompanyId).getFinanceFilter(objRec.FilterSource);
		if (!string.IsNullOrEmpty(text))
		{
			text = $" AND iFaTag IN({text})";
		}
		if (m_iYearId > 0 && !bBrs)
		{
			text2 = $"SELECT ISNULL(SUM(mBalance), 0)[Base], ISNULL(SUM(mBalanceFX), 0)[Tran], \r\n                ISNULL(SUM(mBalanceLocal), 0)[Local] FROM tCore_abalsOb{m_strSuffix} \r\n                WHERE iAccount = {objRec.Code} --AND iType = 2";
			if (!string.IsNullOrEmpty(text))
			{
				text2 += text;
			}
			dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text2) : text2);
			dbCommand.CommandTimeout = 0;
			dataReader = m_objDatabase.ExecuteReader(dbCommand);
			if (dataReader.Read())
			{
				result += Convert.ToDecimal(dataReader["Base"]);
				dTranAmount += Convert.ToDecimal(dataReader["Tran"]);
				dLocalAmount += Convert.ToDecimal(dataReader["Local"]);
			}
			dataReader.Close();
		}
		text2 = string.Format("SELECT ISNULL(SUM(Debit)+SUM(Credit),0)[Base],ISNULL(SUM(TranDr)+SUM(TranCr),0)[Tran],ISNULL(SUM(LocalDr)+SUM(LocalCr),0)[Local]\r\n\t        FROM \r\n\t        (\r\n\t\t        SELECT tCore_Data{0}.iBodyId, tCore_Header{0}.iDate,cCore_Vouchers{0}.sAbbr+' : '+tCore_Header{0}.sVoucherNo[Voucher], iBookNo[iMasterId],\r\n\t\t        CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n                CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit,\r\n\t            CASE WHEN ISNULL(mFxAmount2,mAmount2) < 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranDr, \r\n\t            CASE WHEN ISNULL(mFxAmount2,mAmount2) > 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranCr,\r\n                CASE WHEN ISNULL(fLocalAmount2,mAmount2) < 0 THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalDr, \r\n\t            CASE WHEN ISNULL(fLocalAmount2,mAmount2) > 0 THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalCr\r\n\t\t        FROM tCore_Data{0} \r\n\t\t        JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t\t        JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n\t\t        LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId\r\n\t\t        WHERE tCore_Data{0}.iBookNo  <> 2\r\n\t\t        UNION ALL\r\n\t\t        SELECT tCore_Data{0}.iBodyId, tCore_Header{0}.iDate, cCore_Vouchers{0}.sAbbr+' : '+tCore_Header{0}.sVoucherNo[Voucher], iCode[iMasterId],\r\n\t\t        CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n                CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit,\r\n\t            CASE WHEN ISNULL(mFXAmount1,mAmount1) < 0 THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END TranDr, \r\n\t            CASE WHEN ISNULL(mFXAmount1,mAmount1) > 0 THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END TranCr,\r\n                CASE WHEN ISNULL(fLocalAmount1,mAmount1) < 0 THEN ISNULL(fLocalAmount1,mAmount1) ELSE 0 END LocalDr, \r\n\t            CASE WHEN ISNULL(fLocalAmount1,mAmount1) > 0 THEN ISNULL(fLocalAmount1,mAmount1) ELSE 0 END LocalCr\r\n\t\t        FROM tCore_Data{0}\r\n\t\t        JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t\t        JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n\t\t        LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId\r\n\t\t        WHERE tCore_Data{0}.iCode  <> 2\r\n\t\t        UNION ALL\r\n\t\t        SELECT TOP 1 tCore_Data{0}.iBodyId, tCore_Header{0}.iDate,'', tCore_Data{0}.iBookNo,\r\n                mAmount1,0,ISNULL(mFXAmount1,mAmount1),0,ISNULL(fLocalAmount1,0),0\r\n\t\t        FROM tCore_Data{0}  \r\n\t\t        JOIN tCore_Header{0}  ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId\r\n\t\t        WHERE tCore_Data{0}.iBookNo  = 2\r\n\t        )InnerTable\r\n\t        JOIN tCore_Data{0} ON tCore_Data{0}.iBodyId = InnerTable.iBodyId  \r\n\t        JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t        LEFT JOIN tCore_Indta{0} ON tCore_Indta{0}.iBodyId = tCore_Data{0}.iBodyId\r\n\t        LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = InnerTable.iBodyId\r\n\t        JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n\t        WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA <> 1 AND tCore_Header{0}.bSuspended = 0 and tCore_Data{0}.iAuthStatus =1\r\n\t        AND (InnerTable.iDate <= {2} or tCore_Data{0}.iDueDate <= {2}) AND InnerTable.iMasterId = {3}", m_strSuffix, objRec.StartingDate, objRec.EndingDate, objRec.Code);
		if (bBrs)
		{
			text2 += " AND bBrs = 1";
		}
		if (!string.IsNullOrEmpty(text))
		{
			text2 += text;
		}
		dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text2) : text2);
		dbCommand.CommandTimeout = 0;
		dataReader = m_objDatabase.ExecuteReader(dbCommand);
		if (dataReader.Read())
		{
			result += Convert.ToDecimal(dataReader["Base"]);
			dTranAmount += Convert.ToDecimal(dataReader["Tran"]);
			dLocalAmount += Convert.ToDecimal(dataReader["Local"]);
		}
		dataReader.Close();
		return result;
	}

	public string GetSpecialFilter(_Filter[] arrFilterSource, ref List<IdValuePair> arrTagFilter, Database objDb, int iCompId, ref string sTagJoinTable, ref string sMultiAccountJoin, bool bDonotIncludeMaster = false)
	{
		string faTagName = _focus.company(iCompId).faTagName;
		string invTagName = _focus.company(iCompId).invTagName;
		_ = _focus.company(iCompId).faTagId;
		_ = _focus.company(iCompId).invTagId;
		int num = 0;
		InvoiceLayout invoiceLayout = null;
		string text = null;
		string suffix = FConvert.GetSuffix(iCompId);
		List<string> list = null;
		string text2 = null;
		string text3 = null;
		string text4 = null;
		if (arrTagFilter == null)
		{
			arrTagFilter = new List<IdValuePair>();
		}
		if (arrFilterSource != null && arrFilterSource.Length != 0 && arrFilterSource.Select((_Filter p) => new FieldData
		{
			FieldId = p.FieldId,
			SubParentId = p.SubParentId
		}).ToArray().Length != 0)
		{
			invoiceLayout = new InvoiceLayout();
			list = new List<string>();
			for (num = 0; num < arrFilterSource.Length; num++)
			{
				if (arrFilterSource[num].DataType != MasterDataType.Master && (arrFilterSource[num].DataType != MasterDataType.Number || arrFilterSource[num].SubParentId <= 0))
				{
					continue;
				}
				text3 = invoiceLayout.GetExtraFieldName(arrFilterSource[num].FieldId, 0, -1, bVoucherClass: false, iCompId);
				if (string.IsNullOrEmpty(text3) || !FConvert.IsNumeric(arrFilterSource[num].CompareValue))
				{
					continue;
				}
				text2 = text3.Split('.')[0];
				text = arrFilterSource[num].CompareValue;
				if (arrFilterSource[num].IsGroup)
				{
					text = GetMastersInGroup(Convert.ToInt32(arrFilterSource[num].CompareValue), text2, objDb, iCompId);
				}
				text4 = ((arrFilterSource[num].Conjuction == Conjuction.Where) ? string.Empty : arrFilterSource[num].Conjuction.ToString());
				if (list.Count == 0 && !string.IsNullOrEmpty(text4))
				{
					text4 = string.Empty;
				}
				if (text2 == faTagName)
				{
					if (!text.Contains(","))
					{
						list.Add(string.Format(" {0} tCore_Data{3}.iFaTag {2} {1}", text4, text, (arrFilterSource[num].Operator == Operator.NotEqualTo) ? "<>" : "=", suffix));
					}
					else
					{
						list.Add(string.Format(" {0} tCore_Data{3}.iFaTag {2} IN({1})", text4, text, (arrFilterSource[num].Operator == Operator.NotEqualTo) ? "NOT" : "", suffix));
					}
				}
				else if (text2 == invTagName)
				{
					if (!text.Contains(","))
					{
						list.Add(string.Format(" {0} tCore_Data{2}.iInvTag = {1}", text4, text, suffix));
					}
					else
					{
						list.Add(string.Format(" {0} tCore_Data{2}.iInvTag IN({1})", text4, text, suffix));
					}
				}
				else if (text2 == "vrCore_Account")
				{
					if (arrFilterSource[num].DataType != MasterDataType.Master)
					{
						if (arrFilterSource[num].Operator == Operator.NotEqualTo)
						{
							list.Add(" " + text4 + " (tCore_Data" + suffix + ".iBookNo NOT IN(" + text + ") AND tCore_Data" + suffix + ".iCode NOT IN(" + text + "))");
						}
						else if (bDonotIncludeMaster)
						{
							sMultiAccountJoin = "Create Table #MasterIdTable (iRowSeq int,iMasterId int)\r\n                                                insert into #MasterIdTable\r\n                                                Select iRowNo, cast(value as int) iMasterId from dbo.[fCore_SplitStringListWithIndex]('" + text + "') \r\n                                                ";
							text = string.Empty;
						}
						else
						{
							list.Add(" " + text4 + " (tCore_Data" + suffix + ".iBookNo IN(" + text + ") OR tCore_Data" + suffix + ".iCode IN(" + text + "))");
						}
					}
					else
					{
						text = ((!string.IsNullOrEmpty(arrFilterSource[num].CompareText) && !FConvert.IsNumeric(arrFilterSource[num].CompareText)) ? $"N'{arrFilterSource[num].CompareText}'" : text);
						if (arrFilterSource[num].Operator == Operator.NotEqualTo)
						{
							list.Add(" " + text4 + " " + text3 + " <> " + text);
						}
						else
						{
							list.Add(" " + text4 + " " + text3 + " = " + text);
						}
					}
				}
				else
				{
					if (!text2.StartsWith("vr"))
					{
						continue;
					}
					int tagId = GetTagId(arrFilterSource[num].FieldId, suffix, objDb);
					if (tagId > 2)
					{
						arrTagFilter.Add(new IdValuePair(tagId, text));
						if (arrFilterSource[num].Operator == Operator.NotEqualTo)
						{
							list.Add($" {text4} tCore_Data_Tags{suffix}.iTag{tagId} NOT IN({text})");
						}
						else
						{
							list.Add($" {text4} tCore_Data_Tags{suffix}.iTag{tagId} IN({text})");
						}
					}
					else
					{
						text = string.Empty;
					}
				}
			}
			if (list.Count > 0)
			{
				text = " AND (" + string.Join("", list.ToArray()) + ")";
			}
			if (arrTagFilter != null && arrTagFilter.Count > 0)
			{
				sTagJoinTable = string.Empty;
				for (num = 0; num < arrTagFilter.Count; num++)
				{
					if (arrTagFilter[num].ID > 2)
					{
						sTagJoinTable += string.Format(" LEFT JOIN tCore_Data_Tags{0} ON tCore_Data_Tags{0}.iBodyId = tCore_Data{0}.iBodyId", suffix);
						break;
					}
				}
			}
		}
		return text;
	}

	private int GetTagId(int iFieldId, string strSuffix, Database objDb)
	{
		DbCommand dbCommand = null;
		string text = $"SELECT cCore_MasterTabs.iMasterId\r\n            FROM cCore_MasterFields \r\n            JOIN cCore_MasterTables WITH (READUNCOMMITTED) ON cCore_MasterTables.iTableId = cCore_MasterFields.iTableId\r\n            JOIN cCore_MasterTabs WITH (READUNCOMMITTED) ON cCore_MasterTabs.iTabId = cCore_MasterTables.iTabId\r\n            JOIN cCore_VoucherMasters{strSuffix} WITH (READUNCOMMITTED) ON cCore_VoucherMasters{strSuffix}.iMasterType = cCore_MasterTabs.iMasterId\r\n            WHERE iFieldId = {iFieldId} AND bMainTable = 1 ";
		dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		return Convert.ToInt32(objDb.ExecuteScalar(dbCommand));
	}

	private string GetMastersInGroup(int iGroupId, string strMaster, Database objDb, int iCompId)
	{
		if (objDb == null)
		{
			objDb = DatabaseWrapper.GetDatabase2(iCompId, -1, bReplicationServer: true);
		}
		IDataReader dataReader = null;
		DbCommand dbCommand = null;
		string text = null;
		List<string> list = new List<string>();
		try
		{
			text = $"WITH RecursionCTE (iMasterId, iParentId, bGroup)  AS  \r\n                                (   SELECT iMasterId, iParentId, bGroup\r\n                                    FROM {strMaster}\r\n                                    WHERE iMasterId = {iGroupId} AND iTreeId = 0\r\n                                    UNION ALL  \r\n                                    SELECT R1.iMasterId, R1.iParentId, R1.bGroup\r\n                                    FROM {strMaster} AS R1\r\n                                    JOIN RecursionCTE AS R2 ON R1.iParentId = R2.iMasterId\r\n                                )SELECT iMasterId  FROM RecursionCTE WHERE bGroup = 0 ";
			dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dbCommand.CommandTimeout = 0;
			dataReader = objDb.ExecuteReader(dbCommand);
			while (dataReader.Read())
			{
				list.Add(Convert.ToString(dataReader[0]));
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			m_sError = $"GetMastersInGroup : {ex.Message}";
		}
		if (list.Count == 0)
		{
			list.Add(iGroupId.ToString());
		}
		return string.Join(",", list.ToArray());
	}

	private Dictionary<int, AccountingData> GetDebitCreditBalance(RepRecord objRec, Database objDB)
	{
		string text = null;
		IDataReader dataReader = null;
		DbCommand dbCommand = null;
		AccountingData value = null;
		Dictionary<int, AccountingData> dictionary = new Dictionary<int, AccountingData>();
		text = string.Format("SELECT TempTable.iMasterId,\r\n            CASE WHEN SUM([Debit])+SUM([Credit]) < 0 THEN SUM([Debit])+SUM([Credit]) ELSE 0 END [Debit],\r\n            CASE WHEN SUM([Debit])+SUM([Credit]) > 0 THEN SUM([Debit])+SUM([Credit]) ELSE 0 END [Credit]\r\n            FROM \r\n            (\r\n                SELECT InnerTable.iMasterId, Debit, Credit\r\n                FROM \r\n\t            (\r\n\t\t            SELECT tCore_Header{0}.iDate, tCore_Header{0}.iVoucherType, iBookNo[iMasterId],\r\n\t\t            CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t\t            CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit\r\n\t\t            FROM tCore_Header{0} \r\n                    JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n\t\t            WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA = 0\r\n                    AND tCore_Data{0}.iAuthStatus < 2 AND tCore_Header{0}.bSuspended = 0\r\n\t\t            AND tCore_Header{0}.iDate BETWEEN 0 AND {1} \r\n\t\t            UNION ALL\r\n\t\t            SELECT tCore_Header{0}.iDate, tCore_Header{0}.iVoucherType, iCode[iMasterId],\r\n\t\t            CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n\t\t            CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit\r\n\t\t            FROM tCore_Header{0} \r\n                    JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n\t\t            WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA = 0\r\n\t\t            AND tCore_Data{0}.iAuthStatus  < 2 AND tCore_Header{0}.bSuspended = 0\r\n\t\t            AND tCore_Header{0}.iDate BETWEEN 0 AND {1} \r\n\t            )InnerTable\r\n            ) TempTable \r\n            GROUP BY TempTable.[iMasterId]", m_strSuffix, objRec.EndingDate);
		dbCommand = objDB.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		dbCommand.CommandTimeout = 0;
		dataReader = objDB.ExecuteReader(dbCommand);
		while (dataReader.Read())
		{
			if (!dictionary.TryGetValue(Convert.ToInt32(dataReader["iMasterId"]), out value))
			{
				value = new AccountingData
				{
					Debit = Convert.ToDecimal(dataReader["Debit"]),
					Credit = Convert.ToDecimal(dataReader["Credit"])
				};
				dictionary.Add(Convert.ToInt32(dataReader["iMasterId"]), value);
			}
			else
			{
				value.Debit = Convert.ToDecimal(dataReader["Debit"]);
				value.Credit = Convert.ToDecimal(dataReader["Credit"]);
				dictionary[Convert.ToInt32(dataReader["iMasterId"])] = value;
			}
		}
		dataReader.Close();
		return dictionary;
	}

	private void GetDebitCreditForGroup(int iAccountGroup, Database objDB, Dictionary<int, AccountingData> arrAccountingBalance, ref decimal dDr, ref decimal dCr)
	{
		string text = null;
		List<int> list = null;
		IDataReader dataReader = null;
		DbCommand dbCommand = null;
		AccountingData value = null;
		dDr = (dCr = 0m);
		text = $"SELECT bGroup FROM mCore_Account WHERE iMasterId = {iAccountGroup}";
		bool flag = Convert.ToBoolean(objDB.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
		list = new List<int>();
		if (flag)
		{
			text = $"WITH RecursionCTE (iMasterId, iParentId, bGroup)  AS  \r\n                (   SELECT iMasterId, iParentId, bGroup\r\n                    FROM vmCore_Account \r\n                    WHERE iMasterId = {iAccountGroup} AND iTreeId = 0 \r\n                    UNION ALL  \r\n                    SELECT R1.iMasterId, R1.iParentId, R1.bGroup\r\n                    FROM vmCore_Account AS R1 \r\n                    JOIN RecursionCTE AS R2 ON R1.iParentId = R2.iMasterId WHERE R1.iTreeId = 0 \r\n                )SELECT iMasterId FROM RecursionCTE WHERE bGroup = 0";
			dbCommand = objDB.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dbCommand.CommandTimeout = 0;
			dataReader = objDB.ExecuteReader(dbCommand);
			while (dataReader.Read())
			{
				list.Add(Convert.ToInt32(dataReader["iMasterId"]));
			}
			dataReader.Close();
		}
		else
		{
			list.Add(iAccountGroup);
		}
		if (list.Count <= 0)
		{
			return;
		}
		for (int i = 0; i < list.Count; i++)
		{
			if (arrAccountingBalance.TryGetValue(list[i], out value) && value != null)
			{
				dDr += value.Debit;
				dCr += value.Credit;
			}
			value = null;
		}
	}

	private decimal GetProfitAndLoss(RepRecord objRec, Database objDB, int iCompanyId)
	{
		string text = null;
		text = string.Format("SELECT ISNULL(SUM(Debit)+SUM(Credit), 0)[Balance]\r\n            FROM \r\n            (\r\n\t            SELECT iBookNo[iMasterId],\r\n\t            CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t            CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit\r\n\t            FROM tCore_Header{0} \r\n\t            JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n\t            WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA = 0\r\n\t            AND tCore_Data{0}.iAuthStatus < 2 AND tCore_Header{0}.bSuspended = 0\r\n\t            AND tCore_Header{0}.iDate BETWEEN 0 AND {2} \r\n                UNION ALL\r\n\t            SELECT iCode[iMasterId],\r\n\t            CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n\t            CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit\r\n\t            FROM tCore_Header{0} \r\n\t            JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n\t            WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA = 0\r\n\t            AND tCore_Data{0}.iAuthStatus  < 2 AND tCore_Header{0}.bSuspended = 0\r\n\t            AND tCore_Header{0}.iDate BETWEEN 0 AND {2} \r\n            )InnerTable\r\n            JOIN mCore_Account ON InnerTable.iMasterId = mCore_Account.iMasterId\r\n            WHERE iAccountType IN({3})\t", m_strSuffix, objRec.StartingDate, objRec.EndingDate, General.GetAccountFilter(532u));
		return Convert.ToDecimal(objDB.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
	}

