	private void UpdateProvisionalAccount(int iId, string sName, decimal dValue, decimal dTranValue, decimal dLocalValue, ref List<ProvisionalEntryBody> arrBodyData, List<IdValuePair> arrValues = null, int iTagId = -1, bool bDebit = false)
	{
		int num = 0;
		decimal num2 = 0m;
		ProvisionalEntryBody provisionalEntryBody = null;
		for (num = 0; num < arrBodyData.Count; num++)
		{
			if (arrBodyData[num].Account == iId)
			{
				arrBodyData[num].Amount += dValue;
				arrBodyData[num].TranAmount += dTranValue;
				arrBodyData[num].LocalAmount += dLocalValue;
				arrBodyData[num].FATag = ((iTagId != -1) ? iTagId : arrBodyData[num].FATag);
				break;
			}
		}
		if (num < arrBodyData.Count)
		{
			return;
		}
		if (iTagId > -1 && arrValues != null && arrValues.Count > 0)
		{
			for (num = 0; num < 12; num++)
			{
				provisionalEntryBody = new ProvisionalEntryBody();
				provisionalEntryBody.Account = iId;
				provisionalEntryBody.FATag = num;
				provisionalEntryBody.AccountName = sName;
				if (num == iTagId)
				{
					provisionalEntryBody.Amount = dValue;
					provisionalEntryBody.TranAmount = dTranValue;
					provisionalEntryBody.LocalAmount = dLocalValue;
				}
				else
				{
					for (int i = 0; i < arrValues.Count; i++)
					{
						if (arrValues[i].ID == num)
						{
							num2 = Convert.ToDecimal(arrValues[i].Value);
							ProvisionalEntryBody provisionalEntryBody2 = provisionalEntryBody;
							decimal amount;
							if (bDebit)
							{
								amount = ((num2 < 0m) ? num2 : (num2 * -1m));
							}
							else
							{
								amount = ((num2 > 0m) ? num2 : (num2 * -1m));
							}
							provisionalEntryBody2.Amount = amount;
							break;
						}
					}
				}
				arrBodyData.Add(provisionalEntryBody);
			}
		}
		else
		{
			provisionalEntryBody = new ProvisionalEntryBody();
			provisionalEntryBody.Account = iId;
			provisionalEntryBody.AccountName = sName;
			provisionalEntryBody.Amount = dValue;
			provisionalEntryBody.TranAmount = dTranValue;
			provisionalEntryBody.LocalAmount = dLocalValue;
