					{
						num3 = ((num3 > 0m) ? num3 : (num3 * -1m));
					}
					arrBodyData[num].Amount += num3;
					break;
				}
			}
			flag = true;
		}
		if (!flag)
		{
			for (num2 = 0; num2 < arrValues.Count; num2++)
