				text = $"SELECT dbo.fCore_GetCurrencyRate({iBaseCurrency}, {num}, dbo.fCore_DateTimeToInt( dbo.IntToDate({iDate})+' '+ dbo.fCore_IntToTime(0)))";
				num9 = Convert.ToDecimal(m_objDatabase.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
				text = $"SELECT dbo.fCore_GetCurrencyRate({iBaseCurrency}, {num2}, dbo.fCore_DateTimeToInt( dbo.IntToDate({iDate})+' '+ dbo.fCore_IntToTime(0)))";
				num10 = Convert.ToDecimal(m_objDatabase.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
				num6 = ((num4 < 0m) ? (-Math.Abs(num5 * num9)) : Math.Abs(num5 * num9));
				if (num6 < 0m != num5 < 0m)
				{
					num6 = -num6;
				}
				num6 -= num4;
				if (num11 != 0m)
				{
					num7 = ((num11 < 0m) ? (-Math.Abs(num5 * num10)) : Math.Abs(num5 * num10));
					if (num7 < 0m != num5 < 0m)
					{
						num7 = -num7;
					}
					num7 -= num11;
				}
				if (num5 != 0m)
				{
					num8 = num5;
					if (num8 < 0m != num5 < 0m)
					{
						num8 = -num8;
					}
					num8 -= num5;
				}
			}
			dataReader.Close();
			if (num6 != 0m)
			{
				list.Add(new IdNamePair(arrMasters[num3].ID, arrMasters[num3].Name, new decimal[3] { num6, num8, num7 }));
			}
		}
		return list.ToArray();
	}

	private decimal GetForexExchangeAccount(ref int iBaseCurrency, int iDate, int iMasterId, ref decimal dLocalAmount, Database objDB, int iCompId)
	{
		int num = 0;
		int num2 = 0;
		string text = null;
		decimal num3 = 0m;
		decimal num4 = 0m;
		decimal num5 = 0m;
		decimal num6 = 0m;
		decimal num7 = 0m;
		decimal num8 = 0m;
		IDataReader dataReader = null;
		num5 = (dLocalAmount = 0m);
		if (iBaseCurrency <= 0)
		{
			iBaseCurrency = _focus.company(iCompId).getPreferenceValue(PreferenceCategories.Misc, 10);
		}
		text = string.Format("SELECT iCurrencyId, ISNULL(iLocalCurrencyId,iCurrencyId)[iLocalCurrencyId],\r\n            SUM(CASE WHEN iCode = {1} THEN mAmount1 ELSE mAmount2 END) Base, \r\n            SUM(CASE WHEN iCode = {1} THEN ISNULL(mFXAmount1,mAmount1) ELSE ISNULL(mFxAmount2,mAmount2) END) FX, \r\n            ISNULL(SUM(CASE WHEN iCode = {1} THEN ISNULL(fLocalAmount1,0) ELSE ISNULL(fLocalAmount2,0) END),0) [Local]\r\n            FROM tCore_Data{0} \r\n            LEFT JOIN tCore_Data_FX{0} ON tCore_Data{0}.iBodyId = tCore_Data_FX{0}.iBodyId\r\n            JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n            WHERE (iCode = {1} OR iBookNo = {1}) AND iCurrencyId > 0 AND bUpdateFA = 1 \r\n            AND iDate <= {2} GROUP BY iCurrencyId,iLocalCurrencyId", m_strSuffix, iMasterId, iDate);
		dataReader = objDB.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		while (dataReader.Read())
		{
			num = Convert.ToInt32(dataReader["iCurrencyId"]);
			num2 = Convert.ToInt32(dataReader["iLocalCurrencyId"]);
			num3 = Convert.ToDecimal(dataReader["Base"]);
			num8 = Convert.ToDecimal(dataReader["Local"]);
			num4 = Convert.ToDecimal(dataReader["FX"]);
			if (num != num2)
			{
				if (iBaseCurrency != num)
				{
					text = $"SELECT dbo.fCore_GetCurrencyRate({iBaseCurrency}, {num}, dbo.fCore_DateTimeToInt( dbo.IntToDate({iDate})+' '+ dbo.fCore_IntToTime(0)))";
					num6 = Convert.ToDecimal(objDB.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
				}
				if (iBaseCurrency != num2)
				{
					text = $"SELECT dbo.fCore_GetCurrencyRate({iBaseCurrency}, {num2}, dbo.fCore_DateTimeToInt( dbo.IntToDate({iDate})+' '+ dbo.fCore_IntToTime(0)))";
					num7 = Convert.ToDecimal(objDB.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
				}
			}
			if (num6 != 0m)
			{
				num5 = ((num3 < 0m) ? (-Math.Abs(num4 * num6)) : Math.Abs(num4 * num6));
				if (num5 < 0m != num4 < 0m)
				{
					num5 = -num5;
				}
				num5 -= num3;
			}
			if (num7 != 0m && num8 != 0m)
			{
				dLocalAmount = ((num8 < 0m) ? (-Math.Abs(num4 * num7)) : Math.Abs(num4 * num7));
				if (dLocalAmount < 0m != num4 < 0m)
				{
					dLocalAmount = -dLocalAmount;
				}
				dLocalAmount -= num8;
			}
		}
		dataReader.Close();
		return (Math.Round(num5, 5) < 0.001m) ? 0m : num5;
	}

	private void GetSummaryPDC(int iMasterId, RepRecord objRec, ref decimal dPDCValue, ref decimal dPDCVal1, ref decimal dPDCVal2, int iCompId, ref Database objDB, int iFATagId, string sUniqueId = "")
	{
		string text = null;
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		bool flag = FConvert.GetYearId(iCompId) > 0;
		dPDCValue = (dPDCVal1 = (dPDCVal2 = 0m));
		string empty = string.Empty;
		short num = 0;
		empty = (short)FConvert.GetInputValue(objRec.Inputs, 2) switch
		{
			1 => "AND (((h.iVoucherClass) in (7168)) or ((h.iVoucherClass) in (5888) and iRefType=0) ) and d.bPdc=0 ", 
			0 => "AND (((h.iVoucherClass) in (5888)) or ((h.iVoucherClass) in (7168) and iRefType=0) ) and d.bPdc=0", 
			_ => "AND (h.iVoucherClass) in (5888,7168) and d.bPdc=0", 
		};
		try
		{
			if (flag)
			{
				text = $"SELECT ISNULL(SUM(mBalance),0)[Base], ISNULL(SUM(mBalanceFX),0)[FX], ISNULL(SUM(mBalanceLocal),0)[Local] \r\n                        FROM tCore_abalsOb{m_strSuffix} WHERE iType = 1 AND bStatus = 0 AND iAccount = {iMasterId}";
				dataReader = objDB.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				if (dataReader.Read())
				{
					dPDCValue = Convert.ToDecimal(dataReader["Base"]);
					dPDCVal1 = Convert.ToDecimal(dataReader["FX"]);
					dPDCVal2 = Convert.ToDecimal(dataReader["Local"]);
				}
				dataReader.Close();
			}
			text = string.Format("Select ISNULL(sum(mBaseAmount),0) mBaseAmount,ISNULL(sum(mAmount),0) mAmount, ISNULL(sum(mLocalAmount),0) mLocalAmount from tCore_Refrn_0 r\r\n                                            inner join tCore_Data_0 d on r.iBodyId= d.iBodyId\r\n                                            inner join tCore_Header_0 h on d.iHeaderId= h.iHeaderId\r\n                                            WHERE d.bSuspendUpdateFA <> 1 \r\n                                            AND h.bSuspended = 0 \r\n                                            AND \r\n                                            (\r\n\t                                            h.iDate BETWEEN 0 AND {2} and                        \r\n\t                                            ((d.iDueDate <= {2} AND d.bPdc = 0) OR (d.iDueDate > {1}))\r\n                                            )\r\n                                            --AND (((h.iVoucherClass) in (7168) and iRefType=2) or ((h.iVoucherClass) in (5888) and iRefType=0) )\r\n                                            {4}\r\n                                            and r.iCode={3}\r\n", m_strSuffix, objRec.StartingDate, objRec.EndingDate, iMasterId, empty);
			string financeFilter = _focus.company(m_iCompanyId).getFinanceFilter(objRec.FilterSource);
			if (!string.IsNullOrEmpty(financeFilter))
			{
				text += $" AND iFaTag IN({financeFilter})";
			}
			if (objRec.UserId > 1 && _focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Print, 36) == 0)
			{
				bool bExclude = false;
				financeFilter = CheckRoleMasters(iFATagId, objRec.UserId, ref bExclude, objDB);
				if (!string.IsNullOrEmpty(financeFilter))
				{
					text = ((!bExclude) ? (text + $" AND iFaTag IN ({financeFilter})") : (text + $" AND iFaTag NOT IN ({financeFilter})"));
				}
				bExclude = false;
				financeFilter = CheckRoleMasters(iFATagId, objRec.UserId, ref bExclude, objDB);
				if (!string.IsNullOrEmpty(financeFilter))
				{
					text = ((!bExclude) ? (text + $" AND iInvTag NOT IN ({financeFilter})") : (text + $" AND iInvTag IN ({financeFilter})"));
				}
			}
			dbCommand = objDB.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dbCommand.CommandTimeout = 0;
			dataReader = objDB.ExecuteReader(dbCommand);
			if (dataReader.Read())
			{
				dPDCValue += Convert.ToDecimal(dataReader["mBaseAmount"]);
				dPDCVal1 += Convert.ToDecimal(dataReader["mAmount"]);
				dPDCVal2 += Convert.ToDecimal(dataReader["mLocalAmount"]);
			}
			dataReader.Close();
			LedgerBalanceData value = new LedgerBalanceData();
			_focus.company(m_iCompanyId).report(sUniqueId).accountBalance.TryGetValue(iMasterId, out value);
			if (value == null)
			{
				value = new LedgerBalanceData();
				value.PDCBalance = new decimal[3] { dPDCValue, dPDCVal1, dPDCVal2 };
				_focus.company(m_iCompanyId).report(sUniqueId).accountBalance.Add(iMasterId, value);
				return;
			}
			if (value.PDCBalance == null)
			{
				value.PDCBalance = new decimal[3] { dPDCValue, dPDCVal1, dPDCVal2 };
			}
			else
			{
				value.PDCBalance[0] = dPDCValue;
				value.PDCBalance[1] = dPDCVal1;
				value.PDCBalance[2] = dPDCVal2;
			}
			_focus.company(m_iCompanyId).report(sUniqueId).accountBalance[iMasterId] = value;
		}
		catch (Exception ex)
		{
			m_sError = $"GetSummaryPDC : {ex.Message}";
		}
	}

