	private LineData GetSpecialLine(int iLength, ReportRowType objRowType)
	{
		ReportRowHeader reportRowHeader = null;
		reportRowHeader = new ReportRowHeader();
		LineData lineData = new LineData();
		reportRowHeader.RowType = objRowType;
		lineData.CellData = new object[iLength];
		lineData.CellData[0] = reportRowHeader;
		return lineData;
	}

	private LineData GetSpecialLine(int iLength, int iDisplayColumn, object oDisplayText, int iValueColumn, object oValue, ReportRowType objRowType)
	{
		ReportRowHeader reportRowHeader = null;
		LineData lineData = null;
		reportRowHeader = new ReportRowHeader();
		lineData = new LineData();
		reportRowHeader.RowType = objRowType;
		lineData.CellData = new object[iLength];
		lineData.CellData[0] = reportRowHeader;
		if (iDisplayColumn > 0 && iDisplayColumn < iLength)
		{
			lineData.CellData[iDisplayColumn] = oDisplayText;
		}
		if (iValueColumn > 0 && iValueColumn < iLength)
		{
			lineData.CellData[iValueColumn] = oValue;
		}
		return lineData;
	}

	private int[] GetNumericColumns(FieldData[] arrDataColumns, RepRecord objRec)
	{
		int num = 0;
		_ = objRec.ReportId;
		List<int> list = new List<int>();
		if (arrDataColumns != null)
		{
			for (num = 0; num < objRec.ReportCustomize.Layout.Columns.Length; num++)
			{
				if (objRec.ReportCustomize.Layout.Columns[num].FieldId == -2 && Convert.ToString(objRec.ReportCustomize.Layout.Columns[num].Formula).StartsWith("sqlsf"))
				{
					continue;
				}
				for (int i = 1; i < arrDataColumns.Length; i++)
				{
					if (arrDataColumns[i].DataType != MasterDataType.Fraction)
					{
						continue;
					}
					bool flag = false;
					if (arrDataColumns[i].ColumnId > 0)
					{
						if (arrDataColumns[i].ColumnId == objRec.ReportCustomize.Layout.Columns[num].ColumnId)
						{
							flag = true;
						}
					}
					else if (arrDataColumns[i].FieldId == objRec.ReportCustomize.Layout.Columns[num].FieldId && arrDataColumns[i].SubParentId == objRec.ReportCustomize.Layout.Columns[num].SubParentId)
					{
						flag = true;
					}
					if (flag)
					{
						list.Add(i);
						break;
					}
				}
			}
		}
		return list.ToArray();
	}

	private void UpdateReportTotal(object[] arrCellData, int[] arrNumericColumns, ref object[] arrReportTotal, bool IsLedgerReport = true)
	{
		int num = 0;
		if (arrReportTotal == null)
		{
			arrReportTotal = new object[arrCellData.Length];
			arrReportTotal[0] = new ReportRowHeader();
		}
		if (arrNumericColumns == null)
		{
			return;
		}
		for (num = 0; num < arrNumericColumns.Length; num++)
		{
			if (arrNumericColumns[num] < arrCellData.Length && !string.IsNullOrEmpty(Convert.ToString(arrCellData[arrNumericColumns[num]])) && (((ReportRowHeader)arrCellData[0]).RowType == ReportRowType.Normal || ((ReportRowHeader)arrCellData[0]).RowType == ReportRowType.OpenigClosingBalance || ((ReportRowHeader)arrCellData[0]).RowType == ReportRowType.TreeGroup || ((ReportRowHeader)arrCellData[0]).RowType == ReportRowType.UnmaturedPDC))
			{
				arrReportTotal[arrNumericColumns[num]] = Convert.ToDecimal(arrReportTotal[arrNumericColumns[num]]) + Convert.ToDecimal(arrCellData[arrNumericColumns[num]]);
			}
		}
		if (IsLedgerReport)
		{
			object[] obj = arrReportTotal;
			if (obj != null && obj.Length >= 13)
			{
				arrReportTotal[7] = Convert.ToDecimal(arrReportTotal[5]) + Convert.ToDecimal(arrReportTotal[6]);
				arrReportTotal[10] = Convert.ToDecimal(arrReportTotal[8]) + Convert.ToDecimal(arrReportTotal[9]);
				arrReportTotal[13] = Convert.ToDecimal(arrReportTotal[11]) + Convert.ToDecimal(arrReportTotal[12]);
			}
		}
	}

	private int GetTransactionColumnIndex(RepRecord objRec)
	{
		if (objRec.SourceType != DataSourceType.Cubes)
		{
			for (int i = 0; i < objRec.Columns.Length; i++)
			{
				if (objRec.Columns[i].ID == -10)
				{
					return i;
				}
			}
		}
		return -1;
	}

	private Dictionary<int, LedgerBalanceData> getOpBalanceFromRedis(string sKey)
	{
		byte[] array = null;
		Dictionary<int, LedgerBalanceData> result = null;
		if (m_bUseRedisServer)
		{
			array = ProngHorn.GetCache(sKey);
			if (array != null)
			{
				result = (Dictionary<int, LedgerBalanceData>)FConvert.ByteArrayToObject(array);
			}
		}
		else if (_focus.company(m_iCompanyId).report(sKey).accountBalance != null)
		{
			result = _focus.company(m_iCompanyId).report(sKey).accountBalance;
		}
		return result;
	}

	private void setOpBalanceToRedis(string sKey, Dictionary<int, LedgerBalanceData> arrAccountBalance)
	{
		byte[] array = null;
		if (arrAccountBalance != null)
		{
			if (m_bUseRedisServer)
			{
				array = FConvert.ObjectToByteArray(arrAccountBalance);
				ProngHorn.SaveCashe(sKey, array);
			}
			else
			{
				_focus.company(m_iCompanyId).report(sKey).accountBalance = arrAccountBalance;
			}
		}
	}

	public TransData GetAccountQueryData(InputStockData objInputData, int iCompId)
	{
		bool bExclude = false;
		string text = null;
		string text2 = null;
		decimal Credit = 0m;
		decimal CrLocal = 0m;
		decimal CrBase = 0m;
		decimal Debit = 0m;
		decimal DrBase = 0m;
		decimal DrLocal = 0m;
		RepRecord repRecord = null;
		TransData transData = null;
		Dictionary<int, LedgerBalanceData> dictionary = null;
		IDataReader dataReader = null;
		List<IdNamePair> list = null;
		List<TopCreditNDebitDetails> list2 = null;
		transData = new TransData();
		try
		{
			RDConversion rDConversion = new RDConversion(m_objCalType);
			if (!string.IsNullOrEmpty(m_strDateFormat))
			{
				rDConversion.DateFormat = m_strDateFormat;
			}
			m_strSuffix = FConvert.GetSuffix(iCompId);
			m_iCompanyId = iCompId;
			m_objCalType = _focus.company(iCompId).calType;
			m_objDatabase = DatabaseWrapper.GetDatabase2(iCompId);
			repRecord = new RepRecord();
			repRecord.UserId = objInputData.UserId;
			repRecord.Code = objInputData.Product;
			repRecord.ReportId = 501u;
			repRecord.StartingDate = objInputData.AccountingDate;
			repRecord.EndingDate = new Date(m_objCalType).GetToday(m_objCalType).Value;
			repRecord.Inputs = new IdValuePair[1]
			{
				new IdValuePair(1, 2)
			};
			if (repRecord.UserId > 1 && _focus.company(iCompId).getPreferenceValue(PreferenceCategories.Print, 36) == 0)
			{
				text2 = CheckRoleMasters(_focus.company(iCompId).faTagId, repRecord.UserId, ref bExclude, m_objDatabase);
				if (!string.IsNullOrEmpty(text2))
				{
					text2 = ((!bExclude) ? $" AND iFaTag IN ({text2})" : $" AND iFaTag NOT IN ({text2})");
				}
			}
			GetAccountingDrCr(objInputData.Product, text2, ref Credit, ref Debit, ref DrLocal, ref CrLocal, ref DrBase, ref CrBase, iCompId);
			transData.Credit = (double)CrBase;
			transData.Debit = (double)DrBase;
			transData.Balance = (double)(CrBase + DrBase);
			transData.CreditTran = Credit;
			transData.DebitTran = Debit;
			transData.BalanceTran = Credit + Debit;
			transData.CreditLocal = CrLocal;
			transData.DebitLocal = DrLocal;
			transData.BalanceLocal = CrLocal + DrLocal;
			dictionary = GetLedgerOpeningBalance(repRecord, bLoadAccountProperty: false);
			DrLocal = 0m;
			DrBase = DrLocal;
			Debit = GetLedgerBalanceFromDictionary(objInputData.Product, LedgerBalanceType.OpeningBalance, ref dictionary, ref DrLocal, ref DrBase);
			transData.OpeningBalance = (double)DrBase;
			transData.Balance += transData.OpeningBalance;
			transData.OpeningBalanceTran = Debit;
			transData.BalanceTran += transData.OpeningBalanceTran;
			transData.OpeningBalanceLocal = DrLocal;
			transData.BalanceLocal += transData.OpeningBalanceLocal;
			DrLocal = 0m;
			DrBase = DrLocal;
			Debit = GetLedgerBalanceFromDictionary(objInputData.Product, LedgerBalanceType.PDCBalance, ref dictionary, ref DrLocal, ref DrBase);
			transData.PDCBalance = DrBase;
			transData.Balance += (double)transData.PDCBalance;
			transData.PDCBalanceTran = Debit;
			transData.BalanceTran += transData.PDCBalanceTran;
			transData.PDCBalanceLocal = DrLocal;
			transData.BalanceLocal += transData.PDCBalanceLocal;
			list2 = new List<TopCreditNDebitDetails>();
			text = string.Format("SELECT TOP {1} iDate, Voucher, Account,\r\n                CASE WHEN Amt1 - Amt2 < 0 THEN (Amt1 - Amt2)*-1 ELSE 0 END [Credit]\r\n                FROM \r\n                (\r\n                    SELECT tCore_Data{0}.iBodyId, tCore_Header{0}.iDate,cCore_Vouchers{0}.sAbbr+' : '+tCore_Header{0}.sVoucherNo[Voucher],\r\n                    mCore_Account.iMasterId[iMasterId],\r\n                    CASE \r\n                    WHEN mCore_Account.iMasterId = tCore_Data{0}.iCode\r\n                    THEN mBook.sName\r\n                    ELSE \r\n                    mCode.sName\r\n                    END[Account],\r\n\r\n                    CASE \r\n                    WHEN mCore_Account.iMasterId = tCore_Data{0}.iCode\r\n                    THEN \r\n                        CASE \r\n                        WHEN tCore_Data{0}.mAmount1 < 0 THEN tCore_Data{0}.mAmount1 * -1 \r\n                        ELSE 0 \r\n                        END\r\n                    ELSE \r\n                        CASE \r\n                        WHEN tCore_Data{0}.mAmount1 > 0 THEN tCore_Data{0}.mAmount1\r\n                        ELSE 0 \r\n                        END\r\n                    END[Amt1],\r\n                    CASE \r\n                    WHEN mCore_Account.iMasterId = tCore_Data{0}.iBookNo\r\n                    THEN \r\n                        CASE \r\n                        WHEN tCore_Data{0}.mAmount1 < 0 THEN tCore_Data{0}.mAmount1 * -1 \r\n                        ELSE 0 \r\n                        END\r\n                    ELSE \r\n                        CASE \r\n                        WHEN tCore_Data{0}.mAmount1 > 0 THEN tCore_Data{0}.mAmount1\r\n                        ELSE 0 \r\n                        END\r\n                    END[Amt2]\r\n                    FROM tCore_Header{0} JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                    JOIN mCore_Account ON mCore_Account.iMasterId = tCore_Data{0}.iBookNo OR mCore_Account.iMasterId = tCore_Data{0}.iCode \r\n                    JOIN mCore_Account mBook ON mBook.iMasterId = tCore_Data{0}.iBookNo\r\n                    JOIN mCore_Account mCode ON mCode.iMasterId = tCore_Data{0}.iCode\r\n                    JOIN cCore_Vouchers{0} ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n                    WHERE cCore_Vouchers{0}.bUpdateFA = 1 {3}\r\n                )TempTable where iMasterId = {2} and (Amt1 - Amt2) < 0 \r\n                ORDER BY iDate DESC", m_strSuffix, objInputData.RowsSelected, objInputData.Product, text2);
			dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				list2.Add(new TopCreditNDebitDetails
				{
					Date = rDConversion.SetDateFormat(StandardDataFormat.Default, Convert.ToInt32(dataReader["iDate"]), null),
					Voucher = Convert.ToString(dataReader["Voucher"]),
					Account = Convert.ToString(dataReader["Account"]),
					CrDr = Convert.ToString(dataReader["Credit"]),
					IsDebit = false
				});
			}
			dataReader.Close();
			text = string.Format("SELECT top {1} iDate, Voucher, Account,\r\n                CASE WHEN Amt1 - Amt2 > 0 THEN (Amt1 - Amt2) ELSE 0 END [Debit]\r\n                FROM \r\n                (\r\n                    SELECT tCore_Data{0}.iBodyId, tCore_Header{0}.iDate,cCore_Vouchers{0}.sAbbr+' : '+tCore_Header{0}.sVoucherNo[Voucher],\r\n                    mCore_Account.iMasterId[iMasterId],\r\n                    CASE \r\n                    WHEN mCore_Account.iMasterId = tCore_Data{0}.iCode\r\n                    THEN mBook.sName\r\n                    ELSE \r\n                    mCode.sName\r\n                    END[Account],\r\n\r\n                    CASE \r\n                    WHEN mCore_Account.iMasterId = tCore_Data{0}.iCode\r\n                    THEN \r\n                        CASE \r\n                        WHEN tCore_Data{0}.mAmount1 < 0 THEN tCore_Data{0}.mAmount1 * -1 \r\n                        ELSE 0 \r\n                        END\r\n                    ELSE \r\n                        CASE \r\n                        WHEN tCore_Data{0}.mAmount1 > 0 THEN tCore_Data{0}.mAmount1\r\n                        ELSE 0 \r\n                        END\r\n                    END[Amt1],\r\n                    CASE \r\n                    WHEN mCore_Account.iMasterId = tCore_Data{0}.iBookNo\r\n                    THEN \r\n                        CASE \r\n                        WHEN tCore_Data{0}.mAmount1 < 0 THEN tCore_Data{0}.mAmount1*-1 \r\n                        ELSE 0 \r\n                        END\r\n                    ELSE \r\n                        CASE \r\n                        WHEN tCore_Data{0}.mAmount1 > 0 THEN tCore_Data{0}.mAmount1\r\n                        ELSE 0 \r\n                        END\r\n                    END[Amt2]\r\n                    FROM tCore_Header{0} JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                    JOIN mCore_Account ON mCore_Account.iMasterId = tCore_Data{0}.iBookNo OR mCore_Account.iMasterId = tCore_Data{0}.iCode \r\n                    JOIN mCore_Account mBook ON mBook.iMasterId = tCore_Data{0}.iBookNo\r\n                    JOIN mCore_Account mCode ON mCode.iMasterId = tCore_Data{0}.iCode\r\n                    JOIN cCore_Vouchers{0} ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n                    WHERE cCore_Vouchers{0}.bUpdateFA = 1 {3}\r\n                )TempTable where iMasterId = {2} and (Amt1 - Amt2) > 0 \r\n                ORDER BY iDate DESC", m_strSuffix, objInputData.RowsSelected, objInputData.Product, text2);
			dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				list2.Add(new TopCreditNDebitDetails
				{
					Date = rDConversion.SetDateFormat(StandardDataFormat.Default, Convert.ToInt32(dataReader["iDate"]), null),
					Voucher = Convert.ToString(dataReader["Voucher"]),
					Account = Convert.ToString(dataReader["Account"]),
					CrDr = Convert.ToString(dataReader["Debit"]),
					IsDebit = true
				});
			}
			dataReader.Close();
			transData.arrTopCreditNDebitDetails = list2.ToArray();
			if (objInputData.ExtraFields != null && objInputData.ExtraFields.Length != 0)
			{
				list = new List<IdNamePair>();
				text = "SELECT iFieldId,'vr'+sModule+'_'+sMasterName+'.'+sFieldName[sFieldName] \r\n                    FROM cCore_MasterFields JOIN cCore_MasterTables ON cCore_MasterTables.iTableId = cCore_MasterFields.iTableId\r\n                    JOIN cCore_MasterTabs ON cCore_MasterTabs.iTabId = cCore_MasterTables.iTabId\r\n                    JOIN cCore_MasterDef ON cCore_MasterDef.iMasterTypeId = cCore_MasterTabs.iMasterId\r\n                    WHERE iFieldId IN(" + string.Join(",", objInputData.ExtraFields) + ")";
				dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				while (dataReader.Read())
				{
					list.Add(new IdNamePair(Convert.ToInt32(dataReader["iFieldId"]), Convert.ToString(dataReader["sFieldName"]), null));
				}
				dataReader.Close();
				text = string.Format("SELECT {0} \r\n                        FROM vrCore_Account WHERE iMasterId = {1}", string.Join(",", from p in list
					where string.IsNullOrEmpty(Convert.ToString(p.Tag))
					select p.Name), objInputData.Product);
				dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				if (dataReader.Read())
				{
					for (int num = 0; num < list.Count; num++)
					{
						list[num].Tag = dataReader[num];
					}
				}
				dataReader.Close();
				transData.ExtraValues = list.Select((IdNamePair p) => new IdValuePair(p.ID, p.Tag)).ToArray();
			}
		}
		catch (Exception ex)
		{
			m_sError = $"GetAccountQueryData : {ex.Message}";
		}
		return transData;
	}

	public TagwiseBalance[] LoadDepartmentwiseData(int iMasterId, int iAccountingDate, int iCompId, int iUserId)
	{
		bool bExclude = false;
		decimal num = 0m;
		decimal num2 = 0m;
		string text = null;
		string text2 = null;
		string text3 = null;
		Database database = null;
		IDataReader dataReader = null;
		List<TagwiseBalance> list = null;
		TagwiseBalance tagwiseBalance = null;
		list = new List<TagwiseBalance>();
		try
		{
			database = DatabaseWrapper.GetDatabase2(iCompId);
			if (iUserId > 1 && _focus.company(iCompId).getPreferenceValue(PreferenceCategories.Print, 36) == 0)
			{
				text3 = CheckRoleMasters(_focus.company(iCompId).faTagId, iUserId, ref bExclude, database);
				if (!string.IsNullOrEmpty(text3))
				{
					text3 = ((!bExclude) ? $" AND iFaTag IN ({text3})" : $" AND iFaTag NOT IN ({text3})");
				}
			}
			text2 = FConvert.GetSuffix(iCompId);
			text = string.Format("SELECT {2}.iMasterId, {2}.sName,SUM(Debit)[Debit], SUM(Credit)[Credit]\r\n                FROM \r\n                (\r\n                    SELECT tCore_Data{0}.iBodyId,iBookNo[iMasterId],\r\n                    CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n                    CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit\r\n                    FROM \r\n                    tCore_Data{0} \r\n                    JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                    JOIN cCore_Vouchers{0} ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n                    JOIN mCore_Account ON tCore_Data{0}.iCode = mCore_Account.iMasterId\r\n                    WHERE tCore_Data{0}.iBookNo  <> 2\r\n                    UNION ALL\r\n                    SELECT tCore_Data{0}.iBodyId,  iCode[iMasterId],\r\n                    CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n                    CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit\r\n                    FROM \r\n                    tCore_Data{0}  \r\n                    JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                    JOIN cCore_Vouchers{0} ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n                    JOIN mCore_Account ON tCore_Data{0}.iBookNo = mCore_Account.iMasterId\r\n                    WHERE tCore_Data{0}.iCode  <> 2\r\n                    UNION ALL\r\n                    SELECT TOP 1 tCore_Data{0}.iBodyId, iBookNo[iMasterId], mAmount1,0\r\n                    from tCore_Data{0}  \r\n                    JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                    WHERE tCore_Data{0}.iBookNo  = 2\r\n                )InnerTable\r\n                JOIN tCore_Data{0} ON tCore_Data{0}.iBodyId = InnerTable.iBodyId  \r\n                JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                JOIN mCore_Account ON tCore_Data{0}.iBookNo = mCore_Account.iMasterId \r\n                LEFT JOIN {2} ON {2}.iMasterId = tCore_Data{0}.iFaTag\r\n                WHERE (tCore_Data{0}.bUpdateFA = 1) \r\n                AND tCore_Data{0}.bSuspendUpdateFA <> 1 \r\n                AND tCore_Data{0}.iAuthStatus < 2 AND tCore_Header{0}.bSuspended = 0\r\n                AND iDate BETWEEN 0 AND {1} \r\n                AND InnerTable.iMasterId = {3} {4}\r\n                GROUP BY {2}.iMasterId, {2}.sName\r\n                HAVING SUM(Debit) < 0 or SUM(Credit) > 0", text2, iAccountingDate, _focus.company(iCompId).faTagName, iMasterId, text3);
			dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				tagwiseBalance = new TagwiseBalance();
				num = Convert.ToDecimal(dataReader["Debit"]);
				num2 = Convert.ToDecimal(dataReader["Credit"]);
				tagwiseBalance.Id = Convert.ToInt32(dataReader["iMasterId"]);
				tagwiseBalance.Name = Convert.ToString(dataReader["sName"]);
				tagwiseBalance.Quantity = num + num2;
				list.Add(tagwiseBalance);
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			m_sError = $"LoadDepartmentwiseData : {ex.Message}";
			tagwiseBalance = new TagwiseBalance();
			tagwiseBalance.Id = -1;
			tagwiseBalance.Name = ex.Message;
			list.Add(tagwiseBalance);
		}
		return list.ToArray();
	}

	private void GetAccountingDrCr(int iMasterId, string sFaTagFilter, ref decimal Credit, ref decimal Debit, ref decimal DrLocal, ref decimal CrLocal, ref decimal DrBase, ref decimal CrBase, int iCompId)
	{
		IDataReader dataReader = null;
		string text = null;
		text = string.Format("SELECT SUM(Debit)[Debit], SUM(Credit)[Credit],\r\n            SUM(TranDr)[TranDr], SUM(TranCr)[TranCr],SUM(LocalDr)[LocalDr], SUM(LocalCr)[LocalCr],[iMasterId]\r\n            FROM\r\n            (\r\n\t            SELECT iBookNo[iMasterId],\r\n\t            CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t            CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit,\r\n                CASE WHEN ISNULL(mFxAmount2,mAmount2) < 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranDr, \r\n\t            CASE WHEN ISNULL(mFxAmount2,mAmount2) > 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranCr,\r\n                CASE WHEN ISNULL(fLocalAmount2,0) < 0 THEN ISNULL(fLocalAmount2,0) ELSE 0 END LocalDr, \r\n\t            CASE WHEN ISNULL(fLocalAmount2,0) > 0 THEN ISNULL(fLocalAmount2,0) ELSE 0 END LocalCr\r\n                FROM tCore_Header{0}\r\n\t            JOIN tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t            LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId\r\n\t            WHERE iBookNo = {1} AND (tCore_Data{0}.bUpdateFA = 1) AND tCore_Data{0}.bSuspendUpdateFA <> 1 AND bSuspended=0\r\n                AND tCore_Data{0}.iAuthStatus < 2 AND tCore_Header{0}.bSuspended = 0\r\n                AND tCore_Header{0}.iVoucherClass <> 256 {2}\r\n\t            UNION ALL\r\n\t            SELECT iCode[iMasterId],\r\n\t            CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n                CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit,\r\n                CASE WHEN ISNULL(mFxAmount1,mAmount1) < 0 THEN ISNULL(mFxAmount1,mAmount1) ELSE 0 END TranDr, \r\n\t            CASE WHEN ISNULL(mFxAmount1,mAmount1) > 0 THEN ISNULL(mFxAmount1,mAmount1) ELSE 0 END TranCr,\r\n                CASE WHEN ISNULL(fLocalAmount1,0) < 0 THEN ISNULL(fLocalAmount1,0) ELSE 0 END LocalDr, \r\n\t            CASE WHEN ISNULL(fLocalAmount1,0) > 0 THEN ISNULL(fLocalAmount1,0) ELSE 0 END LocalCr\r\n\t            FROM tCore_Header{0}\r\n\t            JOIN tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t            LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId\r\n                WHERE iCode = {1} AND tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA <> 1 AND bSuspended=0                    \r\n                AND tCore_Data{0}.iAuthStatus < 2 AND tCore_Header{0}.bSuspended = 0\r\n                AND tCore_Header{0}.iVoucherClass <> 256 {2}\r\n            )TempTable GROUP BY [iMasterId]", m_strSuffix, iMasterId, sFaTagFilter);
		dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		if (dataReader.Read())
		{
			CrBase = Convert.ToDecimal(dataReader["Credit"]);
			DrBase = Convert.ToDecimal(dataReader["Debit"]);
			Debit = Convert.ToDecimal(dataReader["TranDr"]);
			Credit = Convert.ToDecimal(dataReader["TranCr"]);
			DrLocal = Convert.ToDecimal(dataReader["LocalDr"]);
			CrLocal = Convert.ToDecimal(dataReader["LocalCr"]);
		}
		dataReader.Close();
	}

	private void ArrangeAuditMasters(ref ReportMatrix objData, RepRecord objRec, int iFieldCount, int iCompId)
	{
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		int num5 = 0;
		bool flag = false;
		bool flag2 = false;
		List<LineData> list = null;
		bool flag3 = _focus.company(m_iCompanyId).securityLevel == 2;
		int num6 = iFieldCount + (flag3 ? 1 : 0);
		flag = _focus.company(iCompId).getPreferenceValue(PreferenceCategories.Misc, 51) > 0;
		list = new List<LineData>();
		string text = string.Empty;
		DocHistory[] array = null;
		LineData lineData = null;
		_ = string.Empty;
		flag = _focus.company(iCompId).getPreferenceValue(PreferenceCategories.Misc, 51) > 0;
		list = new List<LineData>();
		if (flag)
		{
			text = new Focus.Transactions.BL.Transactions().GetAuditFolderPath();
			if (objRec.CurrentPage == 0 && objRec.Code > 0 && objData != null && !string.IsNullOrEmpty(objData.UniqueId) && File.Exists(string.Format("{0}\\{1}\\{1}AuditMrHeader{2}.fdf", text, FConvert.CompanyCodeFromId(iCompId), objRec.Code)))
			{
				new FilesDB($"{text}\\{FConvert.CompanyCodeFromId(iCompId)}", AuditType.Masters);
			}
			if (!string.IsNullOrEmpty(text))
			{
				string.Format("{0}\\{1}\\{1}AuditMrHeader", text, FConvert.CompanyCodeFromId(iCompId));
			}
			flag2 = FConvert.GetInputValue(objRec.Inputs, 1) == 1;
		}
		for (num2 = 0; num2 < objData.ColumnData.Length; num2++)
		{
			if (objData.ColumnData[num2].CellData.Length >= 8)
			{
				num4 = ((ReportRowHeader)objData.ColumnData[num2].CellData[0]).Id;
				num5 = Convert.ToInt32(objData.ColumnData[num2].CellData[1]);
				num3 = objRec.Code;
			}
			if (num3 <= 0)
			{
				continue;
			}
			if (!flag)
			{
				((ReportRowHeader)objData.ColumnData[num2].CellData[0]).LongId = num5;
				((ReportRowHeader)objData.ColumnData[num2].CellData[0]).SetColumnId = num3;
				list.Add(objData.ColumnData[num2]);
			}
			else
			{
				if (!new FileInfo(string.Format("{0}\\{1}\\{1}AuditMrHeader{2}.fdf", text, FConvert.CompanyCodeFromId(iCompId), objRec.Code)).Exists)
				{
					continue;
				}
				array = GetMasterHistoryFromFile(num3, num4, iCompId, text);
				if (array == null || array.Length == 0)
				{
					continue;
				}
				array = array.OrderByDescending((DocHistory p) => p.AuditId).ToArray();
				for (num = 0; num < array.Length; num++)
				{
					if (!flag2 || (array[num].Date >= objRec.StartingDate && array[num].Date <= objRec.EndingDate))
					{
						lineData = new LineData();
						lineData.CellData = new object[num6];
						lineData.CellData[0] = new ReportRowHeader
						{
							Id = num4,
							LongId = array[num].AuditId,
							SetColumnId = num3
						};
						lineData.CellData[1] = array[num].AuditId;
