	public DocHistory[] GetMasterHistoryFromFile(int iMasterTypeId, int iHeaderId, int iCompId, string strFolder)
	{
		strFolder = FConvert.GetCompAuditFolder(strFolder, iCompId);
		FilesDB filesDB = new FilesDB(strFolder, AuditType.Masters);
		List<AuditTrailHeader> lstHeaders = filesDB.FindAll(iHeaderId, iMasterTypeId, iCompId);
		filesDB.CloseRead();
		List<DocHistory> list = new List<DocHistory>();
		if (lstHeaders.Count > 0)
		{
			List<int> list2 = new List<int>();
			for (int i = 0; i < lstHeaders.Count; i++)
			{
				if (!list2.Contains(lstHeaders[i].iUserId))
				{
					list2.Add(lstHeaders[i].iUserId);
				}
			}
			Database database = DatabaseWrapper.GetDatabase2(iCompId);
			FConvert.GetYearId(iCompId);
			IDataReader dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre("select iUserId, sLoginName from mSec_Users where iUserId in (" + FConvert.ArrayToCommaSeparated(list2.ToArray()) + ")") : ("select iUserId, sLoginName from mSec_Users where iUserId in (" + FConvert.ArrayToCommaSeparated(list2.ToArray()) + ")"));
			List<IdNamePair> list3 = new List<IdNamePair>();
			while (dataReader.Read())
			{
				list3.Add(new IdNamePair
				{
					ID = Convert.ToInt32(dataReader[0]),
					Name = Convert.ToString(dataReader[1])
				});
			}
			dataReader.Close();
			string text = $" Select sModule+'_'+sMasterName sMasterName from cCore_MasterDef where iMasterTypeId={iMasterTypeId}";
			string arg = Convert.ToString(database.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
			string createdBy = Convert.ToString(database.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre($"select sLoginName from m{arg} a join mSec_Users b on a.iCreatedBy = b.iUserId where iMasterId = {iHeaderId}") : $"select sLoginName from m{arg} a join mSec_Users b on a.iCreatedBy = b.iUserId where iMasterId = {iHeaderId}"));
			int j;
			for (j = 0; j < lstHeaders.Count; j++)
			{
				DocHistory docHistory = new DocHistory();
				docHistory.AuditId = lstHeaders[j].iPos;
				docHistory.CreatedBy = createdBy;
				docHistory.Date = lstHeaders[j].iModifiedDate;
				docHistory.HeaderId = iHeaderId;
				docHistory.Time = lstHeaders[j].iModifiedTime;
				docHistory.ModifiedBy = list3.Where((IdNamePair p) => p.ID == lstHeaders[j].iUserId).ToArray()[0].Name;
				docHistory.EditReason = lstHeaders[j].EditReason;
				docHistory.ActionType = lstHeaders[j].iActionType;
				list.Add(docHistory);
			}
		}
		return list.ToArray();
	}

	private IdNamePair[] GetMenuNames(int[] arrMenuIds, int iCompId)
	{
		string text = "SELECT iMenuId, REPLACE(mCore_Menu.sMenuText,'_','')[sMenuText] FROM mCore_Menu WHERE iMenuId in (" + FConvert.ArrayToCommaSeparated(arrMenuIds) + ")";
