				ID = Convert.ToInt32(dataReader[0]),
				Name = Convert.ToString(dataReader[1])
			});
		}
		dataReader.Close();
		return list.ToArray();
	}

	private void ArrangeAuditPricebook(ref ReportMatrix objData, RepRecord objRec, int iFieldCount, int iCompId)
