			if (objRec.CurrentPage == 0 && objData != null && !string.IsNullOrEmpty(objData.UniqueId) && File.Exists(string.Format("{0}\\{1}\\{1}AuditPBHeader{2}.fdf", text, FConvert.CompanyCodeFromId(iCompId), b)))
			{
				list2 = new FilesDB($"{text}\\{FConvert.CompanyCodeFromId(iCompId)}", AuditType.Pricebook).FindAllDeleted(objRec.StartingDate, 0, objRec.EndingDate, 0, b, iCompId);
				list2 = list2.Where((AuditTrailHeader p) => p.iHeaderId == objRec.Code).ToList();
			}
			if (!string.IsNullOrEmpty(text))
			{
				string.Format("{0}\\{1}\\{1}AuditPBHeader", text, FConvert.CompanyCodeFromId(iCompId));
			}
			flag2 = FConvert.GetInputValue(objRec.Inputs, 1) == 1;
		}
		for (num2 = 0; num2 < objData.ColumnData.Length; num2++)
		{
			if (objData.ColumnData[num2].CellData.Length >= 8)
			{
				num3 = ((ReportRowHeader)objData.ColumnData[num2].CellData[0]).Id;
				num4 = Convert.ToInt32(objData.ColumnData[num2].CellData[1]);
				b = Convert.ToByte(objData.ColumnData[num2].CellData[2]);
				iSequenceNo = Convert.ToInt32(objData.ColumnData[num2].CellData[6]);
			}
			if (!flag)
			{
				((ReportRowHeader)objData.ColumnData[num2].CellData[0]).LongId = num4;
				((ReportRowHeader)objData.ColumnData[num2].CellData[0]).SetColumnId = b;
				list.Add(objData.ColumnData[num2]);
			}
			else
			{
				if (!new FileInfo(string.Format("{0}\\{1}\\{1}AuditPBHeader{2}.fdf", text, FConvert.CompanyCodeFromId(iCompId), b)).Exists)
				{
					continue;
				}
				array = GetPBHistoryFromFile(b, num3, iSequenceNo, iCompId, text, 1);
				if (array == null || array.Length == 0)
				{
					continue;
				}
				array = array.OrderByDescending((DocHistory p) => p.AuditId).ToArray();
				for (num = 0; num < array.Length; num++)
				{
					if (!flag2 || (array[num].Date >= objRec.StartingDate && array[num].Date <= objRec.EndingDate))
					{
						lineData = new LineData();
						lineData.CellData = new object[num5];
						lineData.CellData[0] = new ReportRowHeader
						{
							Id = num3,
							LongId = array[num].AuditId,
							SetColumnId = b
						};
