						lineData.CellData[3] = objData.ColumnData[num2].CellData[3];
						lineData.CellData[4] = objData.ColumnData[num2].CellData[4];
						lineData.CellData[5] = objData.ColumnData[num2].CellData[5];
						lineData.CellData[6] = objData.ColumnData[num2].CellData[6];
						lineData.CellData[7] = objData.ColumnData[num2].CellData[7];
						lineData.CellData[8] = Date.DateToInt(new FDateTime(Convert.ToInt64(objData.ColumnData[num2].CellData[8]), m_objCalType).DateTime.Date);
						lineData.CellData[9] = Time.TimeToInt(new FDateTime(Convert.ToInt64(objData.ColumnData[num2].CellData[8]), m_objCalType).DateTime);
