		if (objRec.Code > 0 && objData.EndOfFile && list2 != null && list2.Count > 0)
		{
			b = (byte)FConvert.GetInputValue(objRec.Inputs, 0);
			for (num2 = 0; num2 < list2.Count; num2++)
			{
				num3 = objRec.Code;
				if (new FileInfo(string.Format("{0}\\{1}\\{1}AuditPBHeader{2}.fdf", text, FConvert.CompanyCodeFromId(iCompId), b)).Exists)
				{
					array = GetPBHistoryFromFile(b, num3, iSequenceNo, iCompId, text, 2);
