					for (num = 0; num < array.Length; num++)
					{
						if (array[num].AuditId == list2[num2].iPos)
						{
							lineData = new LineData();
							lineData.CellData = new object[num5];
							lineData.CellData[0] = new ReportRowHeader
							{
								Id = -num3,
								LongId = array[num].AuditId,
								SetColumnId = b
							};
							lineData.CellData[1] = array[num].AuditId;
							lineData.CellData[2] = b;
							lineData.CellData[3] = objRec.CodeName;
							lineData.CellData[4] = array[num].DocNo;
							lineData.CellData[5] = "";
							lineData.CellData[6] = 0;
							lineData.CellData[7] = (string.IsNullOrEmpty(array[num].CreatedBy) ? "SU" : array[num].CreatedBy);
							lineData.CellData[8] = array[num].Date;
