					objData.EndOfFile = true;
				}
			}
		}
		objData.ColumnData = list.ToArray();
	}

	public DocHistory[] GetPBHistoryFromFile(byte bPricebookType, int iPricebookId, int iSequenceNo, int iCompId, string strFolder, byte iActionType)
	{
		List<IdNamePair> list = new List<IdNamePair>();
		strFolder = FConvert.GetCompAuditFolder(strFolder, iCompId);
		FilesDB filesDB = new FilesDB(strFolder, AuditType.Pricebook);
		List<AuditTrailHeader> lstHeaders = filesDB.FindAll(iPricebookId, bPricebookType, iCompId);
		lstHeaders = lstHeaders.Where((AuditTrailHeader p) => p.iActionType == iActionType).ToList();
		List<DocHistory> list2 = new List<DocHistory>();
		string arg = ((bPricebookType == 1) ? "mCore_BuyingPriceBookDetails" : "mCore_SellingPriceBookDetails");
		if (lstHeaders.Count > 0)
		{
			List<int> list3 = new List<int>();
			for (int num = 0; num < lstHeaders.Count; num++)
			{
				if (!list3.Contains(lstHeaders[num].iUserId))
				{
					list3.Add(lstHeaders[num].iUserId);
				}
			}
			Database database = DatabaseWrapper.GetDatabase2(iCompId);
			FConvert.GetYearId(iCompId);
			IDataReader dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre("select iUserId, sLoginName from mSec_Users where iUserId in (" + FConvert.ArrayToCommaSeparated(list3.ToArray()) + ")") : ("select iUserId, sLoginName from mSec_Users where iUserId in (" + FConvert.ArrayToCommaSeparated(list3.ToArray()) + ")"));
			List<IdNamePair> list4 = new List<IdNamePair>();
			while (dataReader.Read())
			{
				list4.Add(new IdNamePair
				{
					ID = Convert.ToInt32(dataReader[0]),
					Name = Convert.ToString(dataReader[1])
				});
			}
			dataReader.Close();
			string createdBy = string.Empty;
			if (iActionType == 1)
			{
				createdBy = Convert.ToString(database.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre($"select sLoginName from {arg} a join mSec_Users b on a.iCreatedBy = b.iUserId where iPricebookId = {iPricebookId}") : $"select sLoginName from {arg} a join mSec_Users b on a.iCreatedBy = b.iUserId where iPricebookId = {iPricebookId}"));
			}
			int i;
			for (i = 0; i < lstHeaders.Count; i++)
			{
				list = filesDB.LoadDocWithPos(bPricebookType, lstHeaders[i].iPos, iCompId);
				if (iActionType == 1)
				{
					list = list.Where((IdNamePair p) => Convert.ToInt32(p.Tag) == iSequenceNo).ToList();
				}
				if (list.Count <= 0)
				{
					continue;
				}
				DocHistory docHistory = new DocHistory();
				docHistory.AuditId = lstHeaders[i].iPos;
				docHistory.CreatedBy = createdBy;
				docHistory.Date = lstHeaders[i].iModifiedDate;
				docHistory.HeaderId = iPricebookId;
				docHistory.Time = lstHeaders[i].iModifiedTime;
				docHistory.ModifiedBy = list4.Where((IdNamePair p) => p.ID == lstHeaders[i].iUserId).ToArray()[0].Name;
				docHistory.ActionType = lstHeaders[i].iActionType;
				docHistory.EditReason = lstHeaders[i].EditReason;
				if (iActionType == 2 && list.Count > 1)
				{
					docHistory.DocNo = list[1].Name;
					iSequenceNo = ((Convert.ToInt32(list[1].Tag) > 0) ? Convert.ToInt32(list[1].Tag) : iSequenceNo);
					string text = $"select sLoginName, a.iCreatedDate from {arg} a join mSec_Users b on a.iCreatedBy = b.iUserId where iPricebookId = {iPricebookId} and a.iSequenceNumber = {iSequenceNo}";
					IDataReader dataReader2 = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
					while (dataReader2.Read())
					{
						docHistory.CreatedBy = dataReader2["sLoginName"].ToString();
						docHistory.Date = new FDateTime().LongToInt(Convert.ToInt64(dataReader2["iCreatedDate"]));
						docHistory.Time = new FDateTime().IntToTime(Convert.ToInt64(dataReader2["iCreatedDate"]));
					}
					dataReader2.Close();
				}
				list2.Add(docHistory);
			}
		}
		filesDB.CloseRead();
		return list2.ToArray();
	}

