	public DocHistory[] GetAuthAuditTrailHistoryFromFile(int iDocumentId, int iAuthorizationId, int iCompId, string strFolder, AuditType m_AuditType, int iActionType)
	{
		strFolder = FConvert.GetCompAuditFolder(strFolder, iCompId);
		FilesDB filesDB = new FilesDB(strFolder, m_AuditType);
		List<AuditTrailHeader> lstHeaders = filesDB.FindAll(iAuthorizationId, iDocumentId, iCompId);
		lstHeaders = lstHeaders.Where((AuditTrailHeader p) => p.iActionType == iActionType).ToList();
		filesDB.CloseRead();
		List<DocHistory> list = new List<DocHistory>();
		if (lstHeaders.Count > 0)
		{
			List<int> list2 = new List<int>();
			for (int num = 0; num < lstHeaders.Count; num++)
			{
				if (!list2.Contains(lstHeaders[num].iUserId))
				{
					list2.Add(lstHeaders[num].iUserId);
				}
			}
			Database database = DatabaseWrapper.GetDatabase2(iCompId);
			byte yearId = FConvert.GetYearId(iCompId);
			IDataReader dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre("select iUserId, sLoginName from mSec_Users where iUserId in (" + FConvert.ArrayToCommaSeparated(list2.ToArray()) + ")") : ("select iUserId, sLoginName from mSec_Users where iUserId in (" + FConvert.ArrayToCommaSeparated(list2.ToArray()) + ")"));
			List<IdNamePair> list3 = new List<IdNamePair>();
			while (dataReader.Read())
			{
				list3.Add(new IdNamePair
				{
					ID = Convert.ToInt32(dataReader[0]),
					Name = Convert.ToString(dataReader[1])
				});
			}
			dataReader.Close();
			string createdBy = Convert.ToString(database.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre($"select sLoginName from tCore_Header_{yearId} a join mSec_Users b on a.iUserId = b.iUserId where iHeaderId = {iAuthorizationId}") : $"select sLoginName from tCore_Header_{yearId} a join mSec_Users b on a.iUserId = b.iUserId where iHeaderId = {iAuthorizationId}"));
			int i;
			for (i = 0; i < lstHeaders.Count; i++)
			{
				DocHistory docHistory = new DocHistory();
				docHistory.AuditId = lstHeaders[i].iPos;
				docHistory.CreatedBy = createdBy;
				docHistory.Date = lstHeaders[i].iModifiedDate;
				docHistory.HeaderId = iAuthorizationId;
				docHistory.Time = lstHeaders[i].iModifiedTime;
				docHistory.ModifiedBy = list3.Where((IdNamePair p) => p.ID == lstHeaders[i].iUserId).ToArray()[0].Name;
				docHistory.ActionType = lstHeaders[i].iActionType;
				list.Add(docHistory);
			}
		}
		return list.ToArray();
	}

