			if ((finalAccountTreeData.IsGroup && finalAccountTreeData.Level < inputValue) || finalAccountTreeData.Credit != 0m || finalAccountTreeData.Debit != 0m || Convert.ToDecimal(lineData.CellData[2]) != 0m)
