	private IdNamePair[] GetProductInStock(RepRecord objRec, string strInvTag, FieldData[] arrExtraField)
	{
		IDataReader dataReader = null;
		string text = null;
		string text2 = null;
		string text3 = null;
		List<IdNamePair> list = null;
		List<IdValuePair> list2 = null;
		list = new List<IdNamePair>();
		if (arrExtraField != null && arrExtraField.Length != 0)
		{
			for (int i = 0; i < arrExtraField.Length; i++)
			{
				text3 += ",";
				if (arrExtraField[i].FieldName.Contains("vrCore_Product"))
				{
					text3 += arrExtraField[i].FieldName;
				}
				else
				{
					text3 = ((arrExtraField[i].DataType != MasterDataType.Text) ? (text3 + $"0[Col{i}]") : (text3 + $"''[Col{i}]"));
				}
			}
		}
		text = string.Format("SELECT DISTINCT vrCore_Product.iMasterId[iMasterId], vrCore_Product.sName[sName] \r\n            {3}\r\n            FROM tCore_Header{0} \r\n            JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n            JOIN tCore_Indta{0} ON tCore_Indta{0}.iBodyId = tCore_Data{0}.iBodyId\r\n            JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType \r\n            JOIN vrCore_Product ON tCore_Indta{0}.iProduct = vrCore_Product.iMasterId \r\n            WHERE tCore_Header{0}.bUpdateStocks = 1 AND tCore_Data{0}.bSuspendUpdateStocks <> 1 \r\n            AND tCore_Header{0}.bSuspended = 0 AND tCore_Header{0}.iDate BETWEEN {1} AND {2}\r\n            AND tCore_Indta{0}.fQuantityInBase <> 0 AND cCore_Vouchers{0}.bInventory  = 1 ", m_strSuffix, objRec.StartingDate, objRec.EndingDate, text3);
		if (objRec.Masters != null && !objRec.IsSelectAll)
		{
			text2 = General.GetMasters(objRec.Masters);
			text = text + " AND vrCore_Product.iMasterId IN (" + text2 + ")";
		}
		if (!string.IsNullOrEmpty(strInvTag))
		{
			text = text + " AND tCore_Data" + m_strSuffix + ".iInvTag IN (" + strInvTag + ")";
		}
		if (m_bClosed)
		{
			text = text + "UNION SELECT vrCore_Product.iMasterId[iBodyId], vrCore_Product.sName" + text3 + "\r\n                FROM tCore_ibalsOb" + m_strSuffix + " WITH (READUNCOMMITTED)\r\n                JOIN vrCore_Product ON tCore_ibalsOb" + m_strSuffix + ".iProduct = vrCore_Product.iMasterId AND vrCore_Product.iTreeId = 0";
			if (!string.IsNullOrEmpty(text2))
			{
				text = text + "AND tCore_ibalsOb" + m_strSuffix + ".iProduct IN (" + text2 + ")";
			}
		}
		dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		while (dataReader.Read())
		{
			if (arrExtraField != null && arrExtraField.Length != 0)
			{
				list2 = new List<IdValuePair>();
				for (int j = 0; j < arrExtraField.Length; j++)
				{
					list2.Add(new IdValuePair(3 + j, dataReader[2 + j]));
				}
