			list.Add(new IdNamePair(Convert.ToInt32(dataReader["iMasterId"]), Convert.ToString(dataReader["sName"]), list2?.ToArray()));
		}
		dataReader.Close();
		return list.ToArray();
	}

	private decimal GetProfit(int iProduct, int iInvTag, int iDate, bool bSales, int iUserId)
	{
		string text = string.Format("SELECT ISNULL(SUM(mStockValue), 0) TotalSales \r\n            FROM tCore_Header{0} \r\n            JOIN tCore_Data{0} ON tCore_Header{0} .iHeaderId = tCore_Data{0}.iHeaderId\r\n            JOIN tCore_Indta{0} ON tCore_Indta{0}.iBodyId = tCore_Data{0}.iBodyId\r\n            WHERE tCore_Header{0}.bUpdateStocks = 1\r\n            AND iProduct = {1} AND iDate <= {2} AND fQuantity {3} 0", m_strSuffix, iProduct, iDate, bSales ? "<" : ">");
		return Convert.ToDecimal(m_objDatabase.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
	}

	private Dictionary<int, FinalAccountTreeData> FilterData(RepRecord objRec, Dictionary<int, FinalAccountTreeData> arrTreeData, string[] arrAccountTypeFilter, bool bDontShowGroupTotal, bool bLinearReport, bool bGroupFilter, ref FinalAccountTreeData objAccountTotalData)
	{
		int num = 2;
