		bool flag2 = false;
		bool flag3 = false;
		FinalAccountTreeData objData = null;
		Dictionary<int, FinalAccountTreeData> dictionary = null;
		if (objAccountTotalData == null)
		{
			objAccountTotalData = new FinalAccountTreeData();
		}
		num = FConvert.GetInputValue(objRec.Inputs, 1);
		int iFormatType = Convert.ToInt32(FConvert.GetInputValue(objRec.Inputs, 3));
		bool bIncludeZeroGroupWithNonZeroChild = FConvert.GetInputValue(objRec.Inputs, 12) > 0 && num <= 2;
		flag2 = Convert.ToBoolean(FConvert.GetInputValue(objRec.Inputs, 5)) || (objRec.ReportId == 531 && FConvert.GetInputValue(objRec.Inputs, 11) > 0);
		flag3 = FConvert.GetInputValue(objRec.Inputs, 14) > 0;
		dictionary = new Dictionary<int, FinalAccountTreeData>();
		foreach (KeyValuePair<int, FinalAccountTreeData> arrTreeDatum in arrTreeData)
		{
			objData = arrTreeDatum.Value;
			if ((!flag2 && !bGroupFilter && !IsNonZeroData(objData, num, objRec, bIncludeZeroGroupWithNonZeroChild, arrTreeData, iFormatType, flag3)) || (arrAccountTypeFilter.Length != 1 && arrAccountTypeFilter.Where((string p) => p == objData.AccountType.ToString()).Count() <= 0))
			{
				continue;
			}
			dictionary.Add(objData.MasterId, objData);
			if (((!flag || objData.IsGroup) && (objData.Level != 0 || (bDontShowGroupTotal && num == 2))) || (bLinearReport && objData.HideInFinalReports && !objData.IsGroup))
			{
				continue;
			}
			objAccountTotalData.Debit += objData.Debit;
			objAccountTotalData.Credit += objData.Credit;
			objAccountTotalData.DebitOpBal += objData.DebitOpBal;
			objAccountTotalData.CreditOpBal += objData.CreditOpBal;
			objAccountTotalData.DebitYTD += objData.DebitYTD;
			objAccountTotalData.CreditYTD += objData.CreditYTD;
			objAccountTotalData.DebitForPeriod += objData.DebitForPeriod;
			objAccountTotalData.CreditForPeriod += objData.CreditForPeriod;
			objAccountTotalData.DebitTran += objData.DebitTran;
			objAccountTotalData.CreditTran += objData.CreditTran;
			objAccountTotalData.DebitOpBalTran += objData.DebitOpBalTran;
			objAccountTotalData.CreditOpBalTran += objData.CreditOpBalTran;
			objAccountTotalData.DebitYTDTran += objData.DebitYTDTran;
			objAccountTotalData.CreditYTDTran += objData.CreditYTDTran;
			objAccountTotalData.DebitForPeriodTran += objData.DebitForPeriodTran;
