	private void getPreviousMonthBalance(TagWiseData[] arrTagData, int iTagwiseOption, int iMonthId, ref decimal dOpDr, ref decimal dOpCr)
	{
		if (iTagwiseOption != 1 || arrTagData == null)
		{
			return;
		}
		for (int i = 0; i < arrTagData.Length; i++)
		{
			if (arrTagData[i].TagId != iMonthId)
			{
				continue;
			}
			for (int num = ((iMonthId == 0) ? 11 : (iMonthId - 1)); num >= 0; num--)
			{
				if (arrTagData[num].Data != null && (arrTagData[num].Data.DebitYTD != 0m || arrTagData[num].Data.CreditYTD != 0m))
				{
					dOpDr += arrTagData[num].Data.DebitYTD;
					dOpCr += arrTagData[num].Data.CreditYTD;
					break;
				}
			}
			break;
		}
	}

	private void UpdateTagGroupData(List<int> arrTagwiseAccount, ref Dictionary<int, FinalAccountTreeData> arrTreeData)
	{
		int num = 0;
		int num2 = 0;
		FinalAccountTreeData value = null;
		if (arrTagwiseAccount != null)
		{
			for (num = 0; num < arrTagwiseAccount.Count; num++)
			{
				arrTreeData.TryGetValue(arrTagwiseAccount[num], out value);
				if (value != null && value.TagValues != null)
				{
					for (num2 = 0; num2 < value.TagValues.Length; num2++)
					{
						if (value.TagValues[num2].ChildTags == null)
						{
							continue;
						}
						for (int i = 0; i < value.TagValues[num2].ChildTags.Length; i++)
						{
							for (int j = 0; j < value.TagValues.Length; j++)
							{
								if (value.TagValues[num2].ChildTags[i] == value.TagValues[j].TagId)
								{
									value.TagValues[num2].Data.Debit += value.TagValues[j].Data.Debit;
									value.TagValues[num2].Data.Credit += value.TagValues[j].Data.Credit;
									value.TagValues[num2].Data.DebitOpBal += value.TagValues[j].Data.DebitOpBal;
									value.TagValues[num2].Data.CreditOpBal += value.TagValues[j].Data.CreditOpBal;
									value.TagValues[num2].Data.DebitYTD += value.TagValues[j].Data.DebitYTD;
									value.TagValues[num2].Data.CreditYTD += value.TagValues[j].Data.CreditYTD;
									value.TagValues[num2].Data.DebitForPeriod += value.TagValues[j].Data.DebitForPeriod;
									value.TagValues[num2].Data.CreditForPeriod += value.TagValues[j].Data.CreditForPeriod;
								}
							}
						}
					}
				}
				value = null;
			}
			return;
		}
		for (num = 0; num < arrTreeData.Count; num++)
		{
			value = arrTreeData.ElementAt(num).Value;
			if (value.TagValues == null)
			{
				continue;
			}
			for (num2 = 0; num2 < value.TagValues.Length; num2++)
			{
				if (value.TagValues[num2].ChildTags == null)
				{
					continue;
				}
				for (int k = 0; k < value.TagValues[num2].ChildTags.Length; k++)
				{
					for (int l = 0; l < value.TagValues.Length; l++)
					{
						if (value.TagValues[num2].ChildTags[k] == value.TagValues[l].TagId)
						{
							value.TagValues[num2].Data.Debit += value.TagValues[l].Data.Debit;
							value.TagValues[num2].Data.Credit += value.TagValues[l].Data.Credit;
							value.TagValues[num2].Data.DebitOpBal += value.TagValues[l].Data.DebitOpBal;
							value.TagValues[num2].Data.CreditOpBal += value.TagValues[l].Data.CreditOpBal;
							value.TagValues[num2].Data.DebitYTD += value.TagValues[l].Data.DebitYTD;
							value.TagValues[num2].Data.CreditYTD += value.TagValues[l].Data.CreditYTD;
							value.TagValues[num2].Data.DebitForPeriod += value.TagValues[l].Data.DebitForPeriod;
							value.TagValues[num2].Data.CreditForPeriod += value.TagValues[l].Data.CreditForPeriod;
						}
					}
				}
			}
		}
	}

	private void UpdateLastYearData(RepRecord objRec, string strSecurityFilter, string sTagJoinTable, ref Dictionary<int, FinalAccountTreeData> arrTreeData)
	{
		string strPrevYearSuffix = m_strPrevYearSuffix;
		string empty = string.Empty;
		DateTime dt = new Date(m_objCalType).IntToDate(objRec.StartingDate).AddYears(-1);
		int num = Date.DateToInt(dt);
		dt = new Date(m_objCalType).IntToDate(objRec.EndingDate).AddYears(-1);
		int num2 = Date.DateToInt(dt);
		int num3 = 0;
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		FinalAccountTreeData finalAccountTreeData = null;
		empty = $"tCore_Data{m_strPrevYearSuffix}.bUpdateFA = 1";
		string text = $"  SELECT iMasterId,\r\n            CASE WHEN SUM([Debit])+SUM([Credit]) < 0 THEN SUM([Debit])+SUM([Credit]) Else 0 End Debit,\r\n            CASE WHEN SUM([Debit])+SUM([Credit]) > 0 THEN SUM([Debit])+SUM([Credit]) Else 0 End Credit,\r\n            CASE WHEN SUM([TranDr])+SUM([TranCr]) < 0 THEN SUM([TranDr])+SUM([TranCr]) Else 0 End [TranDr],\r\n            CASE WHEN SUM([TranDr])+SUM([TranCr]) > 0 THEN SUM([TranDr])+SUM([TranCr]) Else 0 End [TranCr],\r\n            CASE WHEN SUM([LocalDr])+SUM([LocalCr]) < 0 THEN SUM([LocalDr])+SUM([LocalCr]) Else 0 End [LocalDr],\r\n            CASE WHEN SUM([LocalDr])+SUM([LocalCr]) > 0 THEN SUM([LocalDr])+SUM([LocalCr]) Else 0 End [LocalCr]\r\n            FROM \r\n            (\r\n                SELECT InnerTable.iMasterId, Debit, Credit, TranDr, TranCr ,LocalDr, LocalCr\r\n    \t        FROM \r\n\t            (\r\n\t\t            SELECT tCore_Data{strPrevYearSuffix}.iBodyId,iBookNo[iMasterId],\r\n\t\t            CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t\t            CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit,\r\n                    CASE WHEN ISNULL(mFxAmount2,mAmount2) < 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranDr, \r\n\t                CASE WHEN ISNULL(mFxAmount2,mAmount2) > 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranCr,\r\n                    CASE WHEN ISNULL(fLocalAmount2,0) < 0 THEN ISNULL(fLocalAmount2,0) ELSE 0 END LocalDr, \r\n\t                CASE WHEN ISNULL(fLocalAmount2,0) > 0 THEN ISNULL(fLocalAmount2,0) ELSE 0 END LocalCr \r\n\t\t            FROM tCore_Data{strPrevYearSuffix} \r\n\t\t            LEFT JOIN tCore_Data_FX{strPrevYearSuffix} ON tCore_Data_FX{strPrevYearSuffix}.iBodyId = tCore_Data{strPrevYearSuffix}.iBodyId\r\n\t\t            UNION ALL\r\n\t\t            SELECT tCore_Data{strPrevYearSuffix}.iBodyId,iCode[iMasterId],\r\n\t\t            CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n\t\t            CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit,\r\n                    CASE WHEN ISNULL(mFXAmount1,mAmount1) < 0 THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END TranDr, \r\n\t                CASE WHEN ISNULL(mFXAmount1,mAmount1) > 0 THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END TranCr,\r\n                    CASE WHEN ISNULL(fLocalAmount1,0) < 0 THEN ISNULL(fLocalAmount1,0) ELSE 0 END LocalDr, \r\n\t                CASE WHEN ISNULL(fLocalAmount1,0) > 0 THEN ISNULL(fLocalAmount1,0) ELSE 0 END LocalCr\r\n\t\t            FROM tCore_Data{strPrevYearSuffix} \r\n\t\t            LEFT JOIN tCore_Data_FX{strPrevYearSuffix} ON tCore_Data_FX{strPrevYearSuffix}.iBodyId = tCore_Data{strPrevYearSuffix}.iBodyId\r\n\t            )InnerTable\r\n\t            JOIN tCore_Data{strPrevYearSuffix} ON InnerTable.[iBodyId] = tCore_Data{strPrevYearSuffix}.iBodyId\r\n\t            JOIN tCore_Header{strPrevYearSuffix} ON tCore_Header{strPrevYearSuffix}.iHeaderId = tCore_Data{strPrevYearSuffix}.iHeaderId \r\n\t            JOIN cCore_Vouchers{strPrevYearSuffix} WITH (READUNCOMMITTED) ON cCore_Vouchers{strPrevYearSuffix}.iVoucherType=tCore_Header{strPrevYearSuffix}.iVoucherType\r\n\t            JOIN mCore_Account ON InnerTable.[iMasterId] = mCore_Account.iMasterId \r\n                {sTagJoinTable}\r\n\t            WHERE {empty} \r\n                AND tCore_Data{strPrevYearSuffix}.bSuspendUpdateFA = 0 AND tCore_Header{strPrevYearSuffix}.bSuspended = 0 AND tCore_Data{strPrevYearSuffix}.iAuthStatus < 2\r\n                AND tCore_Header{strPrevYearSuffix}.iDate BETWEEN {num} AND {num2} \r\n                AND tCore_Header{strPrevYearSuffix}.iVoucherClass <> {256} \r\n                {strSecurityFilter}\r\n            ) TempTable GROUP BY [iMasterId] ";
		dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		dbCommand.CommandTimeout = 0;
		dataReader = m_objDatabase.ExecuteReader(dbCommand);
		while (dataReader.Read())
		{
			num3 = Convert.ToInt32(dataReader["iMasterId"]);
			if (arrTreeData.ContainsKey(num3))
			{
				finalAccountTreeData = null;
				if (arrTreeData.TryGetValue(num3, out finalAccountTreeData))
				{
					finalAccountTreeData.LastYearData = new LastYearAccountData();
					finalAccountTreeData.LastYearData.LastYearDebitBase = Convert.ToDecimal(dataReader["Debit"]);
					finalAccountTreeData.LastYearData.LastYearCreditBase = Convert.ToDecimal(dataReader["Credit"]);
					finalAccountTreeData.LastYearData.LastYearDebitTran = Convert.ToDecimal(dataReader["TranDr"]);
					finalAccountTreeData.LastYearData.LastYearCreditLocal = Convert.ToDecimal(dataReader["TranCr"]);
					finalAccountTreeData.LastYearData.LastYearDebitLocal = Convert.ToDecimal(dataReader["LocalDr"]);
					finalAccountTreeData.LastYearData.LastYearCreditLocal = Convert.ToDecimal(dataReader["LocalCr"]);
					arrTreeData[num3] = finalAccountTreeData;
				}
			}
		}
		dataReader.Close();
	}

	private void UpdateBudgetData(RepRecord objRec, ref Dictionary<int, FinalAccountTreeData> arrTreeData)
	{
		int num = 0;
		int num2 = 0;
		string text = null;
		IDataReader dataReader = null;
		FinalAccountTreeData finalAccountTreeData = null;
		List<IdValuePair> list = null;
		List<DualIdPair> list2 = null;
		if (FConvert.GetInputValue(objRec.Inputs, 3) == 1)
		{
			text = $"SELECT iAccountId,MonthId,Amount FROM fCore_GetBudget({objRec.StartingDate},{objRec.EndingDate},0,0,1)";
			list2 = new List<DualIdPair>();
			dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				list2.Add(new DualIdPair(Convert.ToInt32(dataReader["iAccountId"]), Convert.ToInt32(dataReader["MonthId"]), Convert.ToDecimal(dataReader["Amount"])));
			}
			dataReader.Close();
			for (num = 0; num < list2.Count; num++)
			{
				for (num2 = 0; num2 < arrTreeData.Count; num2++)
				{
					finalAccountTreeData = arrTreeData.ElementAt(num2).Value;
					if (finalAccountTreeData.MasterId == list2[num].Id)
					{
						finalAccountTreeData.Budget += Convert.ToDecimal(list2[num].Value);
						if (finalAccountTreeData.MonthwiseBudgets == null)
						{
							finalAccountTreeData.MonthwiseBudgets = new decimal[12];
						}
						if (list2[num].SubId > 0 && list2[num].SubId <= 12)
						{
							finalAccountTreeData.MonthwiseBudgets[list2[num].SubId - 1] = Convert.ToDecimal(list2[num].Value);
						}
					}
				}
			}
			return;
		}
		text = $"SELECT iAccountId,Amount FROM fCore_GetBudget({objRec.StartingDate},{objRec.EndingDate},0,0,0)";
		list = new List<IdValuePair>();
		dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		while (dataReader.Read())
		{
			list.Add(new IdValuePair(Convert.ToInt32(dataReader["iAccountId"]), Convert.ToDecimal(dataReader["Amount"])));
		}
		dataReader.Close();
		for (num = 0; num < list.Count; num++)
		{
			for (num2 = 0; num2 < arrTreeData.Count; num2++)
			{
				finalAccountTreeData = arrTreeData.ElementAt(num2).Value;
				if (finalAccountTreeData.MasterId == list[num].ID)
				{
					finalAccountTreeData.Budget = Convert.ToDecimal(list[num].Value);
					break;
				}
			}
		}
		bool flag = _focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Budgets, 10) > 0;
		bool flag2 = _focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Budgets, 12) > 0;
		for (num2 = 0; num2 < arrTreeData.Count; num2++)
		{
			finalAccountTreeData = arrTreeData.ElementAt(num2).Value;
			text = string.Format("SELECT \r\n                        dbo.fCore_GetBudgetInfo{0}(1,{1},0,0,0,0,{2},{3},{4})[Define],\r\n                        dbo.fCore_GetBudgetInfo{0}(2,{1},0,0,0,0,{2},{3},{4})[Spend],\r\n                        dbo.fCore_GetBudgetInfo{0}(3,{1},0,0,0,0,{2},{3},{4})[Committed],\r\n                        dbo.fCore_GetBudgetInfo{0}(4,{1},0,0,0,0,{2},{3},{4})[PreCommitted],\r\n                        dbo.fCore_GetBudgetInfo{0}(8,{1},0,0,0,0,{2},{3},{4})[Balance]", m_strSuffix, finalAccountTreeData.MasterId, objRec.EndingDate, flag ? 1 : 0, flag2 ? 1 : 0);
			dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			if (dataReader.Read())
			{
				finalAccountTreeData.BudgetDefine = Convert.ToDecimal(dataReader["Define"]);
				finalAccountTreeData.BudgetSpend = Convert.ToDecimal(dataReader["Spend"]);
				finalAccountTreeData.BudgetCommitted = Convert.ToDecimal(dataReader["Committed"]);
				finalAccountTreeData.BudgetPreCommitted = Convert.ToDecimal(dataReader["PreCommitted"]);
				finalAccountTreeData.BudgetBalance = Convert.ToDecimal(dataReader["Balance"]);
			}
			dataReader.Close();
		}
	}

