	private bool IsOtherColumnsIncluded(RepRecord objRec, int iFormatType, ref bool bOpBal, ref bool bYTD, ref bool bBudget, ref bool bLastYear, int iTagwise)
	{
		bool result = false;
		if (objRec != null && objRec.ReportCustomize != null && objRec.ReportCustomize.Layout != null && objRec.ReportCustomize.Layout.Columns != null)
		{
			if (iFormatType == 2)
			{
				for (int i = 0; i < objRec.ReportCustomize.Layout.Columns.Length; i++)
				{
					if (objRec.ReportCustomize.Layout.Columns[i].FieldId == 2 || objRec.ReportCustomize.Layout.Columns[i].FieldId == 3 || objRec.ReportCustomize.Layout.Columns[i].FieldId == 12 || objRec.ReportCustomize.Layout.Columns[i].FieldId == 13 || objRec.ReportCustomize.Layout.Columns[i].FieldId == 10 || objRec.ReportCustomize.Layout.Columns[i].FieldId == 11)
					{
						result = true;
					}
					if (objRec.ReportCustomize.Layout.Columns[i].FieldId == 4 || objRec.ReportCustomize.Layout.Columns[i].FieldId == 5 || objRec.ReportCustomize.Layout.Columns[i].FieldId == 14 || objRec.ReportCustomize.Layout.Columns[i].FieldId == 15)
					{
						bOpBal = true;
					}
					else if (objRec.ReportCustomize.Layout.Columns[i].FieldId == 6 || objRec.ReportCustomize.Layout.Columns[i].FieldId == 7 || objRec.ReportCustomize.Layout.Columns[i].FieldId == 16 || objRec.ReportCustomize.Layout.Columns[i].FieldId == 17)
					{
						bYTD = true;
					}
					else if (iTagwise == 0 && objRec.ReportCustomize.Layout.Columns[i].FieldId >= 30 && objRec.ReportCustomize.Layout.Columns[i].FieldId <= 35)
					{
						bBudget = true;
					}
					else if (objRec.ReportCustomize.Layout.Columns[i].FieldId >= 31 && objRec.ReportCustomize.Layout.Columns[i].FieldId <= 36)
					{
						bLastYear = true;
					}
					if (iTagwise == 1 && objRec.ReportCustomize.Layout.Columns[i].FieldId >= 500 && objRec.ReportCustomize.Layout.Columns[i].FieldId <= 550)
					{
						bBudget = true;
					}
				}
			}
			else
			{
				result = (bOpBal = (bYTD = true));
			}
		}
		return result;
	}

