	private IdNamePair[] GetDepartmentList(_Filter[] arrFilter, bool bDynamicLayout)
	{
		string text = null;
		string text2 = null;
		string text3 = null;
		IDataReader dataReader = null;
		List<IdNamePair> list = null;
		list = new List<IdNamePair>();
		text2 = _focus.company(m_iCompanyId).faTagName;
		if (!string.IsNullOrEmpty(text2))
		{
			if (bDynamicLayout && arrFilter != null && arrFilter.Length != 0)
			{
				text3 = _focus.company(m_iCompanyId).getFinanceFilter(arrFilter);
			}
			text = $"SELECT iMasterId,sName,bGroup FROM {text2} WHERE iMasterId > 0 AND iStatus <> 5 AND iTreeId = 0";
			if (!string.IsNullOrEmpty(text3))
			{
				text += $" AND iMasterId IN({text3})";
			}
			text += " ORDER BY iMasterId";
			dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				list.Add(new IdNamePair(Convert.ToInt32(dataReader["iMasterId"]), Convert.ToString(dataReader["sName"]), Convert.ToBoolean(dataReader["bGroup"])));
			}
			dataReader.Close();
			List<int> list2 = new List<int>();
			for (int i = 0; i < list.Count; i++)
			{
				if (Convert.ToBoolean(list[i].Tag))
				{
					list2.Clear();
					text = string.Format("WITH RecursionCTE (iMasterId, iParentId, bGroup)  AS  \r\n                        (   SELECT iMasterId, iParentId, bGroup\r\n                            FROM {0} \r\n                            WHERE iMasterId = {1} AND iTreeId = 0\r\n                            UNION ALL  \r\n                            SELECT R1.iMasterId, R1.iParentId, R1.bGroup\r\n                            FROM {0} AS R1\r\n                            JOIN RecursionCTE AS R2 ON R1.iParentId = R2.iMasterId\r\n                        )SELECT iMasterId  FROM RecursionCTE WHERE bGroup = 0", text2, list[i].ID);
					dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
					while (dataReader.Read())
					{
						list2.Add(Convert.ToInt32(dataReader["iMasterId"]));
					}
					dataReader.Close();
					list[i].Tag = list2.ToArray();
				}
				else
				{
					list[i].Tag = null;
				}
			}
		}
		return list.ToArray();
	}

	private IdNamePair[] GetMonthlyList()
	{
		string[] array = null;
		List<IdNamePair> list = null;
		list = new List<IdNamePair>();
		array = new DateTimeFormatInfo().AbbreviatedMonthNames.Select((string p) => p).ToArray();
		for (int num = 0; num < 12 && num < array.Length; num++)
		{
			list.Add(new IdNamePair(num, array[num]));
		}
		return list.ToArray();
	}

	private IdNamePair[] GetYearQuarterList(DateTime dtAccount, bool bYear)
	{
		List<IdNamePair> list = new List<IdNamePair>();
		if (bYear)
		{
			for (int i = dtAccount.Year; i <= DateTime.Today.Year; i++)
			{
				list.Add(new IdNamePair(i, i.ToString()));
			}
		}
		else
		{
			int num = 0;
			int num2 = dtAccount.Month - 1;
			while (num < 4)
			{
				num2 -= ((num2 >= 12) ? 12 : 0);
				list.Add(new IdNamePair(num2, $"Quarter{num + 1}"));
				num++;
				num2 += 3;
			}
		}
		return list.ToArray();
	}

