			text = $"{ex.Message}\r\n{ex.StackTrace}";
		}
		finally
		{
			if (dbCommand != null && dbCommand.Connection != null && dbCommand.Connection.State != ConnectionState.Closed)
			{
				dbCommand.Connection.Close();
			}
		}
		return dictionary;
	}

