		List<IdNameTag> list2 = null;
		List<MasterRights> list3 = null;
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		string empty = string.Empty;
		if (UserId > 1)
		{
			text = $"SELECT COUNT(1)[MasterCount] FROM mSec_UserMasterRestriction With (ReadUncommitted) WHERE iUserId = {UserId} and iMasterTypeId={iMasterTypeId}";
			dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			text = ((!Convert.ToBoolean(objDb.ExecuteScalar(dbCommand))) ? $"SELECT 'm'+sModule+'_'+sMasterName[sMasterName],iMasterId,cCore_MasterDef.iMasterTypeId, case when iType & 0x8 > 0 then 1 else 0 end iType FROM \r\n                    mSec_RolesMasters With (ReadUncommitted)\r\n                    JOIN mSec_RoleHeader With (ReadUncommitted) ON mSec_RolesMasters.iRoleId = mSec_RoleHeader.iRoleId\r\n                    JOIN mSec_Users_Roles With (ReadUncommitted) ON mSec_Users_Roles.iERPRole =  mSec_RoleHeader.iRoleId\r\n                    JOIN cCore_MasterDef With (ReadUncommitted) ON cCore_MasterDef.iMasterTypeId = mSec_RolesMasters.iMasterTypeId\r\n                    WHERE iUserId = {UserId} and cCore_MasterDef.iMasterTypeId={iMasterTypeId}" : $"SELECT 'm'+sModule+'_'+sMasterName[sMasterName],iMasterId,cCore_MasterDef.iMasterTypeId, case when iType & 0x8 > 0 then 1 else 0 end iType FROM \r\n                    mSec_UserMasterRestriction With (ReadUncommitted)\r\n                    JOIN cCore_MasterDef With (ReadUncommitted) ON cCore_MasterDef.iMasterTypeId = mSec_UserMasterRestriction.iMasterTypeId\r\n                    WHERE mSec_UserMasterRestriction.iUserId = {UserId} and cCore_MasterDef.iMasterTypeId={iMasterTypeId}  AND (iType & 0x7) IN (2,3,5,6,7) \r\n                    UNION \r\n                    SELECT 'm'+sModule+'_'+sMasterName[sMasterName],iMasterId,cCore_MasterDef.iMasterTypeId, case when iType & 0x8 > 0 then 1 else 0 end iType FROM \r\n                    mSec_RolesMasters With (ReadUncommitted)\r\n                    JOIN mSec_RoleHeader With (ReadUncommitted) ON mSec_RolesMasters.iRoleId = mSec_RoleHeader.iRoleId\r\n                    JOIN mSec_Users_Roles With (ReadUncommitted) ON mSec_Users_Roles.iERPRole =  mSec_RoleHeader.iRoleId\r\n                    JOIN cCore_MasterDef With (ReadUncommitted) ON cCore_MasterDef.iMasterTypeId = mSec_RolesMasters.iMasterTypeId\r\n                    WHERE iUserId = {UserId} and cCore_MasterDef.iMasterTypeId={iMasterTypeId}\r\n                    AND cCore_MasterDef.iMasterTypeId NOT IN\r\n                    (\r\n                        SELECT cCore_MasterDef.iMasterTypeId \r\n                        FROM \r\n                        mSec_UserMasterRestriction With (ReadUncommitted)\r\n                        JOIN cCore_MasterDef With (ReadUncommitted) ON cCore_MasterDef.iMasterTypeId = mSec_UserMasterRestriction.iMasterTypeId\r\n                        WHERE mSec_UserMasterRestriction.iUserId = {UserId} and cCore_MasterDef.iMasterTypeId={iMasterTypeId}\r\n                    )");
			if (!string.IsNullOrEmpty(strActionTypeFilter))
			{
				text += $" AND (iType & 0x7) IN ({strActionTypeFilter})";
			}
			text += " ORDER BY cCore_MasterDef.iMasterTypeId,case when iType & 0x8 > 0 then 1 else 0 end";
			dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dataReader = objDb.ExecuteReader(dbCommand);
			list2 = new List<IdNameTag>();
			list = new List<string>();
			while (dataReader.Read())
			{
				if (idNamePair != null && idNamePair.ID > 0 && (idNamePair.ID != Convert.ToInt32(dataReader["iMasterTypeId"]) || Convert.ToBoolean(idNamePair.Tag) != Convert.ToBoolean(dataReader["iType"])))
				{
					IdNameTag idNameTag = new IdNameTag();
					idNameTag.Tag = idNamePair;
					idNameTag.Name = string.Join(",", list.ToArray());
					idNameTag.ID = idNamePair.ID;
					list2.Add(idNameTag);
					idNamePair = null;
					list.Clear();
				}
				list.Add(Convert.ToString(dataReader["iMasterId"]));
				idNamePair = new IdNamePair();
				idNamePair.Name = Convert.ToString(dataReader["sMasterName"]);
				idNamePair.ID = Convert.ToInt32(dataReader["iMasterTypeId"]);
				idNamePair.Tag = Convert.ToBoolean(dataReader["iType"]);
			}
			dataReader.Close();
			if (idNamePair != null && idNamePair.ID > 0 && list.Count > 0)
			{
				IdNameTag idNameTag2 = new IdNameTag();
				idNameTag2.Tag = idNamePair;
				idNameTag2.Name = string.Join(",", list.ToArray());
				idNameTag2.ID = idNamePair.ID;
				list2.Add(idNameTag2);
			}
			list3 = new List<MasterRights>();
			for (num = 0; num < list2.Count; num++)
			{
				idNamePair = list2[num].Tag as IdNamePair;
				empty = (Convert.ToBoolean(idNamePair.Tag) ? "" : " union all\r\n                                            SELECT isnull(iParentId,0) iMasterId FROM RecursionCTE where bGroup = 0");
				text = string.Format("WITH RecursionCTE (iMasterId, iParentId, bGroup)  AS  \r\n                                (   SELECT {0}.iMasterId, iParentId, bGroup\r\n                                    FROM {0} \r\n\t\t\t\t\t\t\t\t\tinner join {0}TreeDetails on {0}.iMasterId= {0}TreeDetails.iMasterId\r\n                                    WHERE {0}.iMasterId IN({1}) AND iTreeId = {2}\r\n                                    UNION ALL  \r\n                                    SELECT R1.iMasterId, R1.iParentId, R1.bGroup\r\n                                    FROM (Select {0}.iMasterId, iParentId, bGroup\r\n\t\t\t\t\t\t\t\t\tFROM {0} \r\n\t\t\t\t\t\t\t\t\tinner join {0}TreeDetails on {0}.iMasterId= {0}TreeDetails.iMasterId\r\n                                    where iTreeId = {2}\r\n                                    ) AS R1\r\n                                    JOIN RecursionCTE AS R2 ON R1.iParentId = R2.iMasterId\r\n                                )\r\n                                Select Distinct iMasterId from(\r\n                                SELECT iMasterId  FROM RecursionCTE --WHERE bGroup = 0\r\n                                union all\r\n                                SELECT iMasterId FROM {0} where bDoNotRestrict = 1 and iStatus = 0\r\n                                {3}\r\n                                ) A\r\n                    ", idNamePair.Name, list2[num].Name, TreeId, empty);
				dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				dataReader = objDb.ExecuteReader(dbCommand);
				list = new List<string>();
				while (dataReader.Read())
				{
					list.Add(Convert.ToString(dataReader["iMasterId"]));
				}
				dataReader.Close();
				if (list.Count == 0)
				{
					list.Add(list2[num].Name);
				}
				else if (Convert.ToInt32(idNamePair.Tag) == 0)
				{
					list.Add("0");
				}
				for (num2 = 0; num2 < list3.Count; num2++)
				{
					if (list3[num2].ID == list2[num].ID)
					{
						list3[num2].Tag = string.Format("{0},{1}", list3[num2].Tag, string.Join(",", list.ToArray()));
						break;
					}
				}
				if (num2 >= list3.Count)
				{
					list3.Add(new MasterRights(idNamePair.ID, idNamePair.Name, string.Join(",", list.ToArray()), Convert.ToBoolean(idNamePair.Tag)));
				}
			}
		}
		return list3;
	}

	private string AddSecurityFilter(List<MasterRights> arrRestrictMasters, string strFATag)
	{
		int num = 0;
		string text = string.Empty;
		if (arrRestrictMasters != null)
		{
			for (num = 0; num < arrRestrictMasters.Count; num++)
			{
				if (!string.IsNullOrEmpty(strFATag) && MatchTable(strFATag, arrRestrictMasters[num].Name))
				{
					text += string.Format(" AND iFaTag {0} IN ({1} )", arrRestrictMasters[num].Exclude ? "NOT" : "", arrRestrictMasters[num].Tag);
				}
			}
		}
		return text;
	}

	private bool MatchTable(string sTable1, string sTable2)
	{
		if ((sTable1.Length > 0 && sTable1 == sTable2) || sTable1.Insert(1, "u") == sTable2)
		{
			return true;
		}
		return false;
	}

	private bool IsNonZeroData(FinalAccountTreeData objData, int iFormatOption, RepRecord objRec, bool bIncludeZeroGroupWithNonZeroChild, Dictionary<int, FinalAccountTreeData> arrTreeData, int iFormatType, bool bIncludeZeroBalMovedAc)
	{
		_ = 1;
		if (!bIncludeZeroBalMovedAc && objData.DebitYTD == 0m && objData.CreditYTD == 0m)
		{
			return false;
		}
		if (objData.DebitYTD != 0m || objData.CreditYTD != 0m)
		{
			return true;
		}
		if (m_bOpBal && (objData.DebitOpBal != 0m || objData.CreditOpBal != 0m))
		{
			return true;
		}
		if (m_bDrCr && (objData.Debit != 0m || objData.Credit != 0m))
		{
			return true;
		}
		if (bIncludeZeroGroupWithNonZeroChild && objData.IsGroup && arrTreeData != null)
		{
			int num = Convert.ToInt32(FConvert.GetInputValue(objRec.Inputs, 2));
			for (int i = 0; i < arrTreeData.Count; i++)
			{
				if (arrTreeData.ElementAt(i).Key != objData.MasterId)
				{
					continue;
				}
				for (int j = i + 1; j < arrTreeData.Count; j++)
				{
					FinalAccountTreeData value = arrTreeData.ElementAt(j).Value;
					if (value.Level >= num || value.IsGroup)
					{
						break;
					}
					if (value.DebitYTD != 0m || value.CreditYTD != 0m)
					{
						return true;
					}
					if (m_bOpBal && (value.DebitOpBal != 0m || value.CreditOpBal != 0m))
					{
						return true;
					}
					if (m_bDrCr && (value.Debit != 0m || value.Credit != 0m))
					{
						return true;
					}
				}
				break;
			}
		}
		if (objData.DebitForPeriod != 0m || objData.CreditForPeriod != 0m)
		{
			return true;
		}
		if (iFormatOption == 4 && objData.LastYearData != null && (objData.LastYearData.LastYearDebitBase != 0m || objData.LastYearData.LastYearCreditBase != 0m || objData.LastYearData.LastYearDebitTran != 0m || objData.LastYearData.LastYearCreditTran != 0m))
		{
			return true;
		}
		if (iFormatOption == 2 && iFormatType == 1 && objData.TagValues != null && objData.TagValues.Length != 0)
		{
			for (int k = 0; k < objData.TagValues.Length; k++)
			{
				if (objData.TagValues[k] != null && objData.TagValues[k].Data != null && (objData.TagValues[k].Data.Debit != 0m || objData.TagValues[k].Data.Credit != 0m))
				{
					return true;
				}
			}
		}
		return false;
	}

