					for (num2 = 0; num2 < productTreeData.TagData.Length; num2++)
					{
						for (num3 = 0; num3 < list.Count; num3++)
						{
							if (list[num3].TagId == productTreeData.TagData[num2].TagId)
							{
								list[num3].Quantity += productTreeData.TagData[num2].Quantity;
								list[num3].StockValue += productTreeData.TagData[num2].StockValue;
								list[num3].UnitPrice = ((list[num3].Quantity == 0m) ? list[num3].UnitPrice : (list[num3].StockValue / list[num3].Quantity));
								break;
							}
						}
						if (num3 == list.Count)
						{
							list.Add(new TagWiseStockData
							{
								TagId = productTreeData.TagData[num2].TagId,
								Quantity = productTreeData.TagData[num2].Quantity,
								StockValue = productTreeData.TagData[num2].StockValue,
								UnitPrice = productTreeData.TagData[num2].UnitPrice
							});
						}
					}
					value.TagData = list.ToArray();
				}
				arrTreeData[productTreeData.ParentId] = value;
			}
		}
	}

