					objData.OpeningAssetValue += fADepData[num].OpeningAssetValue;
				}
				fADepData[num].NetAsset = fADepData[num].OpeningAssetValue + fADepData[num].Addition - fADepData[num].Deletion;
				if (Convert.ToDouble(fADepData[num].NetAsset) <= 0.0)
				{
					fADepData[num].NetAsset = 0m;
				}
				if (Convert.ToDouble(fADepData[num].NetAsset) > 0.0 && Convert.ToDouble(fADepData[num].NetAsset) < Convert.ToDouble(fADepData[num].Depreciation))
				{
					fADepData[num].Depreciation = fADepData[num].NetAsset - Convert.ToDecimal(num6);
				}
				if (Convert.ToString(fADepData[num].Method) == "Charge off" || Convert.ToDouble(fADepData[num].DisposalValue) > 0.0)
				{
					fADepData[num].ClosingValue = 0m;
				}
				else
				{
					fADepData[num].ClosingValue = fADepData[num].OpeningAssetValue + fADepData[num].Addition - fADepData[num].Deletion - fADepData[num].Depreciation;
				}
				if (Convert.ToDouble(fADepData[num].ClosingValue) <= num6)
				{
					fADepData[num].ClosingValue = Convert.ToDecimal(num6);
				}
				if (Convert.ToDouble(fADepData[num].DisposalValue) > 0.0)
				{
					fADepData[num].DisposalGainLoss = fADepData[num].OpeningAssetValue - fADepData[num].Depreciation - fADepData[num].DisposalValue;
				}
			}
			objData.Particular += fADepData[num].Particular;
			objData.AssetGroup += fADepData[num].AssetGroup;
			objData.Method += fADepData[num].Method;
			objData.DepreciationRate += fADepData[num].DepreciationRate;
			objData.DepreciationBF += fADepData[num].DepreciationBF;
			objData.Deletion += fADepData[num].Deletion;
			objData.ParentId += fADepData[num].ParentId;
			objData.NetAsset += fADepData[num].NetAsset;
			objData.Depreciation += fADepData[num].Depreciation;
			objData.ClosingValue += fADepData[num].ClosingValue;
			objData.DisposalValue += fADepData[num].DisposalValue;
			objData.DisposalGainLoss += fADepData[num].DisposalGainLoss;
			objData.Status += fADepData[num].Status;
			objData.iStatus += fADepData[num].iStatus;
			objData.DepreciationWithoutAddReduce += fADepData[num].DepreciationWithoutAddReduce;
			objData.DepreciationAddReduce += fADepData[num].DepreciationAddReduce;
			objData.AddedYears += fADepData[num].AddedYears;
			objData.AddedMonths += fADepData[num].AddedMonths;
			arrFATreeData[fADepData[num].Id] = objData;
		}
	}

	private void SetProductDepreciationData(ref Dictionary<int, FixedAsseetTreeData> arrTreeData)
	{
		int num = 0;
		FixedAsseetTreeData fixedAsseetTreeData = null;
		FixedAsseetTreeData value = null;
		byte decimals = (byte)_focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Inventory, 0);
		for (num = arrTreeData.Count - 1; num >= 0; num--)
		{
			fixedAsseetTreeData = arrTreeData.ElementAt(num).Value;
			arrTreeData.TryGetValue(fixedAsseetTreeData.ParentId, out value);
			if (value != null)
			{
				value.Particular = value.Name;
				value.AssetGroup = value.AssetGroup;
				value.DepreciationRate += fixedAsseetTreeData.DepreciationRate;
				value.OriginalValue += fixedAsseetTreeData.OriginalValue;
				value.DepreciationBF += fixedAsseetTreeData.DepreciationBF;
				value.OpeningAssetValue += fixedAsseetTreeData.OpeningAssetValue;
				value.Addition += fixedAsseetTreeData.Addition;
				value.Deletion += fixedAsseetTreeData.Deletion;
				value.NetAsset += fixedAsseetTreeData.NetAsset;
				value.Depreciation += Math.Round(fixedAsseetTreeData.Depreciation, decimals);
				value.ClosingValue += fixedAsseetTreeData.ClosingValue;
				value.DisposalValue += fixedAsseetTreeData.DisposalValue;
				value.DisposalGainLoss += fixedAsseetTreeData.DisposalGainLoss;
				value.AssetGroup += fixedAsseetTreeData.AssetGroup;
				value.iStatus += fixedAsseetTreeData.iStatus;
				value.Status += fixedAsseetTreeData.Status;
				value.DepreciationWithoutAddReduce += fixedAsseetTreeData.DepreciationWithoutAddReduce;
				value.DepreciationAddReduce += fixedAsseetTreeData.DepreciationAddReduce;
				value.AddedYears += fixedAsseetTreeData.AddedYears;
				value.AddedMonths += fixedAsseetTreeData.AddedMonths;
				if (fixedAsseetTreeData.ExtraValues != null)
				{
					for (int i = 0; i < fixedAsseetTreeData.ExtraValues.Length; i++)
					{
						if (IsNumber(fixedAsseetTreeData.ExtraValues[i]))
						{
							value.ExtraValues[i] = Convert.ToDouble(value.ExtraValues[i]) + Convert.ToDouble(fixedAsseetTreeData.ExtraValues[i]);
						}
					}
				}
				arrTreeData[fixedAsseetTreeData.ParentId] = value;
			}
		}
	}

	public bool IsNumber(object value)
	{
		if (!(value is sbyte) && !(value is byte) && !(value is short) && !(value is ushort) && !(value is int) && !(value is uint) && !(value is long) && !(value is ulong) && !(value is float) && !(value is double))
		{
			return value is decimal;
		}
		return true;
	}

