				for (int i = 0; i < value.ExtraValues.Length; i++)
				{
					lineData.CellData[num3 + i] = value.ExtraValues[i];
				}
			}
			list.Add(lineData);
			iCurrentRowIndex++;
			if (list.Count >= objRec.RowsPerPage)
