t4}\r\n                    LEFT JOIN mFixA_AssetChgValHeader_0 AddValue WITH (READUNCOMMITTED) ON AddValue.iAssetId = vrFixA_FixedAsset.iMasterId and AddValue.iStatus<>5\r\n                    LEFT JOIN mFixA_AssetDisposalHeader_0 Disposal WITH (READUNCOMMITTED) ON Disposal.iAssetId = vrFixA_FixedAsset.iMasterId and Disposal.iStatus<>5 \r\n                    LEFT JOIN  vrFixA_FixedAsset FixA  ON FixA.iMasterId= vrFixA_FixedAsset.iParentId    \r\n                    left join mFixA_ChangeDepValue AddYrs on AddYrs.iFixAssetId=vrFixA_FixedAsset.iMasterId                  \r\n                    {text5}\r\n                    Group By vrFixA_FixedAsset.iMasterId, vrFixA_FixedAsset.sName, muFixA_FixedAsset_Depreciation.iDepreciationMethod, vrFixA_FixedAsset.iDepreciationMethod,\r\n                    vrFixA_FixedAsset.iDepreciationInYears , vrFixA_FixedAsset.iDepreciationInMonths,\r\n                    vrFixA_FixedAsset.fPrice , vrFixA_FixedAsset.fCumulativeDepreciation,muFixA_FixedAsset_Depreciation.iDepreciationMethod,\r\n                    vrFixA_FixedAsset.iDateOfCommencement,vrFixA_FixedAsset.fScrapValue,Disposal.dTotValSold,\r\n                    ISNULL(FixA.iMasterId , ''),vrFixA_FixedAsset.fITDepreciationRate,vrFixA_FixedAsset.ITAccruedValue,vrFixA_FixedAsset.iQuantity, vrFixA_FixedAsset.fRateOfDepreciation,Case When vrFixA_FixedAsset.iStatus =4 then 'Disposed' else '' end, vrFixA_FixedAsset.iStatus \r\n                    ,Disposal.iDisposalDate,vrFixA_FixedAsset.iDepreciationInYears,AddYrs.iNoOfYears,AddYrs.iNoOfMonths\r\n                    ORDER BY ISNULL(vrFixA_FixedAsset.sName , ''),iMasterId                    \r\n                        " : $" {stringBuilder}\r\n                    SELECT vrFixA_FixedAsset.iMasterId, vrFixA_FixedAsset.sName, vrFixA_FixedAsset.iDepreciationMethod,\r\n                    Case When muFixA_FixedAsset_Depreciation.iDepreciationMethod in (0,1) then 1 \r\n                    else  (vrFixA_FixedAsset.fRateOfDepreciation) end  \r\n                    [DepRate],\r\n                    vrFixA_FixedAsset.fPrice*vrFixA_FixedAsset.iQuantity fPrice ,\r\n                    --vrFixA_FixedAsset.fCumulativeDepreciation  [Dep b/f],\r\n                    0 [Dep b/f],\r\n                           Case When {FConvert.GetInputValue(objRec.Inputs, 4)} = 0 then  (vrFixA_FixedAsset.fPrice*vrFixA_FixedAsset.iQuantity) - vrFixA_FixedAsset.fCumulativeDepreciation else (vrFixA_FixedAsset.fPrice*vrFixA_FixedAsset.iQuantity) - vrFixA_FixedAsset.ITAccruedValue end  [Opening Asset Value],\r\n                    Sum(CASE WHEN bAddRemoved = 0 THEN (AddValue.dChgValue + AddValue.dServiceChg + AddValue.dOtherChg) ELSE 0 END) [Additions],\r\n                    Sum(CASE WHEN bAddRemoved = 1 THEN (AddValue.dChgValue + AddValue.dServiceChg + AddValue.dOtherChg) ELSE 0 END) [Deletion], \r\n                    0[Net asset value],                    \r\n                    0 [Depreciation],\r\n                    0 ClosingValue, Case When (vrFixA_FixedAsset.iStatus =4 and Disposal.iDisposalDate<={objRec.EndingDate}) then isnull(Disposal.dTotValSold,0) else 0 end DisposalValue , 0 [Disposal Gain/Loss], ISNULL(FixA.iMasterId , '')[ParentAsset],\r\n                    Case When (vrFixA_FixedAsset.iStatus =4 and Disposal.iDisposalDate<={objRec.EndingDate}) then 'Disposed' else '' end Status,vrFixA_FixedAsset.iStatus \r\n                    {text2}\r\n                    {text3}                    \r\n                    , ISNULL(AddYrs.iNoOfYears,0) TotYrs, ISNULL(AddYrs.iNoOfMonths,0) iNoOfMonths --ISNULL(vrFixA_FixedAsset.iDepreciationInYears,0) +\r\n                    FROM vrFixA_FixedAsset \r\n                    JOIN muFixA_FixedAsset_Depreciation ON vrFixA_FixedAsset.iMasterId=muFixA_FixedAsset_Depreciation.iMasterId\r\n                    JOIN mFixA_FixedAsset ON vrFixA_FixedAsset.iMasterId=mFixA_FixedAsset.iMasterId\r\n                    {text4}\r\n                    LEFT JOIN mFixA_AssetChgValHeader_0 AddValue WITH (READUNCOMMITTED) ON AddValue.iAssetId = vrFixA_FixedAsset.iMasterId and AddValue.iStatus<>5\r\n                    LEFT JOIN mFixA_AssetDisposalHeader_0 Disposal WITH (READUNCOMMITTED) ON Disposal.iAssetId = vrFixA_FixedAsset.iMasterId and Disposal.iStatus<>5 \r\n                    LEFT JOIN  vrFixA_FixedAsset FixA  ON FixA.iMasterId= vrFixA_FixedAsset.iParentId    \r\n                    left join mFixA_ChangeDepValue AddYrs on AddYrs.iFixAssetId=vrFixA_FixedAsset.iMasterId                  \r\n                    {text5}\r\n                    Group By vrFixA_FixedAsset.iMasterId, vrFixA_FixedAsset.sName, muFixA_FixedAsset_Depreciation.iDepreciationMethod, vrFixA_FixedAsset.iDepreciationMethod,\r\n                    vrFixA_FixedAsset.iDepreciationInYears , vrFixA_FixedAsset.iDepreciationInMonths,\r\n                    vrFixA_FixedAsset.fPrice , vrFixA_FixedAsset.fCumulativeDepreciation,muFixA_FixedAsset_Depreciation.iDepreciationMethod,\r\n                    vrFixA_FixedAsset.iDateOfCommencement,vrFixA_FixedAsset.fScrapValue,Disposal.dTotValSold,\r\n                    ISNULL(FixA.iMasterId , ''),vrFixA_FixedAsset.fITDepreciationRate,vrFixA_FixedAsset.ITAccruedValue,vrFixA_FixedAsset.iQuantity, vrFixA_FixedAsset.fRateOfDepreciation,Case When vrFixA_FixedAsset.iStatus =4 then 'Disposed' else '' end, vrFixA_FixedAsset.iStatus \r\n                    ,Disposal.iDisposalDate,vrFixA_FixedAsset.iDepreciationInYears,AddYrs.iNoOfYears,AddYrs.iNoOfMonths\r\n                    ORDER BY ISNULL(vrFixA_FixedAsset.sName , ''),iMasterId                    \r\n                        ");
		dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty3) : empty3);
