	private void SetDepreciationAmountIfByMonthly(RepRecord objRec, int iCurrentRowIndex, ref Dictionary<int, FixedAsseetTreeData> arrTreeData)
	{
		try
		{
			FixedAsseetTreeData objData = null;
			int preferenceValue = _focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.FixedAssets, 20);
			if (preferenceValue != 1)
			{
				return;
			}
			short noOfDecimal = _focus.company(m_iCompanyId).currency.NoOfDecimal;
			List<FixAssetDetails> lstFixAssetDetails = new List<FixAssetDetails>();
			FixAssetDetails fixAssetDetails = new FixAssetDetails();
			List<AssetusageStruct> lstAssetusageStruct = new List<AssetusageStruct>();
			List<AddYrsData> lstAddYrsData = new List<AddYrsData>();
			List<IdNamePair> list = new List<IdNamePair>();
			string empty = string.Empty;
			empty = $" select sum(DH.iQtySold) Qty,DH.iAssetId,FA.iQuantity iTotalQty from mFixA_AssetDisposalHeader_0 DH\r\n                        join vmFixA_FixedAsset FA on FA.iMasterId=DH.iAssetId \r\n                        where DH.iDisposalDate<={objRec.EndingDate} and DH.iDisposalDate>={objRec.StartingDate} and DH.iStatus!=5 group by DH.iAssetId,FA.iQuantity  ";
			IDataReader dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			FADep fADep = new FADep();
			List<FADep> lstFADisposal = new List<FADep>();
			while (dataReader.Read())
			{
				fADep = new FADep();
				fADep.iDisposedQty = Convert.ToInt32(dataReader["Qty"]);
				fADep.iFixAId = Convert.ToInt32(dataReader["iAssetId"]);
				fADep.iTotalQty = Convert.ToInt32(dataReader["iTotalQty"]);
				lstFADisposal.Add(fADep);
			}
			dataReader.Close();
			empty = $" select iCommencementdate, iAssetId,isnull(dChgValue,0)dChgValue,bAddRemoved from mFixA_AssetChgValHeader_0 where iStatus!=5 group by iCommencementdate, iAssetId,dChgValue,bAddRemoved ";
			dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			fADep = new FADep();
			List<FADep> lstFADepAddReduce = new List<FADep>();
			while (dataReader.Read())
			{
				fADep = new FADep();
				fADep.iDateOfCommencement = (dataReader.IsDBNull(0) ? new Date().GetToday(m_objCalType).Value : Convert.ToInt32(dataReader["iCommencementdate"]));
				fADep.bAddRemoved = Convert.ToBoolean(dataReader["bAddRemoved"]);
				fADep.dAddReduceAmount = Convert.ToDouble(dataReader["dChgValue"]);
				fADep.iFixAId = Convert.ToInt32(dataReader["iAssetId"]);
				lstFADepAddReduce.Add(fADep);
			}
			dataReader.Close();
			GetFixAssetDetailsForDepCalculation(m_objDatabase, ref lstFixAssetDetails, ref lstAssetusageStruct, ref lstAddYrsData, ref lstFADisposal, ref lstFADepAddReduce, null);
			list = new QueryGenerator().GetMonthWiseStartEndDates(objRec.StartingDate, objRec.EndingDate);
			for (int i = iCurrentRowIndex; i < arrTreeData.Count; i++)
			{
				objData = arrTreeData.ElementAt(i).Value;
				if (preferenceValue != 1 || objData.IsGroup)
				{
					continue;
				}
				decimal depreciation = 0m;
				decimal depreciationWithoutAddReduce = 0m;
				decimal addition = objData.Addition;
				decimal deletion = objData.Deletion;
				for (int j = 0; j < list.Count(); j++)
				{
					fixAssetDetails = lstFixAssetDetails.Where((FixAssetDetails P) => P.iFixAssetId == objData.Id).First();
					depreciation += fn_CalculateDepreciationWithAddYrs(m_objDatabase, fixAssetDetails.iFixAssetId, fixAssetDetails.DepMethod, list[j].ID, Convert.ToInt32(list[j].Tag), fixAssetDetails.CommencementDate, fixAssetDetails.Price, fixAssetDetails.ScrapValue, fixAssetDetails.DepreciationInYears, fixAssetDetails.DepreciationInMonths, ScreenType: false, fixAssetDetails.ITDepRate, noOfDecimal, objRec);
					if (addition > 0m || deletion > 0m)
					{
						depreciationWithoutAddReduce += fn_CalcDepStraightLineWithoutAddReduce(m_objDatabase, fixAssetDetails.iFixAssetId, list[j].ID, Convert.ToInt32(list[j].Tag), fixAssetDetails.CommencementDate, fixAssetDetails.Price, fixAssetDetails.ScrapValue, fixAssetDetails.DepreciationInYears, fixAssetDetails.ITDepRate, noOfDecimal, objRec);
					}
				}
				arrTreeData.ElementAt(i).Value.Depreciation = depreciation;
				arrTreeData.ElementAt(i).Value.DepreciationWithoutAddReduce = depreciationWithoutAddReduce;
			}
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
		}
	}

