	private IdNamePair[] GetItemNames(int[] arrMasters, int iCompId)
	{
		string text = "SELECT iMasterId, sName, sCode FROM mCore_Product WHERE iMasterId IN (" + FConvert.ArrayToCommaSeparated(arrMasters) + ")";
		IDataReader dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		List<IdNamePair> list = new List<IdNamePair>();
		while (dataReader.Read())
		{
			list.Add(new IdNamePair
			{
				ID = Convert.ToInt32(dataReader[0]),
				Name = Convert.ToString(dataReader[1]),
				ExtraInfo = Convert.ToString(dataReader[2])
			});
		}
		dataReader.Close();
		return list.ToArray();
	}

