	private void StockByRMA(ref ReportMatrix objData, RepRecord objRec, int iCompId)
	{
		decimal dQuantity = 0m;
		decimal dValue = 0m;
		string[] arrWarehouseId = null;
		string inventoryFilter = _focus.company(m_iCompanyId).getInventoryFilter(objRec.FilterSource);
		List<StockValue> list = (string.IsNullOrEmpty(inventoryFilter) ? GetStocks(null, objRec, inventoryFilter, bExclude: false, objData.UniqueId) : GetTagwiseStocks(null, objRec, inventoryFilter, bExclude: false, objData.UniqueId));
		if (!string.IsNullOrEmpty(inventoryFilter))
		{
			arrWarehouseId = inventoryFilter.Split(',');
		}
		for (int i = 0; i < objData.ColumnData.Length; i++)
		{
			if (objData.ColumnData[i].CellData.Length >= 5)
			{
				int id = ((ReportRowHeader)objData.ColumnData[i].CellData[0]).Id;
				decimal stockFromDictionary = GetStockFromDictionary(list, id, ref dQuantity, ref dValue, ref dQuantity, arrWarehouseId);
				dQuantity = Convert.ToDecimal(objData.ColumnData[i].CellData[2]);
				objData.ColumnData[i].CellData[3] = stockFromDictionary;
				objData.ColumnData[i].CellData[4] = dQuantity * stockFromDictionary;
			}
		}
		if (objData.EndOfFile)
		{
			deleteRedisData(objData.UniqueId);
		}
		else
		{
			setOpStockToRedis(objData.UniqueId, list);
		}
	}

