	private void GetStockValue(ValuationMethod objValuationMethod, decimal dQuantity, decimal dIssueValue, ref decimal dStockValue, ref List<InventoryStock> arrInventoryStock, decimal dCumBalance, ref decimal dRate)
	{
		int num = 0;
		decimal num2 = dQuantity;
		switch (objValuationMethod)
		{
		case ValuationMethod.BatchRate:
			if (dIssueValue != 0m)
			{
				dStockValue -= dIssueValue;
			}
			if (dCumBalance == 0m || dStockValue == 0m)
			{
				dRate = 0m;
			}
			else
			{
				dRate = dStockValue / dCumBalance;
			}
			break;
		case ValuationMethod.WeightedAvg:
		case ValuationMethod.MonthlyWeightedAvg:
			num2 = 0m;
			dStockValue -= dQuantity * dRate;
			if (!m_bOldMethod)
			{
				dStockValue = FConvert.RoundOff(dStockValue, (decimal)_focus.company(m_iCompanyId).currency.RoundOff, RoundingType.Nearest);
			}
			num2 = dQuantity;
			for (num = 0; num < arrInventoryStock.Count; num++)
			{
				if (!(arrInventoryStock[num].Quantity == 0m))
				{
					if (num2 <= arrInventoryStock[num].Quantity)
					{
						arrInventoryStock[num].Quantity -= num2;
						num2 = 0m;
					}
					else
					{
						num2 -= arrInventoryStock[num].Quantity;
						arrInventoryStock[num].Quantity = 0m;
					}
					if (num2 <= 0m)
					{
						break;
					}
				}
			}
			break;
		case ValuationMethod.Standard:
			if (dIssueValue != 0m)
			{
				dStockValue -= dQuantity * dRate;
			}
			if (dCumBalance == 0m || dStockValue == 0m)
			{
				dRate = 0m;
			}
			else
			{
				dRate = dStockValue / dCumBalance;
			}
			break;
		case ValuationMethod.FIFO:
		case ValuationMethod.FIFOTransactionTime:
			for (num = 0; num < arrInventoryStock.Count; num++)
			{
				if (!(arrInventoryStock[num].Quantity == 0m))
				{
					if (num2 <= arrInventoryStock[num].Quantity)
					{
						arrInventoryStock[num].Quantity -= num2;
						dStockValue -= arrInventoryStock[num].Rate * num2;
						arrInventoryStock[num].Value = arrInventoryStock[num].Quantity * arrInventoryStock[num].Rate;
						num2 = 0m;
					}
					else
					{
						num2 -= arrInventoryStock[num].Quantity;
						dStockValue -= arrInventoryStock[num].Rate * arrInventoryStock[num].Quantity;
						InventoryStock inventoryStock3 = arrInventoryStock[num];
						InventoryStock inventoryStock4 = arrInventoryStock[num];
						decimal num3 = (arrInventoryStock[num].Value = 0m);
						decimal quantity = (inventoryStock4.Rate = num3);
						inventoryStock3.Quantity = quantity;
					}
					if (num2 <= 0m)
					{
						break;
					}
				}
			}
			break;
		case ValuationMethod.LIFO:
			for (num = arrInventoryStock.Count - 1; num >= 0; num--)
			{
				if (!(arrInventoryStock[num].Quantity == 0m))
				{
					if (num2 <= arrInventoryStock[num].Quantity)
					{
						arrInventoryStock[num].Quantity -= num2;
						dStockValue -= arrInventoryStock[num].Rate * num2;
						arrInventoryStock[num].Value = arrInventoryStock[num].Quantity * arrInventoryStock[num].Rate;
						num2 = 0m;
					}
					else
					{
						num2 -= arrInventoryStock[num].Quantity;
						dStockValue -= arrInventoryStock[num].Rate * arrInventoryStock[num].Quantity;
						InventoryStock inventoryStock = arrInventoryStock[num];
						InventoryStock inventoryStock2 = arrInventoryStock[num];
						decimal num3 = (arrInventoryStock[num].Value = 0m);
						decimal quantity = (inventoryStock2.Rate = num3);
						inventoryStock.Quantity = quantity;
					}
					if (num2 <= 0m)
					{
						break;
					}
				}
			}
			break;
		}
	}

	private decimal GetFIFOStockValue(decimal dQuantity, ref decimal dIssueValue, ref decimal dStockValue, ref List<InventoryStock> arrInventoryStock, decimal dCumBalance)
	{
		int num = 0;
		decimal num2 = dQuantity;
		dIssueValue = 0m;
		List<decimal> list = new List<decimal>();
		for (num = 0; num < arrInventoryStock.Count; num++)
		{
			if (!(arrInventoryStock[num].Quantity == 0m))
			{
				if (num2 <= arrInventoryStock[num].Quantity)
				{
					arrInventoryStock[num].Quantity -= num2;
					dIssueValue -= arrInventoryStock[num].Rate * num2;
					dStockValue -= arrInventoryStock[num].Rate * num2;
					list.Add(arrInventoryStock[num].Rate);
					arrInventoryStock[num].Value = arrInventoryStock[num].Quantity * arrInventoryStock[num].Rate;
					num2 = 0m;
				}
				else
				{
					num2 -= arrInventoryStock[num].Quantity;
					dIssueValue -= arrInventoryStock[num].Rate * arrInventoryStock[num].Quantity;
					dStockValue -= arrInventoryStock[num].Rate * arrInventoryStock[num].Quantity;
					list.Add(arrInventoryStock[num].Rate);
					InventoryStock inventoryStock = arrInventoryStock[num];
					InventoryStock inventoryStock2 = arrInventoryStock[num];
					decimal num3 = (arrInventoryStock[num].Value = 0m);
					decimal quantity = (inventoryStock2.Rate = num3);
					inventoryStock.Quantity = quantity;
				}
				if (num2 <= 0m)
				{
					break;
				}
			}
		}
		if (!(dIssueValue != 0m) || !(dQuantity != 0m))
		{
			if (list.Count <= 0)
			{
				return 0m;
			}
			return list.Average();
		}
		return Math.Abs(dIssueValue / dQuantity);
	}

	private InventoryStock AddStock(int iDate, decimal dQuantity, decimal dStockValue, bool bInward, decimal dLocalValue = 0m)
	{
		new InventoryStock();
		return new InventoryStock
		{
			Date = iDate,
			Quantity = dQuantity,
			Value = dStockValue,
			LocalValue = dLocalValue,
			Rate = ((dQuantity != 0m) ? (dStockValue / dQuantity) : 0m),
			IsInward = bInward
		};
	}

	private IdValuePair[] getAccountBalance(List<int> arrAccounts, int iDate, int iCompId)
	{
		string text = null;
		string arg = null;
		IDataReader dataReader = null;
		IdValuePair idValuePair = null;
		List<IdValuePair> list = null;
		try
		{
			if (m_objDatabase == null)
			{
				m_objDatabase = DatabaseWrapper.GetDatabase2(iCompId, -1, bReplicationServer: true);
			}
			if (arrAccounts != null && arrAccounts.Count > 0 && arrAccounts.Count < 1000)
			{
				arg = string.Format(" WHERE iMasterId IN({0})", string.Join(",", arrAccounts));
			}
			text = string.Format("SELECT iMasterId, SUM(Debit+Credit)[Balance]\r\n                FROM\r\n                (\r\n                    SELECT iBookNo[iMasterId],\r\n                    CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n                    CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit\r\n                    FROM tCore_Header{0} \r\n                    JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                    WHERE tCore_Header{0}.iDate <= {1} AND tCore_Data{0}.bUpdateFA = 1 \r\n                    AND tCore_Data{0}.bSuspendUpdateFA <> 1 AND tCore_Header{0}.bSuspended = 0\r\n                    UNION ALL\r\n                    SELECT iCode[iMasterId],\r\n                    CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n                    CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit\r\n                    FROM tCore_Header{0} \r\n                    JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                    WHERE tCore_Header{0}.iDate < = {1} AND tCore_Data{0}.bUpdateFA = 1 \r\n                    AND tCore_Data{0}.bSuspendUpdateFA <> 1 AND tCore_Header{0}.bSuspended = 0\r\n                )Temp {2}\r\n                GROUP BY iMasterId", FConvert.GetSuffix(iCompId), iDate, arg);
			dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			list = new List<IdValuePair>();
			while (dataReader.Read())
			{
				idValuePair = new IdValuePair();
				idValuePair.ID = Convert.ToInt32(dataReader["iMasterId"]);
				idValuePair.Value = Convert.ToDecimal(dataReader["Balance"]);
				list.Add(idValuePair);
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			m_sError = $"GetAccountBalance : {ex.Message}";
		}
		finally
		{
			if (dataReader != null && !dataReader.IsClosed)
			{
				dataReader.Close();
			}
			dataReader = null;
		}
		return list.ToArray();
	}

	private decimal getAmountFromDictionary(IdValuePair[] arrValues, int iAccount)
	{
		decimal result = 0m;
		for (int i = 0; i < arrValues.Length; i++)
		{
			if (arrValues[i].ID == iAccount)
			{
				return (decimal)arrValues[i].Value;
			}
		}
		return result;
	}

