	public TagwiseBalance[] GetTagwiseStocks(int iMasterId, int iUserId, int iCompId)
	{
		List<TagwiseBalance> list = null;
		List<StockValue> list2 = null;
		List<IdValuePair> list3 = null;
		RepRecord repRecord = null;
		IDataReader dataReader = null;
		TagwiseBalance tagwiseBalance = null;
		string text = null;
		decimal num = 0m;
		decimal num2 = 0m;
		decimal num3 = 0m;
		decimal dReservedInSO = 0m;
		repRecord = new RepRecord();
		repRecord.UserId = iUserId;
		repRecord.EndingDate = new Date(m_objCalType).GetToday(m_objCalType).Value;
		list = new List<TagwiseBalance>();
		m_iCompanyId = iCompId;
		if (m_objDatabase == null)
		{
			m_objDatabase = DatabaseWrapper.GetDatabase2(iCompId);
		}
		if (!string.IsNullOrEmpty(_focus.company(iCompId).invTagName))
		{
			SINGLE_MASTER = true;
			DONOTUSEREALTIME = _focus.company(iCompId).getPreferenceValue(PreferenceCategories.Print, 38) > 0;
			list3 = new List<IdValuePair>();
			list3.Add(new IdValuePair(iMasterId, false));
			list2 = GetTagwiseStocks(list3, repRecord, null, bExclude: false);
			text = $"SELECT iMasterId,sName FROM {_focus.company(iCompId).invTagName} WHERE iMasterId > 0 AND bGroup = 0 AND iTreeId = 0";
			dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				tagwiseBalance = new TagwiseBalance();
				tagwiseBalance.Id = Convert.ToInt32(dataReader["iMasterId"]);
				tagwiseBalance.Name = Convert.ToString(dataReader["sName"]);
				list.Add(tagwiseBalance);
			}
			dataReader.Close();
			AverageRateType averageRateType = (AverageRateType)_focus.company(iCompId).getPreferenceValue(PreferenceCategories.Inventory, 32);
			for (int i = 0; i < list.Count; i++)
			{
				num3 = 0m;
				num = (num2 = num3);
				list[i].Rate = GetStockFromDictionary(list2, iMasterId, ref num, ref num3, ref num2, list[i].Id, bDontRemoveAfterFetch: true);
				list[i].Quantity = num;
				if (averageRateType - 1 <= AverageRateType.QtyByInvTagRateOverall)
				{
					list[i].Value = list[i].Rate * num;
				}
				else
				{
					list[i].Value = num3;
				}
				list[i].ReservedQuantity = (decimal)getReservedStock(repRecord, iMasterId, list[i].Id.ToString(), iCompId, ref dReservedInSO);
			}
		}
		return list.ToArray();
	}

