	private string getStockFilter(_Filter[] arrFilter, List<IdValuePair> arrProduct, string strWarehouse, bool bExclude, int iUserId, int iCompId, bool bIncludeServiceType, bool bIncludeNonStockType, ref string sJoinQuery, ref string sCloseFilter, int iDepartment = -1)
	{
		string suffix = FConvert.GetSuffix(iCompId);
		string text = string.Empty;
		bool flag = false;
		bool flag2 = false;
		bool flag3 = false;
		int num = 0;
		List<MasterRights> list = null;
		List<FieldData> arrMasterField = null;
		if (arrProduct != null && arrProduct.Count > 0)
		{
			text = ((arrProduct.Count != 1) ? (text + string.Format(" AND tCore_Indta{0}.iProduct IN({1})", suffix, string.Join(",", (from p in arrProduct
				where !Convert.ToBoolean(p.Value)
				select p.ID.ToString()).ToArray()))) : (text + $" AND tCore_Indta{suffix}.iProduct = {arrProduct[0].ID}"));
		}
		if (!bIncludeServiceType)
		{
			text += $" AND iProductType <> {1}";
		}
		if (!bIncludeNonStockType)
		{
			text += $" AND iProductType <> {5} ";
		}
		if (!string.IsNullOrEmpty(strWarehouse) && strWarehouse != "0")
		{
			text += string.Format(" AND tCore_Data{0}.iInvTag {1} IN ({2})", suffix, bExclude ? "NOT" : string.Empty, strWarehouse);
		}
		else if (iUserId > 1 && _focus.company(iCompId).getPreferenceValue(PreferenceCategories.Print, 36) == 0)
		{
			if (_focus.company(iCompId).user(iUserId).RoleMasters == null)
			{
				list = new COptionbase().CheckRoleMasters(iUserId, "2,3,6,7", ref arrMasterField, m_objDatabase, iCompId);
				_focus.company(iCompId).user(iUserId).RoleMasters = new UserRoleField(list, arrMasterField);
			}
			list = _focus.company(iCompId).user(iUserId).RoleMasters.masterRestrictions;
			if (list != null && list.Count > 0)
			{
				for (num = 0; num < list.Count; num++)
				{
					strWarehouse = list[num].Tag;
					if (string.IsNullOrEmpty(strWarehouse))
					{
						continue;
					}
					if (!list[num].Exclude && (from p in strWarehouse.Split(',')
						where p == "0"
						select p).Count() == 0)
					{
						strWarehouse += ",0";
					}
					if (list[num].ID == _focus.company(iCompId).invTagId)
					{
						text += string.Format(" AND ISNULL(tCore_Data{0}.iInvTag,0) {1} IN ({2})", suffix, list[num].Exclude ? "NOT" : string.Empty, strWarehouse);
						sCloseFilter += string.Format(" AND ISNULL(tCore_ibalsOb{0}.iInvTag,0) {1} IN ({2})", suffix, list[num].Exclude ? "NOT" : string.Empty, strWarehouse);
					}
					else if (list[num].ID == _focus.company(iCompId).faTagId)
					{
						text += string.Format(" AND ISNULL(tCore_Data{0}.iFaTag,0) {1} IN ({2})", suffix, list[num].Exclude ? "NOT" : string.Empty, strWarehouse);
					}
					else if (list[num].ID != 1 && list[num].ID != 2)
					{
						text += string.Format(" AND ISNULL(tCore_Data_Tags{0}.iTag{1},0) {2} IN ({3})", suffix, list[num].ID, list[num].Exclude ? "NOT" : string.Empty, strWarehouse);
						if (!flag3)
						{
							sJoinQuery += string.Format(" LEFT JOIN tCore_Data_Tags{0} ON tCore_Data{0}.iBodyId = tCore_Data_Tags{0}.iBodyId", suffix);
						}
						flag3 = true;
					}
				}
			}
		}
		if (arrFilter != null && arrFilter.Length != 0 && _focus.company(iCompId).faTagName != _focus.company(iCompId).invTagName)
		{
			strWarehouse = _focus.company(iCompId).getFinanceFilter(arrFilter);
			if (!string.IsNullOrEmpty(strWarehouse) && strWarehouse != "0")
			{
				text += string.Format(" AND tCore_Data{0}.iFaTag {1} IN ({2})", suffix, bExclude ? "NOT" : string.Empty, strWarehouse);
			}
		}
		if (iDepartment > 0)
		{
			text += string.Format(" AND tCore_Data{0}.iFaTag {1} IN ({2})", suffix, bExclude ? "NOT" : string.Empty, iDepartment);
		}
		if (arrFilter != null && arrFilter.Length != 0)
		{
			for (int num2 = 0; num2 < arrFilter.Length; num2++)
			{
				if (arrFilter[num2].FieldId == 13)
				{
					if (!flag2)
					{
						sJoinQuery += string.Format(" LEFT JOIN tCore_Batch{0} ON tCore_Data{0}.iBodyId = tCore_Batch{0}.iBodyId", suffix);
					}
					text += $" AND tCore_Batch{suffix}.sBatchNo = '{arrFilter[num2].CompareText}'";
					flag2 = true;
				}
				else if (arrFilter[num2].FieldId == 162 || arrFilter[num2].SubParentId == 162)
				{
					if (!flag)
					{
						sJoinQuery += string.Format(" LEFT JOIN tCore_Bins{0} ON tCore_Data{0}.iBodyId = tCore_Bins{0}.iBodyId", suffix);
					}
					text += $" AND tCore_Bins{suffix}.iBin = {arrFilter[num2].CompareValue}";
					flag = true;
				}
			}
		}
		return text;
	}

