	private string GetQCStatusFilter(IdValuePair[] arrInputs)
	{
		string arg = (string.IsNullOrEmpty(m_strSuffix) ? FConvert.GetSuffix(m_iCompanyId) : m_strSuffix);
		string result = $" AND tCore_Data{arg}.bSuspendUpdateStocks <> 1";
		if (FConvert.GetInputValue(arrInputs, 4) == 1)
		{
			result = string.Format(" AND (tCore_Data{0}.bSuspendUpdateStocks <> 1 OR (tCore_Indta{0}.iQCStatus = 1 AND tCore_Data{0}.iAuthStatus = 1))", arg);
		}
		return result;
	}

	private decimal getStandardRate(List<IdNamePair> arrStandardRate, int iProductId, int iDate, decimal dOrigRate)
	{
		decimal result = dOrigRate;
		if (arrStandardRate != null && arrStandardRate.Count > 0)
		{
			for (int i = 0; i < arrStandardRate.Count; i++)
			{
				if (arrStandardRate[i].ID == iProductId && iDate >= Convert.ToInt32(arrStandardRate[i].Name))
				{
					result = Convert.ToDecimal(arrStandardRate[i].Tag);
				}
			}
		}
		return result;
	}

	private List<IdNamePair> GetStandardStocks(int iStartDate, int iEndDate, string sFilter, string sJoinQuery)
	{
		string suffix = FConvert.GetSuffix(m_iCompanyId);
		string text = null;
		IDataReader dataReader = null;
		DbCommand dbCommand = null;
		List<IdNamePair> list = null;
		text = string.Format("SELECT DISTINCT iProductId,iDate[Date], mCore_StdRate{0}.mRate[Rate] \r\n                FROM tCore_Data{0} \r\n                JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId   \r\n                JOIN mCore_StdRate{0} WITH (READUNCOMMITTED) ON tCore_Indta{0}.iProduct = mCore_StdRate{0}.iProductId           \r\n                JOIN mCore_Product ON mCore_Product.iMasterId =  mCore_StdRate{0}.iProductId {5}\r\n                WHERE iDate BETWEEN {1} AND {2} AND iValuationMethod = {3} {4} \r\n                ORDER BY iProductId, iDate", suffix, iStartDate, iEndDate, 6, sFilter, sJoinQuery);
		dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		dbCommand.CommandTimeout = 0;
		dataReader = m_objDatabase.ExecuteReader(dbCommand);
		list = new List<IdNamePair>();
		while (dataReader.Read())
		{
			list.Add(new IdNamePair(Convert.ToInt32(dataReader["iProductId"]), Convert.ToString(dataReader["Date"]), dataReader["Rate"]));
		}
		dataReader.Close();
		return list;
	}

