	private int getOpeningItemIndex(List<StockValue> arrData, int iItem)
	{
		for (int i = 0; i < arrData.Count; i++)
		{
			if (arrData[i].ProductId == iItem)
			{
				return i;
			}
		}
		return -1;
	}

	private int getTagwiseOpeningItemIndex(List<StockValue> arrData, int iItem, int iWarehouse)
	{
		for (int i = 0; i < arrData.Count; i++)
		{
			if (arrData[i].ProductId == iItem && arrData[i].WarehouseId == iWarehouse)
			{
				return i;
			}
		}
		return -1;
	}

