	private decimal getBalanceFIFOOld(List<InventoryStock> arrInventoryStock, ref decimal dBalQty, ref decimal dLocalStockValue)
	{
		int num = 0;
		int num2 = 0;
		decimal num3 = arrInventoryStock.Sum((InventoryStock p) => p.Quantity);
		List<InventoryStock> list = arrInventoryStock.Where((InventoryStock p) => !p.IsInward).ToList();
		for (num2 = 0; num2 < list.Count; num2++)
		{
			dBalQty = Math.Abs(list[num2].Quantity);
			for (num = 0; num < arrInventoryStock.Count; num++)
			{
				if (arrInventoryStock[num].Quantity > 0m && arrInventoryStock[num].IsInward)
				{
					if (dBalQty <= arrInventoryStock[num].Quantity)
					{
						arrInventoryStock[num].Quantity -= dBalQty;
						arrInventoryStock[num].Value = arrInventoryStock[num].Quantity * arrInventoryStock[num].Rate;
						dBalQty = 0m;
					}
					else
					{
						dBalQty -= arrInventoryStock[num].Quantity;
						InventoryStock inventoryStock = arrInventoryStock[num];
						InventoryStock inventoryStock2 = arrInventoryStock[num];
						decimal num4 = (arrInventoryStock[num].Value = 0m);
						decimal quantity = (inventoryStock2.Rate = num4);
						inventoryStock.Quantity = quantity;
					}
					if (dBalQty <= 0m)
					{
						break;
					}
				}
			}
		}
		decimal result = arrInventoryStock.Where((InventoryStock p) => p.IsInward).Sum((InventoryStock p) => p.Value);
		dLocalStockValue = arrInventoryStock.Where((InventoryStock p) => p.IsInward).Sum((InventoryStock p) => p.LocalValue);
		dBalQty = num3;
		return result;
	}

	private decimal getBalanceFIFO(List<InventoryStock> arrInventoryStock, ref decimal dBalQty, ref decimal dLocalStockValue)
	{
		int num = 0;
		int num2 = 0;
		decimal num3 = arrInventoryStock.Sum((InventoryStock p) => p.Quantity);
		InventoryStock[] array = arrInventoryStock.Where((InventoryStock p) => !p.IsInward && p.Quantity != 0m).ToArray();
		InventoryStock[] array2 = arrInventoryStock.Where((InventoryStock p) => p.IsInward && p.Quantity > 0m).ToArray();
		for (num2 = 0; num2 < array.Length; num2++)
		{
			dBalQty = Math.Abs(array[num2].Quantity);
			for (num = 0; num < array2.Length; num++)
			{
				if (dBalQty <= array2[num].Quantity)
				{
					array2[num].Quantity -= dBalQty;
					array2[num].Value = array2[num].Quantity * array2[num].Rate;
					dBalQty = 0m;
				}
				else
				{
					dBalQty -= array2[num].Quantity;
					InventoryStock obj = array2[num];
					InventoryStock obj2 = array2[num];
					decimal num4 = (array2[num].Value = 0m);
					decimal quantity = (obj2.Rate = num4);
					obj.Quantity = quantity;
				}
				if (dBalQty <= 0m)
				{
					break;
				}
			}
			arrInventoryStock.Clear();
			arrInventoryStock.AddRange(array2);
		}
		decimal result = arrInventoryStock.Where((InventoryStock p) => p.IsInward).Sum((InventoryStock p) => p.Value);
		dLocalStockValue = arrInventoryStock.Where((InventoryStock p) => p.IsInward).Sum((InventoryStock p) => p.LocalValue);
		dBalQty = num3;
		return result;
	}

