	private bool GetUsedItemValuations(ref bool bFIFOAvg, ref bool bStandardAvg, ref bool bBatchRateAvg)
	{
		if (m_bFIFOAvg || m_bStandardAvg || m_bBatchRateAvg || m_bWeightedAvg)
		{
			bFIFOAvg = m_bFIFOAvg;
			bStandardAvg = m_bStandardAvg;
			bBatchRateAvg = m_bBatchRateAvg;
		}
		else
		{
			bool bWeightedAvg = false;
			string text = null;
			DbCommand dbCommand = null;
			IDataReader dataReader = null;
			if (m_objDatabase == null)
			{
				m_objDatabase = DatabaseWrapper.GetDatabase2(m_iCompanyId);
			}
			text = "SELECT DISTINCT iValuationMethod FROM mCore_Product WHERE iMasterId > 0 AND iStatus <> 5";
			dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dbCommand.CommandTimeout = 0;
			dataReader = m_objDatabase.ExecuteReader(dbCommand);
			while (dataReader.Read())
			{
				switch ((ValuationMethod)(byte)Convert.ToInt32(dataReader["iValuationMethod"]))
				{
				case ValuationMethod.None:
				case ValuationMethod.WeightedAvg:
				case ValuationMethod.MonthlyWeightedAvg:
					bWeightedAvg = true;
					break;
				case ValuationMethod.FIFO:
				case ValuationMethod.FIFOTransactionTime:
					bFIFOAvg = true;
					break;
				case ValuationMethod.Standard:
					bStandardAvg = true;
					break;
				case ValuationMethod.BatchRate:
					bBatchRateAvg = true;
					break;
				}
			}
			dataReader.Close();
			m_bWeightedAvg = bWeightedAvg;
			m_bFIFOAvg = bFIFOAvg;
			m_bStandardAvg = bStandardAvg;
			m_bBatchRateAvg = bBatchRateAvg;
		}
		return m_bWeightedAvg;
	}

