		text = string.Format("SELECT sName, ISNULL(SUM(mAmount2),0)[Amount] \r\n            FROM tCore_Header{0} \r\n            JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n            JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iVoucherType = cCore_Vouchers{0}.iVoucherType {3}\r\n            WHERE bInventory = 0 AND tCore_Header{0}.iVoucherClass <> 256 AND (iCode IN({1}) OR iBookNo IN({1})) {2}\r\n            GROUP BY sName HAVING SUM(mAmount2) <> 0", suffix, text2, text3, sJoinQuery);
		dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		while (dataReader.Read())
		{
			list2.Add(getGLDiffLine(Convert.ToString(dataReader[0]), 0, 0m, Convert.ToDecimal(dataReader[1])));
		}
		dataReader.Close();
		num5 = 0m;
		text = string.Format("SELECT TempTable.iDate \r\n            ,CASE WHEN SUM([DrYTD])+SUM([CrYTD]) < 0 THEN SUM([DrYTD])+SUM([CrYTD]) ELSE 0 END[DrYTD]\r\n            ,CASE WHEN SUM([DrYTD])+SUM([CrYTD]) > 0 THEN SUM([DrYTD])+SUM([CrYTD]) ELSE 0 END[CrYTD]\r\n            FROM \r\n            (\r\n\t            SELECT tCore_Header{0}.iDate, Debit [DrYTD], Credit[CrYTD]\r\n\t            FROM \r\n\t            (\r\n\t\t            SELECT tCore_Data{0}.iBodyId,iBookNo[iMasterId],\r\n\t\t            CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t\t            CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit\r\n\t\t            FROM tCore_Data{0} \r\n\t\t            WHERE mAmount2 <> 0 \r\n\t\t            UNION ALL\r\n\t\t            SELECT tCore_Data{0}.iBodyId,iCode[iMasterId],\r\n\t\t            CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n\t\t            CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit\r\n\t\t            FROM tCore_Data{0} \r\n\t\t            WHERE mAmount1 <> 0 \r\n\t            )InnerTable JOIN tCore_Data{0} ON InnerTable.[iBodyId] = tCore_Data{0}.iBodyId\r\n\t            JOIN tCore_Header{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId {4}\r\n\t            WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA = 0 AND tCore_Header{0}.bSuspended = 0 AND tCore_Data{0}.iAuthStatus < 2\r\n\t            AND tCore_Header{0}.iDate BETWEEN 0 AND {1} AND InnerTable.iMasterId IN({2}) {3}\r\n            ) TempTable \r\n            GROUP BY TempTable.iDate\r\n            HAVING (CASE WHEN SUM([DrYTD])+SUM([CrYTD]) < 0 THEN SUM([DrYTD])+SUM([CrYTD]) ELSE 0 END) <> 0 OR \r\n            (CASE WHEN SUM([DrYTD])+SUM([CrYTD]) > 0 THEN SUM([DrYTD])+SUM([CrYTD]) ELSE 0 END) <> 0\r\n            ORDER BY TempTable.iDate", suffix, objRec.EndingDate, text2, text3, sJoinQuery);
		list3 = new List<IdDualValue>();
		dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		while (dataReader.Read())
		{
			list3.Add(new IdDualValue(Convert.ToInt32(dataReader[0]), Convert.ToDecimal(dataReader[1]), Convert.ToDecimal(dataReader[2])));
		}
		dataReader.Close();
		num6 = 0m;
		for (num = 0; num < list3.Count; num++)
		{
			num6 += list3[num].Value1 + list3[num].Value2;
			if (list3[num].Id >= objRec.StartingDate)
			{
				objRec.EndingDate = list3[num].Id;
				num5 = 0m;
				if (num2 > 0)
				{
					list = GetTagwiseStocks(null, objRec, num2.ToString(), bExclude: false);
				}
				else
				{
					list = ((num3 <= 0) ? GetStocks(null, objRec, null, bExclude: false) : GetFinanceTagwiseStocks(null, objRec, bExclude: false, num3));
				}
				num5 = ((num3 <= 0) ? getBalanceValue(list, num2, objRec.Masters) : getBalanceValue(list, num3, objRec.Masters));
				if (Math.Abs(Math.Round(num6, 2)) != Math.Abs(Math.Round(num5, 2)))
				{
					list2.Add(getGLDiffLine(string.Empty, list3[num].Id, num5, num6));
				}
			}
		}
		oMatrixData.ColumnData = list2.ToArray();
	}

	private LineData getGLDiffLine(string sParticular, int iId, decimal dStockValue, decimal dAmount)
	{
		LineData lineData = new LineData
		{
			CellData = new object[6]
		};
		lineData.CellData[0] = new ReportRowHeader
		{
			Id = iId
		};
		lineData.CellData[1] = sParticular;
		lineData.CellData[2] = iId;
		lineData.CellData[3] = dStockValue;
		lineData.CellData[4] = dAmount;
		dAmount = Math.Abs(dAmount);
		lineData.CellData[5] = ((dStockValue > dAmount) ? (dStockValue - dAmount) : (dAmount - dStockValue));
		return lineData;
	}

	private decimal getBalanceValue(List<StockValue> arrStockValue, int iWarehouse, ComboData[] arrItems)
	{
		int num = 0;
		decimal result = 0m;
		decimal dQuantity = 0m;
		decimal dValue = 0m;
		if (arrStockValue != null && arrStockValue.Count > 0)
		{
			if (arrItems != null && arrItems.Length != 0)
			{
				for (num = 0; num < arrItems.Length; num++)
				{
					GetStockFromDictionary(arrStockValue, arrItems[num].ID, ref dQuantity, ref dValue, ref dQuantity, iWarehouse, bDontRemoveAfterFetch: true);
					result += dValue;
				}
			}
			else
			{
				for (num = 0; num < arrStockValue.Count; num++)
				{
					result += arrStockValue[num].Value;
				}
			}
		}
		return result;
	}

