	private LineData getGLDiffLineDatewise(IdNamePair oStock, IdNamePair oLedger)
	{
		LineData lineData = new LineData();
		lineData.CellData = new object[8];
		if (oStock != null)
		{
			lineData.CellData[0] = oStock.ID;
			lineData.CellData[1] = oStock.Name;
			if (Convert.ToDecimal(oStock.Tag) > 0m)
			{
				lineData.CellData[2] = Convert.ToDecimal(oStock.Tag);
			}
			if (Convert.ToDecimal(oStock.Tag) < 0m)
			{
				lineData.CellData[3] = -Convert.ToDecimal(oStock.Tag);
			}
		}
		if (oLedger != null)
		{
			lineData.CellData[4] = oLedger.ID;
			lineData.CellData[5] = oLedger.Name;
			if (Convert.ToDecimal(oLedger.Tag) < 0m)
			{
				lineData.CellData[6] = -Convert.ToDecimal(oLedger.Tag);
			}
			if (Convert.ToDecimal(oLedger.Tag) > 0m)
			{
				lineData.CellData[7] = Convert.ToDecimal(oLedger.Tag);
			}
		}
		return lineData;
	}

	public LineData[] GetBatchNegitiveTransData(IdValuePair[] arrInputs, ref string strHeader, int iCompanyId)
	{
		Database database = null;
		List<LineData> list = new List<LineData>();
		database = DatabaseWrapper.GetDatabase2(iCompanyId, -1, bReplicationServer: true);
		string text = string.Format("\r\n            Select c.sName VoucherType,sVoucherNo,convert(varchar,dbo.IntToDate(iDate),105) Date_,Case  when fQuantityInBase > 0 then fQuantityInBase else 0 End Received,\r\n            Case  when fQuantityInBase < 0 then fQuantityInBase else 0 End Issued, 0 Balance,\r\n            sBatchNo,Case when iExpiryDate = 0 then '' Else convert(varchar,dbo.IntToDate(iExpiryDate),105) End iExpiryDate,Case when iMfDate = 0 then '' Else convert(varchar,dbo.IntToDate(iMfDate),105) End iMfDate,\r\n            isnull(Created.sUserName,'Super user') CreatedBy,isnull(Modified.sUserName,'Super user') ModifiedBy,\r\n            convert(varchar,dbo.IntToDate(b.iCreatedDate),105) iCreatedDate,dbo.fCore_IntToTime(b.iCreatedTime) iCreatedTime,convert(varchar,dbo.IntToDate(b.iModifiedDate),105) iModifiedDate,dbo.fCore_IntToTime(b.iModifiedTime)iModifiedTime,b.iHeaderId\r\n            From tCore_Batch{0} bat\r\n            join tCore_Data{0} a on a.iBodyId = bat.iBodyId\r\n            join tCore_Indta{0} i on a.iBodyId = i.iBodyId\r\n            join tCore_Header{0} b on a.iHeaderId = b.iHeaderId\r\n            join cCore_Vouchers{0} c on c.iVoucherType = b.iVoucherType \r\n            join vmCore_Product p on p.iMasterId = i.iProduct And iTreeId = 0\r\n            Join vmCore_InvTag w on w.iMasterId = iInvTag\r\n            Join mSec_Users Created on Created.iUserId = b.iUserId\r\n            Join mSec_Users Modified on Modified.iUserId = b.iModifiedBy\r\n            Where iProduct ={1} And iInvTag ={2} And sBatchNo ='{3}'\t\r\n            And bSuspended = 0 And bUpdateStocks = 1 ANd bSuspendUpdateStocks = 0  And a.iAuthStatus < 2 \r\n            order by a.iBodyId", FConvert.GetSuffix(iCompanyId), arrInputs[0].Value, arrInputs[2].Value, arrInputs[3].Value);
		IDataReader dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		object[] array = null;
		while (dataReader.Read())
		{
			array = new object[dataReader.FieldCount];
			dataReader.GetValues(array);
			list.Add(new LineData
			{
				CellData = array
			});
		}
		dataReader.Close();
		text = $"Select 'Item Name --'+  sName + ' Code -- '  + sCode From mCore_Product where iMasterId = {arrInputs[0].Value}";
		strHeader = Convert.ToString(database.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text)) + " ( ";
		text = $"Select sName From vmCore_InvTag where iMasterId = {arrInputs[2].Value}";
		strHeader = strHeader + Convert.ToString(database.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text)) + " ) ";
		return list.ToArray();
	}

	private List<StockValue> getOpStockFromRedis(string sKey)
	{
		byte[] array = null;
		List<StockValue> result = null;
		if (m_bUseRedisServer)
		{
			array = ProngHorn.GetCache(sKey);
			if (array != null)
			{
				result = (List<StockValue>)FConvert.ByteArrayToObject(array);
			}
		}
		else if (_focus.company(m_iCompanyId).report(sKey).itemBalance != null)
		{
			result = _focus.company(m_iCompanyId).report(sKey).itemBalance;
		}
		return result;
	}

	private void setOpStockToRedis(string sKey, List<StockValue> arrItemBalance)
	{
		byte[] array = null;
		if (arrItemBalance != null)
		{
			if (m_bUseRedisServer)
			{
				array = FConvert.ObjectToByteArray(arrItemBalance);
				ProngHorn.SaveCashe(sKey, array);
			}
			else
			{
				_focus.company(m_iCompanyId).report(sKey).itemBalance = arrItemBalance;
			}
		}
	}

	private void deleteRedisData(string sKey)
	{
		if (!m_bUseRedisServer && _focus.company(m_iCompanyId).report(sKey).itemBalance != null)
		{
			_focus.company(m_iCompanyId).report(sKey).itemBalance = null;
		}
	}

	public StockData GetStockData(InputStockData objInputDate, int iCompId, string sDateFormat)
