	private IdNamePair[] GetQueryRecentData(int iUserId, bool IsInventory, int iCompanyId)
	{
		int iMasterId = -1;
		string empty = string.Empty;
		m_strSuffix = FConvert.GetSuffix(iCompanyId);
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		string[] array = null;
		LedgerBalanceData value = null;
		Dictionary<int, LedgerBalanceData> dictionary = null;
		List<StockValue> list = null;
		List<IdNamePair> list2 = new List<IdNamePair>();
		List<FieldData> arrMasterField = new List<FieldData>();
		List<MasterRights> list3 = null;
		try
		{
			if (m_objDatabase == null)
			{
				m_objDatabase = DatabaseWrapper.GetDatabase2(iCompanyId, -1, bReplicationServer: true);
			}
			if (_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Print, 36) == 0)
			{
				if (_focus.company(iCompanyId).user(iUserId).RoleMasters == null)
				{
					list3 = new COptionbase().CheckRoleMasters(iUserId, "1,3,7", ref arrMasterField, m_objDatabase, iCompanyId);
					_focus.company(iCompanyId).user(iUserId).RoleMasters = new UserRoleField(list3, arrMasterField);
				}
				list3 = _focus.company(iCompanyId).user(iUserId).RoleMasters.masterRestrictions;
				if (list3 != null && list3.Count > 0)
				{
					if (IsInventory)
					{
						if ((from p in list3
							where p.ID == 2
							select p.Tag).Count() > 0)
						{
							array = (from p in list3
								where p.ID == 2
								select p.Tag).FirstOrDefault().Split(',');
						}
					}
					else if ((from p in list3
						where p.ID == 1
						select p.Tag).Count() > 0)
					{
						array = (from p in list3
							where p.ID == 1
							select p.Tag).FirstOrDefault().Split(',');
					}
				}
			}
			empty = string.Format("SELECT {2} iMasterId, sName, sCode FROM cCore_UserFavorite{0} \r\n                JOIN {3} ON iMasterId = iFieldId\r\n                WHERE iScreenId = {4} AND iUserId = {1} ORDER BY iValue DESC", m_strSuffix, iUserId, (array == null) ? "TOP 10" : string.Empty, IsInventory ? "mCore_Product" : "mCore_Account", IsInventory ? 202 : 204);
			dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			dataReader = m_objDatabase.ExecuteReader(dbCommand);
			while (dataReader.Read())
			{
				iMasterId = dataReader.GetInt32(0);
				if (array != null && array.Length != 0)
				{
					iMasterId = ((array.Where((string p) => p == iMasterId.ToString()).Count() > 0) ? iMasterId : (-1));
				}
				if (iMasterId > 0)
				{
					list2.Add(new IdNamePair(iMasterId, dataReader.GetString(1), dataReader.GetString(2), null));
				}
			}
			dataReader.Close();
			if (list2.Count > 0)
			{
				RepRecord repRecord = new RepRecord();
				repRecord.EndingDate = new Date().GetToday(m_objCalType).Value;
				repRecord.UserId = iUserId;
				m_iCompanyId = iCompanyId;
				if (IsInventory)
				{
					DONOTUSEREALTIME = _focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Print, 38) > 0;
					list = GetStocks(list2.Select((IdNamePair p) => new IdValuePair(p.ID, false)).ToList(), repRecord, null, bExclude: false);
					for (int num = 0; num < list.Count; num++)
					{
						for (int num2 = 0; num2 < list2.Count; num2++)
						{
							if (list[num].ProductId == list2[num2].ID)
							{
								list2[num2].Tag = list[num];
								break;
							}
						}
					}
				}
				else
				{
					repRecord.StartingDate = new Date().GetToday(m_objCalType).Value;
					dictionary = GetLedgerOpeningBalance(repRecord, bLoadAccountProperty: false);
					for (int num3 = 0; num3 < list2.Count; num3++)
					{
						if (dictionary.TryGetValue(list2[num3].ID, out value))
						{
							list2[num3].Tag = value;
							value = null;
						}
					}
				}
			}
		}
		catch (Exception ex)
		{
			list2.Clear();
			list2.Add(new IdNamePair(-1, ex.Message, new StockValue()));
			m_sError = $"GetQueryRecentData : {ex.Message}";
		}
		finally
		{
			if (dbCommand.Connection.State == ConnectionState.Open)
			{
				dbCommand.Connection.Close();
			}
		}
		return (from p in list2
			where p.Tag != null
			select (p)).ToArray();
	}

