	public decimal fn_CalculateDepreciationWithAddYrs(int AssetId, int iDepMethod, int StartDate, int EndDate, int CommencementDate, decimal Price, decimal ScrapVal, int RateOfDepInYears, int RateOfDepInMonths, bool ScreenType, bool CalcuDepforIT, List<AddYrsData> lstAddYrsData, int iFixAQty, bool DepAsPerAccountingDate, List<FADep> lstDisposedData, short DepPostingType, decimal CumDep, List<FADep> lstFADepAddReduce, short DecPrec, decimal ITAccruedValue, decimal ITDepRate, decimal AUStartUnit, decimal AUMaxUsageLimit, List<AssetusageStruct> lstAUStruct, short UnitOfUsage, decimal RateOfDep, DepreciationGetType iDepreciationGetType = DepreciationGetType.Both)
	{
		try
		{
			if (iDepMethod == 2 && lstAddYrsData.Where((AddYrsData p) => p.iFixAssetId == AssetId).Count() > 0)
			{
				AddYrsData addYrsData = lstAddYrsData.Where((AddYrsData p) => p.iFixAssetId == AssetId).First();
				int iCommencementDate = addYrsData.iCommencementDate;
				int iNoOfYears = addYrsData.iNoOfYears;
				int iNoOfMonths = addYrsData.iNoOfMonths;
				decimal fScrapValue = addYrsData.fScrapValue;
				_ = new Date(CommencementDate, m_objCalType).Add(-1, DateAdd.Days).Value;
				iCommencementDate = new Date(iCommencementDate, m_objCalType).Add(-1, DateAdd.Days).Value;
				int value = new Date(CommencementDate, m_objCalType).Add(RateOfDepInYears + iNoOfYears, DateAdd.Years).Value;
				value = new Date(value, m_objCalType).Add(RateOfDepInMonths + iNoOfMonths, DateAdd.Months).Value;
				value = new Date(value, m_objCalType).Add(-1, DateAdd.Days).Value;
				if (EndDate > value)
				{
					EndDate = value;
				}
				decimal num = fn_CalculateDepreciationWithAddYrs(AssetId, iDepMethod, StartDate, iCommencementDate, CommencementDate, Price, ScrapVal, RateOfDepInYears, RateOfDepInMonths, ScreenType, CalcuDepforIT, lstAddYrsData, iFixAQty, DepAsPerAccountingDate, lstDisposedData, DepPostingType, CumDep, lstFADepAddReduce, DecPrec, ITAccruedValue, ITDepRate, AUStartUnit, AUMaxUsageLimit, lstAUStruct, UnitOfUsage, RateOfDep, iDepreciationGetType);
				decimal num2 = CumDep + fn_CalculateDepreciationWithAddYrs(AssetId, iDepMethod, CommencementDate, iCommencementDate, CommencementDate, Price, ScrapVal, RateOfDepInYears, RateOfDepInMonths, ScreenType, CalcuDepforIT, lstAddYrsData, iFixAQty, DepAsPerAccountingDate, lstDisposedData, DepPostingType, CumDep, lstFADepAddReduce, DecPrec, ITAccruedValue, ITDepRate, AUStartUnit, AUMaxUsageLimit, lstAUStruct, UnitOfUsage, RateOfDep, iDepreciationGetType);
				decimal num3 = Price - num2 - ScrapVal - fScrapValue;
				int value2 = new Date(iCommencementDate, m_objCalType).Add(1, DateAdd.Days).Value;
				decimal num4 = Math.Abs(Convert.ToInt32((new Date(m_objCalType).IntToDate(new Date(value, m_objCalType).Add(1, DateAdd.Days).Value) - new Date(m_objCalType).IntToDate(value2)).TotalDays)) + 1;
				decimal num5 = fn_CalculateDepreciationWithAddYrs(AssetId, iDepMethod, value2, new Date(StartDate, m_objCalType).Add(-1, DateAdd.Days).Value, CommencementDate, Price, ScrapVal, RateOfDepInYears, RateOfDepInMonths, ScreenType, CalcuDepforIT, lstAddYrsData, iFixAQty, DepAsPerAccountingDate, lstDisposedData, DepPostingType, CumDep, lstFADepAddReduce, DecPrec, ITAccruedValue, ITDepRate, AUStartUnit, AUMaxUsageLimit, lstAUStruct, UnitOfUsage, RateOfDep, iDepreciationGetType);
				decimal num6 = num4 / 365m;
				_ = num3 / num6;
				decimal num7 = num3 / num4;
				int num8 = Math.Abs(Convert.ToInt32((new Date(m_objCalType).IntToDate(EndDate) - new Date(m_objCalType).IntToDate(value2)).TotalDays)) + 1;
				return num + (decimal)num8 * num7 - num5;
			}
			return fn_CalculateDepreciation(AssetId, iDepMethod, StartDate, EndDate, CommencementDate, Price, ScrapVal, RateOfDepInYears, RateOfDepInMonths, ScreenType, 0, CalcuDepforIT, lstDisposedData, RateOfDep, iFixAQty, 0, DepPostingType, DepAsPerAccountingDate, lstFADepAddReduce, DecPrec, ITAccruedValue, CumDep, ITDepRate, AUStartUnit, AUMaxUsageLimit, lstAUStruct, iDepreciationGetType);
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
			return 0m;
		}
	}

	public decimal fn_CalculateDepreciation(int AssetId, int iDepMethod, int StartDate, int EndDate, int CommencementDate, decimal Price, decimal ScrapVal, int RateOfDepInYears, int RateOfDepInMonths, bool ScreenType, int DisposedQty, bool CalcuDepforIT, List<FADep> lstDisposedData, decimal WDVRateOfDep, int iFAMasterTQty, short iFAStatus, short DepPostingType, bool DepAsPerAccountingDate, List<FADep> lstAddReduce, short iDecimalPrec, decimal ITAccruedValue, decimal fCumulativeDepreciation, decimal fITDepreciationRate, decimal AUStartingUnit, decimal AUMaxUsageLimit, List<AssetusageStruct> lstAssetusageStruct, DepreciationGetType iDepreciationGetType = DepreciationGetType.Both)
	{
		try
		{
			int accountingDate = _focus.company(m_iCompanyId).accountingDate;
			decimal num = Price;
			if (AssetId <= 0 || StartDate <= 0 || EndDate <= 0 || CommencementDate <= 0 || Price <= 0m)
			{
				return 0m;
			}
			if (RateOfDepInYears <= 0 && RateOfDepInMonths <= 0 && iDepMethod == 2)
			{
				return 0m;
			}
			if (WDVRateOfDep == 0m && iDepMethod == 3 && RateOfDepInYears <= 0)
			{
				return 0m;
			}
			WDVRateOfDep = RateOfDepInYears;
			if (CommencementDate < accountingDate)
			{
				CommencementDate = accountingDate;
			}
			decimal num2 = 0m;
			decimal result = 0m;
			int num3 = ((DisposedQty <= 0) ? iFAMasterTQty : DisposedQty);
			if (StartDate <= CommencementDate && RateOfDepInMonths <= 0)
			{
				StartDate = CommencementDate;
			}
			if (iFAStatus == 4)
			{
				int num4 = (from p in lstDisposedData
					where p.iFixAId == AssetId
					orderby p.iDateOfCommencement descending
					select p.iDateOfCommencement).ToArray().First();
				if (EndDate >= num4)
				{
					EndDate = num4;
				}
			}
			int num5 = lstDisposedData.Where((FADep p) => p.iDateOfCommencement < StartDate && p.iFixAId == AssetId).Sum((FADep p) => p.iDisposedQty);
			num3 -= num5;
			int num6 = 0;
			int num7 = 0;
			int num8 = 0;
			int NewFromDate = StartDate;
			int num9 = 0;
			int num10 = 0;
			decimal num11 = 0m;
			bool flag = false;
			if (lstDisposedData.Where((FADep p) => p.iFixAId == AssetId && p.iDateOfCommencement <= EndDate && p.iDateOfCommencement >= StartDate).Count() > 0)
			{
				num6 = num3;
				num5 = lstDisposedData.Where((FADep p) => p.iFixAId == AssetId && p.iDateOfCommencement <= StartDate).Sum((FADep p) => p.iDisposedQty);
				List<FADep> list = new List<FADep>();
				list = (from p in lstDisposedData
					where p.iDateOfCommencement <= EndDate && p.iDateOfCommencement >= NewFromDate && p.iFixAId == AssetId
					orderby p.iDateOfCommencement
					select p).ToList();
				num8 = list.Count();
				num6 -= num5;
				int TempCnt;
				for (TempCnt = 1; TempCnt <= num8; TempCnt++)
				{
					num10 = (from p in list
						where p.Id == TempCnt
						select p.iDisposedQty).Sum();
					num9 = (from p in list
						where p.Id == TempCnt
						select p.iDateOfCommencement).First();
					if (num8 == 1)
					{
						num3--;
						flag = true;
						break;
					}
					decimal num12 = fn_CalculateDepreciation(AssetId, iDepMethod, NewFromDate, num9, CommencementDate, Price, ScrapVal, RateOfDepInYears, RateOfDepInMonths, ScreenType: true, num6 - num10, CalcuDepforIT, lstDisposedData, WDVRateOfDep, iFAMasterTQty, iFAStatus, DepPostingType, DepAsPerAccountingDate, lstAddReduce, iDecimalPrec, ITAccruedValue, fCumulativeDepreciation, fITDepreciationRate, AUStartingUnit, AUMaxUsageLimit, lstAssetusageStruct);
					NewFromDate = new Date(num9, m_objCalType).Add(1, DateAdd.Days).Value;
					result += num12;
					num6 -= num10;
					num7 = num9;
				}
				if (EndDate > num7)
				{
					decimal num12 = fn_CalculateDepreciation(AssetId, iDepMethod, NewFromDate, EndDate, CommencementDate, Price, ScrapVal, RateOfDepInYears, RateOfDepInMonths, ScreenType: true, 0, CalcuDepforIT, lstDisposedData, WDVRateOfDep, iFAMasterTQty, iFAStatus, DepPostingType, DepAsPerAccountingDate, lstAddReduce, iDecimalPrec, ITAccruedValue, fCumulativeDepreciation, fITDepreciationRate, AUStartingUnit, AUMaxUsageLimit, lstAssetusageStruct);
					num12 *= (decimal)num6;
					result += num12;
				}
				if (!flag)
				{
					return result;
				}
			}
			if (StartDate > EndDate)
			{
				return 0m;
			}
			num2 = RateOfDepInYears + RateOfDepInMonths / 12;
			int num13 = 0;
			int num14 = 0;
			Date date = new Date(CommencementDate, m_objCalType).Add(RateOfDepInYears, DateAdd.Years);
			date = date.Add(RateOfDepInMonths, DateAdd.Months);
			num13 = ((DepPostingType != 2) ? Math.Abs(Convert.ToInt32((new Date(m_objCalType).IntToDate(CommencementDate) - date).TotalDays)) : Math.Abs((new Date(m_objCalType).IntToDate(CommencementDate).Year - date.Year) * 12 + (new Date(m_objCalType).IntToDate(CommencementDate).Month - date.Month)));
			num14 = num13;
			int num15 = 0;
			decimal num16 = 0m;
			bool flag2 = false;
			bool flag3 = false;
			decimal num17 = 0m;
			if (CommencementDate != StartDate)
			{
				int endDate = new Date(StartDate, m_objCalType).Add(-1, DateAdd.Days);
