			}
			decimal fRateOfDepreciation = WDVRateOfDep;
			if (iDepMethod == 3)
			{
				if (!CalcuDepforIT)
				{
					Price -= fCumulativeDepreciation;
					result = fn_CalculateWDV(AssetId, StartDate, EndDate, CommencementDate, Price, CalcuDepforIT, accountingDate, DepPostingType, fRateOfDepreciation, fITDepreciationRate, num3, num2);
					if (result > num - ScrapVal - fCumulativeDepreciation - num17)
					{
						return num - ScrapVal - fCumulativeDepreciation - num17;
					}
					return result;
				}
				Price -= ITAccruedValue;
			}
			decimal num18 = (decimal)lstAddReduce.Where((FADep p) => p.iFixAId == AssetId).ToList().Sum((FADep p) => p.dAddReduceAmount);
			if ((flag2 || flag3) && iDepMethod != 0 && iDepMethod != 2)
			{
				if (num13 > 0)
				{
					num16 = (Price - ScrapVal) / (decimal)num13;
				}
				if (num18 != 0m && num16 != 0m)
				{
					num15 = Convert.ToInt32(Math.Ceiling(num18) / num16);
					if (num15 > 0)
					{
						if (!flag2)
						{
							num15 = 0;
						}
					}
					else if (num15 < 0 && !flag3)
					{
						num15 = 0;
					}
				}
				date = new Date(date, m_objCalType).Add(Convert.ToInt32(num15), DateAdd.Days);
				num14 += num15;
				Price += num18;
			}
