	public decimal CalFADep(int iDepMethod, decimal dPrice, decimal dScrapValue, decimal iRateOfDep, int iNoofDays, int iTotalDays, decimal dUsage, int iDecimalPrec)
	{
		decimal num = 0m;
		try
		{
			switch (iDepMethod)
			{
			case 0:
				num = (dPrice - dScrapValue) / iRateOfDep * dUsage;
				if (dScrapValue != 0m && dPrice - num < dScrapValue)
				{
					num = dPrice - dScrapValue;
				}
				return Math.Round(num, iDecimalPrec);
			case 1:
				return dPrice;
			case 2:
				num = (dPrice - dScrapValue) / iRateOfDep * (decimal)iNoofDays / (decimal)iTotalDays;
				if (dScrapValue != 0m && dPrice - num < dScrapValue)
				{
					num = dPrice - dScrapValue;
				}
				if (dPrice > 0m && num > 0m && num > dPrice)
				{
					num = dPrice;
				}
				return Math.Round(num, iDecimalPrec);
			case 3:
				num = dPrice * iRateOfDep / 100m * (decimal)iNoofDays / (decimal)iTotalDays;
				if (dScrapValue != 0m)
				{
					if (dPrice - num < dScrapValue)
					{
						num = dPrice - dScrapValue;
					}
				}
				else if (num > dPrice)
				{
					num = dPrice;
				}
				return Math.Round(num, 7);
			case 4:
				num = dPrice * iRateOfDep / 100m * (decimal)iNoofDays / (decimal)iTotalDays;
				if (dScrapValue != 0m)
				{
					if (dPrice - num < dScrapValue)
					{
						num = dPrice - dScrapValue;
					}
				}
				else if (num > dPrice)
				{
					num = dPrice;
				}
				return Math.Round(num, 7);
			default:
				return 0m;
			}
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
			throw;
		}
	}

	public decimal fn_CalcDepFixedMonthly(int StartDate, int EndDate, decimal EachMonthPrice)
	{
