			}
			Date date2 = new Date(new Date(EndDate, m_objCalType).Year, new Date(EndDate, m_objCalType).Month, 1, m_objCalType);
			new Date(EndDate, m_objCalType);
			PersianCalendar persianCalendar = new PersianCalendar();
			int daysInMonth = persianCalendar.GetDaysInMonth(new Date(StartDate, m_objCalType).Year, new Date(StartDate, m_objCalType).Month);
			int num4 = Math.Abs(Convert.ToInt32((new Date(m_objCalType).IntToDate(StartDate) - new Date(m_objCalType).IntToDate(date)).TotalDays)) + 1;
			int daysInMonth2 = persianCalendar.GetDaysInMonth(new Date(EndDate, m_objCalType).Year, new Date(EndDate, m_objCalType).Month);
			int num5 = (((new Date(EndDate, m_objCalType).Year - new Date(StartDate, m_objCalType).Year) * 12 + (new Date(EndDate, m_objCalType).Month - new Date(StartDate, m_objCalType).Month) >= 0) ? (Math.Abs(Convert.ToInt32((new Date(m_objCalType).IntToDate(date2) - new Date(m_objCalType).IntToDate(EndDate)).TotalDays)) + 1) : 0);
			int num6 = (new Date(EndDate, m_objCalType).Year - new Date(StartDate, m_objCalType).Year) * 12 + (new Date(EndDate, m_objCalType).Month - new Date(StartDate, m_objCalType).Month) + 1;
			if (num6 == 1)
			{
