	public decimal fn_CalculateWDVMonthWise(int AssetId, int StartDate, int EndDate, int CommencementDate, decimal Price, bool CalcuDepforIT, int DepPostingType, decimal fRateOfDepreciation, decimal fITDepreciationRate)
	{
		decimal num = 0m;
		decimal num2 = 0m;
		decimal num3 = fRateOfDepreciation;
		if (CalcuDepforIT)
		{
			num3 = fITDepreciationRate;
		}
		decimal result = 0m;
		if (num3 <= 0m)
		{
			return 0m;
		}
		int iDate = CommencementDate;
		iDate = new Date(new Date(new Date(iDate, m_objCalType).Year, new Date(iDate, m_objCalType).Month, 1, m_objCalType), m_objCalType).Add(1, DateAdd.Months).Add(-1, DateAdd.Days);
		EndDate = new Date(new Date(new Date(EndDate, m_objCalType).Year, new Date(EndDate, m_objCalType).Month, 1, m_objCalType), m_objCalType).Add(1, DateAdd.Months).Add(-1, DateAdd.Days);
		PersianCalendar persianCalendar = new PersianCalendar();
		while (iDate <= EndDate)
		{
			int num4 = iDate;
			int daysInMonth = persianCalendar.GetDaysInMonth(new Date(iDate, m_objCalType).Year, new Date(iDate, m_objCalType).Month);
			decimal num5 = 0m;
			_ = new Date(StartDate, m_objCalType).Year;
			int num6 = 365;
			num = (Price - num2) * num3 / 100m;
			num5 = num * (decimal)daysInMonth / (decimal)num6;
			num2 += num * (decimal)daysInMonth / (decimal)num6;
			if (iDate >= StartDate)
			{
				result += num5;
			}
			iDate = Date.DateToInt(new Date(iDate, m_objCalType).Add(1, DateAdd.Months));
			iDate = new Date(new Date(new Date(iDate, m_objCalType).Year, new Date(iDate, m_objCalType).Month, 1, m_objCalType), m_objCalType).Add(1, DateAdd.Months).Add(-1, DateAdd.Days);
			if (iDate == num4)
			{
				return 0m;
			}
		}
		return result;
	}

	public decimal fn_CalculateWDVYearWise(int AssetId, int StartDate, int EndDate, int CommencementDate, decimal Price, bool CalcuDepforIT, int iAccountingDate, decimal fITDepreciationRate, decimal iQty, decimal RateOfDep)
	{
		int num = Date.DateToInt(new Date(EndDate, m_objCalType).Add(1, DateAdd.Years));
		int num2 = CommencementDate;
		int num3 = 0;
		decimal num4 = 0m;
		decimal num5 = 0m;
		decimal num6 = 0m;
		if (CalcuDepforIT)
		{
			RateOfDep = fITDepreciationRate;
			num2 = iAccountingDate;
		}
		decimal num7 = RateOfDep;
		decimal num8 = 0m;
		int num9 = StartDate;
		if (num9 < CommencementDate)
		{
			num9 = CommencementDate;
		}
		while (num9 <= EndDate)
		{
			int num10 = 0;
			int num11 = 0;
			int num12 = 0;
			while (num2 <= num)
			{
				if (num9 < num2)
				{
					num11 = Date.DateToInt(new Date(num2, m_objCalType).Add(-1, DateAdd.Days));
					num10 = Date.DateToInt(new Date(num2, m_objCalType).Add(-1, DateAdd.Years));
					break;
				}
				num2 = Date.DateToInt(new Date(num2, m_objCalType).Add(1, DateAdd.Years));
			}
			if (num10 < CommencementDate)
			{
				num10 = CommencementDate;
			}
			if (CommencementDate != StartDate && num8 == 0m)
			{
				int endDate = Date.DateToInt(new Date(num10, m_objCalType).Add(-1, DateAdd.Days));
				decimal num13 = fn_CalculateWDVYearWise(AssetId, CommencementDate, endDate, CommencementDate, Price, CalcuDepforIT, iAccountingDate, fITDepreciationRate, iQty, RateOfDep);
				Price -= num13;
				num8 = 1m;
			}
			Date date = new Date(num11, m_objCalType).Add(-1, DateAdd.Years) + 1;
			if (num10 > Date.DateToInt(date))
			{
				date = new Date(num10, m_objCalType);
			}
			int num14 = Math.Abs(Convert.ToInt32(new Date(m_objCalType).IntToDate(num11) - new Date(m_objCalType).IntToDate(date)) + 1);
			num12 = num14;
			if (CalcuDepforIT)
			{
				RateOfDep = ((num14 > 180) ? num7 : (num7 / 2m));
			}
			if (num11 < EndDate)
			{
				num3 = Math.Abs(Convert.ToInt32(new Date(m_objCalType).IntToDate(num9) - new Date(m_objCalType).IntToDate(num11)) + 1);
				num6 = Price / 100m * RateOfDep;
				num5 = num6 / (decimal)num12 * (decimal)num3;
				num4 += num5;
			}
			else
			{
				num3 = Math.Abs(Convert.ToInt32(new Date(m_objCalType).IntToDate(num9) - new Date(m_objCalType).IntToDate(EndDate)) + 1);
				num6 = Price / 100m * RateOfDep;
				num5 = num6 / (decimal)num12 * (decimal)num3;
				num4 += num5;
			}
			num9 = Date.DateToInt(new Date(num11, m_objCalType).Add(1, DateAdd.Days));
			Price -= num6;
		}
		return num4 * iQty;
	}

	public decimal fn_CalculateDepreciationWithAddYrs(Database objDB, int iAssetId, int iDepMethod, int StartDate, int EndDate, int CommencementDate, decimal Price, decimal ScrapVal, int RateOfDepInYears, int RateOfDepInMonths, bool ScreenType, decimal fITDepreciationRate, short iNoOfDecimal, RepRecord objRec)
	{
		decimal result = 0m;
		try
		{
			string commandText = string.Format("select cast(dbo.fn_CalculateDepreciationWithAddYrs({0},{1},{2},{3},{4},{5},{6},\r\n                    Case When {7} = 0 then {8}  else {10} end ,\r\n                    Case When {7} = 0 then {9}  else 0 end ,\r\n                    1,\r\n                    Case When {7} = 0 then 0  else 1 end) as decimal(18,{11}))", iAssetId, iDepMethod, StartDate, EndDate, CommencementDate, Price, ScrapVal, FConvert.GetInputValue(objRec.Inputs, 4), RateOfDepInYears, RateOfDepInMonths, fITDepreciationRate, iNoOfDecimal);
