	private decimal GetSellingRate(int iProd, int iUnit, int iCompId)
	{
		Focus.Transactions.BL.Transactions transactions = new Focus.Transactions.BL.Transactions();
		decimal result = 0m;
		if (transactions.Preference == null)
		{
			Focus.TranSettings.BL.Preference preference = new Focus.TranSettings.BL.Preference();
			transactions.Preference = preference.GetPreferences(iCompId);
		}
		PriceBook priceBook = new PriceBook();
		string strErrorMsg = "";
		decimal[] rates = priceBook.GetRates(0, iProd, 0, new Date().GetToday(m_objCalType).Value, transactions.Preference.objDefCurrency.CurrencyId, iUnit, 0m, new int[1], bPriceBookType: false, ref strErrorMsg, iCompId, RateType.Default);
		if (rates == null || rates.Length == 0 || rates[0] == 0m)
		{
			object[] objData = new object[1];
			int iIndex = 0;
			string lastSalePurchaseValue = transactions.GetLastSalePurchaseValue(0, iProd, 0, 0, bSales: true, FConvert.GetSuffix(iCompId));
			Database database = DatabaseWrapper.GetDatabase2(iCompId, -1, bReplicationServer: true);
			transactions.GetValueFromQuery(lastSalePurchaseValue, database, ref objData, ref iIndex);
			if (objData != null && objData.Length != 0)
			{
				return Convert.ToDecimal(objData[0]);
			}
			return result;
		}
		return rates[0];
	}

