		do
		{
			reportMatrix = GetAnalyzeData(objRec, iCompId);
			objRec.UniqueId = reportMatrix.UniqueId;
			if (array == null)
			{
				array = reportMatrix.Columns;
			}
			objRec.CurrentPage++;
			objRec.Outputs = reportMatrix.BalanceValues;
			objRec.IsStartOfReport = false;
			if (reportMatrix.ColumnData != null)
			{
				list.AddRange(reportMatrix.ColumnData);
			}
			if (rowsPerPage <= 0)
			{
				break;
			}
			objRec.RowsPerPage = ((rowsPerPage - list.Count > 1) ? (rowsPerPage - list.Count) : 2);
		}
		while (!reportMatrix.EndOfFile && reportMatrix.ColumnData != null && list.Count < rowsPerPage);
		reportMatrix.ColumnData = list.ToArray();
		objRec.RowsPerPage = rowsPerPage;
		objRec.CurrentPage = currentPage;
		if (array != null && reportMatrix.Columns.Length != array.Length)
		{
			reportMatrix.Columns = array;
		}
		return reportMatrix;
	}

	public ReportMatrix GetPagewiseDataLite(RepRecordLite objRecLite, string strSessionId, int iCompId)
	{
		if (string.IsNullOrEmpty(m_strDateFormat))
		{
			m_strDateFormat = ConfigurationManager.AppSettings["DateFormat"];
		}
		bool flag = false;
		RepRecord repRecord = null;
		ReportMatrix reportMatrix = null;
		if (objRecLite.SubReportId == 0)
		{
			RDDefault rDDefault = new RDDefault();
			objRecLite.SubReportId = rDDefault.GetSubReportId(objRecLite.ReportId, objRecLite.Inputs);
		}
		if (!objRecLite.DontLoadLayout && objRecLite.LayoutId <= 0)
		{
			objRecLite.LayoutId = LoadLayoutId(objRecLite.ReportId, (int)objRecLite.SubReportId, objRecLite.UserId, iCompId);
		}
		repRecord = convertLiteToInput(objRecLite, strSessionId, iCompId);
		flag = repRecord.ReportCustomize != null && ((repRecord.ReportCustomize.ReportType == ReportType.Standard && repRecord.ReportCustomize.DataSourceType == DataSourceType.Reports) || repRecord.ReportCustomize.ReportType == ReportType.Cubes);
		if (!objRecLite.DontLoadLayout && objRecLite.LayoutId <= 0 && repRecord.Module == Module.None && (objRecLite.SubReportId == 2 || objRecLite.SubReportId == 4))
		{
			objRecLite.LayoutId = LoadLayoutId(objRecLite.ReportId, 1, objRecLite.UserId, iCompId);
			repRecord = convertLiteToInput(objRecLite, strSessionId, iCompId);
		}
		reportMatrix = ((!flag) ? getData(repRecord, iCompId, objRecLite.DontLoadLayout) : getBIData(repRecord, iCompId));
		if (reportMatrix != null)
		{
			if (flag && ((repRecord.ReportCustomize != null && repRecord.ReportCustomize.Groupings != null && repRecord.ReportCustomize.Groupings.Where((_Grouping p) => p.GroupingType == _GroupingType.Column).Count() > 0) || (repRecord.ReportCustomize.DataSourceType == DataSourceType.Reports && repRecord.ReportCustomize.ReportType == ReportType.Cubes)))
			{
				RDDefault rDDefault2 = new RDDefault();
				List<_Column> list = new List<_Column>();
				list.AddRange(LoadColumns(repRecord.ReportCustomize.Layout.LayoutId, IsAnalyzeTypeReport: false, DataSourceType.Cubes, iCompId));
				if (reportMatrix.Columns != null)
				{
					list = rDDefault2.GetRDColumns(reportMatrix.Columns, repRecord, list);
				}
				reportMatrix.ExtraColumns = list.Select((_Column p) => new FieldData
				{
					ColumnAlias = ((!string.IsNullOrEmpty(p.GroupName)) ? $"{p.GroupName}~{p.AliasName}" : p.AliasName),
					ColumnId = p.ColumnId,
					DataType = p.DataTypeId,
					FieldId = p.FieldId,
					FieldName = p.ColumnName,
					Miscellaneous = p.Miscelleneous,
					ParentId = p.ParentId,
					SubParentId = p.SubParentId,
					ColumnWidth = Convert.ToInt32(p.ColumnWidth)
				}).ToArray();
			}
			if (objRecLite.StorePageData)
			{
				List<LineData> list2 = new List<LineData>();
				bool bEndOfFile = reportMatrix.EndOfFile;
				list2.AddRange(reportMatrix.ColumnData);
				_focus.company(iCompId).setBuffer(getPageBufferId(reportMatrix.UniqueId), list2);
				LineData[] lineData = getLineData(repRecord.RowsPerPage, repRecord.CurrentPage, list2, ref bEndOfFile);
				if (lineData != null && lineData.Length <= repRecord.RowsPerPage)
				{
					reportMatrix.ColumnData = lineData;
				}
				if (reportMatrix.EndOfFile)
				{
					_focus.company(iCompId).setBuffer(getBufferEOF(reportMatrix.UniqueId), true);
				}
				reportMatrix.EndOfFile = bEndOfFile;
			}
			if (reportMatrix.EndOfFile)
			{
				_focus.company(iCompId).clearBuffer(getBufferId(reportMatrix.UniqueId));
			}
			else
			{
				repRecord.Outputs = reportMatrix.BalanceValues;
				_focus.company(iCompId).setBuffer(getBufferId(reportMatrix.UniqueId), repRecord);
			}
			if (!flag)
			{
				reportMatrix.BalanceValues = null;
				reportMatrix.Columns = null;
			}
		}
		return reportMatrix;
	}

	public ReportMatrix GetNextPageDataLite(NextRepRecordLite oRecLite, string strSessionId, int iCompId)
	{
		if (string.IsNullOrEmpty(m_strDateFormat))
		{
			m_strDateFormat = ConfigurationManager.AppSettings["DateFormat"];
		}
		ReportMatrix reportMatrix = null;
		object obj = null;
		RepRecord repRecord = null;
		bool flag = false;
		bool bEndOfFile = false;
		bool flag2 = false;
		List<LineData> list = null;
		LineData[] array = null;
		try
		{
			obj = _focus.company(iCompId).getBuffer(getPageBufferId(oRecLite.UniqueId));
			if (obj != null && obj.GetType() == typeof(List<LineData>))
			{
				flag = true;
				list = new List<LineData>();
				list.AddRange((List<LineData>)obj);
				obj = _focus.company(iCompId).getBuffer(getBufferEOF(oRecLite.UniqueId));
				if (obj != null)
				{
					bEndOfFile = Convert.ToBoolean(obj);
				}
			}
			if (reportMatrix == null)
			{
				object buffer = _focus.company(iCompId).getBuffer(getBufferId(oRecLite.UniqueId));
				if (buffer != null && buffer.GetType() == typeof(RepRecord))
				{
					repRecord = (RepRecord)buffer;
					repRecord.CurrentPage = oRecLite.CurrentPage;
					flag2 = repRecord.ReportCustomize != null && ((repRecord.ReportCustomize.ReportType == ReportType.Standard && repRecord.ReportCustomize.DataSourceType == DataSourceType.Reports) || repRecord.ReportCustomize.ReportType == ReportType.Cubes);
					if (!bEndOfFile)
					{
						reportMatrix = ((!flag2) ? getData(repRecord, iCompId, repRecord.Module == Module.None) : getBIData(repRecord, iCompId));
					}
					if (reportMatrix != null)
					{
						_focus.company(iCompId).setBuffer(getBufferId(oRecLite.UniqueId), repRecord);
						if (flag)
						{
							if (list == null)
							{
								list = new List<LineData>();
							}
							list.AddRange(reportMatrix.ColumnData);
							bEndOfFile = reportMatrix.EndOfFile;
							_focus.company(iCompId).setBuffer(getPageBufferId(reportMatrix.UniqueId), list);
							array = getLineData(repRecord.RowsPerPage, oRecLite.CurrentPage, list, ref bEndOfFile);
							if (array != null && array.Length <= repRecord.RowsPerPage)
							{
								reportMatrix.ColumnData = array;
							}
							if (reportMatrix.EndOfFile)
							{
								_focus.company(iCompId).setBuffer(getBufferEOF(reportMatrix.UniqueId), true);
							}
							reportMatrix.EndOfFile = bEndOfFile;
							if (!flag2)
							{
								reportMatrix.BalanceValues = null;
								reportMatrix.Columns = null;
							}
							else
							{
								reportMatrix.ExtraColumns = null;
							}
						}
					}
					else
					{
						array = getLineData(repRecord.RowsPerPage, oRecLite.CurrentPage, list, ref bEndOfFile);
						if (array != null && array.Length <= repRecord.RowsPerPage)
						{
							reportMatrix = new ReportMatrix();
							reportMatrix.UniqueId = oRecLite.UniqueId;
							reportMatrix.ColumnData = array;
							reportMatrix.EndOfFile = bEndOfFile;
						}
					}
				}
			}
		}
		catch (Exception ex)
		{
			if (reportMatrix == null)
			{
				reportMatrix = new ReportMatrix();
			}
			reportMatrix.Error = true;
			reportMatrix.Message = ex.Message;
			reportMatrix.EndOfFile = true;
		}
		if (reportMatrix == null)
		{
			reportMatrix = new ReportMatrix();
		}
		return reportMatrix;
	}

