	private IdValuePair[] CloneObj(IdValuePair[] arrOutputs)
	{
		List<IdValuePair> list = new List<IdValuePair>();
		if (arrOutputs != null)
		{
			for (int i = 0; i < arrOutputs.Length; i++)
			{
				list.Add(new IdValuePair(arrOutputs[i].ID, arrOutputs[i].Value));
			}
		}
		return list.ToArray();
	}

	private LineData[] getLineData(int iRowsPerPage, int iCurrentPage, List<LineData> arrLineData, ref bool bEndOfFile)
	{
		LineData[] result = null;
		int num = iRowsPerPage * iCurrentPage;
		if (num < arrLineData.Count)
		{
			result = arrLineData.Select((LineData p) => p).Skip(num).Take(iRowsPerPage)
				.ToArray();
		}
		if (bEndOfFile)
		{
			num = iRowsPerPage * (iCurrentPage + 1);
			bEndOfFile = arrLineData.Select((LineData p) => p).Skip(num).Take(iRowsPerPage)
				.Count() <= 0;
		}
		return result;
	}

	public uint getSubReportId(uint iReportId, IdValuePair[] arrInputs)
	{
		int num = 0;
		switch ((FocusReport)iReportId)
		{
		case FocusReport.TrialBalance:
		case FocusReport.ProfitAndLoss:
		case FocusReport.TradingAccount:
		case FocusReport.TradingAndProfitAndLoss:
		case FocusReport.BalanceSheet:
		case FocusReport.MasterReport:
		case FocusReport.StockValuation:
		case FocusReport.FundsFlow:
		case FocusReport.CashFlow:
		case FocusReport.CashFlowAnalysis:
		case FocusReport.BudgetReport:
		case FocusReport.MasterAuthorizationReport:
		case FocusReport.FormReport:
			num = FConvert.GetInputValue(arrInputs, 1);
			break;
		}
		if (num >= 0)
		{
			return (uint)num;
		}
		return 0u;
	}

	private int LoadLayoutId(uint iReportId, int iSubReportId, int iUserId, int iCompanyId)
	{
		int num = 0;
		int result = 0;
		IdNamePair[] array = null;
		if (iReportId != 0)
		{
			array = new RDReport
			{
				m_objCalType = m_objCalType
			}.LoadReportLayouts(iReportId, iSubReportId, iUserId, iCompanyId);
		}
		if (array != null && array.Length != 0)
		{
			result = array[0].ID;
			for (num = 0; num < array.Length; num++)
			{
				if (((Convert.ToInt64(array[num].Tag) >> 1) & 1) == 1)
				{
					result = array[num].ID;
					break;
				}
			}
		}
		return result;
	}

	private ReportMatrix getData(RepRecord oRec, int iCompId, bool bDontLoadLayout)
