			{
				list.AddRange(reportMatrix.ColumnData);
			}
			if (num <= 0)
			{
				break;
			}
			oRec.RowsPerPage = ((num - list.Count > 1) ? (num - list.Count) : 2);
		}
		while (!reportMatrix.EndOfFile && reportMatrix.ColumnData != null && list.Count < num);
		oRec.RowsPerPage = num2;
		reportMatrix.ColumnData = list.ToArray();
