						linkLineData.VoucherNo = Convert.ToString(reportMatrix.ColumnData[i].CellData[2]);
						linkLineData.Date = Convert.ToInt32(reportMatrix.ColumnData[i].CellData[3]);
						linkLineData.PendingValue = Convert.ToDecimal(reportMatrix.ColumnData[i].CellData[5]);
						linkLineData.RefIds = Convert.ToInt64(reportMatrix.ColumnData[i].CellData[7]);
