						reportMatrix.ColumnData[i].CellData[0] = reportRowHeader;
					}
				}
				RDConversion rDConversion = new RDConversion(m_objCalType);
				byte iPrintBooleanAs = (byte)_focus.company(iCompId).getPreferenceValue(PreferenceCategories.Print, 26);
				bool bPrintZeroValueAsNumeric = _focus.company(iCompId).getPreferenceValue(PreferenceCategories.Print, 8) > 0;
				bool bNumericSeparator = _focus.company(iCompId).getPreferenceValue(PreferenceCategories.Misc, 12) > 0;
