				string dateFormat = (rDConversion.DateFormat = m_strDateFormat);
				oRec.DateFormat = dateFormat;
				rDConversion.ClientOffset = m_dClientOffet;
				reportMatrix = rDConversion.ApplyCustomization(reportMatrix, oRec, objRDPreferenceData);
				m_arrReportColumns = oRec.ReportCustomize.Layout.Columns;
				reportMatrix.ExtraColumns = oRec.ReportCustomize.Layout.Columns.Select((_Column p) => new FieldData
				{
					ColumnAlias = ((!string.IsNullOrEmpty(p.GroupName)) ? $"{p.GroupName}~{p.AliasName}" : p.AliasName),
					ColumnId = p.ColumnId,
					DataType = p.DataTypeId,
					FieldId = p.FieldId,
					FieldName = p.ColumnName,
					Miscellaneous = p.Miscelleneous,
					ParentId = p.ParentId,
					SubParentId = p.SubParentId,
					ColumnWidth = Convert.ToInt32(p.ColumnWidth)
				}).ToArray();
			}
			else
			{
				ReportColumn[] arrLastYearColumns = null;
				ReportColumn[] defaultColumns = GetDefaultColumns(oRec, bPrefix: false, iCompId, ref arrLastYearColumns);
				if (oRec.Module == Module.None && (byte)oRec.SubReportId == 3)
				{
					ReportRowHeader reportRowHeader2 = null;
					for (int num3 = 0; num3 < reportMatrix.ColumnData.Length; num3++)
					{
						LinkLineData linkLineData2 = new LinkLineData();
