						linkLineData2.Date = Convert.ToInt32(reportMatrix.ColumnData[num3].CellData[3]);
						linkLineData2.PendingValue = Convert.ToDecimal(reportMatrix.ColumnData[num3].CellData[5]);
						linkLineData2.RefIds = Convert.ToInt64(reportMatrix.ColumnData[num3].CellData[7]);
						linkLineData2.Tolerance = Convert.ToDecimal(reportMatrix.ColumnData[num3].CellData[8]);
						reportRowHeader2 = (ReportRowHeader)reportMatrix.ColumnData[num3].CellData[0];
