					}).ToArray();
			}
			oRec.Outputs = reportMatrix.BalanceValues;
		}
		return reportMatrix;
	}

	public RepRecord convertLiteToInput(RepRecordLite objRecLite, string strSessionId, int iCompanyId)
	{
		object obj = null;
		RepRecord repRecord = null;
		string text = "^";
		List<IdNamePair> list = null;
		ReportColumn[] array = null;
		ReportColumn[] arrLastYearColumns = null;
		repRecord = new RepRecord();
		repRecord.ReportId = objRecLite.ReportId;
		repRecord.UserId = objRecLite.UserId;
		repRecord.LayoutId = objRecLite.LayoutId;
		repRecord.LanguageId = objRecLite.LanguageId;
		repRecord.Inputs = objRecLite.Inputs;
		repRecord.RowsPerPage = objRecLite.RowsPerPage;
		repRecord.FilterSource = objRecLite.FilterSource;
		repRecord.SessionId = strSessionId;
		if (objRecLite.CustomSorts != null && objRecLite.CustomSorts.Length != 0)
		{
			if (objRecLite.CustomSorts.Length == 1)
			{
				repRecord.ColumnSort = objRecLite.CustomSorts[0];
			}
			else
			{
				repRecord.CustomSorts = objRecLite.CustomSorts;
			}
		}
		repRecord.FetchAllData = objRecLite.FetchAllData;
		repRecord.CallingFromLite = true;
		repRecord.IsGroup = objRecLite.IsGroup;
		repRecord.StartingDate = FConvert.GetInputValue(objRecLite.Inputs, -102);
		repRecord.EndingDate = FConvert.GetInputValue(objRecLite.Inputs, -103);
		obj = FConvert.GetInputObject(objRecLite.Inputs, -101);
		if (obj != null && obj.GetType() == typeof(ComboData[]))
		{
			repRecord.Masters = (ComboData[])obj;
		}
		obj = FConvert.GetInputObject(objRecLite.Inputs, -104);
		if (obj != null && obj.GetType() == typeof(ComboData))
		{
			repRecord.Code = ((ComboData)obj).ID;
			repRecord.CodeName = ((ComboData)obj).Name;
		}
		repRecord.IsStartOfReport = true;
		repRecord.CurrentPage = 0;
		repRecord.SubReportId = getSubReportId(objRecLite, repRecord.Module);
		if (objRecLite.SubReportId == Convert.ToUInt32(CustomizeColumn.LinkPopupScreen) && objRecLite.ReportId == 512)
		{
			repRecord.Module = Module.None;
		}
		else
		{
			repRecord.Module = new RDDefault().GetReportModule(repRecord.ReportId);
		}
		repRecord.SourceType = DataSourceType.Default;
		if (repRecord.LayoutId > 0)
		{
			if ((objRecLite.SubReportId == Convert.ToUInt32(CustomizeColumn.LinkVoucher) || objRecLite.SubReportId == Convert.ToUInt32(CustomizeColumn.PendingBills)) && repRecord.Module == Module.None)
			{
				repRecord.ReportCustomize = LoadReportDesigner(repRecord.ReportId, repRecord.LayoutId, iCompanyId, 1u);
			}
			else
			{
				repRecord.ReportCustomize = LoadReportDesigner(repRecord.ReportId, repRecord.LayoutId, iCompanyId, repRecord.SubReportId);
			}
			repRecord.Module = repRecord.ReportCustomize.Module;
			repRecord.SourceType = repRecord.ReportCustomize.DataSourceType;
			repRecord.ReportCustomize.DelayFetch = !repRecord.FetchAllData && repRecord.ReportCustomize.DelayFetch;
		}
		repRecord.DateFormat = null;
		repRecord.Outputs = null;
		repRecord.UniqueId = null;
		repRecord.ExtraColumns = null;
		list = new List<IdNamePair>();
		if (repRecord.Module == Module.None && (objRecLite.SubReportId == Convert.ToUInt32(CustomizeColumn.LinkVoucher) || objRecLite.SubReportId == Convert.ToUInt32(CustomizeColumn.PendingBills)))
		{
			uint subReportId = repRecord.SubReportId;
			repRecord.SubReportId = 1u;
			array = GetDefaultColumns(repRecord, bPrefix: true, iCompanyId, ref arrLastYearColumns);
			repRecord.SubReportId = subReportId;
		}
		else
		{
			array = GetDefaultColumns(repRecord, repRecord.Module != Module.None, iCompanyId, ref arrLastYearColumns);
		}
		for (int i = 0; i < array.Length; i++)
		{
			list.Add(new IdNamePair(array[i].FieldId, (array[i].Hidden ? text : string.Empty) + array[i].Name, array[i].DataType));
		}
		repRecord.Columns = list.ToArray();
		if (repRecord.ReportCustomize == null)
		{
			repRecord.ReportCustomize = GetReportObject(repRecord.ReportId, string.Empty, repRecord.Module, (int)repRecord.SubReportId, repRecord.UserId, array);
