					DbCommand dbCommand = null;
					IDataReader dataReader = null;
					dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
					dataReader = m_objDatabase.ExecuteReader(dbCommand);
					list = new List<ReportColumn>();
					list.Add(new ReportColumn(0, "iHeaderId", MasterDataType.Number, bHidden: true));
					int num6 = 0;
					while (dataReader.Read())
					{
						string sColumnName2 = Convert.ToString(dataReader["sHeaderText"]);
						num6 = Convert.ToInt32(dataReader["iColumnIndex"]) + 1;
						int oDataType = Convert.ToInt32(dataReader["iDataTypeId"]);
						ReportColumn item = new ReportColumn(num6, sColumnName2, (MasterDataType)oDataType);
						list.Add(item);
					}
					list.Add(new ReportColumn(num6 + 1, "CreatedBy", MasterDataType.Text));
					list.Add(new ReportColumn(num6 + 2, "Created Date", MasterDataType.DateTime));
					list.Add(new ReportColumn(num6 + 3, "ModifiedBy", MasterDataType.Text));
					list.Add(new ReportColumn(num6 + 4, "Modified Date", MasterDataType.DateTime));
					dataReader.Close();
					break;
				}
				default:
					list.AddRange(rDDefault.GetMasterColumns(num2, invoiceLayout.GetMasterList(1100, iCompanyId)));
					break;
				}
				break;
			case Module.Inventory:
				switch ((FocusReport)num2)
				{
				case FocusReport.LinkChainAnalysis:
				{
					num = 0;
					ComboData[] array5 = invoiceLayout.LoadLayouts(Module.None, objRec.Code, LayoutType.WorkFlowCount, iCompanyId);
					if (array5 != null && array5.Length >= 1)
					{
						num = array5[0].ID;
					}
					list.AddRange(rDDefault.GetInvReportColumns(num2, num));
					break;
				}
				case FocusReport.StockTransferSummary:
					list.AddRange(rDDefault.GetInvReportColumns(num2, FConvert.GetInputValue(objRec.Inputs, 1)));
					array2 = invoiceLayout.GetMasterList(_focus.company(iCompanyId).invTagId, iCompanyId);
					if (array2 != null)
					{
						for (num = 0; num < array2.Length && num < 255; num++)
						{
							list.Add(new ReportColumn(list.Count + 10, $"To-{((array2[num].Name.Length > 30) ? array2[num].Name.Substring(0, 30) : array2[num].Name)}", MasterDataType.Fraction));
						}
					}
					break;
				case FocusReport.TagwiseStockReport:
					array2 = invoiceLayout.GetMasterList(_focus.company(iCompanyId).invTagId, iCompanyId);
					list.AddRange(rDDefault.GetInvReportColumns(num2, array2));
					break;
				case FocusReport.TransactionWiseStockReport:
					list.AddRange(rDDefault.GetInvReportColumns(num2, invoiceLayout.LoadLayouts(Module.CoreTransactions, 1, LayoutType.LoadInventoryVouchers, iCompanyId)));
					break;
				default:
					list.AddRange(rDDefault.GetInvReportColumns(num2, rDDefault.InvTagName));
					break;
				}
				break;
			case Module.FixAssets:
				list.AddRange(rDDefault.GetFixAssetColumns(num2, _focus.company(iCompanyId).invTagName));
				break;
			case Module.Production:
				list.AddRange(rDDefault.GetProductionColumns(num2));
				break;
			case Module.None:
				if (oInputValue != null && oInputValue.GetType() == typeof(int))
				{
					list.AddRange(rDDefault.GetTransactionColumns(0u, (int)objRec.SubReportId, Convert.ToInt32(oInputValue)));
				}
				else
				{
					list.AddRange(rDDefault.GetTransactionColumns(0u, (int)objRec.SubReportId));
				}
				break;
			case Module.WMS:
				list.AddRange(rDDefault.GetWMSReportColumns(num2, _focus.company(iCompanyId).invTagName));
				break;
			case Module.Quality:
				list.AddRange(rDDefault.GetQCColumns(num2));
				break;
			default:
				list.AddRange(new ReportColumn[2]
				{
					new ReportColumn(0, "iHeaderId", MasterDataType.Number),
					new ReportColumn(1, "Date", MasterDataType.Date)
				});
				break;
			}
		}
		if (bPrefix)
		{
			for (num = 0; num < list.Count; num++)
			{
				list[num].Name = list[num].Name.Insert(0, "Report Specific.");
			}
		}
		return list.ToArray();
	}

	private uint getSubReportId(RepRecordLite oRec, Module oModule)
	{
		int num = 0;
		if (oModule == Module.None)
		{
			num = (int)oRec.SubReportId;
		}
		else
		{
			switch ((FocusReport)oRec.ReportId)
			{
			case FocusReport.TrialBalance:
			case FocusReport.ProfitAndLoss:
			case FocusReport.TradingAccount:
			case FocusReport.TradingAndProfitAndLoss:
			case FocusReport.BalanceSheet:
			case FocusReport.MasterReport:
			case FocusReport.StockValuation:
			case FocusReport.FundsFlow:
			case FocusReport.CashFlow:
			case FocusReport.CashFlowAnalysis:
			case FocusReport.BudgetReport:
			case FocusReport.MasterAuthorizationReport:
				num = FConvert.GetInputValue(oRec.Inputs, 1);
				break;
			}
		}
		if (num >= 0)
		{
			return (uint)num;
		}
		return 0u;
	}

	private _Reports GetReportObject(uint iReportId, string strReportName, Module objModule, int iSubReportId, int iUserId, ReportColumn[] arrDefaultColumns)
	{
		int num = 0;
		_Column column = null;
		_Reports reports = null;
		int num2 = 18;
		reports = new _Reports();
		reports.ReportType = ReportType.Standard;
		reports.DataSourceType = DataSourceType.Standard;
		reports.ReportId = iReportId;
		reports.ReportName = strReportName;
		reports.Module = objModule;
		reports.CreatedBy = iUserId;
		reports.ModifiedBy = iUserId;
		reports.Layout = new _Layout();
		reports.Layout.LayoutId = 0;
		reports.Layout.SubReportId = iSubReportId;
		reports.Layout.LayoutName = "Standard";
		reports.Layout.IsDefault = true;
		reports.Layout.IsLandscape = false;
		List<_Column> list = new List<_Column>();
		for (num = 0; num < arrDefaultColumns.Length; num++)
		{
			if (!arrDefaultColumns[num].Hidden)
			{
				column = new _Column();
				_Column column2 = column;
				string aliasName = (column.ColumnName = arrDefaultColumns[num].Name);
				column2.AliasName = aliasName;
				if (!string.IsNullOrEmpty(arrDefaultColumns[num].GroupName))
				{
					column.GroupName = arrDefaultColumns[num].GroupName;
				}
				column.DataTypeId = arrDefaultColumns[num].DataType;
				column.Miscelleneous = 0;
				if (arrDefaultColumns[num].FieldId == -4)
				{
					column.Miscelleneous = 754974848;
				}
				column.ColumnAlignment = ((column.DataTypeId == MasterDataType.Fraction) ? num2 : 0);
				_Column column3 = column;
				int parentId = (column.SubParentId = -1);
				column3.ParentId = parentId;
				column.FieldId = arrDefaultColumns[num].FieldId;
				column.ColumnWidth = ((column.DataTypeId == MasterDataType.Text) ? 120 : 60);
				if (num == 1 && (iReportId == 531 || iReportId == 532 || iReportId == 533 || iReportId == 534 || iReportId == 535))
				{
					column.ColumnWidth = 300.0;
				}
				if (!arrDefaultColumns[num].Hidden)
				{
					list.Add(column);
				}
			}
		}
		reports.Layout.Columns = list.ToArray();
		reports.Layout.RowConditional = null;
		return reports;
	}

	public Dictionary<string, double>[] PrepareGraphDataLite(RepRecordLite objRecLite, GraphOptions objOptions, int iCompanyId)
	{
		ReportMatrix reportMatrix = null;
		RepRecord repRecord = null;
		List<LineData> list = new List<LineData>();
		if (objRecLite.LayoutId <= 0)
		{
			objRecLite.LayoutId = LoadLayoutId(objRecLite.ReportId, (int)objRecLite.SubReportId, objRecLite.UserId, iCompanyId);
		}
		repRecord = convertLiteToInput(objRecLite, null, iCompanyId);
		repRecord.GraphOption = objOptions;
		if (repRecord.ReportCustomize == null)
		{
			repRecord.ReportCustomize = LoadReportDesigner(repRecord.ReportId, repRecord.LayoutId, iCompanyId);
		}
		if (repRecord.LayoutId == 0 && repRecord.ReportCustomize != null && repRecord.ReportCustomize.Layout != null)
		{
			repRecord.LayoutId = repRecord.ReportCustomize.Layout.LayoutId;
		}
		do
		{
			repRecord.RowsPerPage = 200;
			if (repRecord.SourceType == DataSourceType.Reports || repRecord.ReportCustomize.ReportType == ReportType.Cubes)
			{
				reportMatrix = GetAnalyzeData(repRecord, iCompanyId);
				repRecord.CurrentPage++;
				repRecord.Outputs = reportMatrix.BalanceValues;
				repRecord.IsStartOfReport = false;
			}
			else
			{
				reportMatrix = GetPagewiseData(repRecord, iCompanyId);
			}
			repRecord.UniqueId = reportMatrix.UniqueId;
			repRecord.IsStartOfReport = false;
			if (reportMatrix.ColumnData != null)
			{
				list.AddRange(reportMatrix.ColumnData);
			}
		}
		while (!reportMatrix.EndOfFile);
		if (list.Count > 0)
		{
			reportMatrix.ColumnData = list.ToArray();
		}
		if (reportMatrix != null && reportMatrix.ColumnData != null && reportMatrix.ColumnData.Length != 0)
		{
			for (int i = 0; i < repRecord.ReportCustomize.Groupings.Length; i++)
			{
				if (repRecord.ReportCustomize.Groupings[i].GroupingType == _GroupingType.Column)
				{
					repRecord.GraphOption.ValuesColumn = (from p in reportMatrix.Columns
						where Convert.ToString(p.Tag) == "Fraction"
						select new IdNamePair(p.ID, p.Name, 6)).ToArray();
					break;
				}
			}
			return new RDConversion(m_objCalType).PrepareGraphData(repRecord.GraphOption, reportMatrix, repRecord.ReportCustomize.ReportType == ReportType.Cubes);
		}
		return null;
	}

	public IdDualValue GetDataDiagnosticsTotal(RepRecord oRecData, int iCompanyId, ref string sError)
	{
		IdDualValue idDualValue = new IdDualValue();
		string suffix = FConvert.GetSuffix(iCompanyId);
		try
		{
			Database database = DatabaseWrapper.GetDatabase2(iCompanyId, -1, bReplicationServer: true);
			string text2;
			string text = (text2 = string.Empty);
			if (oRecData.Masters != null && oRecData.Masters.Length != 0)
			{
				text = getXmlMaster(General.GetMasters(oRecData.Masters));
				text2 = "JOIN @XML.nodes('/Master/r') T(c) ON tCore_Indta{0}.iProduct = T.c.value('./@id', 'int')";
			}
			string accountInGroup = GetAccountInGroup(oRecData.Code, database);
			string text3 = string.Format("{2}\r\n                SELECT SUM(mStockValue * SIGN(fQuantity))[Stock] \r\n                FROM tCore_Header{0} \r\n                JOIN  tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId\r\n                {3}\r\n                WHERE iDate <= {1}\r\n                AND bUpdateStocks = 1 AND bSuspended = 0 AND iAuthStatus < 2 AND bSuspendUpdateStocks = 0", suffix, oRecData.EndingDate, text, text2);
			decimal value = Convert.ToDecimal(database.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text3) : text3));
			text3 = string.Format("SELECT SUM(CASE WHEN iCode IN ({2}) THEN mAmount1 ELSE mAmount2 END)\r\n                FROM tCore_Header{0} \r\n                JOIN  tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                where bUpdateFA = 1 AND iDate <= {1}\r\n                AND bSuspended = 0 AND iAuthStatus < 2 AND bSuspendUpdateFA = 0\r\n                AND (iCode IN ({2}) OR iBookNo IN ({2}))", suffix, oRecData.EndingDate, accountInGroup);
			decimal value2 = Convert.ToDecimal(database.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text3) : text3));
			idDualValue.Value1 = value;
			idDualValue.Value2 = value2;
		}
		catch (Exception ex)
		{
			idDualValue.Id = -1;
			sError = $"{ex.Message}\r\n{ex.StackTrace}";
		}
		return idDualValue;
	}

	public ReportMatrix GetDataDiagnosticsDetails(RepRecord oRecData, int iCompanyId)
	{
		ReportMatrix reportMatrix = new ReportMatrix();
		List<LineData> list = new List<LineData>();
		List<int> list2 = new List<int>();
		string suffix = FConvert.GetSuffix(iCompanyId);
		try
		{
			int noOfDecimal = _focus.company(iCompanyId).currency.NoOfDecimal;
			Database database = DatabaseWrapper.GetDatabase2(iCompanyId, -1, bReplicationServer: true);
			string text2;
			string text = (text2 = string.Empty);
			if (oRecData.Masters != null && oRecData.Masters.Length != 0)
			{
				text = getXmlMaster(General.GetMasters(oRecData.Masters));
				text2 = "JOIN @XML.nodes('/Master/r') T(c) ON tCore_Indta{0}.iProduct = T.c.value('./@id', 'int')";
			}
			string accountInGroup = GetAccountInGroup(oRecData.Code, database);
			string text3 = string.Format("{1}\r\n                SELECT tCore_Header{0}.iHeaderId, sAbbr + ':'+ tCore_Header{0}.sVoucherNo[sVoucherNo], tCore_Indta{0}.mStockValue,\r\n                CASE WHEN tCore_Data{0}.iCode IN ({2}) THEN tCore_Data{0}.mAmount1 ELSE CASE WHEN tCore_Data{0}.iBookNo IN ({2}) THEN tCore_Data{0}.mAmount2 ELSE \r\n                CASE WHEN d.iCode in ({2}) THEN d.mAMount1 ELSE CASE WHEN d.iBookNo IN ({2}) THEN d.mAmount2 ELSE 0 END END END END [FinVal]\r\n                FROM tCore_Header{0} \r\n                JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId\r\n                {5}\r\n                JOIN cCore_Vouchers{0}  ON tCore_Header{0}.iVoucherType = cCore_Vouchers{0}.iVoucherType\r\n                LEFT JOIN tCore_Data{0} d ON d.iMainBodyId = tCore_Data{0}.iBodyId\r\n                WHERE iDate BETWEEN {3} AND {4}\r\n                AND fQuantity <> 0 AND (tCore_Data{0}.iCode IN ({2})  OR tCore_Data{0}.iBookNo IN ({2}) OR d.iCode IN ({2}) OR d.iBookNo in ({2}))\r\n                AND ABS(mStockValue - ABS(CASE WHEN tCore_Data{0}.iCode IN ({2}) THEN tCore_Data{0}.mAmount1 ELSE CASE WHEN tCore_Data{0}.iBookNo IN ({2}) THEN tCore_Data{0}.mAmount2 \r\n                ELSE CASE WHEN d.iCode in ({2}) THEN d.mAMount1 ELSE CASE WHEN d.iBookNo IN ({2}) THEN d.mAmount2 ELSE 0 END END END END)) > 0.1", suffix, text, accountInGroup, oRecData.StartingDate, oRecData.EndingDate, text2);
			IDataReader dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text3) : text3);
			while (dataReader.Read())
			{
				list.Add(new LineData
				{
					CellData = new object[6]
					{
						dataReader["iHeaderId"],
						dataReader["sVoucherNo"],
						FConvert.AddDecimalInColumn(noOfDecimal, Math.Abs(Convert.ToDecimal(dataReader["mStockValue"]))),
						FConvert.AddDecimalInColumn(noOfDecimal, Math.Abs(Convert.ToDecimal(dataReader["FinVal"]))),
						FConvert.AddDecimalInColumn(noOfDecimal, Math.Abs(Convert.ToDecimal(dataReader["mStockValue"]) - Math.Abs(Convert.ToDecimal(dataReader["FinVal"])))),
						"In the same voucher"
					}
				});
			}
			dataReader.Close();
			text3 = string.Format("SELECT iLinkPathId FROM vmCore_Links{0} WHERE BaseVoucherId & {1} = {2} AND LinkVoucherId & {1} = {3}", suffix, 65280, 1280, 768);
			dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text3) : text3);
			while (dataReader.Read())
			{
				list2.Add(Convert.ToInt32(dataReader["iLinkPathId"]));
			}
			dataReader.Close();
			if (list2.Count > 0)
			{
				for (int i = 0; i < list2.Count; i++)
				{
					text3 = string.Format("{1}\r\n                        SELECT iRefId, sAbbr + ':'+ tCore_Header{0}.sVoucherNo[sVoucherNo], -tCore_Data{0}.mAmount1[StockValue], LinkIndta.mStockValue[FinValue] \r\n\t                    FROM tCore_Links{0} \r\n\t                    JOIN tCore_Data{0} ON iRefId = tCore_Data{0}.iTransactionId AND iLinkId = {5} AND bBase = 0 \r\n\t                    JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId \r\n                        {6}\r\n\t                    JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t                    JOIN cCore_Vouchers{0} ON tCore_Header{0}.iVoucherType = cCore_Vouchers{0}.iVoucherType\r\n\t                    JOIN tCore_Data{0} LinkData ON tCore_Links{0}.iTransactionId = LinkData.iTransactionId AND iLinkId = {5} AND bBase = 0 \r\n\t                    JOIN tCore_Indta{0} LinkIndta ON LinkData.iBodyId = LinkIndta.iBodyId  \r\n\t                    --JOIN tCore_Header{0} Linkheader ON LinkData.iHeaderId = Linkheader.iHeaderId\r\n\t                    WHERE tCore_Header{0}.iDate BETWEEN {3} AND {4}\r\n                        AND (tCore_Data{0}.iCode IN ({2})  OR tCore_Data{0}.iBookNo IN ({2}) OR LinkData.iCode IN ({2}) OR LinkData.iBookNo IN ({2}))\r\n\t                    AND (ABS(-tCore_Data{0}.mAmount1) - ABS(LinkIndta.mStockValue)) >= 0.05", suffix, text, accountInGroup, oRecData.StartingDate, oRecData.EndingDate, list2[i], text2);
					dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text3) : text3);
					while (dataReader.Read())
					{
						list.Add(new LineData
						{
							CellData = new object[6]
							{
								dataReader["iRefId"],
								dataReader["sVoucherNo"],
								FConvert.AddDecimalInColumn(noOfDecimal, Math.Abs(Convert.ToDecimal(dataReader["StockValue"]))),
								FConvert.AddDecimalInColumn(noOfDecimal, Math.Abs(Convert.ToDecimal(dataReader["FinValue"]))),
								FConvert.AddDecimalInColumn(noOfDecimal, Math.Abs(Convert.ToDecimal(dataReader["StockValue"]) - Math.Abs(Convert.ToDecimal(dataReader["FinValue"])))),
								"In the link vouher"
							}
						});
					}
					dataReader.Close();
				}
			}
			text3 = string.Format("{1}\r\n                SELECT tCore_Header{0}.iHeaderId, sAbbr + ':'+ tCore_Header{0}.sVoucherNo[sVoucherNo]\r\n                FROM tCore_Header{0} \r\n                JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId\r\n                JOIN cCore_Vouchers{0}  ON tCore_Header{0}.iVoucherType = cCore_Vouchers{0}.iVoucherType\r\n                {4}\r\n                WHERE iDate BETWEEN {2} and {3}\r\n                AND tCore_Indta{0}.mStockValue = 0", suffix, text, oRecData.StartingDate, oRecData.EndingDate, text2);
			dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text3) : text3);
			while (dataReader.Read())
			{
				list.Add(new LineData
				{
					CellData = new object[6]
					{
						dataReader["iHeaderId"],
						dataReader["sVoucherNo"],
						0,
						0,
						0,
						"Stock value zero voucher"
					}
				});
			}
			dataReader.Close();
			reportMatrix.ColumnData = list.ToArray();
			reportMatrix.ExtraColumns = new FieldData[6]
			{
				new FieldData
				{
					ColumnAlias = "HeaderId",
					ColumnWidth = 0
				},
				new FieldData
				{
