					ColumnWidth = 80
				},
				new FieldData
				{
					ColumnAlias = "Difference",
					ColumnWidth = 80
				},
				new FieldData
				{
					ColumnAlias = "Reason",
					ColumnWidth = 80
				}
			};
		}
		catch (Exception ex)
		{
			reportMatrix.Message = $"{ex.Message}\r\n{ex.StackTrace}";
		}
		return reportMatrix;
	}

	public List<string[]> LoadSettingAuditLog(int iVoucherType, CalendarType oCalType, string sDateFormat, int iCompId)
	{
		string suffix = FConvert.GetSuffix(iCompId);
		RDConversion rDConversion = new RDConversion(oCalType);
		rDConversion.DateFormat = sDateFormat;
		List<string[]> list = new List<string[]>();
		Database database = DatabaseWrapper.GetDatabase2(iCompId);
		string text = string.Format("SELECT cCore_SettingAuditLog{0}.iAuditId,cCore_SettingAuditLog{0}.iModifiedDate\r\n                ,cCore_SettingAuditLog{0}.iModifiedTime ,ISNULL(mSec_Users.sUserName,mSec_Users.sLoginName)[UserName]\r\n                FROM cCore_SettingAuditLog{0} \r\n                JOIN tSec_UserLog ON cCore_SettingAuditLog{0}.iSessionId = tSec_UserLog.iSessionId\r\n                JOIN cCore_Vouchers{0} ON cCore_Vouchers{0}.iVoucherType = cCore_SettingAuditLog{0}.iVoucherType\r\n                LEFT JOIN mSec_Users ON mSec_Users.iUserId =  tSec_UserLog.iUserId\r\n                WHERE cCore_SettingAuditLog{0}.iVoucherType = {1}\r\n                ORDER BY cCore_SettingAuditLog{0}.iModifiedDate,cCore_SettingAuditLog{0}.iModifiedTime", suffix, iVoucherType);
		IDataReader dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		while (dataReader.Read())
		{
			list.Add(new string[6]
			{
				string.Empty,
				Convert.ToString(dataReader["iAuditId"]),
				string.Empty,
				rDConversion.SetDateFormat(StandardDataFormat.Default, Convert.ToInt32(dataReader["iModifiedDate"]), RDCommon.GetDateSeparator(0)),
				new Time(Convert.ToInt32(dataReader["iModifiedTime"])).ToString(),
				Convert.ToString(dataReader["UserName"])
			});
		}
		dataReader.Close();
		return list;
