	private VWAuditDetailData getVWAuditObject(string sFieldName, DualIdPair oOldValue, object oNewValue, MasterDataType oDataType = MasterDataType.Text, int iRowIndex = 0)
	{
		string sDefaultValue = null;
		string oldValue = ConvertVWValue(oOldValue.Value, oDataType, sDefaultValue);
		string newValue = ConvertVWValue(oNewValue, oDataType, sDefaultValue);
		return new VWAuditDetailData
		{
			AuditCategory = (VWTabCategory)oOldValue.Id,
			RowIndex = iRowIndex,
			FieldName = sFieldName,
			OldValue = oldValue,
			NewValue = newValue
		};
	}

	private VWAuditDetailData[] getChangedFlagField(VWTabCategory oVWTabCategory, int iFlagId, DualIdPair oOldValue, object oNewValue)
	{
		int iOldFlagValue = 0;
		int iNewFlagValue = 0;
		IdValuePair[] array = null;
		VWAuditDetailData vWAuditDetailData = null;
		List<VWAuditDetailData> list = new List<VWAuditDetailData>();
		if (TagResourceForFlags != null && TagResourceForFlags.Length != 0)
		{
			array = (IdValuePair[])TagResourceForFlags[iFlagId].Value;
		}
		if (oOldValue != null)
		{
			iOldFlagValue = Convert.ToInt32(oOldValue.Value);
		}
		if (oNewValue != null)
		{
			iNewFlagValue = Convert.ToInt32(oNewValue);
		}
		if (array != null && array.Length != 0)
		{
			for (int i = 0; i < array.Length; i++)
			{
				vWAuditDetailData = GetChangedFlagValues(oVWTabCategory, iOldFlagValue, iNewFlagValue, array[i]);
				if (vWAuditDetailData != null)
				{
					list.Add(vWAuditDetailData);
				}
			}
		}
		return list.ToArray();
	}

	private VWAuditDetailData GetChangedFlagValues(VWTabCategory oVWTabCategory, int iOldFlagValue, int iNewFlagValue, IdValuePair oTagResource)
	{
		string text = "";
		string text2 = "";
		if (oTagResource != null)
		{
			if (oTagResource.ID == 20 && oVWTabCategory == VWTabCategory.Misc)
			{
				text = GetSelectedValueCheckBudget(iOldFlagValue >> oTagResource.ID);
				text2 = GetSelectedValueCheckBudget(iNewFlagValue >> oTagResource.ID);
			}
			else
			{
				text = ((((iOldFlagValue >> oTagResource.ID) & 1) == 1) ? "True" : "False");
				text2 = ((((iNewFlagValue >> oTagResource.ID) & 1) == 1) ? "True" : "False");
			}
		}
		if (text == text2)
		{
			return null;
		}
		return new VWAuditDetailData
		{
			AuditCategory = oVWTabCategory,
			RowIndex = 0,
			FieldName = Convert.ToString(oTagResource.Value),
			OldValue = text,
			NewValue = text2
		};
	}

	private string GetSelectedValueCheckBudget(int iIndex)
	{
		return iIndex switch
		{
			0 => "None", 
			1 => "Precommitted", 
			2 => "Committed", 
			3 => "Cancel Precommitted", 
			4 => "Cancel Committed", 
			5 => "Do Not Check", 
			_ => "Something wrong!!!", 
		};
	}

	private string ConvertVWValue(object oValue, MasterDataType oDataType, string sDefaultValue)
	{
		string text = Convert.ToString(oValue);
		if (!string.IsNullOrEmpty(text))
		{
			switch (oDataType)
			{
			case MasterDataType.Date:
				text = new Date(Convert.ToInt32(oValue), m_objCalType).ToString();
				break;
			case MasterDataType.Time:
				text = FConvert.IntToStringTime(Convert.ToInt32(oValue));
				break;
			case MasterDataType.NumberList:
			{
				if (string.IsNullOrEmpty(sDefaultValue) || string.IsNullOrEmpty(text))
				{
					break;
				}
				bool flag = false;
				string[] array = sDefaultValue.Split(',');
				foreach (string text2 in array)
				{
					if (flag)
					{
						text = text2;
						break;
					}
					if (text2 == text)
					{
						flag = true;
					}
				}
				break;
			}
			case MasterDataType.Boolean:
				FConvert.PrintBooleanAs(_focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Print, 26), ref oValue);
				text = Convert.ToString(oValue);
				break;
			case MasterDataType.Fraction:
				text = RDCommon.InsertComma(Convert.ToDecimal(oValue), 2, bNumericSeparator: true);
				break;
			}
		}
		if (!string.IsNullOrEmpty(text))
		{
			return text;
		}
		return string.Empty;
	}

	public StandardQuery GeRDQueryForPayroll(StandardQuery objQuery, ref RepRecord objRec, int iCompId)
	{
		PayReportDS payReportDS = new PayReportDS();
		objQuery.Query = payReportDS.GeRDQueryForPayroll(objRec.ReportCustomize, objRec, iCompId);
		if (objRec.ExtraColumns == null)
		{
			objRec.ExtraColumns = General.GetAllColumns(objRec.Columns, null);
		}
		return objQuery;
	}

	private InventoryStock[] stock_on(int iProductId, int iDate, string sWarehouseId, int iUserId, int iCompId, ref ValuationMethod objValuationMethod, ref bool bDonotUpdateStock, ref List<IdNamePair> arrStandardRate)
	{
		Database database = null;
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		string text = null;
		ProductType productType = ProductType.None;
		database = DatabaseWrapper.GetDatabase2(iCompId);
		if (ProngHorn.USESOCKET(iCompId) && ProngHorn.GetSocketFlag(iCompId).MastersEnabled)
		{
			MastersGetTypeRetParam masterInfos = ProngHorn.GetMasterInfos(2, iProductId, iCompId);
			objValuationMethod = (ValuationMethod)masterInfos.iValuationMethod;
			if (objValuationMethod != ValuationMethod.BatchRate && objValuationMethod != ValuationMethod.Standard && objValuationMethod != ValuationMethod.FIFO && objValuationMethod != ValuationMethod.FIFOTransactionTime && objValuationMethod != ValuationMethod.LIFO)
			{
				objValuationMethod = ValuationMethod.WeightedAvg;
			}
			productType = (ProductType)masterInfos.iAccountType;
			_ = masterInfos.iGroup;
			productType = ((masterInfos.bDonotUpdateStock > 0) ? ProductType.Service : productType);
		}
		else
		{
			text = $"SELECT iValuationMethod, iProductType, bGroup, ISNULL(bDonotUpdateStock, 0) bDonotUpdateStock FROM mCore_Product join mCore_Product_Props on mCore_Product_Props.iMasterId = mCore_Product.iMasterId  WHERE mCore_Product.iMasterId = {iProductId}";
			dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dataReader = database.ExecuteReader(dbCommand);
			if (dataReader.Read())
			{
				objValuationMethod = (ValuationMethod)Convert.ToByte(dataReader["iValuationMethod"]);
				if (objValuationMethod != ValuationMethod.BatchRate && objValuationMethod != ValuationMethod.Standard && objValuationMethod != ValuationMethod.FIFO && objValuationMethod != ValuationMethod.FIFOTransactionTime && objValuationMethod != ValuationMethod.LIFO)
				{
					objValuationMethod = ValuationMethod.WeightedAvg;
				}
				productType = (ProductType)Convert.ToByte(dataReader["iProductType"]);
				Convert.ToBoolean(dataReader["bGroup"]);
				if (Convert.ToBoolean(dataReader["bDonotUpdateStock"]))
				{
					productType = ProductType.Service;
				}
			}
			dataReader.Close();
		}
		if (productType <= ProductType.Service)
		{
			bDonotUpdateStock = true;
			return null;
		}
		switch (objValuationMethod)
		{
		case ValuationMethod.WeightedAvg:
		case ValuationMethod.MonthlyWeightedAvg:
			text = StockOnWeightedAvg(iProductId, iDate, sWarehouseId, database, iUserId, iCompId);
			break;
		case ValuationMethod.Standard:
			text = StockOnWeightedAvg(iProductId, iDate, sWarehouseId, database, iUserId, iCompId);
			arrStandardRate = StockOnStandard(iProductId, iDate, sWarehouseId, database, iUserId, iCompId);
			break;
		case ValuationMethod.FIFO:
			text = StockOnLifo(iProductId, iDate, sWarehouseId, database, iUserId, iCompId, bLIFO: false);
			break;
		case ValuationMethod.FIFOTransactionTime:
			text = StockOnFIFO2(iProductId, iDate, sWarehouseId, database, iUserId, iCompId);
			break;
		case ValuationMethod.LIFO:
			text = StockOnLifo(iProductId, iDate, sWarehouseId, database, iUserId, iCompId, bLIFO: true);
			break;
		case ValuationMethod.BatchRate:
			return null;
		}
		if (text != null && text.Length > 0)
		{
			if (objValuationMethod == ValuationMethod.FIFO)
			{
				return GetFIFOStockData(text, iDate, database, iUserId, iCompId);
			}
			return GetStockData(text, database, iUserId, iCompId);
		}
		return null;
	}

	private List<IdNamePair> StockOnStandard(int iProductId, int iDate, string sWarehouseId, Database objDB, int iUserId, int iCompId)
	{
		string text = null;
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		List<IdNamePair> list = null;
		try
		{
			text = string.Format("SELECT iProductId,iDate[Date], mRate[Rate] \r\n                FROM mCore_StdRate{0} WITH (READUNCOMMITTED)                   \r\n                WHERE mCore_StdRate{0}.iProductId = {1} AND mCore_StdRate{0}.iDate >= {2} ORDER BY iProductId,iDate", FConvert.GetSuffix(iCompId), iProductId, iDate, CheckUserPermissionOnWarehouse(iUserId, sWarehouseId, objDB, iCompId));
			dbCommand = objDB.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dataReader = objDB.ExecuteReader(dbCommand);
			list = new List<IdNamePair>();
			while (dataReader.Read())
			{
				list.Add(new IdNamePair(Convert.ToInt32(dataReader["iProductId"]), dataReader["Date"].ToString(), Convert.ToDecimal(dataReader["Rate"])));
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
		}
		return list;
	}

	private InventoryStock[] GetFIFOStockData(string strQuery, int iDate, Database objDB, int iUserId, int iCompId)
	{
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		decimal num = 0m;
		InventoryStock inventoryStock = null;
		List<InventoryStock> list = null;
		List<InventoryStock> list2 = null;
		if (objDB == null)
		{
			objDB = DatabaseWrapper.GetDatabase2(iCompId, -1, bReplicationServer: true);
		}
		dbCommand = objDB.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(strQuery) : strQuery);
		dataReader = objDB.ExecuteReader(dbCommand);
		list = new List<InventoryStock>();
		list2 = new List<InventoryStock>();
		while (dataReader.Read())
		{
			inventoryStock = new InventoryStock();
			inventoryStock.Date = Convert.ToInt32(dataReader["Date"]);
			inventoryStock.Quantity = Convert.ToDecimal(dataReader["Quantity"]);
			inventoryStock.Value = Convert.ToDecimal(dataReader["Value"]);
			inventoryStock.LocalValue = Convert.ToDecimal(dataReader["lValue"]);
			inventoryStock.Rate = Convert.ToDecimal(dataReader["Rate"]);
			inventoryStock.IsInward = Convert.ToBoolean(dataReader["Inward"]);
			if (inventoryStock.Date <= iDate)
			{
				if (inventoryStock.Quantity < 0m)
				{
					num += inventoryStock.Quantity;
				}
				else
				{
					list2.Add(inventoryStock);
				}
			}
			else
			{
				list.Add(inventoryStock);
			}
		}
		dataReader.Close();
		if (list2.Count > 0)
		{
			decimal dIssueValue = 0m;
			dIssueValue = GetFIFOStockValue(num * -1m, ref dIssueValue, ref dIssueValue, ref list2, 0m);
			list.InsertRange(0, list2.Where((InventoryStock p) => p.Quantity != 0m));
		}
		return list.ToArray();
	}

