	private string StockOnWeightedAvg(int iProductId, int iDate, string sWarehouseId, Database objDB, int iUserId, int iCompId)
	{
		return string.Format("SELECT tCore_Header{0}.iDate[Date], fQuantity[Quantity], mStockValue[Value], \r\n            case when fQuantity <= 0 or mStockValue = 0 then 0 else mStockValue/fQuantity end[Rate],  \r\n            case when iVoucherClass = 0x200 then 0 else 1 end[Inward],ISNULL(mLocalStockValue,0)[lValue] FROM tCore_Data{0}\r\n            JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId\r\n            JOIN tCore_Header{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n            WHERE bUpdateStocks = 1 AND tCore_Indta{0}.iProduct = {1} AND (iDate <= {2} OR (iVoucherClass = 0x200) {3})\r\n            ORDER BY iDate, iTransactionId", FConvert.GetSuffix(iCompId), iProductId, iDate, CheckUserPermissionOnWarehouse(iUserId, sWarehouseId, objDB, iCompId));
	}

	private string StockOnFIFO2(int iProductId, int iDate, string sWarehouseId, Database objDB, int iUserId, int iCompId)
	{
		return string.Format("SELECT tCore_Header{0}.iDate[Date], \r\n            fQuantity[Quantity], mStockValue[Value], ISNULL(mLocalStockValue,0)[lValue],\r\n            CASE WHEN fQuantity <= 0 then 0 else mStockValue/fQuantity end[Rate], 1[Inward] FROM tCore_Data{0}\r\n            JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId\r\n            JOIN tCore_Header{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n            WHERE tCore_Indta{0}.iProduct = {1} AND (tCore_Header{0}.iDate <= {2} OR iVoucherClass = {3}) {4}\r\n            ORDER BY tCore_Header{0}.iDate, iTransactionId", FConvert.GetSuffix(iCompId), iProductId, iDate, 512, CheckUserPermissionOnWarehouse(iUserId, sWarehouseId, objDB, iCompId));
	}

	private string StockOnLifo(int iProductId, int iDate, string sWarehouseId, Database objDB, int iUserId, int iCompId, bool bLIFO)
	{
		return string.Format("SELECT tCore_Header{0}.iDate[Date], tCore_Indta{0}.fQuantity[Quantity], \r\n                tCore_Indta{0}.mStockValue[Value], ISNULL(mLocalStockValue,0)[lValue],\r\n                case when tCore_Indta{0}.fQuantity <= 0 then 0 else (mStockValue)/tCore_Indta{0}.fQuantity end[Rate], 1[Inward] \r\n                FROM tCore_Data{0} JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId\r\n                JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                WHERE bUpdateStocks = 1 AND tCore_Indta{0}.iProduct = {1} AND (tCore_Header{0}.iDate <= {2} OR iVoucherClass = {3}) {4}\r\n                ORDER BY tCore_Header{0}.iDate {5}, iTransactionId", FConvert.GetSuffix(iCompId), iProductId, iDate, 512, CheckUserPermissionOnWarehouse(iUserId, sWarehouseId, objDB, iCompId), bLIFO ? "DESC" : "");
	}

	private string CheckUserPermissionOnWarehouse(int iUserId, string sWarehouseId, Database objDB, int iCompId)
	{
		int num = -1;
		string text = null;
		string text2 = string.Empty;
		if (iUserId != 1 && _focus.company(iCompId).getPreferenceValue(PreferenceCategories.Print, 36) == 0)
		{
			num = _focus.company(iCompId).invTagId;
			text = CheckRoleMasters(iUserId, num, 1, objDB, iCompId);
			if (text.Length > 0)
			{
				text2 += $" AND iInvTag IN({text})";
			}
		}
		if (!string.IsNullOrEmpty(sWarehouseId))
		{
			text2 = ((!sWarehouseId.Contains(",")) ? (text2 + $" AND iInvTag = {sWarehouseId} ") : (text2 + $" AND iInvTag IN({sWarehouseId}) "));
		}
		return text2;
	}

	private string CheckRoleMasters(int UserId, int iMasterTypeId, int iEntryType, Database objDb, int iCompId)
	{
		string text = null;
		string text2 = null;
		StringBuilder stringBuilder = null;
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		stringBuilder = new StringBuilder();
		if (UserId > 1 && iMasterTypeId > 0)
		{
			if (objDb == null)
			{
				objDb = DatabaseWrapper.GetDatabase2(iCompId);
			}
			text = $"SELECT iMasterId FROM mSec_RolesMasters JOIN mSec_Users_Roles ON mSec_RolesMasters.iRoleId = mSec_Users_Roles.iERPRole  \r\n                    WHERE mSec_Users_Roles.iUserId = {UserId} AND mSec_RolesMasters.iMasterTypeId = {iMasterTypeId} AND mSec_RolesMasters.iType = {iEntryType}";
			dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dataReader = objDb.ExecuteReader(dbCommand);
			while (dataReader.Read())
			{
				stringBuilder.AppendFormat("{0} iMasterId = {1} ", (stringBuilder.Length == 0) ? string.Empty : "OR", dataReader["iMasterId"]);
			}
			dataReader.Close();
			text = $"SELECT 'vm'+sModule+'_'+sMasterName FROM cCore_MasterDef WHERE iMasterTypeId={iMasterTypeId}";
			dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			text2 = Convert.ToString(objDb.ExecuteScalar(dbCommand));
			if (stringBuilder.Length > 0)
			{
				text = string.Format("WITH RecursionCTE (iMasterId) AS  \r\n                    (  \r\n                       SELECT iMasterId FROM {0} WHERE {1} and iStatus = 0\r\n                       UNION ALL  \r\n                       SELECT R1.iMasterId FROM {0} AS R1 JOIN RecursionCTE AS R2 ON R2.iMasterId = R1.iParentId and iStatus = 0\r\n                    )  \r\n                    SELECT DISTINCT iMasterId FROM RecursionCTE\r\n                    union all \r\n\t\t\t\t    SELECT DISTINCT iMasterId FROM {0} where bDoNotRestrict = 1 and iStatus = 0", text2, stringBuilder.ToString());
				dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				dataReader = objDb.ExecuteReader(dbCommand);
				stringBuilder = new StringBuilder();
				while (dataReader.Read())
				{
					stringBuilder.AppendFormat("{0}{1}", (stringBuilder.Length == 0) ? string.Empty : ",", dataReader["iMasterId"]);
				}
				dataReader.Close();
			}
		}
		return stringBuilder.ToString();
	}

	public ReturnStatus SaveCashFlowTemplate(CalRecord oData, int iCompId)
	{
		ReturnStatus result = ReturnStatus.NoError;
		string empty = string.Empty;
		string suffix = FConvert.GetSuffix(iCompId);
		DbCommand dbCommand = null;
		Database database = null;
		DbTransaction dbTransaction = null;
		DbConnection dbConnection = null;
		int num = 0;
		database = DatabaseWrapper.GetDatabase2(iCompId);
		try
		{
			using (dbConnection = database.CreateConnection())
			{
				dbConnection.Open();
				using (dbTransaction = dbConnection.BeginTransaction())
				{
					if (oData.TemplateId > 0)
					{
						num = oData.TemplateId;
						empty = $"Update cCore_CashFlowTemplate{suffix} set iStartDate = {oData.StartDate}, iEndDate = {oData.EndDate}, iTransactionSet = {oData.TransactionSets}, sTemplateName = '{oData.TemplateName}' where iTemplateId = {num}";
						dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
						database.ExecuteNonQuery(dbCommand, dbTransaction);
					}
					else
					{
						empty = $"INSERT INTO cCore_CashFlowTemplate{suffix}( iStartDate, iEndDate, iTransactionSet, sTemplateName) VALUES ({oData.StartDate},{oData.EndDate},{oData.TransactionSets},'{oData.TemplateName}');select @@IDENTITY";
						dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
						num = Convert.ToInt32(database.ExecuteScalar(dbCommand, dbTransaction));
					}
					empty = $"Delete from cCore_CashFlowMasters{suffix} where iTemplateId = {num}";
					dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
					database.ExecuteNonQuery(dbCommand, dbTransaction);
					empty = $"Delete from cCore_CashFlowProjected{suffix} where iTemplateId = {num}";
					dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
					database.ExecuteNonQuery(dbCommand, dbTransaction);
					if (oData.ProjectedData != null && oData.ProjectedData.Length != 0)
					{
						for (int i = 0; i < oData.ProjectedData.Length; i++)
						{
							empty = $"INSERT INTO cCore_CashFlowProjected{suffix}(iTemplateId, iPostingDate, iAccountId, mAmount, sFormula, bBudget) VALUES ({num},{oData.ProjectedData[i].PostingDate},{oData.ProjectedData[i].AccountId},{oData.ProjectedData[i].Amount},'{oData.ProjectedData[i].Formula}',{(oData.ProjectedData[i].IsBudget ? 1 : 0)})";
							dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
							database.ExecuteNonQuery(dbCommand, dbTransaction).ToString();
						}
					}
					if (oData.SelectedMasters != null && oData.SelectedMasters.Length != 0)
					{
						for (int j = 0; j < oData.SelectedMasters.Length; j++)
						{
							empty = $"INSERT INTO cCore_CashFlowMasters{suffix}(iTemplateId, iAccountId) VALUES ({num},{oData.SelectedMasters[j]})";
							dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
							database.ExecuteNonQuery(dbCommand, dbTransaction).ToString();
						}
					}
					dbTransaction.Commit();
				}
				dbConnection.Close();
			}
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
			dbTransaction.Rollback();
			result = ReturnStatus.WrongTableDef;
		}
		finally
		{
			if (dbConnection != null && dbConnection.State == ConnectionState.Open)
			{
				dbConnection.Close();
			}
		}
		return result;
	}

	public CalRecord LoadCashFlowTemplate(int iTemplateId, int iCompId)
	{
		Database database = null;
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		string empty = string.Empty;
		string suffix = FConvert.GetSuffix(iCompId);
		new List<CalRecord>();
		CalRecord calRecord = null;
		CashFlowProjectedData cashFlowProjectedData = null;
		List<CashFlowProjectedData> list = new List<CashFlowProjectedData>();
		int num = 0;
		List<int> list2 = new List<int>();
		try
		{
			database = DatabaseWrapper.GetDatabase2(iCompId);
			empty = $"SELECT iStartDate, iEndDate, iTransactionSet, sTemplateName FROM cCore_CashFlowTemplate{suffix} where iTemplateId = {iTemplateId}";
			using (dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty))
			{
				dataReader = database.ExecuteReader(dbCommand);
				while (dataReader.Read())
				{
					calRecord = new CalRecord();
					calRecord.TemplateId = Convert.ToInt32(iTemplateId);
					calRecord.StartDate = Convert.ToInt32(dataReader["iStartDate"]);
					calRecord.EndDate = Convert.ToInt32(dataReader["iEndDate"]);
					calRecord.TransactionSets = Convert.ToInt32(dataReader["iTransactionSet"]);
					calRecord.TemplateName = Convert.ToString(dataReader["sTemplateName"]);
				}
				dataReader.Close();
			}
			empty = $"SELECT iTemplateId, iAccountId FROM cCore_CashFlowMasters{suffix} where iTemplateId = {iTemplateId}";
			using (dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty))
			{
				dataReader = database.ExecuteReader(dbCommand);
				while (dataReader.Read())
				{
					num = Convert.ToInt32(dataReader["iAccountId"]);
					list2.Add(num);
				}
				dataReader.Close();
			}
			if (list2 != null && list2.Count > 0)
			{
				calRecord.SelectedMasters = list2.ToArray();
			}
			empty = $"SELECT iPostingDate, iAccountId, mAmount, sFormula, bBudget FROM cCore_CashFlowProjected{suffix} where iTemplateId = {iTemplateId}";
			using (dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty))
			{
				dataReader = database.ExecuteReader(dbCommand);
				while (dataReader.Read())
				{
					cashFlowProjectedData = new CashFlowProjectedData();
					cashFlowProjectedData.PostingDate = Convert.ToInt32(dataReader["iPostingDate"]);
					cashFlowProjectedData.AccountId = Convert.ToInt32(dataReader["iAccountId"]);
					cashFlowProjectedData.Amount = Convert.ToInt32(dataReader["mAmount"]);
					cashFlowProjectedData.Formula = Convert.ToString(dataReader["sFormula"]);
					cashFlowProjectedData.IsBudget = Convert.ToBoolean(dataReader["bBudget"]);
					list.Add(cashFlowProjectedData);
				}
				dataReader.Close();
			}
			if (list != null && list.Count > 0)
			{
				calRecord.ProjectedData = list.ToArray();
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
		}
		return calRecord;
	}

