	private void RearrangeData(ref ReportMatrix objData, RepRecord objRec, bool bEndOfFile, int iCompId, int iFieldCount)
	{
		object[] objValue = null;
		int num = 0;
		string text = null;
		m_bUseRedisServer = _focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Print, 42) > 0;
		if (m_objDatabase == null)
		{
			m_objDatabase = DatabaseWrapper.GetDatabase2(iCompId);
		}
		if (FConvert.GetInputObject(objRec.Inputs, -11) != null)
		{
			m_strOpeningBalance = FConvert.GetNameFromResource("lblOpeningBalance", (Dictionary<string, string>)FConvert.GetInputObject(objRec.Inputs, -11));
		}
		switch (objRec.Module)
		{
		case Module.Inventory:
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.MonthlyMasterDetails:
			case FocusReport.DailyMasterDetails:
			case FocusReport.DailyTransactionDetails:
				objData.ColumnData = ArrangeBalanceWithOpeningBalance(objRec, objData.ColumnData, iCompId);
				break;
			case FocusReport.StockLedger:
				objData.ColumnData = ArrangeStockLedger(objData.ColumnData, ref objRec, bEndOfFile, iFieldCount, objData.UniqueId, iCompId);
				objData.BalanceValues = objRec.Outputs;
				break;
			case FocusReport.StockStatement:
				objData.ColumnData = ArrangeStockStatement(objData.ColumnData, ref objRec, objData.EndOfFile, iFieldCount, objData.UniqueId, iCompId);
				objData.BalanceValues = objRec.Outputs;
				break;
			case FocusReport.StockMovement:
				if (objRec.Outputs == null)
				{
					objRec.Outputs = new IdValuePair[1];
					text = _focus.company(m_iCompanyId).getInventoryFilter(objRec.FilterSource);
					objRec.Outputs[0] = new IdValuePair(0, text);
				}
				objData.ColumnData = ArrangeStockMovement(objData.ColumnData, objRec, text, objData.EndOfFile, iFieldCount, objData.UniqueId, iCompId);
				objData.BalanceValues = objRec.Outputs;
				break;
			case FocusReport.StockAgeingAnalysis:
				objData.ColumnData = ArrangeStockAgeingAnalysis(objData.ColumnData, objData.ExtraColumns.Length, objData.EndOfFile, objRec, objData.UniqueId, iCompId);
				objData.BalanceValues = objRec.Outputs;
				break;
			case FocusReport.VirtualStockAnalysis:
				objData.ColumnData = ArrangeVirtualStock(objData.ColumnData, objData.UniqueId, objData.EndOfFile, objRec, iCompId);
				break;
			case FocusReport.ABCAnalysisProdcut:
				objData.ColumnData = ArrangeABCAnalysis(objData.ColumnData, objRec, objData.UniqueId, objData.EndOfFile, iCompId);
				objData.BalanceValues = objRec.Outputs;
				break;
			case FocusReport.StockValuation:
				if (objRec.Outputs == null)
				{
					objRec.Outputs = new IdValuePair[1];
					text = _focus.company(m_iCompanyId).getInventoryFilter(objRec.FilterSource);
					objRec.Outputs[0] = new IdValuePair(0, text);
				}
				text = Convert.ToString(objRec.Outputs[0].Value);
				objData.ColumnData = ArrangeStockValuation(objData.ColumnData, objRec, text, objData.EndOfFile, iFieldCount, objData.UniqueId, iCompId);
				objRec.Outputs[0].Value = text;
				objData.BalanceValues = objRec.Outputs;
				break;
			case FocusReport.StockValuationByFATag:
				objData.ColumnData = ArrangeStockValuationByFaTag(objData.ColumnData, objRec, objData.EndOfFile, iFieldCount, objData.UniqueId, iCompId);
				break;
			case FocusReport.FastMovingStock:
			case FocusReport.SlowMovingStock:
				if (objRec.Outputs == null)
				{
					objRec.Outputs = new IdValuePair[1];
					text = _focus.company(m_iCompanyId).getInventoryFilter(objRec.FilterSource);
					objRec.Outputs[0] = new IdValuePair(0, text);
				}
				text = Convert.ToString(objRec.Outputs[0].Value);
				objData.ColumnData = ArrangeFastmovingItem(objData.ColumnData, objRec, text, objData.EndOfFile, iFieldCount, objData.UniqueId, iCompId);
				objRec.Outputs[0].Value = text;
				objData.BalanceValues = objRec.Outputs;
				break;
			case FocusReport.ReorderReport:
				objData.ColumnData = ArrangeReorderBalance(objData.ColumnData, objRec, objData.UniqueId, objData.EndOfFile, iCompId);
				break;
			case FocusReport.PeakAndLowBalanceStock:
				objData.ColumnData = ArrangePeakLowBalance(objData, objRec, objData.ExtraColumns.Length, iCompId);
				objData.BalanceValues = objRec.Outputs;
				break;
			case FocusReport.AgeingStockByBins:
			case FocusReport.AgeingStockByProductByBins:
				objData.ColumnData = ArrangeAgeingStockByBins(objData.ColumnData, objData.ExtraColumns.Length, objData.EndOfFile, objRec, objData.UniqueId, iCompId);
				objData.BalanceValues = objRec.Outputs;
				break;
			case FocusReport.AgeingAnalysisByBatch:
			case FocusReport.AgeingAnalysisByRMA:
				objData.ColumnData = ArrangeAgeingStockByBatch(objData.ColumnData, objData.ExtraColumns.Length, objData.EndOfFile, objRec, objData.UniqueId, iCompId);
				objData.BalanceValues = objRec.Outputs;
				break;
			case FocusReport.StockAnalysisbyBatch:
			case FocusReport.StockAnalysisbyRMA:
				StockByRMA(ref objData, objRec, iCompId);
				break;
			case FocusReport.TransactionWiseStockReport:
				ArrangeTransactionWiseStockReport(ref objData, objRec, iCompId);
				break;
			case FocusReport.GLAndInvMismatchReport:
				ArrangeGLAndInventoryMismatchReport(ref objData, objRec, iCompId);
				break;
			case FocusReport.LinkChainAnalysis:
				ArrangeLinkChainAnalysisReport(ref objData, objRec, iCompId);
				break;
			case FocusReport.StockBalanceByWarehouse:
				ArrangeStockBalanceByWarehouse(ref objData, objRec, iCompId);
				break;
			}
			break;
		case Module.CoreTransactions:
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.MonthlyMasterDetails:
			case FocusReport.DailyMasterDetails:
			case FocusReport.DailyTransactionDetails:
				objData.ColumnData = ArrangeBalanceWithOpeningBalance(objRec, objData.ColumnData, iCompId);
				break;
			case FocusReport.SalesRegister:
			case FocusReport.SummarySalesRegister:
			case FocusReport.PurchaseRegister:
			case FocusReport.SummaryPurchaseRegister:
				if (FConvert.GetInputValue(objRec.Inputs, 1) == 1)
				{
					if (objRec.Outputs == null)
					{
						objRec.Outputs = new IdValuePair[2];
						objRec.Outputs[0] = new IdValuePair(0, objValue);
						objRec.Outputs[1] = new IdValuePair(1, num);
					}
					objValue = (object[])objRec.Outputs[0].Value;
					num = Convert.ToInt32(objRec.Outputs[1].Value);
					objRec.Columns = objData.Columns;
					objData.ColumnData = ArrangeGroupTotal(objData.ColumnData, objRec, ref objValue, 1, ref num, objData.EndOfFile, bMonthlyTotal: true);
					objRec.Outputs[0].Value = objValue;
					objRec.Outputs[1].Value = num;
					objData.BalanceValues = objRec.Outputs;
				}
				break;
			case FocusReport.SalesGroupedByCustomer:
			case FocusReport.SalesGroupedByProduct:
			case FocusReport.SalesGroupedByDepartment:
			case FocusReport.PurchasesGroupedByVendor:
			case FocusReport.PurchasesGroupedByProduct:
			case FocusReport.PurchasesGroupedByDepartment:
				if (objRec.Outputs == null)
				{
					objRec.Outputs = new IdValuePair[2];
					objRec.Outputs[0] = new IdValuePair(0, objValue);
					objRec.Outputs[1] = new IdValuePair(1, num);
				}
