								array = FConvert.CloneObj(objData.ColumnData[i].CellData);
							}
							else if (oRowHeader.RowType == ReportRowType.Total || oRowHeader.RowType == ReportRowType.TreeGroup)
							{
								array = null;
							}
						}
						else if (oRowHeader.RowType == ReportRowType.Normal || oRowHeader.RowType == ReportRowType.OpenigClosingBalance || (oRowHeader.RowType == ReportRowType.TreeGroup && !oRowHeader.TreeData.IsGroup))
						{
							array = FConvert.CloneObj(objData.ColumnData[i].CellData);
						}
						else if (oRowHeader.RowType == ReportRowType.Total)
						{
							array = null;
						}
					}
					list.Add(objData.ColumnData[i]);
					num3 = oRowHeader.Id;
					i++;
					num4++;
				}
				objData.ColumnData = list.ToArray();
				if (flag)
				{
					IdValuePair[] arrInputs = objData.BalanceValues;
					FConvert.SetInputValue(ref arrInputs, -4, num);
					objData.BalanceValues = arrInputs;
					_focus.company(iCompId).setBuffer(sUniqueId2, array);
				}
				_focus.company(iCompId).setBuffer(sUniqueId, num4);
			}
		}
		if (objData.EndOfFile)
		{
			_focus.company(iCompId).clearBuffer(sUniqueId);
			_focus.company(iCompId).clearBuffer(sUniqueId2);
		}
	}

