	private Transaction getTranObjectForFormula(List<IdValuePair> arrTranColumns, object[] arrCellData, int iUserId)
	{
		Transaction transaction = null;
		if (arrTranColumns != null && arrTranColumns.Count > 0 && arrCellData != null)
		{
			transaction = new Transaction();
			transaction.Header = new TransHeader();
			transaction.Header.ModifiedBy = iUserId;
			transaction.Header.Date = new Date(m_objCalType).GetToday(m_objCalType).Value;
			transaction.BodyData = new TransBody[1];
			transaction.BodyData[0] = new TransBody();
			transaction.BodyData[0].Sales = new TransSales();
			TransSales sales = transaction.BodyData[0].Sales;
			decimal baseQuantity = (transaction.BodyData[0].Sales.Quantity = 1m);
			sales.BaseQuantity = baseQuantity;
			for (int i = 0; i < arrTranColumns.Count; i++)
			{
				if (Convert.ToInt32(arrTranColumns[i].Value) < arrCellData.Length && !string.IsNullOrEmpty(Convert.ToString(arrTranColumns[i].Value)))
				{
					switch ((VTFIELDID)arrTranColumns[i].ID)
					{
					case VTFIELDID.FDF_DATE:
						transaction.Header.Date = Convert.ToInt32(arrCellData[Convert.ToInt32(arrTranColumns[i].Value)]);
						break;
					case VTFIELDID.FDF_VOUCHERTYPE:
						transaction.Header.VoucherType = Convert.ToInt32(arrCellData[Convert.ToInt32(arrTranColumns[i].Value)]);
						break;
					case VTFIELDID.FDF_BODYPRODUCT:
						transaction.BodyData[0].Sales.Product = Convert.ToInt32(arrCellData[Convert.ToInt32(arrTranColumns[i].Value)]);
						break;
					case VTFIELDID.FDF_BODYINVTAG:
						transaction.BodyData[0].InvTag = Convert.ToInt32(arrCellData[Convert.ToInt32(arrTranColumns[i].Value)]);
						break;
					case VTFIELDID.FDF_FATAG:
						transaction.BodyData[0].FATag = Convert.ToInt32(arrCellData[Convert.ToInt32(arrTranColumns[i].Value)]);
						break;
					case VTFIELDID.FDF_BODYCODE:
						transaction.BodyData[0].Code = Convert.ToInt32(arrCellData[Convert.ToInt32(arrTranColumns[i].Value)]);
						break;
					case VTFIELDID.FDF_BODYBOOKNO:
						transaction.BodyData[0].Book = Convert.ToInt32(arrCellData[Convert.ToInt32(arrTranColumns[i].Value)]);
						break;
					case VTFIELDID.FDF_BODYUNITS:
						transaction.BodyData[0].Sales.Unit = Convert.ToInt32(arrCellData[Convert.ToInt32(arrTranColumns[i].Value)]);
						break;
					case VTFIELDID.FDF_BODYCURRENCY:
						transaction.BodyData[0].CurrencyId = Convert.ToInt32(arrCellData[Convert.ToInt32(arrTranColumns[i].Value)]);
						break;
					case VTFIELDID.FDF_BODYQUANTITY:
						transaction.BodyData[0].Sales.Quantity = Convert.ToDecimal(arrCellData[Convert.ToInt32(arrTranColumns[i].Value)]);
						break;
					case VTFIELDID.FDF_QUANTITY_IN_BASE:
						transaction.BodyData[0].Sales.BaseQuantity = Convert.ToDecimal(arrCellData[Convert.ToInt32(arrTranColumns[i].Value)]);
						break;
					}
				}
			}
		}
		return transaction;
	}

