	private decimal EvaluateFormula(string strFormula, List<IdNamePair> lstVars)
	{
		string text = null;
		int num = 0;
		try
		{
			if (m_objFormula == null)
			{
				m_objFormula = new FFormula(m_objCalType);
			}
			for (num = 0; num < lstVars.Count; num++)
			{
				m_objFormula.AddVar(lstVars[num].Name, Convert.ToDecimal(lstVars[num].Tag));
			}
			text = m_objFormula.Result(strFormula, bCallbacksForAllVars: false);
			if (text == "NaN" || text.Contains("Infinity") || text.Contains("E+") || text.Contains("E-"))
			{
				return 0m;
			}
		}
		catch
		{
			text = "0";
		}
		return Convert.ToDecimal(text);
	}

