	private int GetMasterDataType(int iSubParentId)
	{
		if (iSubParentId < 100)
		{
			switch ((VTFIELDID)iSubParentId)
			{
			case VTFIELDID.FDF_CODE:
			case VTFIELDID.FDF_BOOKNO:
			case VTFIELDID.FDF_BODYCODE:
			case VTFIELDID.FDF_BODYBOOKNO:
				return 1;
			case VTFIELDID.FDF_BODYPRODUCT:
				return 2;
			default:
				return iSubParentId;
			}
		}
		return iSubParentId & 0xFFFFFF;
	}

	private double GetSqlFnValue(IdNamePair[] arrValues, int iFnNo, Database objDB)
	{
		if (arrValues != null && arrValues.Length != 0)
		{
			XmlSerializer xmlSerializer = new XmlSerializer(typeof(IdNamePair[]));
			string text = "";
			using (StringWriter stringWriter = new StringWriter())
			{
				using XmlWriter xmlWriter = XmlWriter.Create(stringWriter);
				xmlSerializer.Serialize(xmlWriter, arrValues);
				text = stringWriter.ToString();
				text = text.Replace(" xsi:type=\"xsd:string\"", "");
				text = text.Replace(" xsi:type=\"xsd:int\"", "");
				text = text.Replace(" xsi:type=\"xsd:decimal\"", "");
				text = text.Replace(" xsi:type=\"xsd:double\"", "");
				text = text.Replace(" xsi:type=\"xsd:short\"", "");
				text = text.Replace(" xsi:type=\"xsd:long\"", "");
				text = text.Replace(" xsi:type=\"xsd:unsignedByte\"", "");
				text = text.Replace("'", "''");
				int num = text.IndexOf("<IdNamePair");
				if (num >= 0)
				{
					text = text.Substring(num);
				}
				text = "<ArrayOfIdNamePair>" + text;
			}
			string arg = text.ToString();
			string text2 = $"select ISNULL(dbo.fCore_MVar{iFnNo}('{arg}'),0)";
			return Convert.ToDouble(objDB.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text2) : text2));
		}
		return 0.0;
	}

