	private bool IsTotalOnNumericColumns(RepRecord objRec)
	{
		if (objRec != null && objRec.ReportCustomize != null && objRec.ReportCustomize.Layout != null && objRec.ReportCustomize.Layout.Columns != null)
		{
			for (int i = 0; i < objRec.ReportCustomize.Layout.Columns.Length; i++)
			{
				if (objRec.ReportCustomize.Layout.Columns[i].DataTypeId == MasterDataType.Fraction && !RDCommon.GetMiscValue(objRec.ReportCustomize.Layout.Columns[i].Miscelleneous, MiscFields.TotalTheColumn))
				{
					return true;
				}
			}
		}
		return false;
	}

	public ReportMatrix GetPagewiseData(RepRecord objRec, int iCompId)
	{
