	{
		return $"Session:{sSessionId}, Id:{sUniqueId}";
	}

	private void AddReport(uint iReportId, string sSessionId, string sUniqueId)
	{
		redis.GetDatabase().StringSet(value: FConvert.ObjectToByteArray(new IdNamePair((int)iReportId, sSessionId, sUniqueId)), key: getRedisKey(sSessionId, sUniqueId));
	}

	private string getXmlMaster(string strParamValues)
	{
		StringBuilder stringBuilder = new StringBuilder();
		if (!string.IsNullOrEmpty(strParamValues))
		{
			string[] array = strParamValues.Split(',');
			stringBuilder.Append("DECLARE @XML AS XML SET @XML = '<Master>");
			for (int i = 0; i < array.Length; i++)
			{
				stringBuilder.AppendFormat("<r id=\"{0}\"/>", array[i]);
			}
			stringBuilder.Append("</Master>'");
		}
		return stringBuilder.ToString();
	}

	private string getXmlJoin(string strMaster)
	{
		return $" JOIN @XML.nodes('/Master/r') T(c) ON {strMaster}.iMasterId = T.c.value('./@id', 'int') ";
	}

	private Stack<ComboData> PushSelectedMasters(ComboData[] arrMasterRecord, ref bool IsAddSet)
	{
		if (arrMasterRecord != null && arrMasterRecord.Length > 1)
		{
			Stack<ComboData> stack = new Stack<ComboData>();
			for (int i = 0; i < arrMasterRecord.Length; i++)
			{
				stack.Push(arrMasterRecord[i]);
			}
			IsAddSet = true;
			return stack;
		}
		return null;
	}

	private void PopSelectedMasters(Stack<ComboData> arrSelectedMasters, bool bPopAllData, ref RepRecord objRec)
	{
		if (arrSelectedMasters == null || arrSelectedMasters.Count <= 0)
		{
			return;
		}
		List<ComboData> list = new List<ComboData>();
		int num = ((!bPopAllData) ? 1 : arrSelectedMasters.Count);
		if (IsSpecialReport(objRec) && objRec.FetchAllData)
		{
			objRec.RowsPerPage = 2000;
		}
		for (int i = 0; i < num; i++)
		{
			if (arrSelectedMasters.Count == 0)
			{
				break;
			}
			list.Add(arrSelectedMasters.Pop());
		}
		objRec.Masters = list.ToArray();
	}

	private bool IsSpecialReport(RepRecord objRec, bool bCallQuery = false)
	{
		bool result = false;
		if (objRec.ReportId == 500 || objRec.ReportId == 551 || objRec.ReportId == 560 || objRec.ReportId == 542)
		{
			if (bCallQuery && (objRec.ReportId != 500 || RDCommon.IsAccountPropertyEnable(objRec.Inputs, objRec.Masters) <= 0))
			{
				result = true;
			}
		}
		else if (objRec.SourceType == DataSourceType.Query)
		{
			result = true;
		}
		return result;
	}

	private void ReplaceReportVariables(RepRecord objRec, ReportRecordSet objReportRecordSet, ref string strQuery, ref bool bDontExecuteQuery, bool bFetchAllData)
	{
		if (strQuery.Contains("@MasterIdTable"))
		{
			if (bFetchAllData)
			{
				switch ((FocusReport)objRec.ReportId)
				{
				case FocusReport.StockMovement:
				case FocusReport.StockTransferSummary:
					strQuery = strQuery.Replace("AND vrCore_Product.iMasterId IN(@MasterId) ", string.Empty);
					strQuery = strQuery.Replace("AND vrCore_Product.iMasterId = @MasterId ", string.Empty);
					strQuery = strQuery.Replace("@MasterIdTable", " JOIN #MasterIdTable MasterIdTable ON vrCore_Product.iMasterId = MasterIdTable.iMasterId");
					break;
				case FocusReport.LedgerDetail:
					strQuery = strQuery.Replace("AND InnerTable.iMasterId IN(@MasterId) ", string.Empty);
					strQuery = strQuery.Replace("@MasterIdTable", " JOIN #MasterIdTable MasterIdTable ON InnerTable.iMasterId = MasterIdTable.iMasterId");
					break;
				}
			}
			else
			{
				strQuery = strQuery.Replace("@MasterIdTable", string.Empty);
			}
		}
		if (strQuery.Contains("@MasterId"))
		{
			strQuery = strQuery.Replace("@MasterId", General.GetMasters(objRec.Masters));
		}
		if (objReportRecordSet != null && objReportRecordSet.Columns != null && RDCommon.IsAccountPropertyEnable(objRec.Inputs, objRec.Masters) == -2)
		{
			bDontExecuteQuery = ((objReportRecordSet.SelectedMasters == null || objReportRecordSet.SelectedMasters.Count != 0) ? true : false);
		}
	}

	private bool? IsMasterTreeReport(RepRecord oRec)
	{
		bool? result = null;
		if (oRec != null && oRec.Masters != null && oRec.Masters.Length > 1)
		{
			switch ((FocusReport)oRec.ReportId)
			{
			case FocusReport.StockMovement:
			case FocusReport.ABCAnalysisProdcut:
			case FocusReport.FastMovingStock:
			case FocusReport.SlowMovingStock:
			case FocusReport.StockTransferSummary:
			case FocusReport.LedgerDetail:
			case FocusReport.VirtualBankLedger:
				result = oRec.FetchAllData || (oRec.FilterSource != null && oRec.FilterSource.Length != 0);
				break;
			}
		}
		return result;
	}

