	private ReportPreferences GetReportPreferences(int iCompanyId)
	{
		return new ReportPreferences
		{
			PageTotalsInAllReports = (_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Print, 27) == 1),
			PrintDarkLinesInGrid = (_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Print, 3) == 1),
			PrintLineSeparator = (_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Print, 7) == 1),
			VerticalLinesInPrint = (_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Print, 12) == 1),
			ThousandSeparator = (_focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.Misc, 12) == 1)
		};
	}

	private string getFileName(string sReportName, string sMasterName, string sCompanyName)
	{
		Random random = new Random();
		string text = null;
		text = ((!string.IsNullOrEmpty(sMasterName)) ? string.Format("{0}_{1}_{2}{1}_{3}", (sMasterName.Length > 31) ? sMasterName.Substring(0, 30) : sMasterName, random.Next(1, 999999), (sReportName != null) ? sReportName : "", (sCompanyName != null) ? sCompanyName : "") : string.Format("{0}{1}_{2}", (sReportName != null) ? sReportName : "", random.Next(1, 999999), (sCompanyName != null) ? sCompanyName : ""));
		return FConvert.GetValidName(text);
	}

	private void ArrangeDatainHierarchy(ref ReportMatrix objReportMatrix)
	{
		ReportRowHeader reportRowHeader = null;
		string text = "   ";
		if (objReportMatrix == null || objReportMatrix.ColumnData == null)
		{
			return;
		}
		for (int i = 0; i < objReportMatrix.ColumnData.Length; i++)
		{
			reportRowHeader = objReportMatrix.ColumnData[i].CellData[0] as ReportRowHeader;
			if (reportRowHeader.TreeData != null && (reportRowHeader.RowType == ReportRowType.TreeGroup || reportRowHeader.RowType == ReportRowType.Normal))
			{
				for (int j = 0; j < reportRowHeader.TreeData.GroupLevel; j++)
				{
					objReportMatrix.ColumnData[i].CellData[1] = text + objReportMatrix.ColumnData[i].CellData[1];
				}
			}
		}
	}

	private PrintTagDetails GetAccountAgeingDetails(RepRecord objRec, ReportMatrix oReportData, int iCompanyId, ref LayoutInformation objLayoutInformation)
	{
		PrintTagDetails result = null;
		RDPrintCommon rDPrintCommon = null;
		int[] array = null;
		List<int> list = null;
		List<string> list2 = null;
		List<FieldData> list3 = null;
		int transactionId = 0;
		bool flag = false;
		rDPrintCommon = new RDPrintCommon();
		RDDefault rDDefault = new RDDefault();
		InvoiceLayout invoiceLayout = new InvoiceLayout();
		BackTrackType backTrackType = rDDefault.GetBackTrackType(objRec.ReportId, objRec.Module);
		objLayoutInformation = invoiceLayout.LoadReportInvoiceLayout((int)objRec.ReportId, objRec.LayoutId, iCompanyId);
		if (rDPrintCommon.IsTransactionTypeReport(objRec.ReportId) || backTrackType == BackTrackType.Transaction || backTrackType == BackTrackType.TransactionHeaderId)
		{
			list = new List<int>();
			list2 = new List<string>();
			list3 = new List<FieldData>();
			for (int i = 0; i < oReportData.ColumnData.Length; i++)
			{
				if ((oReportData.ColumnData[i].CellData[0] as ReportRowHeader).RowType == ReportRowType.Normal)
				{
					transactionId = (oReportData.ColumnData[i].CellData[0] as ReportRowHeader).Id;
					flag = (oReportData.ColumnData[i].CellData[0] as ReportRowHeader).IsHeader;
					break;
				}
			}
			if (rDPrintCommon.IsAgeingFieldsInLayout(objLayoutInformation, ref list, ref list2, ref list3) || list3.Count > 0 || list.Count > 0 || list2.Count > 0)
			{
				ComboData[] masters = objRec.Masters;
				if (masters != null && masters.Length != 0)
				{
					array = objRec.Masters.Select((ComboData p) => p.ID).ToArray();
				}
				else if (objRec.Code > 0)
				{
					array = new int[1] { objRec.Code };
				}
				if ((array != null && array.Length != 0) || array == null)
