							list.Add(getAuditObjectDeleted(VTFIELDID.FDF_RMANO, sValue, num2));
						}
						if (IsValueChanges(oAuditData.BodyData[num2].Sales.BinDisplay, string.Empty, ref sValue, ref sValue2))
						{
							list.Add(getAuditObjectDeleted(VTFIELDID.FDF_BINS, sValue, num2));
						}
						if (oAuditData.BodyData[num2].Sales.ScreenData != null)
						{
							for (num4 = 0; num4 < oAuditData.BodyData[num2].Sales.ScreenData.Length; num4++)
							{
								if (oAuditData.BodyData[num2].Sales.ScreenData[num4].Input > 0m)
								{
									list.Add(getAuditObjectDeleted((VTFIELDID)oAuditData.BodyData[num2].Sales.ScreenData[num4].FieldId, oAuditData.BodyData[num2].Sales.ScreenData[num4].Input, num2, MasterDataType.Fraction));
								}
							}
						}
					}
					if (oAuditData.BodyData[num2].Tags != null)
					{
						for (num4 = 0; num4 < oAuditData.BodyData[num2].Tags.Length; num4++)
						{
							if (!string.IsNullOrEmpty(Convert.ToString(oAuditData.BodyData[num2].Tags[num4].Tag)))
							{
								list.Add(getAuditObjectDeleted((VTFIELDID)oAuditData.BodyData[num2].Tags[num4].ID, oAuditData.BodyData[num2].Tags[num4].Tag, num2, MasterDataType.Master, oAuditData.BodyData[num2].Tags[num4].ID));
							}
						}
					}
					if (oAuditData.BodyData[num2].BodyExtra == null)
					{
						continue;
					}
					for (num4 = 0; num4 < oAuditData.BodyData[num2].BodyExtra.Length; num4++)
					{
						if (!string.IsNullOrEmpty(Convert.ToString(oAuditData.BodyData[num2].BodyExtra[num4].Tag)))
						{
							list.Add(getAuditObjectDeleted((VTFIELDID)oAuditData.BodyData[num2].BodyExtra[num4].ID, oAuditData.BodyData[num2].BodyExtra[num4].Tag, num2));
						}
					}
				}
			}
			if (oAuditData.Footer != null)
			{
				for (num2 = 0; num2 < oAuditData.Footer.Length; num2++)
				{
					if (oAuditData.Footer[num2].Input != 0m)
					{
						list.Add(getAuditObjectDeleted((VTFIELDID)oAuditData.Footer[num2].FieldId, oAuditData.Footer[num2].Input, -2, MasterDataType.Fraction));
					}
				}
			}
		}
		return list.ToArray();
	}

	private bool IsValueChanges(object oValue1, object oValue2, ref string sValue1, ref string sValue2)
	{
		sValue1 = (sValue2 = string.Empty);
		if (oValue1 != null)
		{
			if (oValue1.GetType() == typeof(BillAdjustment[]))
			{
				if (((BillAdjustment[])oValue1).Length != 0 && !string.IsNullOrEmpty(((BillAdjustment[])oValue1)[0].sReference))
				{
					sValue1 = ((BillAdjustment[])oValue1)[0].sReference;
				}
			}
			else if (oValue1.GetType() == typeof(DataLink[]))
			{
				if (((DataLink[])oValue1).Length != 0 && !string.IsNullOrEmpty(((DataLink[])oValue1)[0].VoucherNo))
				{
					sValue1 = string.Join(", ", ((DataLink[])oValue1).Select((DataLink p) => p.VoucherNo));
				}
			}
			else if (oValue1.GetType() == typeof(BatchData))
			{
				if (!string.IsNullOrEmpty(((BatchData)oValue1).BatchNo))
				{
					sValue1 = ((BatchData)oValue1).BatchNo;
				}
			}
			else if (oValue1.GetType() == typeof(Reservations))
			{
				sValue1 = ((Reservations)oValue1).Quantity.ToString();
			}
			else if (oValue1.GetType() == typeof(StockToRelease))
			{
				sValue1 = ((StockToRelease)oValue1).Quantity.ToString();
			}
			else if (oValue1.GetType() == typeof(StockReservationList))
			{
				sValue1 = ((StockReservationList)oValue1).Quantity.ToString();
			}
			else if (oValue1.GetType() == typeof(string[]))
			{
				sValue1 = string.Join(",", (string[])oValue1);
			}
			else
			{
				sValue1 = Convert.ToString(oValue1);
			}
		}
		if (oValue2 != null)
		{
			if (oValue2.GetType() == typeof(BillAdjustment[]))
			{
				if (m_bLoadCurrent)
				{
					sValue2 = BillAdjustment.FormBillwiseString((BillAdjustment[])oValue2);
				}
				else if (((BillAdjustment[])oValue2).Length != 0 && !string.IsNullOrEmpty(((BillAdjustment[])oValue2)[0].sReference))
				{
					sValue2 = ((BillAdjustment[])oValue2)[0].sReference;
				}
			}
			else if (oValue2.GetType() == typeof(DataLink[]))
			{
				if (((DataLink[])oValue2).Length != 0 && !string.IsNullOrEmpty(((DataLink[])oValue2)[0].VoucherNo))
				{
					sValue2 = string.Join(", ", ((DataLink[])oValue2).Select((DataLink p) => p.VoucherNo));
				}
			}
			else if (oValue2.GetType() == typeof(BatchData))
			{
				if (!string.IsNullOrEmpty(((BatchData)oValue2).BatchNo))
				{
					sValue2 = ((BatchData)oValue2).BatchNo;
				}
			}
			else if (oValue2.GetType() == typeof(Reservations))
			{
				sValue2 = ((Reservations)oValue2).Quantity.ToString();
			}
			else if (oValue2.GetType() == typeof(BatchReservationList))
			{
				sValue2 = ((BatchReservationList)oValue2).Quantity.ToString();
			}
			else if (oValue2.GetType() == typeof(StockToRelease))
			{
				sValue2 = ((StockToRelease)oValue2).Quantity.ToString();
			}
			else if (oValue2.GetType() == typeof(StockReservationList))
			{
				sValue2 = ((StockReservationList)oValue2).Quantity.ToString();
			}
			else if (oValue2.GetType() == typeof(string[]))
			{
				sValue2 = string.Join(",", (string[])oValue2);
			}
			else
			{
				sValue2 = Convert.ToString(oValue2);
			}
		}
		return sValue1 != sValue2;
	}

