		int num2 = 1024;
		if (m_arrDocFields != null && m_arrDocFields.Length != 0)
		{
			vWVoucherFields = m_arrDocFields.Where((VWVoucherFields p) => p.iFieldId == (int)iFieldId).FirstOrDefault();
