				if (!string.IsNullOrEmpty(vWVoucherFields.sDefaultValue))
				{
					sDefaultValue = vWVoucherFields.sDefaultValue;
				}
			}
			else if (oDataType == MasterDataType.Master && iMasterTypeId > 0)
			{
