			OldValue = text2,
			NewValue = text3
		};
	}

	private string ConvertTranValue(object oValue, VTFIELDID iFieldId, MasterDataType oDataType, int iMasterType, string sDefaultValue)
	{
		string text = Convert.ToString(oValue);
		RDConversion rDConversion = null;
		int num = ((_focus.company(m_iCompanyId).currency != null) ? _focus.company(m_iCompanyId).currency.NoOfDecimal : 2);
		if (!string.IsNullOrEmpty(text))
		{
			try
			{
				switch (oDataType)
				{
				case MasterDataType.Date:
					if (oValue is int)
					{
						rDConversion = new RDConversion(m_objCalType);
						if (!string.IsNullOrEmpty(m_strDateFormat))
						{
							rDConversion.DateFormat = m_strDateFormat;
						}
						text = rDConversion.SetDateFormat(StandardDataFormat.Default, Convert.ToInt32(oValue), null);
					}
					break;
				case MasterDataType.Time:
					text = FConvert.IntToStringTime(Convert.ToInt32(oValue));
					break;
				case MasterDataType.Master:
					if (iMasterType > 0)
					{
						text = GetMasterValue(iMasterType, Convert.ToInt32(oValue), m_iCompanyId);
					}
					else if (iFieldId == VTFIELDID.FDF_HEADERCURRENCY || iFieldId == VTFIELDID.FDF_BODYCURRENCY)
					{
						text = GetMasterValueFromField((int)iFieldId, -1, Convert.ToString(oValue), -2, m_iCompanyId);
					}
					break;
				case MasterDataType.NumberList:
				{
					if (string.IsNullOrEmpty(sDefaultValue) || string.IsNullOrEmpty(text))
					{
						break;
					}
					bool flag = false;
					string[] array = sDefaultValue.Split(',');
					foreach (string text2 in array)
					{
						if (flag)
						{
							text = text2;
							break;
						}
						if (text2 == text)
						{
							flag = true;
						}
					}
					break;
				}
				case MasterDataType.Boolean:
					FConvert.PrintBooleanAs(_focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Print, 26), ref oValue);
					text = Convert.ToString(oValue);
					break;
				case MasterDataType.Fraction:
					if (oValue is decimal)
					{
						text = RDCommon.InsertComma(Convert.ToDecimal(oValue), (iFieldId == VTFIELDID.FDF_EXCHANGERATE) ? 10 : num, bNumericSeparator: true);
					}
					break;
				case MasterDataType.DocumentViewer:
					if (oValue != null && oValue.GetType() == typeof(DocumentData) && !string.IsNullOrEmpty(((DocumentData)oValue).FileName))
					{
						text = ((DocumentData)oValue).FileName;
					}
					break;
				case MasterDataType.DateTime:
				case MasterDataType.Picture:
				case MasterDataType.StringList:
				case MasterDataType.UpdatedTime:
					break;
				}
			}
			catch
			{
				text = string.Empty;
			}
		}
		if (!string.IsNullOrEmpty(text))
		{
			return text;
		}
		return string.Empty;
	}

	private string GetMasterValueFromField(int iFieldId, int iSubParentId, string sFilter, int iLanguageId, int iCompId)
	{
		return new InvoiceLayout
		{
			m_objCalType = m_objCalType
		}.GetMasterValueFromField(iFieldId, iSubParentId, sFilter, iLanguageId, iCompId);
	}

	private bool IsNonEmptyObject(object oValue, int iFieldId)
	{
		string text = Convert.ToString(oValue);
		if (!string.IsNullOrEmpty(text))
		{
			MasterDataType masterDataType = MasterDataType.Text;
			if (m_arrDocFields != null && m_arrDocFields.Length != 0)
			{
				VWVoucherFields vWVoucherFields = m_arrDocFields.Where((VWVoucherFields p) => p.iFieldId == iFieldId).FirstOrDefault();
				if (vWVoucherFields != null)
				{
					masterDataType = (MasterDataType)vWVoucherFields.iDataTypeId;
				}
			}
			switch (masterDataType)
			{
			case MasterDataType.Number:
			case MasterDataType.DateTime:
			case MasterDataType.Date:
			case MasterDataType.Time:
			case MasterDataType.Fraction:
			case MasterDataType.StringList:
			case MasterDataType.NumberList:
			case MasterDataType.Master:
			case MasterDataType.BigNumber:
				if (FConvert.IsNumeric(text))
				{
					return Convert.ToDecimal(text) != 0m;
				}
				return false;
			case MasterDataType.Boolean:
				return text == "1";
			case MasterDataType.DocumentViewer:
				if (oValue != null && oValue.GetType() == typeof(DocumentData) && !string.IsNullOrEmpty(((DocumentData)oValue).FileName))
				{
					return true;
				}
				break;
			default:
				return !string.IsNullOrEmpty(text);
			case MasterDataType.Picture:
			case MasterDataType.ExternalTable:
				break;
			}
		}
		return false;
	}

	public TranAuditDetailData[] GetLockUnlockAuditDetails(int iHeaderId, int iVoucherType, string sVoucherName, int iCompanyId, CalendarType oCalType, ref string sError)
	{
		int num = 0;
		int iOldFlag = 0;
		int num2 = 0;
		int iNewFlag = 0;
		List<IdNamePair> list = new List<IdNamePair>();
		List<IdValuePair> list2 = new List<IdValuePair>();
		List<TranAuditDetailData> lstTranAuditDetailData = new List<TranAuditDetailData>();
		string empty = string.Empty;
		string fieldName = string.Empty;
		IDataReader dataReader = null;
		string text = "";
		string text2 = "";
		try
		{
			FilesDB filesDB = new FilesDB(FConvert.GetCompAuditFolder(GetAuditFolderPath(), iCompanyId), AuditType.LockUnlockDb);
			list = filesDB.LoadDocWithPos(iVoucherType, iHeaderId, iCompanyId);
			filesDB.CloseRead();
			Database database = DatabaseWrapper.GetDatabase2(iCompanyId);
			empty = $"SELECT iLockFlag, iReadDate, iWriteDate, iPrintDate FROM mCore_LockDatabase{FConvert.GetSuffix(iCompanyId)} WHERE iVoucherType = {iVoucherType}";
			dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			while (dataReader.Read())
			{
				list2.Add(new IdValuePair(1, Convert.ToInt32(dataReader["iLockFlag"])));
				list2.Add(new IdValuePair(2, Convert.ToInt32(dataReader["iReadDate"])));
				list2.Add(new IdValuePair(3, Convert.ToInt32(dataReader["iWriteDate"])));
				list2.Add(new IdValuePair(4, Convert.ToInt32(dataReader["iPrintDate"])));
			}
			dataReader.Close();
			List<int> list3 = new List<int>();
			bool flag = false;
			if (list != null)
			{
				if (list2 == null || list2.Count == 0)
				{
					for (num = 0; num < list.Count; num++)
					{
						switch (list[num].ID)
						{
						case 1:
							fieldName = "Lock Flag";
							iOldFlag = Convert.ToInt32(list[num].Name);
							continue;
						case 2:
							fieldName = "Read Date";
							AddReadWritePrintRow(iOldFlag, iNewFlag, 1, ref lstTranAuditDetailData);
							break;
						case 3:
							fieldName = "Write Date";
							AddReadWritePrintRow(iOldFlag, iNewFlag, 2, ref lstTranAuditDetailData);
							break;
						case 4:
							fieldName = "Print Date";
							AddReadWritePrintRow(iOldFlag, iNewFlag, 4, ref lstTranAuditDetailData);
							break;
						}
						text2 = ((Convert.ToInt32(list[num].Name) > 0) ? new Date(oCalType).IntToDate(Convert.ToInt32(list[num].Name)).ToString(m_strDateFormat) : string.Empty);
						if (text != text2)
						{
							lstTranAuditDetailData.Add(new TranAuditDetailData
							{
								AuditType = TranAuditType.Header,
								RowIndex = 0,
								FieldName = fieldName,
								OldValue = text2,
								NewValue = text
							});
						}
					}
				}
				else
				{
					for (num2 = 0; num2 < list2.Count; num2++)
					{
						flag = false;
						for (num = 0; num < list.Count; num++)
						{
							if (list2[num2].ID != list[num].ID)
							{
								continue;
							}
							flag = true;
							if (list[num].Name != Convert.ToString(list2[num2].Value))
							{
								switch (list[num].ID)
								{
								case 1:
									fieldName = "Lock Flag";
									iOldFlag = Convert.ToInt32(list[num].Name);
									iNewFlag = Convert.ToInt32(list2[num2].Value);
									continue;
								case 2:
									fieldName = "Read Date";
									AddReadWritePrintRow(iOldFlag, iNewFlag, 1, ref lstTranAuditDetailData);
									break;
								case 3:
									fieldName = "Write Date";
									AddReadWritePrintRow(iOldFlag, iNewFlag, 2, ref lstTranAuditDetailData);
									break;
								case 4:
									fieldName = "Print Date";
									AddReadWritePrintRow(iOldFlag, iNewFlag, 4, ref lstTranAuditDetailData);
									break;
								}
								text2 = ((Convert.ToInt32(list[num].Name) > 0) ? new Date(oCalType).IntToDate(Convert.ToInt32(list[num].Name)).ToString(m_strDateFormat) : string.Empty);
								text = ((Convert.ToInt32(list2[num2].Value) > 0) ? new Date(oCalType).IntToDate(Convert.ToInt32(list2[num2].Value)).ToString(m_strDateFormat) : string.Empty);
								if (text != text2)
								{
									lstTranAuditDetailData.Add(new TranAuditDetailData
									{
										AuditType = TranAuditType.Header,
										RowIndex = 0,
										FieldName = fieldName,
										OldValue = text2,
										NewValue = text
									});
								}
								break;
							}
						}
						if (!flag)
						{
							list3.Add(num2);
						}
					}
					if (list3 != null && list3.Count > 0 && list2 != null && list2.Count > list3.Count)
					{
						for (int i = 0; i < list3.Count; i++)
						{
							switch (list2[list3[i]].ID)
							{
							case 2:
								fieldName = "Read Date";
								AddReadWritePrintRow(iOldFlag, iNewFlag, 1, ref lstTranAuditDetailData);
								break;
							case 3:
								fieldName = "Write Date";
								AddReadWritePrintRow(iOldFlag, iNewFlag, 2, ref lstTranAuditDetailData);
								break;
							case 4:
								fieldName = "Print Date";
								AddReadWritePrintRow(iOldFlag, iNewFlag, 4, ref lstTranAuditDetailData);
								break;
							}
							text2 = string.Empty;
							text = ((Convert.ToInt32(list2[list3[i]].Value) > 0) ? Convert.ToString(new Date(oCalType).IntToDate(Convert.ToInt32(list2[list3[i]].Value)).ToString(m_strDateFormat)) : string.Empty);
							if (text != text2)
							{
								lstTranAuditDetailData.Add(new TranAuditDetailData
								{
									AuditType = TranAuditType.Header,
									RowIndex = 0,
									FieldName = fieldName,
									OldValue = text2,
									NewValue = text
								});
							}
						}
					}
				}
			}
		}
		catch (Exception ex)
		{
			sError = "\r\nException RDReport->GetLockUnlockAuditDetails  : " + ex.Message + " \r\n " + ex.StackTrace;
		}
		return lstTranAuditDetailData.ToArray();
	}

	private void AddReadWritePrintRow(int iOldFlag, int iNewFlag, int iMaskValue, ref List<TranAuditDetailData> lstTranAuditDetailData)
	{
		if (iOldFlag != iNewFlag && (iOldFlag & iMaskValue) != (iNewFlag & iMaskValue))
		{
			string fieldName = iMaskValue switch
			{
				2 => "Write", 
				1 => "Read", 
				_ => "Print", 
			};
			lstTranAuditDetailData.Add(new TranAuditDetailData
			{
				AuditType = TranAuditType.Header,
				RowIndex = 0,
				FieldName = fieldName,
				OldValue = (((iOldFlag & iMaskValue) != 0) ? "True" : "False"),
				NewValue = (((iNewFlag & iMaskValue) != 0) ? "True" : "False")
			});
		}
	}

	private int IsHiddenColumn(RepRecord objRec, DataSourceType oBaseSourceType)
	{
		if (objRec.SourceType == DataSourceType.Excel || objRec.SourceType == DataSourceType.View || oBaseSourceType == DataSourceType.Query || (objRec.ReportCustomize != null && objRec.ReportCustomize.DataSourceType == DataSourceType.Query) || (objRec.SourceType == DataSourceType.Query && objRec.ReportCustomize.ReportType != ReportType.Standard))
		{
			return 1;
		}
		return 0;
	}

	private object GetIsNull(RepRecord objRec, int iColumn, int iParticular)
	{
		if (iColumn >= objRec.Columns.Length)
		{
			return 0;
		}
		if ((MasterDataType)objRec.Columns[iColumn + iParticular].Tag == MasterDataType.Text || (MasterDataType)objRec.Columns[iColumn + iParticular].Tag == MasterDataType.StringList)
		{
			return string.Empty;
		}
		if ((MasterDataType)objRec.Columns[iColumn - iParticular].Tag == MasterDataType.Fraction)
		{
			return Convert.ToDecimal(0);
		}
		return 0;
	}

	private int[] GetMandatoryColumns(RepRecord objRec, bool bParticularColumn, FieldData[] arrDataColumns, bool bFinalColumnOnly = false)
	{
		int num = 0;
		int num2 = 0;
		List<int> list = new List<int>();
		if (objRec != null && objRec.ReportCustomize != null && objRec.ReportCustomize.Layout.Columns != null && arrDataColumns != null)
		{
			for (num = 0; num < objRec.ReportCustomize.Layout.Columns.Length; num++)
			{
				bool flag = false;
				flag = ((!bFinalColumnOnly) ? RDCommon.GetMiscValue(objRec.ReportCustomize.Layout.Columns[num].Miscelleneous, MiscFields.FinalCalculation) : (!RDCommon.GetMiscValue(objRec.ReportCustomize.Layout.Columns[num].Miscelleneous, MiscFields.FinalCalculation)));
				if (((objRec.ReportCustomize.Layout.Columns[num].Miscelleneous >> 2) & 1) != 1 || flag)
				{
					continue;
				}
				for (num2 = 0; num2 < arrDataColumns.Length; num2++)
				{
					if ((arrDataColumns[num2].ColumnId > 0 && arrDataColumns[num2].ColumnId == objRec.ReportCustomize.Layout.Columns[num].ColumnId) || ((arrDataColumns[num2].FieldId != -2 || arrDataColumns[num2].ColumnId == 0) && arrDataColumns[num2].FieldId == objRec.ReportCustomize.Layout.Columns[num].FieldId && arrDataColumns[num2].SubParentId == objRec.ReportCustomize.Layout.Columns[num].SubParentId))
					{
						list.Add(num2 + (bParticularColumn ? 1 : 0));
						break;
					}
				}
			}
		}
		return list.ToArray();
	}

	private bool IsNullOrEmptyOrZero(object objValue)
	{
		if (objValue == null || Convert.ToString(objValue).Length == 0 || Convert.ToString(objValue).Contains("E+") || Convert.ToString(objValue).Contains("E-"))
		{
			return true;
		}
		if (FConvert.IsNumeric(Convert.ToString(objValue)) && Math.Round(Convert.ToDecimal(objValue), 2) == 0m)
		{
			return true;
		}
		return false;
	}

	private StandardQuery GetStandardQuery(Database objDb, ref RepRecord objRec, ref DataSourceType oBaseDatasourceType, ref bool bGlobalReport, string sUniqueId)
	{
		bool flag = false;
		bool bAddPagingQuery = true;
		int i = 0;
		string strViewName = null;
		RDBackend rDBackend = null;
		StandardQuery standardQuery = null;
		StandardQuery oQuery = null;
		string text = null;
		ComboData[] array = null;
		standardQuery = new StandardQuery();
		if (objRec.ReportQuery != null && !string.IsNullOrEmpty(objRec.ReportQuery.Query) && IsSpecialReport(objRec, bCallQuery: true))
		{
			standardQuery.Query = objRec.ReportQuery.Query;
			if (!string.IsNullOrEmpty(objRec.ReportQuery.PrimaryColumn))
			{
				standardQuery.PrimaryColumn = objRec.ReportQuery.PrimaryColumn;
			}
			if (objRec.ExtraColumns == null)
			{
				objRec.ExtraColumns = General.GetAllColumns(objRec.Columns, null);
			}
		}
		else if (objRec.ReportId >= RDCommon.RD_STARTID)
		{
			if (objRec.Module == Module.Payroll)
			{
				return GeRDQueryForPayroll(standardQuery, ref objRec, m_iCompanyId);
			}
			rDBackend = new RDBackend();
			if (objRec.ReportId >= RDCommon.RD_STARTID && objRec.ReportCustomize.DataSourceType != DataSourceType.Query && objRec.ReportCustomize.DataSourceType != DataSourceType.View && oBaseDatasourceType != DataSourceType.Query && (objRec.ReportCustomize.ReportType == ReportType.Detail || objRec.ReportCustomize.DataSourceType == DataSourceType.Default || objRec.ReportCustomize.DataSourceType == DataSourceType.Reports))
			{
				QueryGenerator queryGenerator = null;
				queryGenerator = new QueryGenerator();
				queryGenerator.Suffix = m_strSuffix;
				queryGenerator.m_iCompId = m_iCompanyId;
				queryGenerator.m_bCallingFromBI = m_bCallingFromBI;
				queryGenerator.SELECTED_MASTERS = SELECTED_MASTERS;
				queryGenerator.DefaultFaTag = DefaultFaTag;
				queryGenerator.AlternateLanguage = AlternateLanguage;
				standardQuery.Query = queryGenerator.GetQueryFromReportId(ref objRec, objDb, m_iCompanyId, ref oQuery, sUniqueId);
				standardQuery.PrimaryColumn = get_order_by(objRec, queryGenerator.m_bDetailRowGrouping, queryGenerator.m_bDetailRowGrouping && !string.IsNullOrEmpty(standardQuery.Query) && standardQuery.Query.Contains("sAbbr"), queryGenerator.m_bTreeSequence);
				if (queryGenerator.m_bVoucherSequence && !string.IsNullOrEmpty(standardQuery.PrimaryColumn))
				{
					standardQuery.PrimaryColumn += $", tCore_Data{m_strSuffix}.iType";
				}
			}
			else
			{
				standardQuery = rDBackend.GetRDQuery(objRec, objDb, m_iCompanyId, ref oBaseDatasourceType);
			}
			if (string.IsNullOrEmpty(standardQuery.PrimaryColumn))
			{
				text = string.Empty;
				getColumnSorting(objRec, ref text);
				if (!string.IsNullOrEmpty(text))
				{
					standardQuery.PrimaryColumn = text;
				}
			}
			text = null;
		}
		else
		{
			QueryGenerator queryGenerator2 = null;
			queryGenerator2 = new QueryGenerator();
			queryGenerator2.Suffix = m_strSuffix;
			queryGenerator2.m_iCompId = m_iCompanyId;
			queryGenerator2.SELECTED_MASTERS = SELECTED_MASTERS;
			queryGenerator2.DefaultFaTag = DefaultFaTag;
			queryGenerator2.AlternateLanguage = AlternateLanguage;
			if (objRec.Module == Module.CoreMasters || objRec.ReportId == 612)
			{
				standardQuery.Query = queryGenerator2.GetMasterQuery(objRec, ref strViewName, ref oQuery);
				if (oQuery != null)
				{
					if (!string.IsNullOrEmpty(oQuery.PrimaryColumn))
					{
						standardQuery.PrimaryColumn = oQuery.PrimaryColumn;
					}
					if (!string.IsNullOrEmpty(oQuery.Query))
					{
						standardQuery.Query = oQuery.Query;
						bGlobalReport = true;
					}
				}
			}
			else if (queryGenerator2.IsClosedCompanyReport(objRec))
			{
				standardQuery.Query = GetCurrentYearQuery(objRec, objDb, m_iCompanyId, queryGenerator2, sUniqueId);
			}
			else if (m_bClosed)
			{
				switch ((FocusReport)objRec.ReportId)
				{
				case FocusReport.VendorListingofOutstandingBills:
				case FocusReport.VendorStatements:
				case FocusReport.VendorDueDateAnalysis:
				case FocusReport.VendorAgeingDetailsBillwise:
				case FocusReport.VendorDetailAgeingByDueDate:
				case FocusReport.VendorOverdueAnalysis:
				case FocusReport.CustomerListingofOutstandingBills:
				case FocusReport.CustomerStatements:
				case FocusReport.CustomerDueDateAnalysis:
				case FocusReport.CustomerAgeingDetailsBillwise:
				case FocusReport.CustomerDetailAgeingByDueDate:
				case FocusReport.CustomerOverdueAnalysis:
					text = string.Empty;
					for (i = 0; i <= m_iYearId; i++)
					{
						queryGenerator2.Suffix = $"_{i}";
						if (i != m_iYearId)
						{
							flag = true;
							m_strPrevYearSuffix = $"_{i}";
						}
						if (i > 0)
						{
							text += " UNION --ALL \r\n                                                ";
							if (i == m_iYearId)
							{
								flag = false;
							}
						}
						text += queryGenerator2.GetQueryFromReportId(ref objRec, objDb, m_iCompanyId, ref oQuery, sUniqueId, flag);
					}
					standardQuery.Query = text;
					break;
				case FocusReport.BankReconciliationStatement:
					text = string.Empty;
					for (i = m_iYearId; i >= 0; i--)
					{
						if (i != m_iYearId)
						{
							flag = true;
							text += " UNION ";
						}
						text += queryGenerator2.GetQueryFromReportId(ref objRec, objDb, m_iCompanyId, ref oQuery, sUniqueId, flag);
					}
					if (flag)
					{
						text = text.Insert(0, "SELECT * FROM(");
						text += ")Temp ";
					}
					standardQuery.Query = text;
					break;
				case FocusReport.VirtualStockAnalysis:
				case FocusReport.StockValuation:
				case FocusReport.StockAnalysisbyBatch:
				case FocusReport.StockAnalysisbyRMA:
				case FocusReport.StockBalanceByProduct:
				case FocusReport.StockBalanceByBins:
				case FocusReport.StockBalanceByProductByBins:
				case FocusReport.ExpiredStockByBins:
				case FocusReport.AgeingOfPendingDocument:
				case FocusReport.AgeingOfPendingDocumentByDueDate:
				case FocusReport.LinkChainAnalysis:
				case FocusReport.StockBalanceByWarehouse:
					standardQuery.Query = GetCurrentYearQuery(objRec, objDb, m_iCompanyId, queryGenerator2, sUniqueId);
					break;
				case FocusReport.ListingOfDocument:
				case FocusReport.ListingOfDocumentByDueDate:
				{
					text = string.Empty;
					object inputObject = FConvert.GetInputObject(objRec.Inputs, 7);
					array = ((inputObject != null && inputObject.GetType() == typeof(ComboData[])) ? ((ComboData[])inputObject) : new ComboData[1]
					{
						new ComboData(objRec.Code, objRec.CodeName)
					});
					if (array.Length > 1)
					{
						for (i = 0; i < array.Length; i++)
						{
							if (i > 0)
							{
								text += " UNION ALL ";
							}
							objRec.Code = array[i].ID;
							objRec.CodeName = array[i].Name;
							text += queryGenerator2.GetQueryFromReportId(ref objRec, objDb, m_iCompanyId, ref oQuery, sUniqueId, flag);
						}
						standardQuery.Query = text;
					}
					else
					{
						objRec.Code = array[0].ID;
						objRec.CodeName = array[0].Name;
						standardQuery.Query = GetCurrentYearQuery(objRec, objDb, m_iCompanyId, queryGenerator2, sUniqueId);
					}
					break;
				}
				default:
					standardQuery.Query = queryGenerator2.GetQueryFromReportId(ref objRec, objDb, m_iCompanyId, ref oQuery, sUniqueId);
					break;
				}
				if (!string.IsNullOrEmpty(text))
				{
					standardQuery.Query = text;
				}
				else if (oQuery != null)
				{
					if (!string.IsNullOrEmpty(oQuery.PrimaryColumn))
					{
						standardQuery.PrimaryColumn = oQuery.PrimaryColumn;
					}
					if (!string.IsNullOrEmpty(oQuery.Query))
					{
						standardQuery.Query = oQuery.Query;
						bGlobalReport = true;
					}
				}
			}
			else if (objRec.ReportId == 601 || objRec.ReportId == 602)
			{
				text = string.Empty;
				object inputObject2 = FConvert.GetInputObject(objRec.Inputs, 7);
				array = ((inputObject2 != null && inputObject2.GetType() == typeof(ComboData[])) ? ((ComboData[])inputObject2) : new ComboData[1]
				{
					new ComboData(objRec.Code, objRec.CodeName)
				});
				for (i = 0; i < array.Length; i++)
				{
					if (i > 0)
					{
						text += " UNION ALL ";
					}
					objRec.Code = array[i].ID;
					objRec.CodeName = array[i].Name;
					text += queryGenerator2.GetQueryFromReportId(ref objRec, objDb, m_iCompanyId, ref oQuery, sUniqueId, flag);
				}
				standardQuery.Query = text;
			}
			else
			{
				text = string.Empty;
				text = queryGenerator2.GetQueryFromReportId(ref objRec, objDb, m_iCompanyId, ref oQuery, sUniqueId);
				if (!string.IsNullOrEmpty(text))
				{
					standardQuery.Query = text;
				}
				else if (oQuery != null)
				{
					if (!string.IsNullOrEmpty(oQuery.PrimaryColumn))
					{
						standardQuery.PrimaryColumn = oQuery.PrimaryColumn;
					}
					if (!string.IsNullOrEmpty(oQuery.Query))
					{
						standardQuery.Query = oQuery.Query;
						bGlobalReport = true;
					}
				}
			}
			if (string.IsNullOrEmpty(standardQuery.PrimaryColumn))
			{
				standardQuery.PrimaryColumn = GetOrderBy(objRec);
			}
			if (string.IsNullOrEmpty(standardQuery.PrimaryColumn))
			{
				if (objRec.ReportId == 663 || objRec.ReportId == 758 || objRec.ReportId == 759 || objRec.ReportId == 667 || objRec.ReportId == 668 || objRec.ReportId == 706)
				{
					standardQuery.PrimaryColumn = oQuery.PrimaryColumn;
				}
				else if (objRec.ReportId == 601)
				{
					if (FConvert.GetYearId(m_iCompanyId) > 0 && array != null && array.Length <= 1)
					{
						standardQuery.PrimaryColumn = string.Format("tCore_LinksOb{0}.iLinkId,tCore_LinksOb{0}.iRefId,bBase Desc", m_strSuffix);
					}
					else
					{
						standardQuery.PrimaryColumn = string.Format("tCore_Links{0}.iLinkId,tCore_Links{0}.iRefId,bBase Desc", m_strSuffix);
					}
				}
				else
				{
					standardQuery.PrimaryColumn = GetPrimaryColumn(objRec, m_strSuffix, objDb, m_iCompanyId, ref bAddPagingQuery, ref strViewName, standardQuery.Query);
				}
			}
		}
		standardQuery.PrimaryColumn = get_customSorting(objRec, standardQuery.PrimaryColumn, ref i);
		return standardQuery;
	}

	private void UpdateReportId(Database objDb, bool bFinalReport, ref RepRecord objRec, ref DataSourceType oBaseDatasourceType)
	{
		if (objRec.SourceType != DataSourceType.Reports)
		{
			return;
		}
		string text = string.Format("SELECT ISNULL(iVoucherType,0)[LinkId] FROM cCore_ReportTransactionSet{0} WITH (READUNCOMMITTED)\r\n                JOIN cCore_Reports{0} WITH (READUNCOMMITTED) ON cCore_ReportTransactionSet{0}.iVoucherType=cCore_Reports{0}.iReportId\r\n                WHERE cCore_ReportTransactionSet{0}.iReportId={1}", m_strSuffix, objRec.ReportId);
		uint num = Convert.ToUInt32(objDb.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
		if (num == 0)
		{
			return;
		}
		objRec.ReportId = num;
		if (objRec.Code == 0)
		{
			RDDefault rDDefault = new RDDefault();
			objRec.Code = rDDefault.GetMasterTypeId(objRec.ReportId);
		}
		bool flag = false;
		if (objRec.ReportCustomize != null && objRec.ReportCustomize.Layout != null && objRec.ReportCustomize.Layout.ExtraValues != null)
		{
			for (int i = 0; i < objRec.ReportCustomize.Layout.ExtraValues.Length; i++)
			{
				if (objRec.ReportCustomize.Layout.ExtraValues[i].ID == 3 && FConvert.IsNumeric(Convert.ToString(objRec.ReportCustomize.Layout.ExtraValues[i].Value)) && Convert.ToInt32(objRec.ReportCustomize.Layout.ExtraValues[i].Value) > 0)
				{
					num = Convert.ToUInt32(objRec.ReportCustomize.Layout.ExtraValues[i].Value);
					flag = true;
					break;
				}
			}
		}
		if (!flag)
		{
			text = string.Format("SELECT iLayoutId FROM cCore_ReportLayouts{0} WITH (READUNCOMMITTED)\r\n                        WHERE iReportId = {1} ORDER BY iFlag DESC", m_strSuffix, num, GetFlagValue(bDefault: true, bLandscape: false, objRec.ReportCustomize.Layout.ColumnHeadingAlignment));
			num = Convert.ToUInt32(objDb.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
		}
		if (num != 0)
		{
			objRec.LayoutId = (int)num;
			text = $"SELECT iSourceType FROM cCore_Reports{m_strSuffix} WHERE iReportId = {objRec.ReportId}";
			oBaseDatasourceType = (DataSourceType)Convert.ToInt32(objDb.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
		}
	}

	private string get_customSorting(RepRecord objRec, string strSortBy, ref int iIndex)
	{
		int num = 0;
		int num2 = 0;
		if ((objRec.ColumnSort != null && objRec.ColumnSort.OrderId > 0) || (objRec.CustomSorts != null && objRec.CustomSorts.Length != 0))
		{
			if (objRec.CustomSorts != null && objRec.CustomSorts.Length != 0)
			{
				List<string> list = new List<string>();
				for (num2 = 0; num2 < objRec.CustomSorts.Length; num2++)
				{
					for (num = 0; num < objRec.Columns.Length; num++)
					{
						if (objRec.Columns[num].ID == objRec.CustomSorts[num2].OrderId)
						{
							iIndex = num + 1;
							list.Add(string.Format("{0} {1}", num + ((objRec.SourceType != DataSourceType.Query) ? 1 : 0), objRec.CustomSorts[num2].IsAscending ? "ASC" : "DESC"));
							break;
						}
					}
				}
				strSortBy = string.Join(",", list);
			}
			else if (objRec.Module == Module.None && (byte)objRec.SubReportId == 1 && objRec.ColumnSort.OrderId == 2)
			{
				strSortBy = string.Format("len(tCore_Header{0}.sVoucherNo) {1}, tCore_Header{0}.sVoucherNo {1}", m_strSuffix, objRec.ColumnSort.IsAscending ? "ASC" : "DESC");
			}
			else
			{
				for (num = 0; num < objRec.Columns.Length; num++)
				{
					if (objRec.Columns[num].ID != objRec.ColumnSort.OrderId)
					{
						continue;
					}
					if (objRec.Columns[num].ID == 1 && objRec.SourceType != DataSourceType.Query && objRec.Module != Module.None && objRec.Module != Module.CoreMasters && IsDocNoSorting(objRec.ReportId, objRec.Inputs))
					{
						switch ((FocusReport)objRec.ReportId)
						{
						case FocusReport.TransactionAuthorizationReport:
							strSortBy = string.Format("len(sVoucherNo) {1}, sVoucherNo {1}", m_strSuffix, objRec.ColumnSort.IsAscending ? "ASC" : "DESC");
							break;
						case FocusReport.BankReconciliationStatement:
							strSortBy = string.Format("len(TempTable.Voucher) {1}, TempTable.Voucher {1}", m_strSuffix, objRec.ColumnSort.IsAscending ? "ASC" : "DESC");
							break;
						case FocusReport.DayBook:
						case FocusReport.EntryJournal:
							strSortBy = string.Format("len(Voucher) {1}, Voucher {1}", m_strSuffix, objRec.ColumnSort.IsAscending ? "ASC" : "DESC");
							break;
						case FocusReport.AuditTrnasactions:
						case FocusReport.ChequeBookRegisterReport:
						case FocusReport.AuditMasters:
						case FocusReport.AuditPricebook:
							strSortBy = string.Format("{0} {1}", num + 1, objRec.ColumnSort.IsAscending ? "ASC" : "DESC");
							break;
						case FocusReport.CreditLimitAuthorizationReport:
							strSortBy = string.Format("len(sVoucherNo) {1}, sVoucherNo {1}", m_strSuffix, objRec.ColumnSort.IsAscending ? "ASC" : "DESC");
							break;
						default:
							strSortBy = string.Format("len(tCore_Header{0}.sVoucherNo) {1}, tCore_Header{0}.sVoucherNo {1}", m_strSuffix, objRec.ColumnSort.IsAscending ? "ASC" : "DESC");
							break;
						}
					}
					else
					{
						if (!string.IsNullOrEmpty(objRec.ColumnSort.ColumnName) && objRec.Columns[num].Name.Replace("Report Specific.", "") != objRec.ColumnSort.ColumnName)
						{
							continue;
						}
						strSortBy = string.Format("{0} {1}", num + ((objRec.SourceType != DataSourceType.Query) ? 1 : 0), objRec.ColumnSort.IsAscending ? "ASC" : "DESC");
					}
					iIndex = num + 1;
					break;
				}
			}
			num = new RDDefault().GetSpecialSortableColumn(objRec.ReportId);
			if (num > 0 && strSortBy.Length > 0 && !strSortBy.Contains($"{num} "))
			{
				strSortBy = $"{num}, {strSortBy}";
			}
			if (!string.IsNullOrEmpty(strSortBy) && objRec.Module == Module.None && objRec.ReportCustomize != null && objRec.ReportCustomize.DelayFetch)
			{
				strSortBy = ((objRec.OffSetRows <= 0) ? $"{strSortBy} OFFSET {objRec.RowsPerPage * objRec.CurrentPage} ROWS FETCH NEXT {objRec.RowsPerPage} ROWS ONLY" : $"{strSortBy} OFFSET {objRec.OffSetRows} ROWS");
			}
		}
		return strSortBy;
	}

