	private string GetCurrentYearQuery(RepRecord objRec, Database objDb, int iCompId, QueryGenerator objQueryEngine, string sUniqueId)
	{
		string text = string.Empty;
		bool bPreviousYear = false;
		string suffix = objQueryEngine.Suffix;
		string text2 = null;
		string text3 = null;
		bool flag = true;
		StandardQuery oQuery = null;
		int yearId = FConvert.GetYearId(iCompId);
		int num = 0;
		int num2 = yearId;
		int num3 = 0;
		while (num3 <= FConvert.GetYearId(iCompId))
		{
			objQueryEngine.Suffix = $"_{num3}";
			if (num3 != FConvert.GetYearId(iCompId))
			{
				bPreviousYear = true;
			}
			if (objRec.Module == Module.None && objRec.SubReportId == 3)
			{
				objQueryEngine.Suffix = $"_{num2}";
				if (num == 1)
				{
					bPreviousYear = false;
				}
				else if (num == 2)
				{
					break;
				}
				num++;
			}
			if (objRec.ReportId == 601)
			{
				objQueryEngine.Suffix = $"_{num2 - 1}";
				if (num == 1)
				{
					objQueryEngine.Suffix = $"_{yearId}";
					bPreviousYear = false;
				}
				else if (num == 2)
				{
					break;
				}
				num++;
			}
			if (num3 > 0)
			{
				if (text != "")
				{
					text = ((objRec.ReportId != 578) ? (text + " UNION ALL ") : (text + " UNION "));
				}
				if (num3 == FConvert.GetYearId(iCompId))
				{
					bPreviousYear = false;
				}
				flag = true;
			}
			string queryFromReportId = objQueryEngine.GetQueryFromReportId(ref objRec, objDb, iCompId, ref oQuery, sUniqueId, bPreviousYear);
			text += queryFromReportId;
			if (num3 > 0 && queryFromReportId == "")
			{
				text = text.Remove(text.Length - 11, 10);
			}
			if (string.IsNullOrEmpty(text2))
			{
				text2 = objQueryEngine.m_strExtraColumnsAlias;
			}
			if (string.IsNullOrEmpty(text3))
			{
				text3 = objQueryEngine.m_strExtraColumnsWithFormula;
			}
			num3++;
			num2--;
		}
		objQueryEngine.Suffix = suffix;
		if (flag)
		{
			text = objQueryEngine.UnionSubQuery(objRec, text, text2, text3);
		}
		return text;
	}

