		list = new List<int>();
		if (objRec.SourceType != DataSourceType.Reports && objRec.ReportCustomize != null && objRec.ReportCustomize.Groupings != null)
		{
			for (num = 0; num < objRec.ReportCustomize.Groupings.Length; num++)
			{
				for (num2 = 2; num2 < objRec.Columns.Length; num2++)
				{
					num4 = objRec.ReportCustomize.Groupings[num].FieldId;
					if (objRec.Columns[num2].Tag != null && (MasterDataType)objRec.Columns[num2].Tag == MasterDataType.Date)
					{
						RDCommon.GetSubFieldId(ref num4);
					}
					if (objRec.ReportCustomize.Groupings[num].GroupingType != _GroupingType.Row || num4 != objRec.Columns[num2].ID)
					{
						continue;
					}
					for (num3 = 0; num3 < list.Count && list[num3] != num2; num3++)
					{
					}
					if (num3 >= list.Count)
					{
						if (text.Length > 0)
						{
