					list.Add(num2);
					break;
				}
			}
		}
		return text;
	}

	private string GetPrimaryColumn(RepRecord objRec, string strSuffix, Database objDb, int iCompId, ref bool bAddPagingQuery, ref string strViewName, string strQuery)
	{
		string text = null;
		string text2 = null;
		if (objRec.Module == Module.None)
		{
			switch ((CustomizeColumn)(byte)objRec.SubReportId)
			{
			case CustomizeColumn.HomePage:
				text = ((FConvert.GetYearId(iCompId) <= 0) ? string.Format("tCore_Header{0}.iDate DESC,tCore_Header{0}.iCreatedTime DESC", strSuffix) : "2 DESC, 8 DESC");
				break;
			case CustomizeColumn.LinkVoucher:
				text = "2 DESC, 8 DESC, 1 ASC";
				break;
			case CustomizeColumn.LinkPopupScreen:
				text = string.Format("tCore_Header{0}.iDate, tCore_Header{0}.iHeaderId", strSuffix);
				if (0 == 0)
				{
					text += $", tCore_Data{strSuffix}.iSerialNo";
				}
				break;
			case CustomizeColumn.NormalCustomize:
			case CustomizeColumn.CompactCustomize:
				text = "iDate desc";
				break;
			case CustomizeColumn.PendingLinkStatus:
				text = string.Empty;
				break;
			}
		}
		else
		{
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.UserRightsReport:
				text = " iUserId, [MenuName]";
				break;
			case FocusReport.RoleRightsReport:
				text = " sRoleName, replace(sMenuText, '_', '')";
				break;
			case FocusReport.ProfileRightsReport:
				text = " sProfileName, replace(sMenuText, '_', '')";
				break;
			case FocusReport.LinkChainAnalysis:
				text = "[iDate-b],[iDate0],[DocNo-b]";
				break;
			case FocusReport.AdvanceCashFlow:
				text = "iCashFlowSegmentType";
				break;
			case FocusReport.LogBook:
				text = "sLoginName,iLoginDate DESC,iLoginTime DESC";
				break;
			case FocusReport.SalesGroupedByCustomer:
			case FocusReport.PurchasesGroupedByVendor:
				text = ((!_focus.company(iCompId).isModuleImplemented(ModulesImplemented.SubLedger)) ? "BookNo.sName" : "mCore_SubLedger.sName");
				break;
			case FocusReport.VATSalesByCustomer:
				text = "Code.sName";
				break;
			case FocusReport.MonthlySales:
				text = string.Format("dbo.GetDatePart('m', iDate)", strSuffix);
				break;
			case FocusReport.TopCustomers:
				text = $"SUM(tCore_Data{strSuffix}.mAmount2)";
				break;
			case FocusReport.SalesGroupedByProduct:
			case FocusReport.PurchasesGroupedByProduct:
				text = "vrCore_Product.sName";
				break;
			case FocusReport.SalesGroupedByDepartment:
			case FocusReport.PurchasesGroupedByDepartment:
				text = $"{_focus.company(m_iCompanyId).faTagName}.sName";
				break;
			case FocusReport.Ledger:
			case FocusReport.SubLedger:
			{
				int iDisplayTotal = 0;
				int i = new QueryGenerator
				{
					Suffix = m_strSuffix,
					m_iCompId = m_iCompanyId,
					DefaultFaTag = DefaultFaTag,
					AlternateLanguage = AlternateLanguage
				}.IsAccountPropertyEnable(objRec.Inputs, objRec.Masters, (FocusReport)objRec.ReportId, objRec.Code, ref iDisplayTotal);
				if (objRec.ReportId == 500 && FConvert.GetInputValue(objRec.Inputs, -12) == 1)
				{
					i = 2;
					iDisplayTotal = 0;
					text = "ATree.iSeq,";
				}
				if (_focus.company(iCompId).isModuleImplemented(ModulesImplemented.SubLedger))
				{
					text += ((i > 0) ? "2,[SubLedgerName]," : "2,vrCore_SubLedger.sName,");
				}
				switch (iDisplayTotal)
				{
				case 2:
					text = "dbo.GetDatePart('y',iDate),dbo.GetDatePart('m',iDate)";
					break;
				case 3:
				case 4:
					text = "iDate";
					break;
				default:
					text = FConvert.GetInputValue(objRec.Inputs, 5) switch
					{
						1 => text + "[Currency],iDate,1", 
						2 => text + "iDate,[Currency],1", 
						_ => (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.Print, 45) <= 0) ? (i switch
						{
							0 => text + $"3,tCore_Data{strSuffix}.iHeaderId,1", 
							3 => "3,4", 
							_ => text + "3,1", 
						}) : (text + "3,6"), 
					};
					break;
				}
				break;
			}
			case FocusReport.LedgerDetail:
			{
				int i = FConvert.GetInputValue(objRec.Inputs, 1);
				text = ((i != 1 && i != 3) ? string.Format("AccTree.iSeq,InnerTable.iMasterId,tCore_Header{0}.iDate,cCore_Vouchers{0}.sAbbr,LEN(tCore_Header{0}.sVoucherNo),tCore_Header{0}.sVoucherNo", strSuffix) : $"AccTree.iSeq,InnerTable.iMasterId,tCore_Header{strSuffix}.iDate,CASE WHEN (tCore_Header{strSuffix}.iVoucherClass) = {7168} OR (tCore_Header{strSuffix}.iVoucherClass) = {5888} THEN 1 ELSE 0 END");
				if (objRec.ReportCustomize.DelayFetch)
				{
					text += $",tCore_Data{strSuffix}.iBodyId";
				}
				break;
			}
			case FocusReport.VirtualBankLedger:
				text = string.Format("InnerTable.iMasterId,CASE WHEN tCore_Header{0}.iVoucherClass IN(7168,5888) THEN tCore_Data{0}.iDueDate ELSE tCore_Header{0}.iDate END", strSuffix);
				break;
			case FocusReport.BankReconciliationStatement:
				text = "iDate,iHeaderId";
				break;
			case FocusReport.SummaryPurchaseRegister:
				text = "iDate,tCore_Data" + strSuffix + ".iHeaderId";
				break;
			case FocusReport.PeakandLowBalanceAmount:
				text = "Account";
				break;
			case FocusReport.CashBook:
			case FocusReport.BankBook:
			case FocusReport.PettyCashBook:
			case FocusReport.DayBook:
				text = ((_focus.company(iCompId).getPreferenceValue(PreferenceCategories.Print, 45) <= 0) ? "iDate,Voucher,iHeaderId" : "2,5");
				break;
			case FocusReport.EntryJournalDetailReport:
				text = string.Format("tCore_Header{0}.iDate,tCore_Data{0}.iBodyId,CASE WHEN InnerTable.mAmount2 < 0 THEN 1 ELSE 0 END DESC", strSuffix);
				break;
			case FocusReport.JournalEntryRegister:
				text = string.Format("tCore_Header{0}.iDate,tCore_Header{0}.iCreatedTime,tCore_Data{0}.iBodyId", strSuffix);
				break;
			case FocusReport.EntryJournal:
				text = "iDate,right\r\n                         (\r\n\t                         replicatE\r\n\t                         (\r\n\t\t                        '0', 60-LEN(Voucher)\r\n\t                        )\r\n\t                        +Voucher,\r\n\t                        60\r\n                         )";
				break;
			case FocusReport.IncomeExpenseTrend:
				text = string.Format("dbo.GetDatePart('y', iDate),dbo.GetDatePart('m', iDate)", strSuffix);
				break;
			case FocusReport.MonthlyMasterDetails:
