			case FocusReport.BOMExplosionDetailsReport:
				text = "";
				break;
			case FocusReport.BOMListReport:
				text = "";
				break;
			case FocusReport.PIODetailsReport:
				text = "";
				break;
			case FocusReport.BOMProcessReport:
				text = " iProcessId,RowId ";
				break;
			case FocusReport.ChequeBookRegisterReport:
				text = $"tCore_Header{strSuffix}.iDate";
				break;
			case FocusReport.CreditLimitAuthorizationReport:
			{
				text = " iDate,iHeaderId,iCrLmtAuthId";
				int creditLimitMaxLevel = new QueryGenerator().GetCreditLimitMaxLevel(iCompId);
				for (int i = 1; i <= creditLimitMaxLevel; i++)
				{
					text += $",Status{i} DESC";
				}
				break;
			}
			case FocusReport.AuditMasters:
				text = ((_focus.company(iCompId).getPreferenceValue(PreferenceCategories.Misc, 51) <= 0) ? "tCore_MasterAuditLog.iMasterTypeId,tCore_MasterAuditLog.iMasterId,tCore_MasterAuditLog.iAuditId" : " iMasterId ");
				break;
			case FocusReport.AuditPricebook:
				if (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.Misc, 51) > 0)
				{
					text = " iModifiedDate DESC ";
				}
				break;
			case FocusReport.AuthorizationMatrix:
				if (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.Misc, 51) > 0)
				{
					text = " a.iAuthorizationId, a.iAuthorizationDetailId ";
				}
				break;
			case FocusReport.AuditTrailAuthorization:
				if (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.Misc, 51) > 0)
				{
					text = " iAuthorizationId ";
				}
				break;
			case FocusReport.AverageDaysToPayReport:
				text = "3 DESC";
				break;
			case FocusReport.UserAuditReport:
				text = " CUser.sLoginName, tSec_Users_LogHeader.iModifiedDate";
				break;
			case FocusReport.BackupSchedulerAuditReport:
				text = " ISNULL(sUSerName, sLoginName), a.iModifiedDate, a.iModifiedTime";
				break;
			case FocusReport.PricebookAuthorizationReport:
				text = " iSeqNo ";
				break;
			case FocusReport.WMSAdvanceBillingReport:
				text = " BillSummary.iBillDate Desc ";
				break;
			default:
				text = ((objRec.Module != Module.CoreMasters) ? string.Format("tCore_Header{0}.iDate,tCore_Header{0}.iCreatedTime", strSuffix) : string.Format("{0}.iParentId, {0}.iMasterId", strViewName));
				break;
			case FocusReport.VATMonthlyReport:
			case FocusReport.UnitConversion:
			case FocusReport.ProductionSummary:
			case FocusReport.WorkInProcess:
			case FocusReport.WorkInProcessSummary:
			case FocusReport.ProductwiseWorkInProcess:
			case FocusReport.ProductionAnalysisByProductionBatch:
			case FocusReport.ConsumptionSummary:
			case FocusReport.MRPReservationDetailsReport:
			case FocusReport.AuditBackup:
			case FocusReport.ScheduledReport:
			case FocusReport.AuditTrailWorkflow:
			case FocusReport.LockUnlockDatabaseAuditReport:
			case FocusReport.AuditTransactionDetail:
			case FocusReport.MembershipRecruitmentByDate:
			case FocusReport.POSRestDailySales:
				break;
			}
		}
		if (objRec.ReportCustomize != null && objRec.ReportCustomize.DelayFetch && !string.IsNullOrEmpty(text))
		{
			text = ((objRec.OffSetRows <= 0) ? $"{text} OFFSET {objRec.RowsPerPage * objRec.CurrentPage} ROWS FETCH NEXT {objRec.RowsPerPage} ROWS ONLY" : $"{text} OFFSET {objRec.OffSetRows} ROWS");
		}
		return text;
	}

	public IdValuePair[] LoadDocumentOrders(Database objDB, int iComp)
	{
		string text = null;
		IDataReader dataReader = null;
		List<IdValuePair> list = new List<IdValuePair>();
		try
		{
			if (objDB == null)
			{
				objDB = DatabaseWrapper.GetDatabase2(iComp);
			}
			text = $"SELECT iSequence, iVoucherType FROM tCore_DocumentOrder{FConvert.GetSuffix(iComp)} order by iSequence";
			dataReader = objDB.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				list.Add(new IdValuePair(Convert.ToInt32(dataReader["iSequence"]), Convert.ToInt32(dataReader["iVoucherType"])));
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
			list.Clear();
		}
		return list.ToArray();
	}

	private string GetAccountInGroup(int iAccountGroup, Database objDb, bool bLoadAllHierarchy = false)
	{
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		string text = string.Empty;
		string empty = string.Empty;
		try
		{
			string arg = ((!bLoadAllHierarchy) ? "WHERE bGroup = 0" : string.Empty);
			empty = $"WITH RecursionCTE (iMasterId, iParentId, bGroup)  AS  \r\n                                (   SELECT iMasterId, iParentId, bGroup\r\n                                    FROM vmCore_Account \r\n                                    WHERE iMasterId = {iAccountGroup} AND iTreeId = 0\r\n                                    UNION ALL  \r\n                                    SELECT R1.iMasterId, R1.iParentId, R1.bGroup\r\n                                    FROM vmCore_Account AS R1 \r\n                                    JOIN RecursionCTE AS R2 ON R1.iParentId = R2.iMasterId\r\n                                )SELECT iMasterId  FROM RecursionCTE {arg} ";
			dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			dataReader = objDb.ExecuteReader(dbCommand);
			while (dataReader.Read())
			{
				text += string.Format("{0}{1}", (text.Length > 0) ? "," : "", dataReader[0]);
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
		}
		if (string.IsNullOrEmpty(text))
		{
			text = $"{iAccountGroup}";
		}
		return text;
	}

	public RDReport()
	{
		if (m_arrReportRecordSet == null)
		{
			m_arrReportRecordSet = new List<ReportRecordSet>();
		}
		if (m_arrAnalyzeData == null)
		{
			m_arrAnalyzeData = new List<AnalyzeData>();
		}
		if (m_arrReportPageSet == null)
		{
			m_arrReportPageSet = new List<ReportPageSet>();
		}
	}

	public bool EndOfReport(string objKey, int iCompId)
	{
		ReportRecordSet reportRecordSet = new ReportRecordSet();
		reportRecordSet.KeyValue = objKey;
		return RemoveKey(reportRecordSet, iCompId);
	}

	public bool FlushReportPageData(string objKey, string strSession, int iCompId)
	{
		return RemovePageKey(new ReportPageSet(objKey, strSession));
	}

	public bool EndAllReports(string sSessionId, int iCompId)
	{
		int num = 0;
		if (m_arrReportRecordSet != null)
		{
			for (num = 0; num < m_arrReportRecordSet.Count; num++)
			{
				if (m_arrReportRecordSet[num].SessionId == sSessionId)
				{
					string keyValue = m_arrReportRecordSet[num].KeyValue;
					if (m_arrReportRecordSet[num].Reader != null && !m_arrReportRecordSet[num].Reader.IsClosed)
					{
						m_arrReportRecordSet[num].Reader.Close();
					}
					m_arrReportRecordSet[num].BalanceOutput = null;
					m_arrReportRecordSet[num].Columns = null;
					m_arrReportRecordSet[num].ExtraColumns = null;
					m_arrReportRecordSet[num].FieldCount = 0;
					m_arrReportRecordSet[num].KeyValue = null;
					m_arrReportRecordSet[num].Reader = null;
					if (m_arrReportRecordSet[num].SelectedMasters != null)
					{
						m_arrReportRecordSet[num].SelectedMasters.Clear();
					}
					m_arrReportRecordSet[num].SelectedMasters = null;
					m_arrReportRecordSet[num].SessionId = null;
					redis.GetDatabase().KeyDelete(keyValue);
					m_arrReportRecordSet.RemoveAt(num);
					num--;
				}
			}
		}
		if (m_arrAnalyzeData != null)
		{
			for (num = 0; num < m_arrAnalyzeData.Count; num++)
			{
				if (m_arrAnalyzeData[num].SessionId == sSessionId)
				{
					m_arrAnalyzeData[num].ColumnGrouping = null;
					m_arrAnalyzeData[num].ColumnMeasures = null;
					m_arrAnalyzeData[num].Data = null;
					m_arrAnalyzeData[num].DataColumns = null;
					m_arrAnalyzeData[num].DontShowTotalColumnMeasures = null;
					m_arrAnalyzeData[num].ExtraMasterColumns = null;
					m_arrAnalyzeData[num].KeyValue = null;
					m_arrAnalyzeData[num].OrderBy = null;
					m_arrAnalyzeData[num].SessionId = null;
					m_arrAnalyzeData[num].SortedIndex = null;
					m_arrAnalyzeData.RemoveAt(num);
					num--;
				}
			}
		}
		if (m_arrReportPageSet != null)
		{
			for (num = 0; num < m_arrReportPageSet.Count; num++)
			{
				if (m_arrReportPageSet[num].SessionId == sSessionId)
				{
					m_arrReportPageSet[num].CloseReader();
					m_arrReportPageSet[num].Columns = null;
					m_arrReportPageSet[num].ExtraColumns = null;
					m_arrReportPageSet[num].KeyValue = null;
					m_arrReportPageSet[num].SessionId = null;
					m_arrReportPageSet.RemoveAt(num);
					num--;
				}
			}
		}
		IEnumerable<RedisKey> enumerable = redis.GetServer(FConvert.GetRedisServer()).Keys(-1, default, 250, 0L);
		IDatabase database = redis.GetDatabase();
		foreach (RedisKey item in enumerable)
		{
			if (item.ToString().StartsWith("Session:"))
			{
				database.KeyDelete(item);
			}
		}
		_focus.company(iCompId).clearUser();
		return true;
	}

	public ReportLogs[] GetAllOpenReports(int iCompId)
	{
		List<ReportLogs> list = new List<ReportLogs>();
		if (m_arrReportRecordSet != null)
		{
			ReportRecordSet[] array = (from p in m_arrReportRecordSet
				where p.CompanyId == iCompId && !string.IsNullOrEmpty(p.ReportName)
				orderby p.StartDate
				select p).ToArray();
			for (int num = 0; num < array.Length; num++)
			{
				list.Add(new ReportLogs
				{
					UniqueId = array[num].KeyValue,
					ReportName = array[num].ReportName,
					SessionId = array[num].SessionId,
					LoginTime = new DateTime(array[num].StartDate).ToString(),
					OpenSince = new DateTime(array[num].StartDate).ToString()
				});
			}
		}
		return list.ToArray();
	}

	public IdNamePair[] GetAllReports()
	{
		byte[] array = null;
		List<IdNamePair> list = null;
		IDatabase database = redis.GetDatabase();
		IEnumerable<RedisKey> enumerable = redis.GetServer(FConvert.GetRedisServer()).Keys(-1, default, 250, 0L);
		list = new List<IdNamePair>();
		foreach (RedisKey item in enumerable)
		{
			if (item.ToString().StartsWith("Session:"))
			{
				array = database.StringGet(item);
				if (array != null)
				{
					list.Add((IdNamePair)FConvert.ByteArrayToObject(array));
				}
			}
		}
		return list.ToArray();
	}

