	private void ContainsKey(ref ReportRecordSet objSet)
	{
		int num = 0;
		if (m_arrReportRecordSet == null)
		{
			return;
		}
		lock (m_arrReportRecordSet)
		{
			for (num = 0; num < m_arrReportRecordSet.Count; num++)
			{
				if (m_arrReportRecordSet[num].KeyValue == objSet.KeyValue)
				{
					objSet = m_arrReportRecordSet[num];
					break;
				}
			}
		}
	}

	private bool IsKeyExist(string sUniqueKey)
	{
		if (m_arrReportRecordSet != null)
		{
			lock (m_arrReportRecordSet)
			{
				for (int i = 0; i < m_arrReportRecordSet.Count; i++)
				{
					if (m_arrReportRecordSet[i].KeyValue == sUniqueKey)
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	private bool RemoveKey(ReportRecordSet objSet, int iCompId)
	{
		int num = 0;
		bool result = false;
		if (m_arrReportRecordSet != null)
		{
			lock (m_arrReportRecordSet)
			{
				for (num = 0; num < m_arrReportRecordSet.Count; num++)
				{
					if (m_arrReportRecordSet[num] == null)
					{
						m_arrReportRecordSet.RemoveAt(num);
					}
					else
					{
						if (!(m_arrReportRecordSet[num].KeyValue == objSet.KeyValue))
						{
							continue;
						}
						_ = m_arrReportRecordSet[num].SessionId;
						string keyValue = m_arrReportRecordSet[num].KeyValue;
						if (m_arrReportRecordSet[num].Reader != null && !m_arrReportRecordSet[num].Reader.IsClosed)
						{
							m_arrReportRecordSet[num].Reader.Close();
						}
						m_arrReportRecordSet[num].BalanceOutput = null;
						if (m_arrReportRecordSet[num].SelectedMasters != null)
						{
							m_arrReportRecordSet[num].SelectedMasters.Clear();
						}
						m_arrReportRecordSet[num].SelectedMasters = null;
						m_arrReportRecordSet[num].SessionId = null;
						m_arrReportRecordSet[num].KeyValue = null;
						m_arrReportRecordSet[num].Reader = null;
						m_arrReportRecordSet[num] = null;
						m_arrReportRecordSet.RemoveAt(num);
						result = true;
						foreach (RedisKey item in redis.GetServer(FConvert.GetRedisServer()).Keys(-1, default, 250, 0L))
						{
							if (item.ToString().StartsWith("Session:") && item.ToString().EndsWith(keyValue))
							{
								redis.GetDatabase().KeyDelete(item);
								break;
							}
						}
						break;
					}
				}
			}
		}
		if (m_arrAnalyzeData != null)
		{
			lock (m_arrAnalyzeData)
			{
				for (num = 0; num < m_arrAnalyzeData.Count; num++)
				{
					if (m_arrAnalyzeData[num].KeyValue == objSet.KeyValue)
					{
						m_arrAnalyzeData[num].ColumnGrouping = null;
						m_arrAnalyzeData[num].ColumnMeasures = null;
						m_arrAnalyzeData[num].Data = null;
						m_arrAnalyzeData[num].DataColumns = null;
						m_arrAnalyzeData[num].DontShowTotalColumnMeasures = null;
						m_arrAnalyzeData[num].ExtraMasterColumns = null;
						m_arrAnalyzeData[num].OrderBy = null;
						m_arrAnalyzeData[num].KeyValue = null;
						m_arrAnalyzeData[num].SortedIndex = null;
						m_arrAnalyzeData[num] = null;
						m_arrAnalyzeData.RemoveAt(num);
						break;
					}
				}
			}
		}
		return result;
	}

	private void ContainsPageKey(ref ReportPageSet objSet)
	{
		if (m_arrReportPageSet == null)
		{
			return;
		}
		for (int i = 0; i < m_arrReportPageSet.Count; i++)
		{
			if (m_arrReportPageSet[i].KeyValue == objSet.KeyValue)
			{
				objSet = m_arrReportPageSet[i];
				break;
			}
		}
	}

	private bool RemovePageKey(ReportPageSet objSet)
	{
		if (m_arrReportPageSet != null)
		{
			for (int i = 0; i < m_arrReportPageSet.Count; i++)
			{
				if (m_arrReportPageSet[i].KeyValue == objSet.KeyValue)
				{
					m_arrReportPageSet[i].CloseReader();
					m_arrReportPageSet.RemoveAt(i);
					return true;
				}
			}
		}
		return false;
	}

