	public Dictionary<string, double>[] PrepareGraphData(RepRecord objRecord, int iCompanyId)
	{
		ReportMatrix reportMatrix = null;
		IdNamePair[] array = null;
		List<LineData> list = new List<LineData>();
		if (objRecord.ReportCustomize == null)
		{
			objRecord.ReportCustomize = LoadReportDesigner(objRecord.ReportId, objRecord.LayoutId, iCompanyId);
		}
		if (objRecord.LayoutId == 0 && objRecord.ReportCustomize != null && objRecord.ReportCustomize.Layout != null)
		{
			objRecord.LayoutId = objRecord.ReportCustomize.Layout.LayoutId;
		}
		do
		{
			objRecord.RowsPerPage = 200;
			if (objRecord.SourceType == DataSourceType.Reports || objRecord.ReportCustomize.ReportType == ReportType.Cubes)
			{
				reportMatrix = GetAnalyzeData(objRecord, iCompanyId);
				objRecord.CurrentPage++;
				objRecord.Outputs = reportMatrix.BalanceValues;
				objRecord.IsStartOfReport = false;
				if (array == null)
				{
					array = reportMatrix.Columns;
				}
			}
			else
			{
				reportMatrix = GetPagewiseData(objRecord, iCompanyId);
			}
			objRecord.UniqueId = reportMatrix.UniqueId;
			objRecord.IsStartOfReport = false;
			if (reportMatrix.ColumnData != null)
			{
				list.AddRange(reportMatrix.ColumnData);
			}
		}
		while (!reportMatrix.EndOfFile);
		if (list.Count > 0)
		{
			reportMatrix.ColumnData = list.ToArray();
		}
		if (array != null && reportMatrix.Columns.Length != array.Length)
		{
			reportMatrix.Columns = array;
		}
		if (reportMatrix != null && reportMatrix.ColumnData != null && reportMatrix.ColumnData.Length != 0)
		{
			return new RDConversion(m_objCalType)
			{
				DecimalInCurrency = ((_focus.company(iCompanyId).currency != null) ? _focus.company(iCompanyId).currency.NoOfDecimal : 2)
			}.PrepareGraphData(objRecord.GraphOption, reportMatrix, objRecord.ReportCustomize.ReportType == ReportType.Cubes);
		}
		return null;
	}

	public CashFlowMatrix GetCashFlowCalendarData(CalRecord oRec, int iCompanyId)
	{
		double num = 0.0;
