				text3 = string.Format(" AND mCore_Account.iMasterId IN({0})", string.Join(",", oRec.SelectedMasters.Select((int p) =>
				{
					int num3 = p;
					return num3.ToString();
				}).ToArray()));
			}
			rDConversion.GetCheckValue(oRec.TransactionSets, 0);
			rDConversion.GetCheckValue(oRec.TransactionSets, 1);
			if (rDConversion.GetCheckValue(oRec.TransactionSets, 2))
			{
				if (!string.IsNullOrEmpty(text2))
				{
					text2 += " OR";
				}
				text2 += $"(\r\n                        (\r\n                            (tCore_Header{suffix}.iDate <= {oRec.EndDate} AND tCore_Data{suffix}.bPdc = 0) OR\r\n                            (tCore_Data{suffix}.iDueDate > {oRec.EndDate} AND tCore_Data{suffix}.bPdc = 1) OR tCore_Data{suffix}.bUpdateFA = 1\r\n\t\t\t\t\t    ) \r\n                        AND (tCore_Header{suffix}.iVoucherClass = {5888})\r\n                    )";
			}
			if (rDConversion.GetCheckValue(oRec.TransactionSets, 3))
			{
				if (!string.IsNullOrEmpty(text2))
				{
					text2 += " OR";
				}
				text2 += $"(\r\n                        (\r\n                            (tCore_Header{suffix}.iDate <= {oRec.EndDate} AND tCore_Data{suffix}.bPdc = 0) OR\r\n                            (tCore_Data{suffix}.iDueDate > {oRec.EndDate} AND tCore_Data{suffix}.bPdc = 1) OR tCore_Data{suffix}.bUpdateFA = 1\r\n\t\t\t\t\t    ) \r\n                        AND (tCore_Header{suffix}.iVoucherClass = {7168})\r\n                    )";
			}
			if (rDConversion.GetCheckValue(oRec.TransactionSets, 7))
			{
				if (!string.IsNullOrEmpty(text2))
				{
					text2 += " OR";
				}
				text2 += $" tCore_Header{suffix}.iVoucherClass = {8704}";
			}
			rDConversion.GetCheckValue(oRec.TransactionSets, 4);
			if (!string.IsNullOrEmpty(text2))
			{
				text2 = " AND (" + text2 + ")";
				if (!text2.Contains("bUpdateFA = 1"))
				{
					text2 = text2 + " AND tCore_Data" + suffix + ".bUpdateFA = 1";
				}
			}
			else
			{
				text2 = " AND tCore_Data" + suffix + ".bUpdateFA = 1";
			}
			text = $"SELECT iMasterId,sName,iDate,SUM([Debit])[Debit], SUM([Credit])[Credit]\r\n                --,CASE \r\n\t              --  WHEN SUM([Debit])+SUM([Credit]) > 0 AND TempTable.iAccountType IN({5},{7}) THEN {1} \r\n\t                --WHEN SUM([Debit])+SUM([Credit]) < 0 AND TempTable.iAccountType IN({6},{7}) THEN {2}\r\n                    --WHEN SUM([Debit])+SUM([Credit]) < 0 AND TempTable.iVoucherType & {65280}  = {2560} THEN {7} \r\n                    --WHEN SUM([Debit])+SUM([Credit]) > 0 AND TempTable.iVoucherType & {65280} = {5632} THEN {6} \r\n                    --WHEN TempTable.iVoucherType & {65280} IN({8704},{3584}) THEN {8} \r\n                    --WHEN SUM([Debit])+SUM([Credit]) > 0 AND TempTable.iVoucherType & {65280} = {5888} AND TempTable.bPdc = 1 THEN {3}\r\n                    --WHEN SUM([Debit])+SUM([Credit]) < 0 AND TempTable.iVoucherType & {65280} = {7168} AND TempTable.bPdc = 1 THEN {4}\r\n                --ELSE \r\n\t                ,0 \r\n                --END \r\n                [SetType]\r\n                FROM \r\n                (\r\n\t                SELECT InnerTable.iMasterId,mCore_Account.sName, tCore_Header{suffix}.iDate, Debit, Credit\r\n                    ,mCore_Account.iAccountType,tCore_Header{suffix}.iVoucherClass[iVoucherType]\r\n                    ,CASE WHEN (tCore_Header{suffix}.iDate <= {oRec.EndDate} AND tCore_Data{suffix}.bPdc = 0) \r\n                        OR (tCore_Data{suffix}.iDueDate > {oRec.EndDate} AND tCore_Data{suffix}.bPdc = 1) THEN 1 ELSE 0 END[bPdc]\r\n\t                FROM \r\n\t                (\r\n\t\t                SELECT tCore_Data{suffix}.iBodyId,iBookNo[iMasterId],\r\n\t\t                CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t\t                CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit\r\n\t\t                FROM tCore_Data{suffix} \r\n\t\t                JOIN tCore_Header{suffix} ON tCore_Data{suffix}.iHeaderId = tCore_Header{suffix}.iHeaderId\r\n                        JOIN mCore_Account ON tCore_Data{suffix}.iCode = mCore_Account.iMasterId  \r\n\t\t                WHERE (mCore_Account.iAccountType = {1} OR mCore_Account.iAccountType = {2})\r\n                        {text3}\r\n\t\t                UNION ALL\r\n\t\t                SELECT tCore_Data{suffix}.iBodyId,iCode[iMasterId],\r\n\t\t                CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n\t\t                CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit\r\n\t\t                FROM tCore_Data{suffix} \r\n\t\t                JOIN tCore_Header{suffix} ON tCore_Data{suffix}.iHeaderId = tCore_Header{suffix}.iHeaderId\r\n                        JOIN mCore_Account ON tCore_Data{suffix}.iBookNo = mCore_Account.iMasterId  \r\n\t\t                WHERE (mCore_Account.iAccountType = {1} OR mCore_Account.iAccountType = {2})\r\n                        {text3}\r\n\t                )InnerTable\r\n\t                JOIN tCore_Data{suffix} ON InnerTable.[iBodyId] = tCore_Data{suffix}.iBodyId\r\n\t                JOIN tCore_Header{suffix} ON tCore_Header{suffix}.iHeaderId = tCore_Data{suffix}.iHeaderId \r\n\t                JOIN cCore_Vouchers{suffix} WITH (READUNCOMMITTED) ON cCore_Vouchers{suffix}.iVoucherType=tCore_Header{suffix}.iVoucherType\r\n\t                JOIN mCore_Account ON InnerTable.[iMasterId] = mCore_Account.iMasterId  \r\n\t                WHERE tCore_Data{suffix}.bSuspendUpdateFA = 0 AND tCore_Header{suffix}.bSuspended = 0 AND tCore_Data{suffix}.iAuthStatus < 2\r\n                    AND tCore_Header{suffix}.iDate BETWEEN {oRec.StartDate} AND {oRec.EndDate}\r\n                    {text2}\r\n                ) TempTable \r\n                GROUP BY [iMasterId],sName,iDate--,TempTable.iAccountType,TempTable.iVoucherType,TempTable.bPdc\r\n                HAVING SUM([Debit]) <> 0 OR SUM([Credit]) <> 0 ORDER BY iMasterId";
			database = DatabaseWrapper.GetDatabase2(iCompanyId, -1, bReplicationServer: true);
			dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			list = new List<CashFlowSetData>();
			while (dataReader.Read())
			{
				cashFlowSetData = new CashFlowSetData();
				cashFlowSetData.Date = Convert.ToInt32(dataReader["iDate"]);
				cashFlowSetData.ID = Convert.ToInt32(dataReader["iMasterId"]);
				cashFlowSetData.Name = Convert.ToString(dataReader["sName"]);
				cashFlowSetData.SetType = (CashFlowSetType)Convert.ToInt32(dataReader["SetType"]);
				num = Convert.ToDouble(dataReader["Debit"]);
				num2 = Convert.ToDouble(dataReader["Credit"]);
				if (num != 0.0 && num2 != 0.0)
				{
					cashFlowSetData.Amount = num2;
					list.Add(cashFlowSetData);
					cashFlowSetData = new CashFlowSetData();
					cashFlowSetData.Date = Convert.ToInt32(dataReader["iDate"]);
					cashFlowSetData.ID = Convert.ToInt32(dataReader["iMasterId"]);
					cashFlowSetData.Name = Convert.ToString(dataReader["sName"]);
					cashFlowSetData.SetType = (CashFlowSetType)Convert.ToInt32(dataReader["SetType"]);
					cashFlowSetData.Amount = num;
					list.Add(cashFlowSetData);
				}
				else
				{
					cashFlowSetData.Amount = num + num2;
					list.Add(cashFlowSetData);
				}
			}
			dataReader.Close();
			if (rDConversion.GetCheckValue(oRec.TransactionSets, 6))
			{
				list.AddRange(GetPendingPO_SO(oRec.SelectedMasters, oRec.StartDate, oRec.EndDate, bPurchaseOrder: true, database, iCompanyId));
