			if (rDConversion.GetCheckValue(oRec.TransactionSets, 5))
			{
				list.AddRange(GetPendingPO_SO(oRec.SelectedMasters, oRec.StartDate, oRec.EndDate, bPurchaseOrder: false, database, iCompanyId));
			}
			cashFlowMatrix.LineData = UpdateProjectedData(list, oRec.ProjectedData, oRec.SelectedMasters, database);
			text = string.Format("SELECT ISNULL(SUM(Debit)+SUM(Credit),0)[Dr]\r\n                FROM\r\n                (\r\n\t                SELECT [iBodyId], CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t                CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit\r\n\t                FROM tCore_Data{0} \r\n\t                JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t                JOIN mCore_Account ON tCore_Data{0}.iCode = mCore_Account.iMasterId  \r\n\t\t            WHERE (mCore_Account.iAccountType = {3} OR mCore_Account.iAccountType = {4})\r\n                    {1} AND (iDate < {2} OR iVoucherClass = 256) \r\n\t                UNION ALL\r\n\t                SELECT [iBodyId], CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n\t                CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit\r\n\t                FROM tCore_Data{0} \r\n\t                JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t                JOIN mCore_Account ON tCore_Data{0}.iBookNo = mCore_Account.iMasterId  \r\n\t\t            WHERE (mCore_Account.iAccountType = {3} OR mCore_Account.iAccountType = {4})\r\n                    {1} AND (iDate < {2} OR iVoucherClass = 256) \r\n                )a\r\n                JOIN tCore_Data{0} ON a.[iBodyId] = tCore_Data{0}.iBodyId\r\n\t            JOIN tCore_Header{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                WHERE tCore_Data{0}.bSuspendUpdateFA = 0 AND tCore_Header{0}.bSuspended = 0 AND tCore_Data{0}.iAuthStatus < 2\r\n                {5}", suffix, text3, oRec.StartDate, 1, 2, text2);
			cashFlowMatrix.OpeningBalance = Convert.ToDouble(database.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
		}
		catch (Exception ex)
		{
			cashFlowMatrix.OpeningBalance = -1.0;
			cashFlowMatrix.LineData = new CashFlowSetData[2]
			{
				new CashFlowSetData
				{
					Name = ex.Message
				},
				new CashFlowSetData
				{
					Name = text
				}
			};
		}
		return cashFlowMatrix;
	}

	private CashFlowSetData[] GetPendingPO_SO(int[] arrMasters, int iStartDate, int iEndDate, bool bPurchaseOrder, Database objDB, int iCompanyId)
	{
		string text = null;
		string text2 = null;
		string suffix = FConvert.GetSuffix(iCompanyId);
		int num = (bPurchaseOrder ? 2560 : 5632);
		int num2 = (bPurchaseOrder ? 7 : 6);
		IDataReader dataReader = null;
		CashFlowSetData cashFlowSetData = null;
		List<CashFlowSetData> list = null;
		text2 = $" AND tCore_Header{suffix}.iDate BETWEEN {iStartDate} AND {iEndDate}";
		if (arrMasters != null && arrMasters.Length != 0)
		{
			text2 += string.Format(" AND tCore_Data{0}.iBookNo IN({1})", suffix, string.Join(",", arrMasters.Select((int p) =>
			{
				int num3 = p;
				return num3.ToString();
			}).ToArray()));
		}
		text = $"WITH RecursionCTE (iTransactionId, iRefId, mAmount2, iBookNo, iDate)\r\n            AS\r\n            (\r\n\t            SELECT tCore_Links{suffix}.iTransactionId, ISNULL(CASE WHEN tCore_Links{suffix}.iTransactionId = tCore_Links{suffix}.iRefId THEN 0 ELSE tCore_Links{suffix}.iRefId END,0)[iRefId],\r\n\t            mAmount2, iBookNo, iDate\r\n\t            FROM tCore_Header{suffix} \r\n\t            JOIN tCore_Data{suffix} ON tCore_Data{suffix}.iHeaderId = tCore_Header{suffix}.iHeaderId\r\n\t            JOIN tCore_Links{suffix} ON tCore_Data{suffix}.iTransactionId = tCore_Links{suffix}.iTransactionId\r\n\t            WHERE (tCore_Header{suffix}.iVoucherClass) = {num} AND bSuspended = 0 \r\n\t            AND ISNULL(tCore_Links{suffix}.bClosed, 0) = 0 AND tCore_Links{suffix}.iTransactionId = tCore_Links{suffix}.iRefId  \r\n                {text2}\r\n\t            UNION ALL\r\n\t            SELECT R1.iTransactionId, R1.iRefId, -R1.mAmount2[mAmount2], R1.iBookNo, R1.iDate\r\n\t            FROM\r\n\t            (\r\n\t\t            SELECT tCore_Links{suffix}.iTransactionId,ISNULL(CASE WHEN tCore_Links{suffix}.iTransactionId = tCore_Links{suffix}.iRefId THEN 0 ELSE tCore_Links{suffix}.iRefId END,0)[iRefId], \r\n\t\t            mAmount2, iBookNo, iDate\r\n\t\t            FROM tCore_Header{suffix} \r\n\t\t            JOIN tCore_Data{suffix} ON tCore_Data{suffix}.iHeaderId = tCore_Header{suffix}.iHeaderId\r\n\t\t            JOIN tCore_Links{suffix} ON tCore_Data{suffix}.iTransactionId = tCore_Links{suffix}.iTransactionId\r\n\t\t            WHERE (tCore_Header{suffix}.iVoucherClass) <> {num} AND bSuspended = 0 \r\n                    AND tCore_Links{suffix}.iTransactionId <> tCore_Links{suffix}.iRefId \r\n                    {text2}\r\n\t            ) R1\r\n\t            JOIN RecursionCTE AS R2 ON R2.iTransactionId = R1.iRefId\r\n            )\r\n            SELECT iMasterId, sName, iDate, SUM(mAmount2)[Amount],{num2}[SetType]\r\n            FROM \r\n            (\r\n                SELECT DISTINCT * FROM RecursionCTE \r\n            )d\r\n            JOIN mCore_Account ON mCore_Account.iMasterId = d.iBookNo \r\n            GROUP BY iMasterId,sName,iDate";
		dataReader = objDB.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		list = new List<CashFlowSetData>();
		while (dataReader.Read())
		{
			cashFlowSetData = new CashFlowSetData();
