	public LineData[] GetPendingBill(int iDate, int iCompanyId)
	{
		string text = null;
		IDataReader dataReader = null;
		LineData lineData = null;
		ReportRowHeader reportRowHeader = null;
		List<LineData> list = null;
		list = new List<LineData>();
		try
		{
			text = string.Format("SELECT tCore_Header{0}.iHeaderId, cCore_Vouchers{0}.sAbbr + ':'+ tCore_Header{0}.sVoucherNo[sVoucherNo] \r\n                ,tCore_Header{0}.iDate ,BookNo.sName,tCore_Data{0}.iDueDate,SUM(tCore_Indta{0}.mGross)[Amount],tCore_Header{0}.iVoucherType\r\n                FROM tCore_Header{0} \r\n                JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType\r\n                JOIN vrCore_Account BookNo ON BookNo.iMasterId = tCore_Data{0}.iBookNo AND BookNo.iTreeId = 0\r\n                JOIN tCore_Indta{0} ON tCore_Indta{0}.iBodyId = tCore_Data{0}.iBodyId \r\n                WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA <> 1 AND tCore_Header{0}.bSuspended = 0 \r\n                AND tCore_Data{0}.iAuthStatus < 2 AND tCore_Header{0}.iDate = {1}\r\n                AND tCore_Header{0}.iVoucherClass IN({2},{3})\r\n                GROUP BY tCore_Header{0}.iHeaderId, tCore_Header{0}.iVoucherType,cCore_Vouchers{0}.sAbbr ,tCore_Header{0}.sVoucherNo,\r\n                tCore_Header{0}.iDate ,BookNo.sName,tCore_Data{0}.iDueDate\r\n                ORDER BY CASE WHEN tCore_Header{0}.iVoucherClass = {2} THEN 0 ELSE 1 END", FConvert.GetSuffix(iCompanyId), iDate, 3328, 768);
			dataReader = DatabaseWrapper.GetDatabase2(iCompanyId, -1, bReplicationServer: true).ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				reportRowHeader = new ReportRowHeader();
				reportRowHeader.RowType = ReportRowType.Normal;
				reportRowHeader.Id = Convert.ToInt32(dataReader[0]);
				reportRowHeader.LongId = Convert.ToInt32(dataReader[6]);
				lineData = new LineData();
				lineData.CellData = new object[6];
				lineData.CellData[0] = reportRowHeader;
				lineData.CellData[1] = dataReader[1];
				lineData.CellData[2] = dataReader[2];
				lineData.CellData[3] = dataReader[3];
				lineData.CellData[4] = dataReader[4];
				lineData.CellData[5] = dataReader[5];
				list.Add(lineData);
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
		}
		return list.ToArray();
	}

