	private CashFlowSetData[] UpdateProjectedData(List<CashFlowSetData> arrLine, CashFlowProjectedData[] arrProjected, int[] arrSelectedMasters, Database objDB)
	{
		int num = 0;
		int num2 = 0;
		IDataReader dataReader = null;
		CashFlowSetData cashFlowSetData = null;
		if (arrProjected != null && arrProjected.Length != 0)
		{
			string[] array = arrProjected.Select((CashFlowProjectedData p) => p.AccountId.ToString()).ToArray();
			List<IdNamePair> list = new List<IdNamePair>();
			if (array.Length != 0)
			{
				string text = string.Format("SELECT iMasterId,sName,sCode FROM mCore_Account WHERE iMasterId IN({0})", string.Join(",", array));
				dataReader = objDB.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				while (dataReader.Read())
				{
					list.Add(new IdNamePair(Convert.ToInt32(dataReader["iMasterId"]), Convert.ToString(dataReader["sName"]), Convert.ToString(dataReader["sCode"])));
				}
				dataReader.Close();
			}
			for (num = 0; num < arrProjected.Length; num++)
			{
				if (arrProjected[num].IsBudget)
				{
					continue;
				}
				for (num2 = 0; num2 < arrLine.Count; num2++)
				{
					if (arrProjected[num].AccountId == arrLine[num2].ID)
					{
						if (FConvert.IsNumeric(arrProjected[num].Formula))
						{
							arrLine[num2].Amount += Convert.ToDouble(arrProjected[num].Formula);
						}
						break;
					}
				}
				if (num2 != arrLine.Count || arrSelectedMasters == null)
				{
					continue;
				}
				for (num2 = 0; num2 < arrSelectedMasters.Length; num2++)
				{
					if (arrProjected[num].AccountId != arrSelectedMasters[num2])
					{
						continue;
					}
					cashFlowSetData = new CashFlowSetData();
					cashFlowSetData.Date = arrProjected[num].PostingDate;
					cashFlowSetData.ID = arrProjected[num].AccountId;
					if (FConvert.IsNumeric(arrProjected[num].Formula))
					{
						cashFlowSetData.Amount = Convert.ToDouble(arrProjected[num].Formula);
					}
					for (num2 = 0; num2 < list.Count; num2++)
					{
						if (list[num2].ID == arrProjected[num].AccountId)
						{
							cashFlowSetData.Name = list[num2].Name;
							break;
						}
					}
					arrLine.Add(cashFlowSetData);
					break;
				}
			}
		}
		return arrLine.ToArray();
	}

