	public IdValuePair[] getVoucherInfo(int iId, LoadTransactionBy oLoadOption, bool bIncludeItem, int iCompanyId)
	{
		string text = null;
		string suffix = FConvert.GetSuffix(iCompanyId);
		IDataReader dataReader = null;
		Database database = DatabaseWrapper.GetDatabase2(iCompanyId);
		List<IdValuePair> list = new List<IdValuePair>();
		if (iId > 0)
		{
			text = "SELECT TOP 1 iCode, iBookNo, iFaTag, iInvTag";
			if (bIncludeItem)
			{
				text += ", iProduct";
			}
			text += $" FROM tCore_Data{suffix}";
			if (bIncludeItem)
			{
				text += string.Format(" JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId", suffix);
			}
			text = ((oLoadOption != LoadTransactionBy.BodyId) ? (text + $" WHERE tCore_Data{suffix}.iHeaderId = {iId}") : (text + $" WHERE tCore_Data{suffix}.iBodyId = {iId}"));
			text += " ORDER BY iSerialNo";
			dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			if (dataReader.Read())
			{
