				list.Add(new IdValuePair(48, Convert.ToInt32(dataReader["iFaTag"])));
				list.Add(new IdValuePair(51, Convert.ToInt32(dataReader["iInvTag"])));
				if (bIncludeItem)
				{
					list.Add(new IdValuePair(23, Convert.ToInt32(dataReader["iProduct"])));
				}
			}
			dataReader.Close();
		}
		return list.ToArray();
	}

	public int LoadMRPLayoutId(int iVoucherType, int iSubReportId, int iLoginId, int iCompanyId)
	{
		int num = 0;
		int result = 0;
		IdNamePair[] array = null;
		if (iVoucherType > 0)
		{
			array = LoadReportLayouts((uint)iVoucherType, iSubReportId, iLoginId, iCompanyId);
		}
		if (array != null && array.Length != 0)
		{
			result = array[0].ID;
			for (num = 0; num < array.Length; num++)
			{
				if (((Convert.ToInt64(array[num].Tag) >> 1) & 1) == 1)
				{
					result = array[num].ID;
					break;
				}
			}
		}
		else
		{
			_Reports reports = new _Reports();
			reports.ReportId = (uint)iVoucherType;
			reports.Module = Module.None;
			reports.ReportName = "";
			reports.DataSourceType = DataSourceType.Standard;
			reports.Layout = new _Layout();
			reports.Layout.LayoutName = "Standard";
			reports.Layout.ReportId = (uint)iVoucherType;
			reports.Layout.SubReportId = iSubReportId;
			reports.Layout.LayoutId = 0;
			ReportColumn[] mRPScreenColumns = new RDDefault().GetMRPScreenColumns(reports.ReportId, iSubReportId);
			reports.Layout.Columns = (from p in mRPScreenColumns
				where !p.Hidden
				select new _Column
				{
					ColumnWidth = ((p.DataType == MasterDataType.Fraction || p.DataType == MasterDataType.Date) ? 60 : 120),
					FieldId = p.FieldId,
					AliasName = p.Name,
					DataTypeId = p.DataType,
					SubParentId = -1
				}).ToArray();
			IdNamePair idNamePair = SaveReportDesigner(reports, iCompanyId);
			if (idNamePair != null && idNamePair.Tag != null)
			{
				result = Convert.ToInt32(idNamePair.Tag);
			}
		}
		return result;
	}

