								masterAuditDetailData2.NewValue = list2[num9].DefaultValue.ToString();
							}
							masterAuditDetailData2.FieldName = lstOldFields[num8].FieldName;
							masterAuditDetailData2.TabName = lstOldFields[num8].TabName;
							list.Add(masterAuditDetailData2);
						}
					}
				}
			}
		}
		catch (Exception ex)
