	private List<MAPIField> GetMasterAPITablesNFields(int iMasterTypeId, int iCompanyId, int iAuditId, string strTableName, Database objDB)
	{
		new MAPIField();
		DbCommand dbCommand = null;
		List<MAPIField> list = new List<MAPIField>();
		try
		{
			string query = string.Format(" \r\n                                    Select sFieldName,  a.sTableName , a.iFieldId, iDataTypeId, a.bTableType, isnull(iLinkMasterId,0)iLinkMasterId,\r\n                                        sExternalTableName,  sExternalValueMember, sExternalDisplayMember, AuditData.sValue, c.sCaption TabName\r\n                                        from vmuCore_MasterFields a Join\r\n\t\t\t\t\t\t\t\t\t\tcCore_MasterTables b On b.iTableId = a.iTableId Join\r\n\t\t\t\t\t\t\t\t\t\tcCore_MasterTabs c On c.iTabId = b.iTabId\r\n                                        inner join t{2}_AuditLogDetails AuditData on AuditData.iFieldId = a.iFieldId\r\n                                     where a.iMasterId ={0} and iAuditId={1}\r\n                                     order by c.iTabId, a.iTableId, a.bTableType\r\n                                    ", iMasterTypeId, iAuditId, strTableName);
			dbCommand = objDB.GetSqlStringCommand(query);
			IDataReader dataReader = objDB.ExecuteReader(dbCommand);
			new StringBuilder();
			while (dataReader.Read())
			{
				MAPIField mAPIField = new MAPIField();
				string fieldName = ((dataReader["sFieldName"] == null) ? "" : Convert.ToString(dataReader["sFieldName"]));
				mAPIField.FieldName = fieldName;
				mAPIField.TableName = ((dataReader["sTableName"] == null) ? "" : dataReader["sTableName"].ToString());
				mAPIField.FieldId = ((dataReader["iFieldId"] != null) ? Convert.ToInt32(dataReader["iFieldId"]) : 0);
				mAPIField.DataTypeId = ((dataReader["iDataTypeId"] != null) ? Convert.ToInt32(dataReader["iDataTypeId"]) : 0);
				mAPIField.TableType = dataReader["bTableType"] != null && Convert.ToBoolean(dataReader["bTableType"]);
				mAPIField.LinkMasterId = ((dataReader["iLinkMasterId"] != null) ? Convert.ToInt32(dataReader["iLinkMasterId"]) : 0);
				mAPIField.ExternalTableName = ((dataReader["sExternalTableName"] == DBNull.Value || dataReader["sExternalTableName"] == null) ? "" : dataReader["sExternalTableName"].ToString());
				mAPIField.ExternalValueMember = ((dataReader["sExternalValueMember"] == DBNull.Value || dataReader["sExternalValueMember"] == null) ? "" : dataReader["sExternalValueMember"].ToString());
				mAPIField.ExternalDisplayMember = ((dataReader["sExternalDisplayMember"] == DBNull.Value || dataReader["sExternalDisplayMember"] == null) ? "" : dataReader["sExternalDisplayMember"].ToString());
				mAPIField.DefaultValue = ((dataReader["sValue"] == null) ? "" : dataReader["sValue"].ToString());
				mAPIField.TabName = ((dataReader["TabName"] == null) ? "" : dataReader["TabName"].ToString());
				list.Add(mAPIField);
			}
			dataReader.Close();
			new List<MAPIField>();
			for (int i = 0; i < list.Count; i++)
			{
				if (list[i].DataTypeId == 12)
				{
					query = $"Select {list[i].ExternalDisplayMember} from {list[i].ExternalTableName} where iMasterId={list[i].DefaultValue}";
					list[i].DefaultValue = Convert.ToString(objDB.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(query) : query));
				}
				else if (list[i].DataTypeId == 22 || list[i].DataTypeId == 14)
				{
					query = $" select {list[i].ExternalDisplayMember}  from {list[i].ExternalTableName} where {list[i].ExternalValueMember} in ({list[i].DefaultValue})";
					list[i].DefaultValue = Convert.ToString(objDB.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(query) : query));
				}
				else if (list[i].DataTypeId == 9)
				{
					if (list[i].FieldName == "iAccountType")
					{
						list[i].DefaultValue = Convert.ToString((AccountType)Convert.ToInt32(list[i].DefaultValue));
						continue;
					}
					if (list[i].FieldName == "iProductType")
					{
						list[i].DefaultValue = Convert.ToString((ProductType)Convert.ToInt32(list[i].DefaultValue));
						continue;
					}
					if (list[i].FieldName == "iValuationMethod")
					{
						list[i].DefaultValue = Convert.ToString((ValuationMethod)Convert.ToInt32(list[i].DefaultValue));
						continue;
					}
					query = $" Select sDefaultValue from cCore_MasterFields where iFieldId = {list[i].FieldId}";
					string[] array = Convert.ToString(objDB.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(query) : query)).Split(',');
					int num;
					for (num = 0; num < array.Length; num++)
					{
						if (list[i].DefaultValue == array[num])
						{
							list[i].DefaultValue = array[num + 1];
						}
						num++;
					}
				}
				else if (list[i].DataTypeId == 4)
				{
					list[i].DefaultValue = new Date(m_objCalType).IntToDate(Convert.ToInt32(list[i].DefaultValue)).ToString();
				}
				else if (list[i].DataTypeId == 3)
				{
					if (FConvert.IsNumeric(Convert.ToString(list[i].DefaultValue)))
					{
						list[i].DefaultValue = new FDateTime(Convert.ToInt64(list[i].DefaultValue), m_objCalType).ToString();
					}
					else
					{
						list[i].DefaultValue = Convert.ToString(list[i].DefaultValue);
					}
				}
				else
				{
					list[i].DefaultValue = list[i].DefaultValue;
				}
			}
			return list;
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
			list.Clear();
			return list;
		}
	}

