	private string GetPbValueName(List<string> lstValueNames, int pbFieldId)
	{
		int num = pbFieldId - 9;
		if (lstValueNames != null && num >= 0 && num < lstValueNames.Count)
		{
			return lstValueNames[num];
		}
		return $"Val{num}";
	}

