			FilesDB filesDB = new FilesDB(strFolder, AuditType.Pricebook);
			list = filesDB.LoadDocWithPos(bPricebookType, iAuditId, iCompId);
			list = ((iSequenceNo <= 0) ? list.Where((IdNamePair p) => p.ID != 202).ToList() : list.Where((IdNamePair p) => Convert.ToInt32(p.Tag) == iSequenceNo && p.ID != 202).ToList());
			filesDB.CloseRead();
			for (int num = 0; num < list.Count; num++)
			{
				switch ((PBFieldDetails)list[num].ID)
				{
				case PBFieldDetails.Product:
					list[num].ExtraInfo = "iProductId";
					break;
				case PBFieldDetails.Account:
					if (bPricebookType == 1)
					{
						list[num].ExtraInfo = "iVendorTagId";
					}
					else
					{
						list[num].ExtraInfo = "iAccountId";
					}
					break;
				case PBFieldDetails.Tag:
					list[num].ExtraInfo = "iTagId";
					break;
				case PBFieldDetails.Currency:
					list[num].ExtraInfo = "iCurrency";
					break;
				case PBFieldDetails.StartDate:
				{
					if (!string.IsNullOrEmpty(list[num].Name) && int.TryParse(list[num].Name, out var result2) && result2 != 0)
					{
						list[num].Name = new Date(oCalType).IntToDate(result2).ToString(strDateFormat);
					}
					else
					{
						list[num].Name = string.Empty;
					}
					list[num].ExtraInfo = "iStartDate";
					break;
				}
				case PBFieldDetails.EndDate:
				{
					if (!string.IsNullOrEmpty(list[num].Name) && int.TryParse(list[num].Name, out var result) && result != 0)
					{
						list[num].Name = new Date(oCalType).IntToDate(result).ToString(strDateFormat);
					}
					else
					{
						list[num].Name = string.Empty;
					}
					list[num].ExtraInfo = "iEndDate";
					break;
				}
				case PBFieldDetails.MinQty:
					list[num].ExtraInfo = "fMinQty";
					break;
				case PBFieldDetails.MaxQty:
					list[num].ExtraInfo = "fMaxQty";
					break;
				case PBFieldDetails.Unit:
					list[num].ExtraInfo = "iUnit";
					break;
				case PBFieldDetails.Rate:
					list[num].ExtraInfo = "fVal0";
					break;
				case PBFieldDetails.Val1:
					list[num].ExtraInfo = "fVal1";
					break;
				case PBFieldDetails.Val2:
					list[num].ExtraInfo = "fVal2";
					break;
				case PBFieldDetails.Val3:
					list[num].ExtraInfo = "fVal3";
					break;
				case PBFieldDetails.Val4:
