	private string GetNames(string table, string field, List<int> userRoleIds, string strFilterField, int iCompanyId)
	{
		DatabaseWrapper.GetDatabase2(iCompanyId);
		Database database = DatabaseWrapper.GetDatabase2(iCompanyId);
		IDataReader dataReader = null;
		List<int> list = userRoleIds.Where((int id) => id != 0).ToList();
		if (list.Count == 0)
		{
			return string.Empty;
		}
		string text = string.Empty;
		string text2 = string.Join(",", list);
		string text3 = "SELECT " + field + " AS Value FROM " + table + " WHERE " + strFilterField + " IN (" + text2 + ")";
		using DbCommand dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text3) : text3);
		dbCommand.CommandTimeout = 0;
		using (dataReader = database.ExecuteReader(dbCommand))
		{
			while (dataReader.Read())
			{
				string text4 = dataReader["Value"].ToString();
				if (!string.IsNullOrEmpty(text4))
				{
					text = (string.IsNullOrEmpty(text) ? text4 : (text + ", " + text4));
				}
			}
			return text;
		}
	}

