			{
			case 1:
				empty = string.Format("SELECT mCore_AuthorizationFilterCondition_{2}.iConjunction,mCore_AuthorizationFilterCondition_{2}.iFieldId,\r\n                     case mCore_AuthorizationFilterCondition_{2}.iFieldId when -1 then 'iParentId' else  isnull(vmuCore_MasterFields.sFieldName,'') end sFieldName,isnull(iDataTypeId,0)iDataTypeId,\r\n                                isnull(vmuCore_MasterFields.sCaption,'')sCaption,mCore_AuthorizationFilterCondition_{2}.iOperatorId, \r\n                                mCore_AuthorizationFilterCondition_{2}.iCompareWith,mCore_AuthorizationFilterCondition_{2}.sValue,isnull(mCore_AuthorizationFilterCondition_{2}.iValue ,0)iValue \r\n                                FROM mCore_AuthorizationFilterCondition_{2}  With (ReadUncommitted) \r\n                                INNER JOIN mCore_AuthorizationDetails_{2}  With (ReadUncommitted) \r\n                                ON mCore_AuthorizationDetails_{2}.iAuthorizationDetailId = mCore_AuthorizationFilterCondition_{2}.iAuthorizationDetailId \r\n                                left JOIN (Select vmuCore_MasterFields.iFieldId,vmuCore_MasterFields.sFieldName,iDataTypeId,vmuCore_MasterFields.sCaption from vmuCore_MasterFields\r\n                                WITH (READUNCOMMITTED)  where vmuCore_MasterFields.iMasterId ={1} ) vmuCore_MasterFields ON vmuCore_MasterFields.iFieldId = mCore_AuthorizationFilterCondition_{2}.iFieldId \r\n                                WHERE mCore_AuthorizationDetails_{2}.iAuthorizationDetailId ={0}  order by mCore_AuthorizationFilterCondition_{2}.iSequenceNo\r\n                                ", iAuthorizationDetId, iDocumentID, iYear);
				break;
			case 3:
			case 4:
				empty = string.Format("SELECT mCore_AuthorizationFilterCondition_{2}.iConjunction,mCore_AuthorizationFilterCondition_{2}.iFieldId,\r\n                    isnull(sName,'')sFieldName,\r\n                                isnull(sName,'')sCaption,mCore_AuthorizationFilterCondition_{2}.iOperatorId, \r\n                                mCore_AuthorizationFilterCondition_{2}.iCompareWith,mCore_AuthorizationFilterCondition_{2}.sValue,isnull(mCore_AuthorizationFilterCondition_{2}.iValue ,0)iValue\r\n                                ,isnull(mCore_AuthorizationFilterCondition_{2}.iValueType ,0) iValueType \r\n                                FROM mCore_AuthorizationFilterCondition_{2}  With (ReadUncommitted) \r\n                                INNER JOIN mCore_AuthorizationDetails_{2}  With (ReadUncommitted) \r\n                                ON mCore_AuthorizationDetails_{2}.iAuthorizationDetailId = mCore_AuthorizationFilterCondition_{2}.iAuthorizationDetailId \r\n                                \r\n                                WHERE mCore_AuthorizationDetails_{2}.iAuthorizationDetailId ={0}  order by mCore_AuthorizationFilterCondition_{2}.iSequenceNo\r\n                                ", iAuthorizationDetId, iDocumentID, iYear);
				break;
			default:
				empty = ((!isFromWeb) ? string.Format("SELECT mCore_AuthorizationFilterCondition_{1}.iConjunction,mCore_AuthorizationFilterCondition_{1}.iFieldId,\r\n                            '' as sCaption,mCore_AuthorizationFilterCondition_{1}.iOperatorId, \r\n                            mCore_AuthorizationFilterCondition_{1}.iCompareWith,sValue,isnull(iParentId,-1)iParentId,isnull(iSubParentId,-1)iSubParentId,isnull(mCore_AuthorizationFilterCondition_{1}.iValue ,0)iValue \r\n                            --case when cCore_Fields.iDataTypeId in (3,4) then cast(dbo.IntToDate(cast(mCore_AuthorizationFilterCondition_{1}.sValue as int)) as varchar(12)) when cCore_Fields.iDataTypeId=5 then cast(dbo.fCore_IntToTime(cast(mCore_AuthorizationFilterCondition_{1}.sValue as int)) as varchar(12)) else mCore_AuthorizationFilterCondition_{1}.sValue end sValue  \r\n                            FROM mCore_AuthorizationFilterCondition_{1}  With (ReadUncommitted) \r\n                            INNER JOIN mCore_AuthorizationDetails_{1}  With (ReadUncommitted) \r\n                            ON mCore_AuthorizationDetails_{1}.iAuthorizationDetailId = mCore_AuthorizationFilterCondition_{1}.iAuthorizationDetailId \r\n                            LEFT  join cCore_Fields  WITH (READUNCOMMITTED)  on cCore_Fields.iFieldId=mCore_AuthorizationFilterCondition_{1}.iFieldId & 0X00FFFFFF\r\n                            WHERE mCore_AuthorizationDetails_{1}.iAuthorizationDetailId = {0} order by mCore_AuthorizationFilterCondition_{1}.iSequenceNo", iAuthorizationDetId, iYear) : string.Format("SELECT mCore_AuthorizationFilterCondition_{1}.iValueType,mCore_AuthorizationFilterCondition_{1}.iConjunction,mCore_AuthorizationFilterCondition_{1}.iFieldId,\r\n                            '' as sCaption,isnull(sName,'')sFieldName, mCore_AuthorizationFilterCondition_{1}.iOperatorId, \r\n                            mCore_AuthorizationFilterCondition_{1}.iCompareWith,sValue,isnull(iParentId,-1)iParentId,isnull(iSubParentId,-1)iSubParentId,isnull(mCore_AuthorizationFilterCondition_{1}.iValue ,0)iValue \r\n                            --case when cCore_Fields.iDataTypeId in (3,4) then cast(dbo.IntToDate(cast(mCore_AuthorizationFilterCondition_{1}.sValue as int)) as varchar(12)) when cCore_Fields.iDataTypeId=5 then cast(dbo.fCore_IntToTime(cast(mCore_AuthorizationFilterCondition_{1}.sValue as int)) as varchar(12)) else mCore_AuthorizationFilterCondition_{1}.sValue end sValue  \r\n                            FROM mCore_AuthorizationFilterCondition_{1}  With (ReadUncommitted) \r\n                            INNER JOIN mCore_AuthorizationDetails_{1}  With (ReadUncommitted) \r\n                            ON mCore_AuthorizationDetails_{1}.iAuthorizationDetailId = mCore_AuthorizationFilterCondition_{1}.iAuthorizationDetailId \r\n                            LEFT  join cCore_Fields  WITH (READUNCOMMITTED)  on cCore_Fields.iFieldId=mCore_AuthorizationFilterCondition_{1}.iFieldId & 0X00FFFFFF\r\n                            WHERE mCore_AuthorizationDetails_{1}.iAuthorizationDetailId = {0} order by mCore_AuthorizationFilterCondition_{1}.iSequenceNo", iAuthorizationDetId, iYear));
				break;
			}
			IDataReader dataReader = m_db.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			while (dataReader.Read())
			{
				AdvanceFilterQuery advanceFilterQuery = new AdvanceFilterQuery();
				advanceFilterQuery.Conjunction = Convert.ToInt32(dataReader["iConjunction"]);
				advanceFilterQuery.Name = dataReader["sCaption"].ToString();
				if (iAuthorizationType == 1)
				{
					advanceFilterQuery.FieldName = Convert.ToString(dataReader["sFieldName"]);
					advanceFilterQuery.iValueType = (MasterDataType)Convert.ToInt32(dataReader["iDataTypeId"]);
				}
				if (iAuthorizationType == 3 || iAuthorizationType == 4)
				{
					advanceFilterQuery.FieldName = Convert.ToString(dataReader["sFieldName"]);
					advanceFilterQuery.iValueType = (MasterDataType)Convert.ToInt32(dataReader["iValueType"]);
				}
				if (isFromWeb)
				{
					if (iAuthorizationType == 2)
					{
						advanceFilterQuery.FieldName = Convert.ToString(dataReader["sFieldName"]);
						advanceFilterQuery.iValueType = (MasterDataType)Convert.ToInt32(dataReader["iValueType"]);
					}
					advanceFilterQuery.CompareText = dataReader["sValue"].ToString();
				}
				advanceFilterQuery.FieldId = Convert.ToInt32(dataReader["iFieldId"]);
				advanceFilterQuery.Operator = Convert.ToInt32(dataReader["iOperatorId"]);
				advanceFilterQuery.CompareWith = Convert.ToInt32(dataReader["iCompareWith"]);
				advanceFilterQuery.CompareValue = dataReader["sValue"].ToString();
				advanceFilterQuery.iValue = Convert.ToInt32(dataReader["iValue"]);
				if (iAuthorizationType == 2)
				{
					advanceFilterQuery.TreeData = new TreeHierarchyDetails
					{
						FieldId = Convert.ToInt32(dataReader["iFieldId"]),
						DataType = 0,
						ParentId = Convert.ToInt32(dataReader["iParentId"]),
						SubParentId = Convert.ToInt32(dataReader["iSubParentId"])
					};
				}
				list.Add(advanceFilterQuery);
			}
			dataReader.Close();
			dataReader.Dispose();
			return list;
		}
		catch (Exception ex)
		{
			iErrorNo = -1;
			strErrorMsg = ex.ToString();
			return null;
		}
	}

	public IdNamePair[] getReportSettings(uint ReportId, int iCompId)
	{
		string objTag = "Yes";
		string objTag2 = "Missing";
		List<IdNamePair> list = new List<IdNamePair>();
		if (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.Print, 36) > 0)
		{
			list.Add(new IdNamePair(38, "Do not apply security restriction Enabled"));
		}
		switch ((FocusReport)ReportId)
		{
		case FocusReport.Ledger:
			if (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.Print, 45) > 0)
			{
				list.Add(new IdNamePair(38, "Show debits first in ledger", objTag));
			}
			if (_focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Misc, 19) > 0)
			{
				list.Add(new IdNamePair(38, "Do not show opening balances in nominal ledger", objTag));
			}
			if (_focus.company(m_iCompanyId).getPreferenceValue(PreferenceCategories.Misc, 22) > 0)
			{
				list.Add(new IdNamePair(38, "Show exchange rate difference in ledger", objTag));
			}
			break;
		case FocusReport.VATDetailedReport:
			if (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.VAT, 15) <= 0)
			{
				list.Add(new IdNamePair(38, "VAT input account", objTag2));
			}
			if (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.VAT, 22) <= 0)
			{
				list.Add(new IdNamePair(38, "VAT output account", objTag2));
			}
			if (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.VAT, 26) <= 0)
			{
				list.Add(new IdNamePair(38, "VAT advance sales account", objTag2));
			}
			if (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.VAT, 27) <= 0)
			{
				list.Add(new IdNamePair(38, "VAT advance purchase account", objTag2));
			}
			break;
		case FocusReport.CreditLimitAuthorizationReport:
			if (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.ARAP, 23) > 0)
			{
				list.Add(new IdNamePair(38, "Define Credit Limit by Finance Tag", objTag));
			}
			if (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.ARAP, 27) > 0)
			{
				list.Add(new IdNamePair(38, "Define Credit days by Finance Tag", objTag));
			}
			break;
		case FocusReport.VendorAgeingSummaryBillwise:
		case FocusReport.VendorSummaryAgeingByDueDate:
		case FocusReport.CustomerAgeingSummaryBillwise:
		case FocusReport.CustomerSummaryAgeingByDueDate:
			if (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.ARAP, 28) > 0)
			{
				list.Add(new IdNamePair(38, "Do not ignore round off", objTag));
			}
			break;
		case FocusReport.StockLedger:
			if (_focus.company(iCompId).getPreferenceValue(PreferenceCategories.Print, 38) > 0)
			{
				list.Add(new IdNamePair(38, "Do not use real time valuation", objTag));
			}
			if (_focus.company(iCompId).documentOrder)
			{
				list.Add(new IdNamePair(38, "Document order applied", objTag));
			}
			break;
		}
		return list.ToArray();
	}

	public IdNamePair SaveReportDesigner(_Reports objReports, int iCompanyId)
	{
		string empty = string.Empty;
		bool bNewData = true;
		DbConnection dbConnection = null;
		DbTransaction dbTransaction = null;
		DbCommand dbCommand = null;
		m_iCompanyId = iCompanyId;
		m_objDatabase = DatabaseWrapper.GetDatabase2(m_iCompanyId);
		dbConnection = m_objDatabase.CreateConnection();
		using (dbConnection = m_objDatabase.CreateConnection())
		{
			try
			{
				dbConnection.Open();
				dbTransaction = dbConnection.BeginTransaction();
				if (objReports.ReportId != 0)
				{
					empty = $"SELECT COUNT(1) FROM cCore_Reports{FConvert.GetSuffix(m_iCompanyId)} WHERE iReportId={objReports.ReportId}";
					dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
					bNewData = Convert.ToInt32(m_objDatabase.ExecuteScalar(dbCommand, dbTransaction)) == 0;
				}
				objReports.ReportId = SaveReports(objReports.ReportId, objReports.ReportName, objReports.Remarks, objReports.Module, objReports.ReportType, objReports.MenuGroupId, dbTransaction, (int)objReports.DataSourceType, objReports.CreatedBy, objReports.ModifiedBy, objReports.AdvancedEngine, objReports.DelayFetch, bNewData);
				SaveReportFilter((int)objReports.ReportId, objReports.Filters, _FilterType.Report, dbTransaction);
				if (objReports.DataSourceType == DataSourceType.Excel || objReports.DataSourceType == DataSourceType.XML)
				{
					SaveReportFolder(objReports.ReportId, objReports.RDFolder, dbTransaction, bNewData);
				}
				switch (objReports.DataSourceType)
				{
				case DataSourceType.Query:
				case DataSourceType.View:
					SaveRdQuery(objReports, dbTransaction, bNewData);
					break;
				case DataSourceType.Default:
				case DataSourceType.Reports:
					SaveTransactionSet(objReports.ReportId, objReports.TransactionSets, dbTransaction, bNewData);
					break;
				}
				SaveParameters(objReports.ReportId, objReports.Parameters, dbTransaction, bNewData);
				SaveReportGrouping(objReports.ReportId, objReports.Groupings, dbTransaction, bNewData);
				if (objReports.Layout != null)
				{
					if (objReports.Layout.LayoutId <= 0)
					{
						empty = $"SELECT TOP 1 iLayoutId FROM cCore_ReportLayouts{FConvert.GetSuffix(m_iCompanyId)} WHERE iReportId={objReports.ReportId} AND sLayoutName =N'{objReports.Layout.LayoutName}'";
						dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
						objReports.Layout.LayoutId = Convert.ToInt32(m_objDatabase.ExecuteScalar(dbCommand, dbTransaction));
					}
					bNewData = objReports.Layout.LayoutId == 0;
					objReports.Layout.LayoutId = SaveLayout(objReports.ReportId, objReports.Layout, dbTransaction, bNewData);
					SaveReportFormatting(objReports.Layout.LayoutId, objReports.Layout.RowConditional, dbTransaction, bNewData);
					SaveReportTopClause(objReports.Layout.LayoutId, 0, objReports.Layout.SelectClause, objReports.Layout.ClauseValue, dbTransaction, bNewData);
					SaveColumns(objReports.Layout.LayoutId, objReports.Layout.Columns, objReports.Groupings, dbTransaction, bNewData);
					SaveUserRestriction(objReports.Layout.LayoutId, objReports.Layout.IsRestrictionOnRoles, objReports.Layout.UserOrRoleIds, m_objDatabase, dbTransaction, bNewData, LayoutSecurityType.Report);
					SaveExtraValues(objReports.Layout.LayoutId, objReports.Layout.ExtraValues, dbTransaction, bNewData);
				}
				dbTransaction.Commit();
			}
			catch (Exception ex)
			{
				dbTransaction.Rollback();
				return new IdNamePair(-1, ex.Message, -1);
			}
			finally
			{
				if (dbConnection != null && dbConnection.State != ConnectionState.Closed)
				{
					dbConnection.Close();
				}
			}
		}
		return new IdNamePair((int)objReports.ReportId, objReports.Layout.LayoutName, objReports.Layout.LayoutId);
	}

	public _Reports LoadReportDesigner(uint iReportId, int iLayoutId, int iCompanyId, uint iSubReportId = 0u)
	{
		_Reports reports = new _Reports();
		bool bUserOrRole = false;
		try
		{
			m_iCompanyId = iCompanyId;
			m_objDatabase = DatabaseWrapper.GetDatabase2(m_iCompanyId);
			reports = LoadReportDefinition(iReportId);
			reports.Layout = LoadReportLayout(iReportId, iSubReportId, iLayoutId);
			reports.Parameters = LoadReportparameters(iReportId);
			reports.TransactionSets = LoadTransactionSet(iReportId, m_iCompanyId);
			reports.Groupings = LoadGrouping(iReportId);
			if (iReportId >= RDCommon.RD_STARTID)
			{
				reports.Layout.ExtraValues = LoadExtraValues(reports.Layout.LayoutId);
				reports.RDQuery = LoadRdQuery(iReportId);
			}
			if (reports.TransactionSets != null && reports.TransactionSets.Length != 0 && reports.TransactionSets[0].TransactionSetId == TransactionSetType.None && (reports.TransactionSets[0].VoucherType >= RDCommon.RD_STARTID || reports.DataSourceType == DataSourceType.Reports))
			{
				int iBaseLayout = 0;
				if (reports.Layout.ExtraValues != null)
				{
					for (int i = 0; i < reports.Layout.ExtraValues.Length; i++)
					{
						if (reports.Layout.ExtraValues[i].ID == 3 && FConvert.IsNumeric(Convert.ToString(reports.Layout.ExtraValues[i].Value)))
						{
							iBaseLayout = Convert.ToInt32(reports.Layout.ExtraValues[i].Value);
							break;
						}
					}
				}
				reports.Layout.Columns = LoadColumns(reports.TransactionSets[0].VoucherType, IsAnalyzeTypeReport: true, reports.DataSourceType, m_iCompanyId, iBaseLayout);
			}
			else
			{
				reports.Layout.Columns = LoadColumns(reports.Layout.LayoutId, IsAnalyzeTypeReport: false, reports.DataSourceType, m_iCompanyId);
			}
			reports.Layout.RowConditional = LoadReportFormatting(reports.Layout.LayoutId);
			reports.Layout.UserOrRoleIds = LoadUserSecurity(reports.Layout.LayoutId, LayoutSecurityType.Report, m_objDatabase, ref bUserOrRole);
			reports.Layout.IsRestrictionOnRoles = bUserOrRole;
		}
		catch (Exception ex)
		{
			FConvert.LogFile(FConvert.CompanyCodeFromId(iCompanyId) + "FQuery.log", $"LOADREPORTDESIGNER : {DateTime.Now.ToString()}, CompanyId : {iCompanyId}, ReportId : {reports.ReportId}\r\nException : {ex.Message}\r\n{ex.StackTrace}");
			reports.ReportId = 0u;
			reports.ReportName = ex.Message.ToUpper();
		}
		return reports;
	}

	public string DeleteReportDesigner(uint iReportId, int iCompanyId)
	{
		DbConnection dbConnection = null;
		string text = string.Empty;
		m_iCompanyId = iCompanyId;
		m_objDatabase = DatabaseWrapper.GetDatabase2(m_iCompanyId);
		dbConnection = m_objDatabase.CreateConnection();
		using (dbConnection = m_objDatabase.CreateConnection())
		{
			try
			{
				dbConnection.Open();
				text = string.Format($"select Count(*) from cCore_DashBoardDashlets a Join\r\n                    cCore_Dashlet b On a.iDashletId = b.iDashletId \r\n                    Where b.iDashletType = 2 and iCustomReportId = {iReportId}");
				DbCommand sqlStringCommand = m_objDatabase.GetSqlStringCommand(text);
				if (Convert.ToInt32(m_objDatabase.ExecuteScalar(sqlStringCommand)) > 0)
				{
					return "Report using in Dashboard";
				}
				text = string.Format("DELETE FROM cCore_ReportColumnsFilter{0} \r\n                    WHERE iColumnId IN (SELECT iColumnId From cCore_ReportColumns{0} \r\n                    WHERE iLayoutId IN (SELECT iLayoutId FROM cCore_ReportLayouts{0} \r\n                    WHERE iReportId = {1}))\r\n\r\n                    DELETE FROM cCore_ReportColumnsOrder{0} \r\n                    WHERE iColumnId IN (SELECT iColumnId From cCore_ReportColumns{0} \r\n                    WHERE iLayoutId IN (SELECT iLayoutId FROM cCore_ReportLayouts{0} \r\n                    WHERE iReportId = {1}))\r\n\r\n                    DELETE FROM cCore_ReportColumnsFunction{0}\r\n                    WHERE iColumnId IN (SELECT iColumnId From cCore_ReportColumns{0} \r\n                    WHERE iLayoutId IN (SELECT iLayoutId FROM cCore_ReportLayouts{0} \r\n                    WHERE iReportId = {1}))\r\n\r\n                    DELETE FROM cCore_ReportColumns{0} \r\n                    WHERE iLayoutId IN (SELECT iLayoutId FROM cCore_ReportLayouts{0} \r\n                    WHERE iReportId = {1})\r\n\r\n                    DELETE FROM cCore_ReportParameter{0} \r\n                    WHERE iReportId = {1}\r\n\r\n                    DELETE FROM cCore_ReportGrouping{0}\r\n                    WHERE iReportId = {1}\r\n\r\n                    DELETE FROM cCore_ReportFilter{0}\r\n                    WHERE iFilterGroupId IN (SELECT iReportId FROM cCore_Reports{0}\r\n                    WHERE iReportId = {1})\r\n                    \r\n                    DELETE FROM cCore_ReportFilter{0} \r\n                    WHERE iFilterGroupId IN (SELECT iConditionId FROM cCore_ReportFormatting{0}\r\n                    WHERE iLayoutId IN (SELECT iLayoutId FROM cCore_ReportLayouts{0} \r\n                    WHERE iReportId = {1}))\r\n\r\n                    DELETE FROM cCore_ReportFilter{0}\r\n                    WHERE iFilterGroupId IN (SELECT iColumnId FROM cCore_ReportColumns{0}\r\n                    WHERE iLayoutId IN (SELECT iLayoutId FROM cCore_ReportLayouts{0}\r\n                    WHERE iReportId = {1}))\r\n\r\n                    DELETE FROM cCore_ReportTransactionSet{0} \r\n                    WHERE iReportId = {1}\r\n\r\n                    DELETE FROM cCore_ReportFormatting{0} \r\n                    WHERE iLayoutId IN (SELECT iLayoutId FROM cCore_ReportLayouts{0} \r\n                    WHERE iReportId = {1})\r\n                    \r\n                    DELETE FROM cCore_ReportExtraValues{0} \r\n                    WHERE iLayoutId IN (SELECT iLayoutId FROM cCore_ReportLayouts{0} \r\n                    WHERE iReportId = {1})\r\n                   \r\n                    DELETE FROM cCore_InvoiceBodyFont{0} WHERE iHeaderId IN (SELECT iLayoutId FROM cCore_ReportLayouts{0} \r\n                    WHERE iReportId = {1}) AND iPageId = 0 AND iFontType = 3\r\n\r\n                    DELETE FROM cCore_ReportLayouts{0} \r\n                    WHERE iReportId = {1}\r\n\r\n                    DELETE FROM cCore_RDQuery{0} WHERE iReportId = {1}                    \r\n                    DELETE FROM cCore_RepFolder{0} WHERE iReportId = {1}                    \r\n                    DELETE FROM cCore_ReportUser{0} WHERE iReportId = {1}            \r\n\r\n                    DELETE FROM cCore_Reports{0} \r\n                    WHERE iReportId = {1}\r\n                    DELETE FROM tSec_ProfileLogDetails WHERE iMenuId = {1}\r\n                    DELETE FROM tSec_UserLogDetails WHERE iMenuId = {1}\r\n                    DELETE FROM tCore_UsageLog WHERE iMenuId = {1}\r\n                    DELETE FROM mSec_MenuSpecificRights WHERE iMenuId = {1}\r\n                    DELETE FROM mSec_ProfileDetails WHERE iMenuId = {1}\r\n                    DELETE FROM mSec_RolesExtraRights WHERE iMenuId = {1}\r\n                    DELETE FROM cCore_MenuLanguages WHERE iMenuId = {1} --AND iLanguageId = 0\r\n                    DELETE FROM mCore_Menu WHERE iMenuId = {1}\r\n                    DELETE FROM cCore_MasterReportsLink{0} WHERE iReportId = {1}", FConvert.GetSuffix(m_iCompanyId), iReportId);
				sqlStringCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				m_objDatabase.ExecuteNonQuery(sqlStringCommand);
				text = string.Empty;
			}
			catch (Exception ex)
			{
				text = ex.Message;
			}
			finally
			{
				dbConnection.Close();
			}
		}
		return text;
	}

	public _Menu[] GetMenuDetails(bool bGroup, int iCompanyId)
	{
		List<_Menu> list = new List<_Menu>();
		string empty = string.Empty;
		try
		{
			m_iCompanyId = iCompanyId;
			m_objDatabase = DatabaseWrapper.GetDatabase2(m_iCompanyId);
			empty = "SELECT iMenuId,sMenuText,iMenuGroupId,bGroup FROM mCore_Menu";
			if (bGroup)
			{
				empty += " WHERE bGroup = 1";
			}
			empty += " ORDER BY iMenuGroupId, iMenuIndex";
			DbCommand sqlStringCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			IDataReader dataReader = m_objDatabase.ExecuteReader(sqlStringCommand);
			while (dataReader.Read())
			{
				_Menu menu = new _Menu();
				menu.MenuId = Convert.ToInt32(dataReader["iMenuId"]);
				menu.MenuText = Convert.ToString(dataReader["sMenuText"]);
				menu.MenuGroupId = ((dataReader["iMenuGroupId"] == DBNull.Value) ? (-1) : Convert.ToInt32(dataReader["iMenuGroupId"]));
				menu.IsGroup = Convert.ToBoolean(dataReader["bGroup"]);
				list.Add(menu);
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			list.Clear();
			_Menu menu = new _Menu();
			menu.MenuId = -1;
			menu.MenuText = ex.Message;
			list.Add(menu);
		}
		return list.ToArray();
	}

	public _Menu UpdateRDMenuGroup(_Menu oMenu, MenuOptions eMenuOpt, int iCompanyId)
	{
		string text = null;
		DbCommand dbCommand = null;
		Database database = null;
		uint num = 0u;
		int num2 = 0;
		string suffix = FConvert.GetSuffix(iCompanyId);
		try
		{
			database = DatabaseWrapper.GetDatabase2(iCompanyId);
			switch (eMenuOpt)
			{
			case MenuOptions.Add:
				text = $"SELECT ISNULL(MAX(iMenuIndex),0)+1[iMenuIndex] FROM mCore_Menu WHERE iMenuGroupId={oMenu.MenuId}";
				dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				num2 = Convert.ToInt32(database.ExecuteScalar(dbCommand));
				text = string.Format("SELECT ISNULL(MAX(iReportId),{1})+1[iReportId] FROM cCore_Reports{0} WHERE iReportId > {1}", suffix, RDCommon.RD_STARTID);
				dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				num = Convert.ToUInt32(database.ExecuteScalar(dbCommand));
				text = string.Format("INSERT INTO cCore_Reports{5} (iReportId, sReportName, iModule, iReportType, iSourceType, iCreatedDate)\r\n                                            VALUES ({0}, N'{1}', 0, 0, 0, {6});\r\n                                            INSERT INTO mCore_Menu(iMenuId,sMenuName,sMenuText,iMenuGroupId,iMenuIndex,iType,iTypeId,bGroup) VALUES({0}, 'mnuRD{1}', '{2}', {3}, {4}, 5, {0}, 1);\r\n                                            INSERT INTO mSec_MenuSpecificRights (iMenuId, iActionId) VALUES ({0},1)\r\n                                            INSERT INTO cCore_MenuLanguages (iMenuId, iLanguageId, sCaption) VALUES ({0}, 0, N'{2}')", num, FConvert.GetValidName(oMenu.MenuText), oMenu.MenuText, oMenu.MenuId, num2, suffix, new Date().GetToday(m_objCalType).Value);
				dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				database.ExecuteNonQuery(dbCommand);
				break;
			case MenuOptions.Update:
				text = $"UPDATE mCore_Menu SET sMenuText = '{oMenu.MenuText}' WHERE iMenuId = {oMenu.MenuId}";
				dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				database.ExecuteNonQuery(dbCommand);
				text = $"Update cCore_MenuLanguages SET sCaption = N'{oMenu.MenuText}' WHERE iMenuId = {oMenu.MenuId} AND iLanguageId = {oMenu.AltLanguageId}";
				dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				database.ExecuteNonQuery(dbCommand);
				break;
			case MenuOptions.Delete:
				text = $"SELECT Count(1) FROM mCore_Menu WHERE iMenuGroupId={oMenu.MenuId}";
				dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				if (Convert.ToInt32(database.ExecuteScalar(dbCommand)) == 0)
				{
					text = string.Format("DELETE FROM tSec_UserLogDetails WHERE iMenuId = {0}\r\n                                                            DELETE FROM tCore_UsageLog WHERE iMenuId = {0}                                                                                    \r\n                                                            DELETE FROM mSec_MenuSpecificRights WHERE iMenuId = {0}\r\n                                                            DELETE FROM mSec_ProfileDetails WHERE iMenuId = {0}\r\n                                                            DELETE FROM mSec_RolesExtraRights WHERE iMenuId = {0}\r\n                                                            DELETE FROM cCore_MenuLanguages WHERE iMenuId = {0}\r\n                                                            DELETE FROM mCore_Menu WHERE iMenuId = {0}", oMenu.MenuId);
					dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
					database.ExecuteNonQuery(dbCommand);
					break;
				}
				throw new Exception("Menu item already exists under the group");
			}
		}
		catch (Exception ex)
		{
			oMenu.MenuId = -1;
			oMenu.MenuText = ex.Message;
		}
		return oMenu;
	}

	public IdNamePair[] LoadReportLayouts(uint iReportId, int iSubReportId, int iUserId, int iCompanyId)
	{
		long num = 0L;
		string empty = string.Empty;
		string suffix = FConvert.GetSuffix(iCompanyId);
		List<string> list = null;
		List<IdNamePair> list2 = null;
		list2 = new List<IdNamePair>();
		list = new List<string>();
		try
		{
			Database database = DatabaseWrapper.GetDatabase2(iCompanyId);
			DbCommand sqlStringCommand;
			IDataReader dataReader;
			if (iUserId > 1)
			{
				empty = $"SELECT cCore_ReportUserSecurity{suffix}.iLayoutId \r\n                    FROM cCore_ReportUserSecurity{suffix} \r\n                    JOIN cCore_ReportLayouts{suffix} ON cCore_ReportUserSecurity{suffix}.iLayoutId = cCore_ReportLayouts{suffix}.iLayoutId\r\n                    WHERE iUserOrRoleId = {iUserId} AND iReportId = {iReportId} AND iSubReportId = {iSubReportId}";
				sqlStringCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
				dataReader = database.ExecuteReader(sqlStringCommand);
				while (dataReader.Read())
				{
					list.Add(Convert.ToString(dataReader["iLayoutId"]));
				}
				dataReader.Close();
			}
			empty = $"SELECT iLayoutId, sLayoutName, iFlag[iFlag] FROM cCore_ReportLayouts{suffix} \r\n                WHERE iReportId = {iReportId} AND iSubReportId = {iSubReportId}";
			if (list.Count > 0)
			{
				empty += string.Format(" AND iLayoutId IN ({0})", string.Join(",", list));
			}
			sqlStringCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			dataReader = database.ExecuteReader(sqlStringCommand);
			while (dataReader.Read())
			{
				if (Convert.ToInt64(dataReader["iFlag"]) > num)
				{
					list2.Insert(0, new IdNamePair(Convert.ToInt32(dataReader["iLayoutId"]), Convert.ToString(dataReader["sLayoutName"]), Convert.ToInt64(dataReader["iFlag"])));
				}
				else
				{
					list2.Add(new IdNamePair(Convert.ToInt32(dataReader["iLayoutId"]), Convert.ToString(dataReader["sLayoutName"]), Convert.ToInt64(dataReader["iFlag"])));
				}
				num = Convert.ToInt64(dataReader["iFlag"]);
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			list2.Add(new IdNamePair(-1, ex.Message, 0));
		}
		return list2.ToArray();
	}

