	public _RDVirtual LoadRDVirtual(int iFieldId, bool bSearchByField, int iCompanyId)
	{
		DbCommand dbCommand = null;
		_RDVirtual rDVirtual = null;
		_RDVirtualValue rDVirtualValue = null;
		string empty = string.Empty;
		List<string> list = null;
		byte b = 0;
		List<_RDVirtualValue> list2 = null;
		string suffix = FConvert.GetSuffix(iCompanyId);
		rDVirtual = new _RDVirtual();
		try
		{
			empty = $"SELECT iFieldId, iVirtualId, sFieldName, bNumeric FROM cCore_RDVirtual{suffix}";
			empty = ((!bSearchByField) ? (empty + $" WHERE iVirtualId = {iFieldId} ") : (empty + $" WHERE iFieldId = {iFieldId} "));
			Database database = DatabaseWrapper.GetDatabase2(iCompanyId);
			dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			IDataReader dataReader = database.ExecuteReader(dbCommand);
			if (dataReader.Read())
			{
				rDVirtual.VirtualId = Convert.ToInt32(dataReader["iVirtualId"]);
				rDVirtual.FieldId = Convert.ToInt32(dataReader["iFieldId"]);
				rDVirtual.FieldName = Convert.ToString(dataReader["sFieldName"]);
				rDVirtual.IsRangeData = Convert.ToBoolean(dataReader["bNumeric"]);
			}
			dataReader.Close();
			if (rDVirtual.VirtualId > 0)
			{
				empty = $"SELECT iConditionId, sGroupLabel FROM cCore_RDVirtualCondition{suffix} WHERE iVirtualId = {rDVirtual.VirtualId}";
				list2 = new List<_RDVirtualValue>();
				database = DatabaseWrapper.GetDatabase2(iCompanyId);
				dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
				dataReader = database.ExecuteReader(dbCommand);
				while (dataReader.Read())
				{
					rDVirtualValue = new _RDVirtualValue();
					rDVirtualValue.Label = Convert.ToString(dataReader["sGroupLabel"]);
					rDVirtualValue.ConditionId = Convert.ToInt32(dataReader["iConditionId"]);
					list2.Add(rDVirtualValue);
				}
				dataReader.Close();
				for (b = 0; b < list2.Count; b++)
				{
					if (rDVirtual.IsRangeData)
					{
						empty = $"SELECT iStartValue, iEndValue FROM cCore_RDVirtualRange{suffix} WHERE iConditionId = {list2[b].ConditionId} ";
						dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
						dataReader = database.ExecuteReader(dbCommand);
						if (dataReader.Read())
						{
							list2[b].StartValue = Convert.ToDouble(dataReader["iStartValue"]);
							list2[b].EndValue = Convert.ToDouble(dataReader["iEndValue"]);
						}
						dataReader.Close();
					}
					else
					{
						empty = $"SELECT sValue FROM cCore_RDVirtualValue{suffix} WHERE iConditionId = {list2[b].ConditionId} ";
						list = new List<string>();
						dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
						dataReader = database.ExecuteReader(dbCommand);
						while (dataReader.Read())
						{
							list.Add(Convert.ToString(dataReader["sValue"]));
						}
						dataReader.Close();
						list2[b].Values = list.ToArray();
					}
				}
				rDVirtual.Values = list2.ToArray();
			}
		}
		catch (Exception ex)
		{
			rDVirtual.FieldName = ex.Message;
			rDVirtual.FieldId = -1;
		}
		finally
		{
			if (dbCommand != null && dbCommand.Connection != null && dbCommand.Connection.State != ConnectionState.Closed)
			{
				dbCommand.Connection.Close();
			}
		}
		return rDVirtual;
	}

	public IdNamePair SaveRDVirtual(_RDVirtual oData, int iCompanyId)
	{
		DbCommand dbCommand = null;
		DbTransaction dbTransaction = null;
		DbConnection dbConnection = null;
		IdNamePair idNamePair = null;
		string empty = string.Empty;
		string suffix = FConvert.GetSuffix(iCompanyId);
		int num = 0;
		idNamePair = new IdNamePair();
		Database database = DatabaseWrapper.GetDatabase2(iCompanyId);
		using (dbConnection = database.CreateConnection())
		{
			try
			{
				dbConnection.Open();
				dbTransaction = dbConnection.BeginTransaction();
				empty = $"SELECT ISNULL(iVirtualId, 0) FROM cCore_RDVirtual{suffix} WHERE iFieldId = {oData.FieldId} ";
				dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
				idNamePair.ID = Convert.ToInt32(database.ExecuteScalar(dbCommand, dbTransaction));
				if (idNamePair.ID > 0)
				{
					empty = $"UPDATE cCore_RDVirtual{suffix} SET sFieldName = N'{oData.FieldName}', bNumeric = {(oData.IsRangeData ? 1 : 0)} WHERE iFieldId = {oData.FieldId}";
					dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
					database.ExecuteNonQuery(dbCommand, dbTransaction);
					empty = string.Format("\r\n                        DELETE FROM cCore_RDVirtualRange{0} WHERE iConditionId IN (SELECT iConditionId FROM cCore_RDVirtualCondition{0} WHERE iVirtualId = {1});\r\n                        DELETE FROM cCore_RDVirtualValue{0} WHERE iConditionId IN (SELECT iConditionId FROM cCore_RDVirtualCondition{0} WHERE iVirtualId = {1})\r\n                        DELETE FROM cCore_RDVirtualCondition{0} WHERE iVirtualId = {1}", suffix, idNamePair.ID);
					dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
					database.ExecuteNonQuery(dbCommand, dbTransaction);
				}
				else
				{
					empty = $"INSERT INTO cCore_RDVirtual{suffix}(iFieldId, sFieldName, bNumeric) \r\n                            VALUES ({oData.FieldId}, N'{oData.FieldName}', {(oData.IsRangeData ? 1 : 0)}); SELECT @@IDENTITY;";
					dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
					idNamePair.ID = Convert.ToInt32(database.ExecuteScalar(dbCommand, dbTransaction));
				}
				for (num = 0; num < oData.Values.Length; num++)
				{
					empty = $"INSERT INTO cCore_RDVirtualCondition{suffix}(iVirtualId, sGroupLabel) \r\n                            VALUES ({idNamePair.ID}, N'{oData.Values[num].Label}'); SELECT @@IDENTITY;";
					dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
					int num2 = Convert.ToInt32(database.ExecuteScalar(dbCommand, dbTransaction));
					if (oData.IsRangeData)
					{
						empty = $"INSERT INTO cCore_RDVirtualRange{suffix} (iConditionId, iStartValue, iEndValue)\r\n                                VALUES ({num2}, {oData.Values[num].StartValue}, {oData.Values[num].EndValue});";
					}
					else
					{
						empty = string.Empty;
						string[] values = oData.Values[num].Values;
						foreach (string arg in values)
						{
							empty += $"INSERT INTO cCore_RDVirtualValue{suffix} (iConditionId, sValue)\r\n                                VALUES ({num2}, N'{arg}');";
						}
					}
					dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
					database.ExecuteNonQuery(dbCommand, dbTransaction);
				}
				dbTransaction.Commit();
			}
			catch (Exception ex)
			{
				dbTransaction.Rollback();
				idNamePair.ID = -1;
				idNamePair.Name = ex.Message;
			}
			finally
			{
				if (dbConnection.State == ConnectionState.Open)
				{
					dbConnection.Close();
				}
			}
		}
		return idNamePair;
	}

