	public string SaveReportFilter(uint iReportId, _Filter[] arrFilter, int iUserId, int iCompanyId)
	{
		DbConnection dbConnection = null;
		DbTransaction dbTransaction = null;
		DbCommand dbCommand = null;
		string text = null;
		m_iCompanyId = iCompanyId;
		m_objDatabase = DatabaseWrapper.GetDatabase2(m_iCompanyId);
		using (dbConnection = m_objDatabase.CreateConnection())
		{
			dbConnection.Open();
			try
			{
				dbTransaction = dbConnection.BeginTransaction();
				string suffix = FConvert.GetSuffix(iCompanyId);
				text = $"DELETE FROM cCore_ReportUser{suffix} WHERE iReportId = {iReportId} AND iUserId = {iUserId} AND (bTemplate IS NULL OR bTemplate = 0)";
				ExecuteNonQuery(text, dbTransaction);
				if (arrFilter != null && arrFilter.Length != 0)
				{
					text = $"INSERT INTO cCore_ReportUser{suffix} (iReportId, iUserId, bTemplate) VALUES ({iReportId}, {iUserId}, 0); SELECT @@IDENTITY;";
					dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
					iReportId = Convert.ToUInt32(m_objDatabase.ExecuteScalar(dbCommand, dbTransaction));
				}
				if (arrFilter != null)
				{
					SaveReportFilter((int)iReportId, arrFilter, _FilterType.Report, dbTransaction);
				}
				dbTransaction.Commit();
			}
			catch (Exception ex)
			{
				dbTransaction.Rollback();
				return ex.Message;
			}
		}
		return string.Empty;
	}

