	public IdValuePair[] LoadReportFilterTemplate(int iUserId, int iCompanyId)
	{
		int num = -1;
		string text = null;
		Database database = null;
		IDataReader dataReader = null;
		_Filter filter = null;
		List<_Filter> list = null;
		List<IdValuePair> list2 = null;
		try
		{
			list2 = new List<IdValuePair>();
			database = DatabaseWrapper.GetDatabase2(iCompanyId);
			text = string.Format("SELECT iReportId, iFilterId, iFieldId, iOperator, sValue, ISNULL(sCompareText,'')[sCompareText], iConjunction, ISNULL(iCompareWith,0)[iCompareWith], iType, ISNULL(iDataType,0)[iDataType], ISNULL(iSubParentId, 0)iSubParentId, ISNULL(bGroup,0) [bGroup]\r\n                FROM cCore_ReportFilter{0} \r\n                JOIN cCore_ReportUser{0} ON cCore_ReportUser{0}.iFilterGroupId = cCore_ReportFilter{0}.iFilterGroupId\r\n                WHERE iType = {1} AND iUserId = {2} AND bTemplate = 1\r\n                ORDER BY  iReportId", FConvert.GetSuffix(iCompanyId), 5, iUserId);
			using (DbCommand command = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text))
			{
				dataReader = database.ExecuteReader(command);
				list = new List<_Filter>();
				while (dataReader.Read())
				{
					if (num > 0 && Convert.ToInt32(dataReader["iReportId"]) != num)
					{
						list2.Add(new IdValuePair(num, list.ToArray()));
						list.Clear();
					}
					filter = new _Filter();
					filter.FilterId = Convert.ToInt32(dataReader["iFilterId"]);
					filter.FieldId = Convert.ToInt32(dataReader["iFieldId"]);
					filter.Operator = (Operator)Convert.ToInt32(dataReader["iOperator"]);
					filter.CompareValue = Convert.ToString(dataReader["sValue"]);
					filter.CompareText = Convert.ToString(dataReader["sCompareText"]);
					filter.Conjuction = (Conjuction)Convert.ToInt32(dataReader["iConjunction"]);
					filter.CompareWith = (Focus.Common.DataStructs.CompareWith)Convert.ToInt32(dataReader["iCompareWith"]);
					filter.FilterType = (_FilterType)Convert.ToInt32(dataReader["iType"]);
					filter.DataType = (MasterDataType)Convert.ToInt32(dataReader["iDataType"]);
					filter.SubParentId = Convert.ToInt32(dataReader["iSubParentId"]);
					filter.IsGroup = Convert.ToBoolean(dataReader["bGroup"]);
					num = Convert.ToInt32(dataReader["iReportId"]);
					list.Add(filter);
				}
				dataReader.Close();
			}
			if (num > 0 && list.Count > 0)
			{
				list2.Add(new IdValuePair(num, list.ToArray()));
			}
		}
		catch (Exception ex)
		{
			list2.Add(new IdValuePair(-1, ex.Message));
		}
		return list2.ToArray();
	}

