	private uint SaveReports(uint iReportId, string sReportName, string sRemarks, Module objModule, ReportType objReportType, int iMenuGroupId, DbTransaction objTran, int iSourceType, int iCreatedBy, int iModifedBy, bool bAdvanceEngine, bool bDelayFetch, bool bNewData)
	{
