			}
			text = $"INSERT INTO cCore_Reports{suffix} (iReportId, sReportName, iModule, iReportType, iSourceType, iCreatedDate, iCreatedBy, iModifiedBy, bAdvance, bDelayFetch, sRemarks)\r\n                        VALUES ({iReportId}, N'{sReportName}', {(byte)objModule}, {(byte)objReportType}, {iSourceType}, {new Date().GetToday(m_objCalType).Value}, {iCreatedBy}, {iModifedBy}, {(bAdvanceEngine ? 1 : 0)}, {(bDelayFetch ? 1 : 0)}, N'{sRemarks}')";
			dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			m_objDatabase.ExecuteNonQuery(dbCommand, objTran);
			if (iMenuGroupId > 0)
			{
				text = $"SELECT ISNULL(MAX(iMenuIndex),0)+1[iMenuIndex] FROM mCore_Menu WHERE iMenuGroupId={iMenuGroupId}";
				dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				num2 = Convert.ToInt32(m_objDatabase.ExecuteScalar(dbCommand, objTran));
				text = $"SELECT iLanguageId FROM cCore_LanguageSupported";
				dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				dataReader = m_objDatabase.ExecuteReader(dbCommand);
				list = new List<int>();
				while (dataReader.Read())
				{
					list.Add(Convert.ToInt32(dataReader[0]));
				}
				dataReader.Close();
				if (list.Count == 0)
				{
					list.Add(0);
				}
				text = string.Format("INSERT INTO mCore_Menu(iMenuId,sMenuName,sMenuText,iMenuGroupId,iMenuIndex,iType,iTypeId,bGroup)\r\n                    VALUES({0}, 'mnuRD{1}', '{2}', {3}, {4}, 5, {0}, 0);\r\n                    INSERT INTO mSec_MenuSpecificRights (iMenuId, iActionId) \r\n                    VALUES ({0},1);\r\n                    --by rasool\r\n                    insert into mCore_MenuTreeDetails (iTreeId,iMenuId,iMenuGroupId,iMenuIndex) values(0,{0},{3},{4});", iReportId, FConvert.GetValidName(text2), text2, iMenuGroupId, num2);
				for (num = 0; num < list.Count; num++)
				{
					text += $" INSERT INTO cCore_MenuLanguages VALUES ({iReportId},{list[num]},N'{text2}');";
				}
				dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				m_objDatabase.ExecuteNonQuery(dbCommand, objTran);
				if (iCreatedBy > 1)
				{
					List<int> list2 = new List<int>
					{
						1, 5, 7, 11, 13, 24, 25, 26, 27, 47,
						77, 207, 208, 209, 210, 211
					};
					text = $"SELECT iProfileId FROM mSec_RolesProfiles a \r\n                        join mSec_Users_Roles r ON r.iERPRole = a.iRoleId WHERE r.iUserId = {iCreatedBy} and r.iYearId = 0";
					int num3 = Convert.ToInt32(m_objDatabase.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
					text = string.Empty;
					for (num = 0; num < list2.Count; num++)
					{
