					}
					dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
					m_objDatabase.ExecuteNonQuery(dbCommand, objTran);
				}
			}
		}
		else
		{
			text = string.Format("UPDATE cCore_Reports{0} SET sReportName = N'{1}', iModule = {2}, \r\n                        iReportType = {3}, iSourceType = {4}, iModifiedDate = {5}, iModifiedBy={6}, bAdvance = {7}, bDelayFetch = {8}, sRemarks = N'{10}'  \r\n                        WHERE iReportId = {9}", suffix, sReportName, (byte)objModule, (byte)objReportType, iSourceType, new Date().GetToday(m_objCalType).Value, iModifedBy, bAdvanceEngine ? 1 : 0, bDelayFetch ? 1 : 0, iReportId, sRemarks);
