					else
					{
						arrrColumns[num2].ColumnName = arrrColumns[num2].ColumnName.Substring(0, 49);
					}
				}
				if (!string.IsNullOrEmpty(arrrColumns[num2].GroupName))
				{
					arrrColumns[num2].GroupName = arrrColumns[num2].GroupName.Replace("'", "''");
				}
				if (arrrColumns[num2].ColumnFont != null && arrrColumns[num2].ColumnFont.Length != 0)
				{
					text = string.Format("INSERT INTO cCore_ReportColumns{0}\r\n                        (iLayoutId, iFieldId, sColumn, sAliasName, sGroupName, \r\n                        fColumnWidth, iMiscOption, iAlignment, iParentId, iSubParentId, \r\n                        iType, sFormula, sToolTip, sFormat, iDecimalInColumn, byFont) \r\n                        VALUES ({1}, {2}, N'{3}', @sAliasName, @sGroupName, \r\n                        {6}, {7}, {8}, {9}, {10}, \r\n                        {11}, @sFormula, @sToolTip, @sFormat, {15}, @Font); SELECT @@IDENTITY;", FConvert.GetSuffix(m_iCompanyId), iLayoutId, arrrColumns[num2].FieldId, arrrColumns[num2].ColumnName, arrrColumns[num2].AliasName, arrrColumns[num2].GroupName, arrrColumns[num2].ColumnWidth, arrrColumns[num2].Miscelleneous, arrrColumns[num2].ColumnAlignment, arrrColumns[num2].ParentId, arrrColumns[num2].SubParentId, Convert.ToInt32(arrrColumns[num2].DataTypeId), arrrColumns[num2].Formula, arrrColumns[num2].ColumnToolTip, arrrColumns[num2].Format, arrrColumns[num2].DecimalInColumn);
					dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
					m_objDatabase.AddInParameter(dbCommand, "@Font", DbType.Binary, arrrColumns[num2].ColumnFont);
				}
				else
				{
					text = string.Format("INSERT INTO cCore_ReportColumns{0}\r\n                        (iLayoutId, iFieldId, sColumn, sAliasName, sGroupName, \r\n                        fColumnWidth, iMiscOption, iAlignment, iParentId, iSubParentId, \r\n                        iType, sFormula, sToolTip, sFormat, iDecimalInColumn) \r\n                        VALUES ({1}, {2}, N'{3}', @sAliasName, @sGroupName, \r\n                        {6}, {7}, {8}, {9}, {10}, \r\n                        {11}, @sFormula, @sToolTip, @sFormat, {15}); SELECT @@IDENTITY;", FConvert.GetSuffix(m_iCompanyId), iLayoutId, arrrColumns[num2].FieldId, arrrColumns[num2].ColumnName, arrrColumns[num2].AliasName, arrrColumns[num2].GroupName, arrrColumns[num2].ColumnWidth, arrrColumns[num2].Miscelleneous, arrrColumns[num2].ColumnAlignment, arrrColumns[num2].ParentId, arrrColumns[num2].SubParentId, Convert.ToInt32(arrrColumns[num2].DataTypeId), arrrColumns[num2].Formula, arrrColumns[num2].ColumnToolTip, arrrColumns[num2].Format, arrrColumns[num2].DecimalInColumn);
					dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				}
				m_objDatabase.AddInParameter(dbCommand, "@sAliasName", DbType.String, arrrColumns[num2].AliasName);
				m_objDatabase.AddInParameter(dbCommand, "@sGroupName", DbType.String, arrrColumns[num2].GroupName);
				m_objDatabase.AddInParameter(dbCommand, "@sFormula", DbType.String, arrrColumns[num2].Formula);
				m_objDatabase.AddInParameter(dbCommand, "@sToolTip", DbType.String, arrrColumns[num2].ColumnToolTip);
				m_objDatabase.AddInParameter(dbCommand, "@sFormat", DbType.String, arrrColumns[num2].Format);
				num = Convert.ToInt32(m_objDatabase.ExecuteScalar(dbCommand, objTran));
				SaveColumnFunction(num, arrrColumns[num2].ColumnFunction, arrrColumns[num2].SQLFunction, objTran);
				SaveReportFilter(num, arrrColumns[num2].ColumnFilter, _FilterType.Column, objTran);
				SaveColumnOrder(num, arrrColumns[num2].ColumnOrder, 1, objTran);
			}
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
			throw;
		}
	}

	private void SaveColumnFunction(int iColumnId, _ColumnFunction objColumnFunction, string sSqlFunction, DbTransaction objTran)
	{
		string text = null;
		if (objColumnFunction != null && objColumnFunction.Function != AggregateFunction.None)
		{
			text = $"INSERT INTO cCore_ReportColumnsFunction{FConvert.GetSuffix(m_iCompanyId)}\r\n                (iColumnId,sValue,iType) VALUES({iColumnId}, {(byte)objColumnFunction.Function}, {(byte)objColumnFunction.FunctionType})";
			ExecuteNonQuery(text, objTran);
		}
		if (!string.IsNullOrEmpty(sSqlFunction))
		{
			text = string.Format("INSERT INTO cCore_ReportColumnsFunction{0}\r\n                (iColumnId,sValue,iType) VALUES({1}, '{2}', {3})", FConvert.GetSuffix(m_iCompanyId), iColumnId, sSqlFunction.Replace("'", "''"), 3);
			ExecuteNonQuery(text, objTran);
		}
	}

	private void SaveColumnOrder(int iColumnId, _ColumnOrder objColumnOrder, byte iLinkType, DbTransaction objTran)
	{
		string text = null;
		DeleteColumnOrder(iColumnId, iLinkType, objTran);
		if (objColumnOrder != null)
		{
			text = $"INSERT INTO cCore_ReportColumnsOrder{FConvert.GetSuffix(m_iCompanyId)}\r\n                (iColumnId,bAscending,iOrderBy,iLinkType) VALUES({iColumnId}, {(objColumnOrder.IsAscending ? ((byte)1) : ((byte)0))}, {objColumnOrder.OrderBy}, {iLinkType})";
			ExecuteNonQuery(text, objTran);
		}
	}

	private void SaveRdQuery(_Reports objReport, DbTransaction objTran, bool bNewData)
	{
		string text = null;
		if (objReport != null && objReport.RDQuery != null)
		{
			text = (bNewData ? string.Format("INSERT INTO cCore_RDQuery{0}\r\n                            (iReportId,iSecurityType,sSqlQuery, sConnection) VALUES ({1},{2}, @Query, @Connection)", FConvert.GetSuffix(m_iCompanyId), objReport.ReportId, Convert.ToByte(objReport.RDQuery.SecurityType), objReport.RDQuery.SqlQuery, objReport.RDQuery.ConnectionString) : string.Format("UPDATE cCore_RDQuery{0} SET iSecurityType = {1}, sSqlQuery = @Query, sConnection = @Connection \r\n                        WHERE iReportId = {4}", FConvert.GetSuffix(m_iCompanyId), Convert.ToByte(objReport.RDQuery.SecurityType), objReport.RDQuery.SqlQuery, objReport.RDQuery.ConnectionString, objReport.ReportId));
			DbCommand sqlStringCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			m_objDatabase.AddInParameter(sqlStringCommand, "@Query", DbType.String, objReport.RDQuery.SqlQuery);
			m_objDatabase.AddInParameter(sqlStringCommand, "@Connection", DbType.String, objReport.RDQuery.ConnectionString);
			m_objDatabase.ExecuteNonQuery(sqlStringCommand, objTran);
		}
	}

	public string updateLayoutColumn(int iColumnId, IdValuePair[] arrFields, int iCompanyId)
	{
		int num = 0;
		string text = null;
		string result = string.Empty;
		Database database = null;
		DbCommand dbCommand = null;
		List<IdNamePair> list = new List<IdNamePair>();
		try
		{
			if (arrFields != null && arrFields.Length != 0 && iColumnId > 0)
			{
				text = $"UPDATE cCore_ReportColumns{FConvert.GetSuffix(m_iCompanyId)} SET ";
				for (num = 0; num < arrFields.Length; num++)
				{
					if (num > 0)
					{
						text += ", ";
					}
					switch ((ColumnFieldType)arrFields[num].ID)
					{
					case ColumnFieldType.AliasName:
						text += "sAliasName = @sAliasName";
						list.Add(new IdNamePair(arrFields[num].ID, "@sAliasName", arrFields[num].Value));
						break;
					case ColumnFieldType.ToolTip:
						text += "sToolTip = @sToolTip";
						list.Add(new IdNamePair(arrFields[num].ID, "@sToolTip", arrFields[num].Value));
						break;
					case ColumnFieldType.Width:
						text += $"fColumnWidth = {arrFields[num].Value}";
						break;
					case ColumnFieldType.DataTypeId:
						text += $"iType = {arrFields[num].Value}";
						break;
					case ColumnFieldType.DecimalInColumn:
						text += $"iDecimalInColumn = {arrFields[num].Value}";
						break;
					case ColumnFieldType.Format:
						text += "sFormat = @sFormat";
						list.Add(new IdNamePair(arrFields[num].ID, "@sFormat", arrFields[num].Value));
						break;
					case ColumnFieldType.Formula:
						text += "sFormula = @sFormula";
						list.Add(new IdNamePair(arrFields[num].ID, "@sFormula", arrFields[num].Value));
						break;
					case ColumnFieldType.GroupName:
						text += "sGroupName = @sGroupName";
						list.Add(new IdNamePair(arrFields[num].ID, "@sGroupName", arrFields[num].Value));
						break;
					case ColumnFieldType.Alignment:
						text += $"iAlignment = {arrFields[num].Value}";
						break;
					case ColumnFieldType.Miscellaneous:
						text += $"iMiscOption = {arrFields[num].Value}";
						break;
					}
				}
				text += $" WHERE iColumnId = {iColumnId}";
				database = DatabaseWrapper.GetDatabase2(iCompanyId);
				dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				for (num = 0; num < list.Count; num++)
				{
					database.AddInParameter(dbCommand, list[num].Name, DbType.String, list[num].Tag);
				}
				database.ExecuteNonQuery(dbCommand);
			}
			else
			{
				result = "No valid data exist";
			}
		}
		catch (Exception ex)
		{
			result = ex.Message;
		}
		return result;
	}

	public string UpdateLayoutColumns(_Column[] arColumns, int iLayoutId, int iCompanyId)
	{
		int iCol = 0;
		string text = string.Empty;
		List<IdValuePair> list = null;
		_Column column = null;
		try
		{
			_Column[] source = LoadColumns(iLayoutId, IsAnalyzeTypeReport: false, DataSourceType.Reports, iCompanyId);
			if (arColumns != null && arColumns.Length != 0)
			{
				for (iCol = 0; iCol < arColumns.Length; iCol++)
				{
					list = new List<IdValuePair>();
					column = source.Where((_Column a) => a.ColumnId == arColumns[iCol].ColumnId).SingleOrDefault();
					if (arColumns[iCol].AliasName != column.AliasName)
					{
						list.Add(new IdValuePair(1, arColumns[iCol].AliasName));
					}
					if (arColumns[iCol].ColumnToolTip != column.ColumnToolTip)
					{
						list.Add(new IdValuePair(6, arColumns[iCol].ColumnToolTip));
					}
					if (arColumns[iCol].ColumnWidth != column.ColumnWidth)
					{
						list.Add(new IdValuePair(7, arColumns[iCol].ColumnWidth));
					}
					if (Convert.ToInt32(arColumns[iCol].DataTypeId) != Convert.ToInt32(column.DataTypeId))
					{
						list.Add(new IdValuePair(8, arColumns[iCol].DataTypeId));
					}
					if (Convert.ToByte(arColumns[iCol].DecimalInColumn) != Convert.ToByte(column.DecimalInColumn))
					{
						list.Add(new IdValuePair(9, Convert.ToByte(arColumns[iCol].DecimalInColumn)));
					}
					if (Convert.ToString(arColumns[iCol].Format) != Convert.ToString(column.Format))
					{
						list.Add(new IdValuePair(10, arColumns[iCol].Format));
					}
					if (Convert.ToString(arColumns[iCol].Formula) != Convert.ToString(column.Formula))
					{
						list.Add(new IdValuePair(11, arColumns[iCol].Formula));
					}
					if (Convert.ToString(arColumns[iCol].GroupName) != Convert.ToString(column.GroupName))
					{
						list.Add(new IdValuePair(12, arColumns[iCol].GroupName));
					}
					if (arColumns[iCol].Miscelleneous != column.Miscelleneous)
					{
						list.Add(new IdValuePair(28, arColumns[iCol].Miscelleneous));
					}
					if (arColumns[iCol].ColumnAlignment != column.ColumnAlignment)
					{
						list.Add(new IdValuePair(27, arColumns[iCol].ColumnAlignment));
					}
					text += updateLayoutColumn(arColumns[iCol].ColumnId, list.ToArray(), iCompanyId);
				}
			}
		}
		catch (Exception ex)
		{
			text = ex.Message;
		}
		return text;
	}

	public string DeleteLayoutColumns(int[] arColumnIds, int iLayoutId, int iCompanyId)
	{
		DbCommand dbCommand = null;
		string empty = string.Empty;
		try
		{
			Database database = DatabaseWrapper.GetDatabase2(iCompanyId);
			empty = string.Format("DELETE FROM cCore_ReportColumns{0} WHERE iLayoutId = {1} AND iColumnId in ({2})", FConvert.GetSuffix(iCompanyId), iLayoutId, string.Join(",", arColumnIds.Select((int p) => p)));
			dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			database.ExecuteNonQuery(dbCommand);
		}
		catch (Exception ex)
		{
			return ex.Message;
		}
		finally
		{
			if (dbCommand != null && dbCommand.Connection != null && dbCommand.Connection.State != ConnectionState.Closed)
			{
				dbCommand.Connection.Close();
			}
		}
		return string.Empty;
	}

	private _Reports LoadReportDefinition(uint iReportId)
	{
		string text = null;
		_Reports reports = null;
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		text = string.Format("SELECT sReportName, ISNULL(sRemarks, '')sRemarks, iModule, iReportType, ISNULL(mCore_Menu.iMenuGroupId, 0)[iMenuGroupId], \r\n                ISNULL(iSourceType,0)[iSourceType],ISNULL(bAdvance,1)[bAdvance], ISNULL(bDelayFetch,0)[bDelayFetch]\r\n                ,ISNULL(iCreatedBy,0)[iCreatedBy],ISNULL(iModifiedBy,0)[iModifiedBy],ISNULL(iCreatedDate,0)[iCreatedDate],ISNULL(iModifiedDate,0)[iModifiedDate]\r\n                FROM cCore_Reports{0} JOIN mCore_Menu ON cCore_Reports{0}.iReportId = mCore_Menu.iTypeId\r\n                WHERE iReportId = {1}", FConvert.GetSuffix(m_iCompanyId), iReportId);
		dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		dbCommand.CommandTimeout = 0;
		dataReader = m_objDatabase.ExecuteReader(dbCommand);
		reports = new _Reports();
		reports.ReportId = iReportId;
		reports.ReportName = string.Empty;
		if (dataReader.Read())
		{
			reports.ReportName = Convert.ToString(dataReader["sReportName"]);
			reports.Remarks = Convert.ToString(dataReader["sRemarks"]);
			reports.Module = (Module)Convert.ToByte(dataReader["iModule"]);
			reports.ReportType = (ReportType)Convert.ToByte(dataReader["iReportType"]);
			reports.MenuGroupId = Convert.ToInt32(dataReader["iMenuGroupId"]);
			reports.DataSourceType = (DataSourceType)Convert.ToInt32(dataReader["iSourceType"]);
			reports.AdvancedEngine = CheckAdvanceEngine(iReportId, Convert.ToBoolean(dataReader["bAdvance"]));
			reports.DelayFetch = Convert.ToBoolean(dataReader["bDelayFetch"]);
			reports.CreatedBy = Convert.ToInt32(dataReader["iCreatedBy"]);
			reports.ModifiedBy = Convert.ToInt32(dataReader["iModifiedBy"]);
			reports.CreatedDate = Convert.ToInt32(dataReader["iCreatedDate"]);
			reports.ModifedDate = Convert.ToInt32(dataReader["iModifiedDate"]);
		}
		dataReader.Close();
		if (string.IsNullOrEmpty(reports.ReportName) && iReportId < RDCommon.RD_STARTID)
		{
			RDDefault rDDefault = new RDDefault();
			reports.ReportName = rDDefault.GetReportName(iReportId);
		}
		reports.Filters = LoadReportFilter((int)iReportId, _FilterType.Report);
		if (reports.DataSourceType == DataSourceType.Excel || reports.DataSourceType == DataSourceType.XML)
		{
			text = $"SELECT sFolderName FROM cCore_RepFolder{FConvert.GetSuffix(m_iCompanyId)} WHERE iReportId = {iReportId}";
			dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dbCommand.CommandTimeout = 0;
			dataReader = m_objDatabase.ExecuteReader(dbCommand);
			if (dataReader.Read())
			{
				reports.RDFolder = new _RDFolder();
				reports.RDFolder.FolderName = Convert.ToString(dataReader["sFolderName"]);
			}
			dataReader.Close();
		}
		return reports;
	}

	private bool CheckAdvanceEngine(uint iReportId, bool bAdvance)
	{
		bAdvance = iReportId < RDCommon.RD_STARTID || true;
		return bAdvance;
	}

	private _Layout LoadReportLayout(uint iReportId, uint iSubReportId, int iLayoutId)
	{
		string text = null;
		bool bDefault = false;
		bool bLandscape = false;
		int iColumnHeadingAlignment = 0;
		string suffix = FConvert.GetSuffix(m_iCompanyId);
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		IdValuePair idValuePair = null;
		_Layout layout = new _Layout();
		layout.InvoiceLayout = new ComboData();
		text = $"SELECT iLayoutId, sLayoutName,ISNULL(iFlag,0)[iFlag], ISNULL(iSubReportId,0)[iSubReportId], ISNULL(bPrintZero, 0)[bPrintZero] \r\n                FROM cCore_ReportLayouts{suffix} WHERE iReportId = {iReportId}";
		if (iLayoutId > 0)
		{
			text += $" AND iLayoutId = {iLayoutId}";
		}
		if (iSubReportId != 0)
		{
			text += $" AND iSubReportId = {iSubReportId}";
		}
		dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		dbCommand.CommandTimeout = 0;
		dataReader = m_objDatabase.ExecuteReader(dbCommand);
		if (dataReader.Read())
		{
			layout.LayoutId = Convert.ToInt32(dataReader["iLayoutId"]);
			layout.LayoutName = Convert.ToString(dataReader["sLayoutName"]);
			layout.IsDefault = Convert.ToBoolean(dataReader["iFlag"]);
			layout.IsPrintZeroValue = Convert.ToBoolean(dataReader["bPrintZero"]);
			layout.SubReportId = Convert.ToInt32(dataReader["iSubReportId"]);
			SetFlagValue(Convert.ToInt64(dataReader["iFlag"]), ref bDefault, ref bLandscape, ref iColumnHeadingAlignment);
			layout.IsDefault = bDefault;
			layout.IsLandscape = bLandscape;
			layout.ColumnHeadingAlignment = iColumnHeadingAlignment;
		}
		dataReader.Close();
		text = $"SELECT iLayoutId, sLayout FROM cCore_InvoiceLayout{suffix} WHERE iReportId = {iReportId}";
		dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		dbCommand.CommandTimeout = 0;
		dataReader = m_objDatabase.ExecuteReader(dbCommand);
		if (dataReader.Read())
		{
			layout.InvoiceLayout.ID = Convert.ToInt32(dataReader["iLayoutId"]);
			layout.InvoiceLayout.Name = Convert.ToString(dataReader["sLayout"]);
		}
		dataReader.Close();
		text = $"SELECT byFont FROM cCore_InvoiceBodyFont{suffix} \r\n                WHERE iHeaderId = {layout.LayoutId} AND iPageId = 0 AND iPageId = 0 AND iFontType = 3";
		dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		dataReader = m_objDatabase.ExecuteReader(dbCommand);
		if (dataReader.Read())
		{
			layout.BodyFont = ((dataReader["byFont"] == DBNull.Value) ? null : ((byte[])dataReader["byFont"]));
		}
		dataReader.Close();
		if (iReportId >= RDCommon.RD_STARTID)
		{
			idValuePair = LoadReportTopClause(layout.LayoutId, 0);
			if (idValuePair != null)
			{
				layout.SelectClause = (_SelectClause)idValuePair.ID;
				layout.ClauseValue = Convert.ToUInt16(idValuePair.Value);
			}
		}
		return layout;
	}

	private _Parameter[] LoadReportparameters(uint iReportId)
	{
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		_Parameter parameter = null;
		string text = null;
		List<_Parameter> list = null;
		list = new List<_Parameter>();
		text = $"SELECT iParameterId, sFieldName, iControlType, iFieldType, iSelectionMode, \r\n                sValue, ISNULL(sDefault,'')[sDefault], ISNULL(iFieldId,0)[iFieldId], ISNULL(sFieldVariable,'@')[sFieldVariable], bGroup\r\n                FROM cCore_ReportParameter{FConvert.GetSuffix(m_iCompanyId)} WHERE iReportId = {iReportId} AND iSelectionMode <> {(byte)3}";
		dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		dbCommand.CommandTimeout = 0;
		dataReader = m_objDatabase.ExecuteReader(dbCommand);
		while (dataReader.Read())
		{
			parameter = new _Parameter();
			parameter.ParameterId = Convert.ToInt32(dataReader["iParameterId"]);
			parameter.FieldName = Convert.ToString(dataReader["sFieldName"]);
			parameter.ControlId = Convert.ToInt32(dataReader["iControlType"]);
			parameter.FieldType = (_FieldType)Convert.ToByte(dataReader["iFieldType"]);
			parameter.SelectionMode = (_SelectionMode)Convert.ToByte(dataReader["iSelectionMode"]);
			parameter.SelectionValue = Convert.ToString(dataReader["sValue"]);
			parameter.IsGroupMaster = parameter.SelectionMode == _SelectionMode.Group;
			parameter.DefaultValue = Convert.ToString(dataReader["sDefault"]);
			parameter.FieldId = Convert.ToInt32(dataReader["iFieldId"]);
			parameter.FieldVariable = Convert.ToString(dataReader["sFieldVariable"]);
			parameter.IsGroupMaster = Convert.ToBoolean(dataReader["bGroup"]);
			if (parameter.ControlId == 6 && parameter.FieldId == 0)
			{
				parameter.FieldId = parameter.ParameterId;
			}
			list.Add(parameter);
		}
		dataReader.Close();
		return list.ToArray();
	}

