				grouping.FieldId = Convert.ToInt32(dataReader["iFieldId"]);
				grouping.SubParentId = Convert.ToInt32(dataReader["iSubParentId"]);
				grouping.ParentId = Convert.ToInt32(dataReader["iParentId"]);
				grouping.GroupingType = (_GroupingType)Convert.ToByte(dataReader["iType"]);
				grouping.OrderBy = Convert.ToByte(dataReader["iOrderBy"]);
				grouping.IsAscending = Convert.ToBoolean(dataReader["bAscending"]);
				grouping.MiscellaneousOptions = Convert.ToInt32(dataReader["iMiscOption"]);
				grouping.DisplayValue = Convert.ToString(dataReader["sGroupValue"]);
				list.Add(grouping);
			}
			dataReader.Close();
			if (list.Count > 0)
			{
				for (num = 0; num < list.Count; num++)
				{
					array = LoadSortingOrder(list[num].FieldId, 2, m_iCompanyId);
					if (array != null && array.Length != 0)
					{
						list[num].Sorting = new IdNamePair[array.Length];
						for (num2 = 0; num2 < array.Length; num2++)
						{
							list[num].Sorting[num2] = new IdNamePair();
							list[num].Sorting[num2].ID = array[num2].OrderId;
							list[num].Sorting[num2].Tag = array[num2].IsAscending;
						}
					}
					list[num].SelectedClause = LoadReportTopClause(list[num].FieldId, 2);
				}
			}
		}
		return list.ToArray();
	}

	public _Column[] LoadColumns(int iLayoutId, bool IsAnalyzeTypeReport, DataSourceType oSourceType, int iCompanyId, int iBaseLayout = 0)
	{
		int num = 0;
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		_Column column = null;
		string text = null;
		List<_Column> list = null;
		list = new List<_Column>();
		if (m_objDatabase == null)
		{
			m_objDatabase = DatabaseWrapper.GetDatabase2(iCompanyId);
		}
		if (string.IsNullOrEmpty(m_strSuffix))
		{
			m_strSuffix = FConvert.GetSuffix(iCompanyId);
		}
		if (IsAnalyzeTypeReport)
		{
			if (iBaseLayout > 0)
			{
				iLayoutId = iBaseLayout;
			}
			else
			{
				text = $"SELECT iLayoutId FROM cCore_ReportLayouts{m_strSuffix} WITH (READUNCOMMITTED)\r\n                        WHERE iReportId = {iLayoutId} ORDER BY CASE WHEN iFlag={GetFlagValue(bDefault: true, bLandscape: false, 0)} OR iFlag IS NULL THEN 0 ELSE 1 END";
				dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				dbCommand.CommandTimeout = 0;
				iLayoutId = Convert.ToInt32(m_objDatabase.ExecuteScalar(dbCommand));
			}
		}
		text = string.Format("SELECT iColumnId, cCore_ReportColumns{0}.iFieldId, sColumn, sAliasName, sGroupName, fColumnWidth, \r\n            iMiscOption, iAlignment, iParentId, iSubParentId, iType[iDataTypeId], sFormula, ISNULL(byFont,0x)[byFont], sToolTip, sFormat, ISNULL(iDecimalInColumn,0)[iDecimalInColumn]\r\n            FROM cCore_ReportColumns{0} WHERE iLayoutId = {1} ORDER BY {2}", m_strSuffix, iLayoutId, (oSourceType == DataSourceType.Query) ? "iFieldId" : "iColumnId");
		dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		dbCommand.CommandTimeout = 0;
		dataReader = m_objDatabase.ExecuteReader(dbCommand);
		while (dataReader.Read())
		{
			column = new _Column();
			column.ColumnId = Convert.ToInt32(dataReader["iColumnId"]);
			column.FieldId = Convert.ToInt32(dataReader["iFieldId"]);
			column.ColumnName = Convert.ToString(dataReader["sColumn"]);
			column.AliasName = Convert.ToString(dataReader["sAliasName"]);
			column.GroupName = Convert.ToString(dataReader["sGroupName"]);
			column.ColumnWidth = Convert.ToDouble(dataReader["fColumnWidth"]);
			column.Miscelleneous = Convert.ToInt32(dataReader["iMiscOption"]);
			column.ColumnAlignment = Convert.ToInt32(dataReader["iAlignment"]);
			column.ParentId = Convert.ToInt32(dataReader["iParentId"]);
			column.SubParentId = Convert.ToInt32(dataReader["iSubParentId"]);
			column.DataTypeId = (MasterDataType)Convert.ToInt32(dataReader["iDataTypeId"]);
			if (column.FieldId == -2)
			{
				column.Formula = Convert.ToString(dataReader["sFormula"]);
			}
			column.ColumnToolTip = Convert.ToString(dataReader["sToolTip"]);
			column.Format = Convert.ToString(dataReader["sFormat"]);
			column.ColumnFont = (byte[])dataReader["byFont"];
			column.DecimalInColumn = Convert.ToByte(dataReader["iDecimalInColumn"]);
			if (column.DecimalInColumn == 0)
			{
				column.DecimalInColumn = RDCommon.GetDecimalInColumn(column.ColumnAlignment);
			}
			list.Add(column);
		}
		dataReader.Close();
		if (list.Count > 0 && iLayoutId > 0)
		{
			text = string.Format("SELECT RC.iColumnId\r\n                , CF.iFunctionId, CF.sValue[sFValue], CF.iType[iFType], CO.iOrderId, CO.bAscending, CO.iOrderBy\r\n                , RF.iFilterId, RF.iFieldId, RF.iOperator, RF.sValue, RF.sCompareText, RF.iConjunction, RF.iCompareWith\r\n                , RF.iType, RF.iDataType, RF.iSubParentId, RF.bGroup, RF.iFilterGroupId\r\n                FROM cCore_ReportColumns{0} RC\r\n                LEFT JOIN cCore_ReportColumnsFunction{0} CF ON CF.iColumnId = RC.iColumnId \r\n                LEFT JOIN cCore_ReportColumnsOrder{0} CO ON CO.iColumnId = RC.iColumnId \r\n                LEFT JOIN cCore_ReportFilter{0} RF ON RF.iFilterGroupId = RC.iColumnId AND RF.iType = 1\r\n                WHERE RC.iLayoutId = {1}", m_strSuffix, iLayoutId);
			dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dbCommand.CommandTimeout = 0;
			dataReader = m_objDatabase.ExecuteReader(dbCommand);
			List<_Filter> list2 = new List<_Filter>();
			while (dataReader.Read())
			{
				for (num = 0; num < list.Count; num++)
				{
					if (list[num].ColumnId != Convert.ToInt32(dataReader["iColumnId"]))
					{
						continue;
					}
					if (dataReader["iFType"] != DBNull.Value)
					{
						if ((byte)Convert.ToInt32(dataReader["iFType"]) == 3)
						{
							list[num].SQLFunction = Convert.ToString(dataReader["sFValue"]);
						}
						else
						{
							list[num].ColumnFunction = new _ColumnFunction();
							list[num].ColumnFunction.FunctionId = Convert.ToInt32(dataReader["iFunctionId"]);
							list[num].ColumnFunction.FunctionType = (_FunctionType)Convert.ToInt32(dataReader["iFType"]);
							list[num].ColumnFunction.Function = (AggregateFunction)Convert.ToInt32(dataReader["sFValue"]);
						}
					}
					if (dataReader["iOrderId"] != DBNull.Value)
					{
						list[num].ColumnOrder = new _ColumnOrder();
						list[num].ColumnOrder.OrderId = Convert.ToInt32(dataReader["iOrderId"]);
						list[num].ColumnOrder.IsAscending = Convert.ToBoolean(dataReader["bAscending"]);
						list[num].ColumnOrder.OrderBy = Convert.ToByte(dataReader["iOrderBy"]);
					}
					if (dataReader["iFilterId"] != DBNull.Value)
					{
						if (list[num].ColumnFilter != null && list[num].ColumnFilter.Length != 0)
						{
							list2.Clear();
							list2.AddRange(list[num].ColumnFilter);
						}
						_Filter filter = new _Filter();
						filter.FilterGroupId = Convert.ToInt32(dataReader["iFilterGroupId"]);
						filter.FilterId = Convert.ToInt32(dataReader["iFilterId"]);
						filter.FieldId = Convert.ToInt32(dataReader["iFieldId"]);
						filter.Operator = (Operator)Convert.ToInt32(dataReader["iOperator"]);
						filter.CompareValue = Convert.ToString(dataReader["sValue"]);
						filter.CompareText = Convert.ToString(dataReader["sCompareText"]);
						filter.Conjuction = (Conjuction)Convert.ToInt32(dataReader["iConjunction"]);
						filter.CompareWith = (Focus.Common.DataStructs.CompareWith)Convert.ToInt32(dataReader["iCompareWith"]);
						filter.FilterType = (_FilterType)Convert.ToInt32(dataReader["iType"]);
						filter.DataType = (MasterDataType)Convert.ToInt32(dataReader["iDataType"]);
						filter.SubParentId = Convert.ToInt32(dataReader["iSubParentId"]);
						filter.IsGroup = Convert.ToBoolean(dataReader["bGroup"]);
						list2.Add(filter);
						list[num].ColumnFilter = list2.ToArray();
						list2.Clear();
					}
					break;
				}
			}
			dataReader.Close();
		}
		return list.ToArray();
	}

