	public IdNamePair[] GetAnalyzeReports(int iUserId, int iCompanyId)
	{
		Database database = null;
		IDataReader dataReader = null;
		List<IdNamePair> list = null;
		try
		{
			list = new List<IdNamePair>();
			database = DatabaseWrapper.GetDatabase2(iCompanyId);
			string text = string.Format("SELECT iVoucherType, sReportName, cCore_Reports{0}.iReportId FROM cCore_Reports{0} \r\n                JOIN cCore_ReportTransactionSet{0} ON cCore_ReportTransactionSet{0}.iReportId = cCore_Reports{0}.iReportId\r\n                WHERE iSourceType = {1} ORDER BY iVoucherType", FConvert.GetSuffix(iCompanyId), 5);
			using DbCommand command = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dataReader = database.ExecuteReader(command);
			while (dataReader.Read())
			{
				list.Add(new IdNamePair(Convert.ToInt32(dataReader["iVoucherType"]), Convert.ToString(dataReader["sReportName"]), Convert.ToInt32(dataReader["iReportId"])));
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			list.Add(new IdNamePair(-1, ex.Message));
		}
		return list.ToArray();
	}

