	private void DeleteColumnDependenData(int iLayoutId, DbTransaction objTran)
	{
		string text = string.Empty;
		string text2 = $"SELECT iColumnId FROM cCore_ReportColumns{FConvert.GetSuffix(m_iCompanyId)} WHERE iLayoutId={iLayoutId}";
		DbCommand sqlStringCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text2) : text2);
		IDataReader dataReader = m_objDatabase.ExecuteReader(sqlStringCommand);
		while (dataReader.Read())
		{
			text += string.Format("{0}{1}", (text.Length > 0) ? ',' : ' ', dataReader["iColumnId"]);
		}
		dataReader.Close();
		if (text.Length > 0)
		{
			text2 = string.Format("DELETE FROM cCore_ReportColumnsFilter{0} WHERE iColumnId IN ({1});\r\n                    DELETE FROM cCore_ReportColumnsOrder{0} WHERE iColumnId IN ({1});\r\n                    DELETE FROM cCore_ReportColumnsFunction{0} WHERE iColumnId IN ({1})\r\n                    DELETE FROM cCore_ReportColumns{0} WHERE iColumnId IN ({1})", FConvert.GetSuffix(m_iCompanyId), text);
			ExecuteNonQuery(text2, objTran);
		}
	}

	private int ExecuteNonQuery(string strQuery, DbTransaction objTran)
	{
		DbCommand dbCommand = null;
		dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(strQuery) : strQuery);
		if (objTran == null)
		{
			return m_objDatabase.ExecuteNonQuery(dbCommand);
		}
		return m_objDatabase.ExecuteNonQuery(dbCommand, objTran);
	}

	private long GetFlagValue(bool bDefault, bool bLandscape, int iColumnHeadingAlignment)
	{
		return (int)(((bLandscape ? 1u : 0u) << 1) | (bDefault ? 1u : 0u)) | (iColumnHeadingAlignment << 4);
	}

	private void SetFlagValue(long iValue, ref bool bDefault, ref bool bLandscape, ref int iColumnHeadingAlignment)
	{
		bDefault = Convert.ToBoolean(iValue & 1);
		bLandscape = Convert.ToBoolean(iValue & 2);
		iColumnHeadingAlignment = Convert.ToInt32(iValue >> 4);
	}

	public string CopyFileToServer(string sReportName, string sModule, bool IsExcel, string sExt, byte[] arrData)
	{
		try
		{
			string serverFilePath = General.GetServerFilePath(sReportName, sModule, IsExcel, sExt);
			if (arrData == null)
			{
				FileInfo fileInfo = new FileInfo(serverFilePath);
				if (fileInfo.Exists)
				{
					fileInfo.Delete();
				}
			}
			else
			{
				FileStream fileStream = new FileStream(serverFilePath, FileMode.Append, FileAccess.Write);
				BinaryWriter binaryWriter = new BinaryWriter(fileStream);
				binaryWriter.Write(arrData);
				binaryWriter.Close();
				fileStream.Close();
			}
		}
		catch (Exception ex)
		{
			return ex.Message;
		}
		return string.Empty;
	}

