	public string SaveProvisionalData(ProvisionalEntryHeader objHeader, int iCompId)
	{
		DbConnection dbConnection = null;
		DbTransaction dbTransaction = null;
		DbCommand dbCommand = null;
		string empty = string.Empty;
		string empty2 = string.Empty;
		int num = 0;
		int num2 = 0;
		bool flag = false;
		try
		{
			m_objDatabase = DatabaseWrapper.GetDatabase2(iCompId);
			dbConnection = m_objDatabase.CreateConnection();
			dbConnection.Open();
			dbTransaction = dbConnection.BeginTransaction();
			if (CheckDatewiseData(objHeader.Date, iCompId) == 0 || (objHeader.ProvisionalBody != null && objHeader.ProvisionalBody.Length != 0) || objHeader.IsIncludeDepriciation || objHeader.IsOpeningStockValue || objHeader.OpeningDebitAccount > 0 || objHeader.OpeningCreditAccount > 0 || objHeader.IsClosingStockValue || objHeader.ClosingDebitAccount > 0 || objHeader.ClosingCreditAccount > 0 || objHeader.IsUnrealizedGainOrLoss || objHeader.IsUnrealizedForexGainOrLoss || objHeader.IsRealizedForexGainOrLoss || objHeader.UnrealizedAccount > 0)
			{
				flag = true;
			}
			if (flag)
			{
				empty = $"INSERT INTO cCore_ProvisionalEntryHeader{FConvert.GetSuffix(m_iCompanyId)}( iDate, bDisableProvisionalEntry, bIncludeDepriciation, bOpeningStockValue, iOpeningDebitAccount, iOpeningCreditAccount, bClosingStockValue, iClosingDebitAccount, iClosingCreditAccount, bUnrealizedGainOrLoss, bUnrealizedForexGainOrLoss, bRealizedForexGainOrLoss, iUnrealizedAccount )\r\n                                            VALUES ( {objHeader.Date}, {(objHeader.IsDisableProvisionalEntry ? 1 : 0)}, {(objHeader.IsIncludeDepriciation ? 1 : 0)}, {(objHeader.IsOpeningStockValue ? 1 : 0)}, {objHeader.OpeningDebitAccount}, {objHeader.OpeningCreditAccount}, {(objHeader.IsClosingStockValue ? 1 : 0)}, {objHeader.ClosingDebitAccount}, {objHeader.ClosingCreditAccount}, {(objHeader.IsUnrealizedGainOrLoss ? 1 : 0)}, {(objHeader.IsUnrealizedForexGainOrLoss ? 1 : 0)}, {(objHeader.IsRealizedForexGainOrLoss ? 1 : 0)}, {objHeader.UnrealizedAccount} )SELECT @@IDENTITY;";
				dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
				num2 = Convert.ToInt32(m_objDatabase.ExecuteScalar(dbCommand, dbTransaction));
				if (objHeader.ProvisionalBody != null)
				{
					for (num = 0; num < objHeader.ProvisionalBody.Length; num++)
					{
						empty = $"INSERT INTO cCore_ProvisionalEntryBody{FConvert.GetSuffix(m_iCompanyId)} ( iReportId, iAccount, iFATag, mAmount )\r\n                                                VALUES ( {num2}, {objHeader.ProvisionalBody[num].Account}, {objHeader.ProvisionalBody[num].FATag}, {objHeader.ProvisionalBody[num].Amount} )";
						dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
						m_objDatabase.ExecuteNonQuery(dbCommand, dbTransaction);
					}
				}
			}
			dbTransaction.Commit();
			return empty2;
		}
		catch (Exception ex)
		{
			empty2 = ex.Message;
			dbTransaction.Rollback();
			return empty2;
		}
		finally
		{
			if (dbConnection.State == ConnectionState.Open)
			{
				dbConnection.Close();
			}
		}
	}

	public ProvisionalEntryHeader LoadProvisionalData(ProvisionalType oType, int iValue, int iCompId)
	{
		string text = string.Empty;
		string suffix = FConvert.GetSuffix(iCompId);
		bool flag = false;
		ProvisionalEntryHeader provisionalEntryHeader = new ProvisionalEntryHeader();
		ProvisionalEntryBody provisionalEntryBody = null;
		List<ProvisionalEntryBody> list = null;
		list = new List<ProvisionalEntryBody>();
		try
		{
			switch (oType)
			{
			case ProvisionalType.Normal:
				flag = true;
				text = string.Format("SELECT TOP 1 iReportId, iDate, bDisableProvisionalEntry, bIncludeDepriciation, bOpeningStockValue, \r\n                                                iOpeningDebitAccount, OpenDr.sName[OpenDrName],\r\n                                                iOpeningCreditAccount, OpenCr.sName[OpenCrName],\r\n                                                bClosingStockValue, \r\n                                                iClosingDebitAccount, CloseDr.sName[ClosDrName],\r\n                                                iClosingCreditAccount, CloseCr.sName[ClosCrName],\r\n                                                bUnrealizedGainOrLoss, bUnrealizedForexGainOrLoss, bRealizedForexGainOrLoss, \r\n                                                iUnrealizedAccount, UnRealizedAc.sName[UnRealAcName] \r\n                                                FROM cCore_ProvisionalEntryHeader{0} \r\n                                                JOIN mCore_Account OpenDr on cCore_ProvisionalEntryHeader{0}.iOpeningDebitAccount = OpenDr.iMasterId\r\n                                                JOIN mCore_Account OpenCr on cCore_ProvisionalEntryHeader{0}.iOpeningCreditAccount = OpenCr.iMasterId\r\n                                                JOIN mCore_Account CloseDr on cCore_ProvisionalEntryHeader{0}.iClosingDebitAccount = CloseDr.iMasterId\r\n                                                JOIN mCore_Account CloseCr on cCore_ProvisionalEntryHeader{0}.iClosingCreditAccount = CloseCr.iMasterId\r\n                                                JOIN mCore_Account UnRealizedAc on cCore_ProvisionalEntryHeader{0}.iUnrealizedAccount = UnRealizedAc.iMasterId\r\n                                                ORDER BY iReportId DESC", suffix);
				break;
			case ProvisionalType.Recent:
				text = $"SELECT TOP 1 iReportId, iDate, bDisableProvisionalEntry, bIncludeDepriciation, \r\n                                bOpeningStockValue, iOpeningDebitAccount, iOpeningCreditAccount, bClosingStockValue, iClosingDebitAccount, \r\n                                iClosingCreditAccount, bUnrealizedGainOrLoss, bUnrealizedForexGainOrLoss, bRealizedForexGainOrLoss, iUnrealizedAccount \r\n                                            FROM cCore_ProvisionalEntryHeader{suffix} WHERE iReportId < {iValue}  ORDER BY iReportId DESC";
				break;
			case ProvisionalType.Date:
				text = $"SELECT TOP 1 iReportId, iDate, bDisableProvisionalEntry, bIncludeDepriciation, \r\n                            bOpeningStockValue, iOpeningDebitAccount, iOpeningCreditAccount, bClosingStockValue, iClosingDebitAccount, \r\n                            iClosingCreditAccount, bUnrealizedGainOrLoss, bUnrealizedForexGainOrLoss, bRealizedForexGainOrLoss, iUnrealizedAccount \r\n                                            FROM cCore_ProvisionalEntryHeader{suffix} WHERE iDate <= {iValue} ORDER BY iDate DESC";
				break;
			}
			Database database = DatabaseWrapper.GetDatabase2(iCompId);
			DbCommand sqlStringCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			IDataReader dataReader = database.ExecuteReader(sqlStringCommand);
			if (dataReader.Read())
			{
				provisionalEntryHeader.ReportId = Convert.ToInt32(dataReader["iReportId"]);
				provisionalEntryHeader.Date = Convert.ToInt32(dataReader["iDate"]);
				provisionalEntryHeader.IsDisableProvisionalEntry = Convert.ToBoolean(dataReader["bDisableProvisionalEntry"]);
				provisionalEntryHeader.IsIncludeDepriciation = Convert.ToBoolean(dataReader["bIncludeDepriciation"]);
				provisionalEntryHeader.IsOpeningStockValue = Convert.ToBoolean(dataReader["bOpeningStockValue"]);
				provisionalEntryHeader.OpeningDebitAccount = Convert.ToInt32(dataReader["iOpeningDebitAccount"]);
				if (flag)
				{
					provisionalEntryHeader.OpeningDebitAccountName = Convert.ToString(dataReader["OpenDrName"]);
				}
				provisionalEntryHeader.OpeningCreditAccount = Convert.ToInt32(dataReader["iOpeningCreditAccount"]);
				if (flag)
				{
					provisionalEntryHeader.OpeningCreditAccountName = Convert.ToString(dataReader["OpenCrName"]);
				}
				provisionalEntryHeader.IsClosingStockValue = Convert.ToBoolean(dataReader["bClosingStockValue"]);
				provisionalEntryHeader.ClosingDebitAccount = Convert.ToInt32(dataReader["iClosingDebitAccount"]);
				if (flag)
				{
					provisionalEntryHeader.ClosingDebitAccountName = Convert.ToString(dataReader["ClosDrName"]);
				}
				provisionalEntryHeader.ClosingCreditAccount = Convert.ToInt32(dataReader["iClosingCreditAccount"]);
				if (flag)
				{
					provisionalEntryHeader.ClosingCreditAccountName = Convert.ToString(dataReader["ClosCrName"]);
				}
				provisionalEntryHeader.IsUnrealizedGainOrLoss = Convert.ToBoolean(dataReader["bUnrealizedGainOrLoss"]);
				provisionalEntryHeader.IsUnrealizedForexGainOrLoss = Convert.ToBoolean(dataReader["bUnrealizedForexGainOrLoss"]);
				provisionalEntryHeader.IsRealizedForexGainOrLoss = Convert.ToBoolean(dataReader["bRealizedForexGainOrLoss"]);
				provisionalEntryHeader.UnrealizedAccount = Convert.ToInt32(dataReader["iUnrealizedAccount"]);
				if (flag)
				{
					provisionalEntryHeader.UnrealizedAccountName = Convert.ToString(dataReader["UnRealAcName"]);
				}
			}
			dataReader.Close();
			text = string.Format("SELECT iAccount, iFATag, mAmount, mCore_Account.sName[Name] \r\n                                            FROM cCore_ProvisionalEntryBody{0} JOIN mCore_Account \r\n                                            ON cCore_ProvisionalEntryBody{0}.iAccount = mCore_Account.iMasterId\r\n                                            WHERE iReportId = {1}", suffix, provisionalEntryHeader.ReportId);
			sqlStringCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dataReader = database.ExecuteReader(sqlStringCommand);
			while (dataReader.Read())
			{
				provisionalEntryBody = new ProvisionalEntryBody();
				provisionalEntryBody.Account = Convert.ToInt32(dataReader["iAccount"]);
				provisionalEntryBody.FATag = Convert.ToInt32(dataReader["iFATag"]);
				provisionalEntryBody.Amount = Convert.ToDecimal(dataReader["mAmount"]);
				provisionalEntryBody.AccountName = Convert.ToString(dataReader["Name"]);
				list.Add(provisionalEntryBody);
			}
			dataReader.Close();
			provisionalEntryHeader.ProvisionalBody = list.ToArray();
			return provisionalEntryHeader;
		}
		catch (Exception ex)
		{
			provisionalEntryHeader.ReportId = -1;
			provisionalEntryHeader.Error = ex.Message;
			return provisionalEntryHeader;
		}
	}

	public IdNamePair[] LoadProvLayouts(string sDateFormat, CalendarType oCalType, int iCompId)
	{
		string suffix = FConvert.GetSuffix(iCompId);
		List<IdNamePair> list = new List<IdNamePair>();
		try
		{
			Database database = DatabaseWrapper.GetDatabase2(iCompId);
			new Date(oCalType);
			RDConversion rDConversion = new RDConversion(oCalType);
			rDConversion.DateFormat = sDateFormat;
			string text = $"SELECT iReportId, iDate FROM cCore_ProvisionalEntryHeader{suffix} ORDER BY iDate";
			using DbCommand command = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			IDataReader dataReader = database.ExecuteReader(command);
			while (dataReader.Read())
			{
				list.Add(new IdNamePair(Convert.ToInt32(dataReader["iReportId"]), rDConversion.SetDateFormat(StandardDataFormat.Default, Convert.ToInt32(dataReader["iDate"]), null), Convert.ToInt32(dataReader["iDate"])));
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			list.Add(new IdNamePair(-1, ex.Message));
		}
		return list.ToArray();
