				cashFlowTemplateData.AccountGroup = Convert.ToInt32(dataReader["iAccountGroup"]);
				cashFlowTemplateData.GroupName = Convert.ToString(dataReader["sGroupName"]);
				cashFlowTemplateData.IsDeduct = Convert.ToBoolean(dataReader["bDeduct"]);
