	private int CheckDatewiseData(int iDate, int iCompId)
	{
		string empty = string.Empty;
		int num = 0;
		empty = $"SELECT COUNT(*) FROM cCore_ProvisionalEntryHeader{FConvert.GetSuffix(m_iCompanyId)}\r\n                                        WHERE iDate = {iDate}";
		Database database = DatabaseWrapper.GetDatabase2(iCompId);
		DbCommand sqlStringCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
		if (Convert.ToInt32(database.ExecuteScalar(sqlStringCommand)) == 1)
		{
			empty = $"SELECT iReportId FROM cCore_ProvisionalEntryHeader{FConvert.GetSuffix(m_iCompanyId)}\r\n                                    WHERE iDate = {iDate}";
		}
		sqlStringCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
		num = Convert.ToInt32(database.ExecuteScalar(sqlStringCommand));
		empty = $"DELETE cCore_ProvisionalEntryBody{FConvert.GetSuffix(m_iCompanyId)}\r\n                                        WHERE iReportId = {num}";
		sqlStringCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
		m_objDatabase.ExecuteNonQuery(sqlStringCommand);
		empty = $"DELETE cCore_ProvisionalEntryHeader{FConvert.GetSuffix(m_iCompanyId)}\r\n                                        WHERE iReportId  = {num}";
		sqlStringCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
		m_objDatabase.ExecuteNonQuery(sqlStringCommand);
		return num;
	}

	public string CreateAIFAMenu(string sServer, string sValue, string sMenuName, string sAifaURL, int iCompId)
	{
		string text = null;
		try
		{
			text = string.Format("declare @surl as varchar(512)\r\n                declare @saifaurl as varchar(512)\r\n                declare @smenuname as varchar(600)\r\n                declare @smenutext as varchar(64)\r\n                declare @imenugroupid as int = 0\r\n                declare @imenuid as int = 0\r\n                declare @imenuindex as int = 0\r\n\r\n                set @surl = '{0}' + '{1}';\r\n                set @smenutext = '{2}';\r\n                set @smenuname = '{3}';\r\n                set @saifaurl = '{4}';\r\n\r\n                select @imenugroupid = \r\n\t            CASE \r\n                    WHEN ISNULL(MAX(imenuid), 89999) + 1 < 90000 \r\n                        THEN 90000 \r\n                    ELSE ISNULL(MAX(imenuid), 89999) + 1 \r\n                END\r\n                from mCore_Menu where itype = 21\r\n\r\n                select @imenuindex = max(iMenuIndex) + 1 from mCore_Menu where iMenuGroupId is null\r\n                Insert into mCore_Menu values(@imenugroupid,'mnuAIFA_Forecasting','AIFA Forecasting',@imenuindex,NULL,NULL,NULL,NULL,NULL,NULL,'',21,0,1)\r\n                Insert into mSec_MenuSpecificRights (iMenuId, iActionId) VALUES (@imenugroupid,1)\r\n                Insert into cCore_MenuLanguages values(@imenugroupid,0,'AIFA Forecasting') \r\n\r\n                select @imenuid = isnull(max(imenuid),@imenugroupid) + 1 from mCore_Menu where iMenuGroupId = @imenugroupid\r\n                --Inserting \r\n                Insert into mCore_Menu values(@imenuid,'mnuAIFA_Application','AIFA Application',1,NULL,@imenugroupid,NULL,NULL,NULL,NULL,@saifaurl,21,@imenuid,0)\r\n                Insert into mSec_MenuSpecificRights (iMenuId, iActionId) VALUES (@imenuid,1)\r\n                Insert into cCore_MenuLanguages values(@imenuid,0,'AIFA Application')\r\n\r\n                select @imenuid = isnull(max(imenuid),@imenugroupid) + 1 from mCore_Menu where iMenuGroupId = @imenugroupid\r\n\r\n                Insert into mCore_Menu values(@imenuid,'mnuAIFA_Forecast_Reports','AIFA Forecast Reports',2,NULL,@imenugroupid,NULL,NULL,NULL,NULL,'',21,@imenuid,1)\r\n                Insert into mSec_MenuSpecificRights (iMenuId, iActionId) VALUES (@imenuid,1)\r\n                Insert into cCore_MenuLanguages values(@imenuid,0,'AIFA Forecast Reports') \r\n\r\n                set @imenugroupid = @imenuid\r\n                select @imenuid = isnull(max(imenuid),@imenugroupid) + 1 from mCore_Menu where iMenuGroupId = @imenugroupid\r\n                Insert into mCore_Menu values(@imenuid,@smenuname,@smenutext,1,NULL,@imenugroupid,NULL,NULL,NULL,NULL,@surl,21,@imenuid,0)\r\n                Insert into mSec_MenuSpecificRights (iMenuId, iActionId) VALUES (@imenuid,1)\r\n                Insert into cCore_MenuLanguages values(@imenuid,0,@smenutext)  ", sServer, sValue, sMenuName, "mnu" + FConvert.GetValidName(sMenuName), sAifaURL);
			Database database = DatabaseWrapper.GetDatabase2(iCompId);
			DbCommand sqlStringCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			database.ExecuteNonQuery(sqlStringCommand);
			return string.Empty;
		}
		catch (Exception ex)
		{
			return ex.Message;
		}
	}

	public IdNamePair[] GetFinalReportDiscrepancy(int iReportId, int iCompanyId)
	{
		int num = 0;
		int num2 = 15;
		int num3 = EnumUtils.GetEnumMembers(DISCREPANCY_REASON.VOUCHER_WITHOUT_ACCOUNT, IsDisplayDescription: false).Length;
		string suffix = FConvert.GetSuffix(iCompanyId);
		string text = null;
		DbCommand dbCommand = null;
		Database database = null;
		IDataReader dataReader = null;
		List<IdNamePair> list = new List<IdNamePair>();
		List<IdNamePair> list2 = new List<IdNamePair>();
		try
		{
			database = DatabaseWrapper.GetDatabase2(iCompanyId);
			for (num = 0; num < num3; num++)
			{
				switch ((FocusReport)iReportId)
				{
				case FocusReport.TrialBalance:
				case FocusReport.TradingAccount:
				case FocusReport.TradingAndProfitAndLoss:
				case FocusReport.FinalAccountSchedules:
				case FocusReport.FundsFlow:
				case FocusReport.CashFlow:
				case FocusReport.CashFlowAnalysis:
				case FocusReport.ReceivableAndPaybleBalance:
					if (num < 6)
					{
						text = getDiscrepancyQuery((DISCREPANCY_REASON)num, suffix);
					}
					break;
				case FocusReport.BalanceSheet:
					if (num != 7)
					{
						text = getDiscrepancyQuery((DISCREPANCY_REASON)num, suffix);
					}
					break;
				case FocusReport.ProfitAndLoss:
					if (num != 6)
					{
						text = getDiscrepancyQuery((DISCREPANCY_REASON)num, suffix);
					}
					break;
				}
				if (!string.IsNullOrEmpty(text))
				{
					using (dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text))
					{
						dataReader = database.ExecuteReader(dbCommand);
						while (dataReader.Read())
						{
							list.Add(new IdNamePair(num, Convert.ToString(dataReader["sName"]), Convert.ToString(dataReader["sValue"])));
							if (list.Count >= num2)
							{
								break;
							}
						}
						dataReader.Close();
					}
				}
				if (list.Count > 0)
				{
					break;
				}
			}
			if (list.Count == 0)
			{
				text = string.Format("SELECT TempTable.iMasterId,sName\r\n                    FROM \r\n                    (\r\n\t                    SELECT InnerTable.iMasterId, Debit, Credit\r\n\t                    FROM \r\n\t                    (\r\n\t\t                    SELECT tCore_Data{0}.iBodyId,iBookNo[iMasterId],\r\n\t\t                    CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t\t                    CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit\r\n\t\t                    FROM \r\n\t\t                    tCore_Data{0} \r\n\t\t                    JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t\t                    UNION ALL\r\n\t\t                    SELECT tCore_Data{0}.iBodyId,iCode[iMasterId],\r\n\t\t                    CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n\t\t                    CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit\r\n\t\t                    FROM \r\n\t\t                    tCore_Data{0} \r\n\t\t                    JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t                    )InnerTable\r\n\t                    JOIN tCore_Data{0} ON InnerTable.[iBodyId] = tCore_Data{0}.iBodyId\r\n\t                    JOIN tCore_Header{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n\t                    JOIN mCore_Account ON InnerTable.[iMasterId] = mCore_Account.iMasterId  \r\n                        WHERE (tCore_Data{0}.bUpdateFA = 1 OR tCore_Data{0}.iType = 5) \r\n\t                    AND tCore_Data{0}.bSuspendUpdateFA = 0  AND tCore_Header{0}.bSuspended = 0 AND tCore_Data{0}.iAuthStatus < 2\r\n\t                    --AND tCore_Header{0}.iVoucherType & 65280 <> 256  \r\n                    ) TempTable \r\n                    JOIN mCore_Account ON TempTable.iMasterId = mCore_Account.iMasterId\r\n                    GROUP BY TempTable.[iMasterId] ,sName\r\n                    HAVING SUM([Debit]) + SUM([Credit]) <> 0 \r\n                    ORDER BY TempTable.[iMasterId]  ", suffix);
				using (dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text))
				{
					dataReader = database.ExecuteReader(dbCommand);
					while (dataReader.Read())
					{
						list2.Add(new IdNamePair(Convert.ToInt32(dataReader["iMasterId"]), Convert.ToString(dataReader["sName"]), null));
					}
					dataReader.Close();
				}
				if (list2.Count > 0)
				{
					text = string.Format("SELECT iMasterId,m.sName\r\n                        FROM \r\n                        (\r\n\t                        SELECT InnerTable.iMasterId, Debit, Credit\r\n\t                        FROM \r\n\t                        (\r\n\t\t                        SELECT tCore_Data{0}.iBodyId,iBookNo[iMasterId],\r\n\t\t                        CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t\t                        CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit\r\n\t\t                        FROM \r\n\t\t                        tCore_Data{0} \r\n\t\t                        JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t\t                        UNION ALL\r\n\t\t                        SELECT tCore_Data{0}.iBodyId,iCode[iMasterId],\r\n\t\t                        CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n\t\t                        CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit\r\n\t\t                        FROM \r\n\t\t                        tCore_Data{0} \r\n\t\t                        JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t                        )InnerTable\r\n\t                        JOIN tCore_Data{0} ON InnerTable.[iBodyId] = tCore_Data{0}.iBodyId\r\n\t                        JOIN tCore_Header{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n\t                        JOIN mCore_Account ON InnerTable.[iMasterId] = mCore_Account.iMasterId  \r\n                            WHERE (tCore_Data{0}.bUpdateFA = 1 OR tCore_Data{0}.iType = 5) \r\n\t                        AND tCore_Data{0}.bSuspendUpdateFA = 0  AND tCore_Header{0}.bSuspended = 0 AND tCore_Data{0}.iAuthStatus < 2\r\n\t                        --AND tCore_Header{0}.iVoucherType & 65280 <> 256  \r\n                        ) TempTable \r\n                        JOIN\r\n                        (\r\n\t                        SELECT ATree.iMasterId[Id],vrCore_Account.sName\r\n\t                        FROM dbo.fCore_GetAccountTreeSequence(0,0) ATree \r\n\t                        JOIN vrCore_Account ON vrCore_Account.iMasterId = ATree.iMasterId \r\n\t                        LEFT JOIN mCore_Account_Props ON mCore_Account_Props.iMasterId = ATree.iMasterId \r\n\t                        LEFT JOIN mCore_AccountLanguage ON mCore_AccountLanguage.iMasterId = vrCore_Account.iMasterId AND iLanguageId = 0\r\n\t                        WHERE ATree.iMasterId > 0 AND iTreeId = 0 \r\n                        )m ON m.Id = iMasterId\r\n                        GROUP BY [iMasterId], m.sName\r\n                        HAVING SUM([Debit]) + SUM([Credit]) <> 0 \r\n                        ORDER BY [iMasterId] ", suffix);
					using (dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text))
					{
						dataReader = database.ExecuteReader(dbCommand);
						while (dataReader.Read())
						{
							if (list2.Count > 0)
							{
								for (num = 0; num < list2.Count; num++)
								{
									if (list2[num].ID == Convert.ToInt32(dataReader["iMasterId"]))
									{
										list2.RemoveAt(num);
										break;
									}
								}
								if (num == list2.Count && list2.Count > 0)
								{
									list.Add(new IdNamePair(3, Convert.ToString(dataReader["sName"]), Convert.ToInt32(dataReader["iMasterId"])));
								}
							}
							else
							{
								list.Add(new IdNamePair(3, Convert.ToString(dataReader["sName"]), Convert.ToInt32(dataReader["iMasterId"])));
							}
						}
						dataReader.Close();
					}
				}
			}
			for (num = 0; num < list2.Count; num++)
			{
				list.Add(new IdNamePair(3, list2[num].Name, list2[num].ID));
			}
		}
		catch (Exception ex)
		{
			list.Add(new IdNamePair(-1, ex.Message, ex.StackTrace));
		}
		return list.ToArray();
	}

	private string getDiscrepancyQuery(DISCREPANCY_REASON iStep, string sSuffix)
	{
		string result = null;
		switch (iStep)
		{
		case DISCREPANCY_REASON.VOUCHER_WITHOUT_ACCOUNT:
			result = string.Format("SELECT sName, sAbbr + ':' + sVoucherNo[sValue] FROM tCore_Data{0} \r\n                JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                JOIN cCore_Vouchers{0} ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType\r\n                WHERE (iCode = 0 OR iBookNo = 0) AND (tCore_Data{0}.bUpdateFA = 1 OR  tCore_Data{0}.iType = 5) \r\n                AND tCore_Data{0}.bSuspendUpdateFA = 0 AND tCore_Header{0}.bSuspended = 0", sSuffix);
			break;
		case DISCREPANCY_REASON.VOUCHER_CR_DR_NOT_EQUAL:
			result = string.Format("SELECT sName, sAbbr + ':' + sVoucherNo[sValue]\r\n                FROM \r\n                (\r\n                    SELECT tCore_Header{0}.iVoucherType, iBookNo[iMasterId],sVoucherNo,\r\n                    CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n                    CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit\r\n                    FROM tCore_Header{0} \r\n                    JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                    WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA = 0\r\n                    AND tCore_Data{0}.iAuthStatus < 2 AND tCore_Header{0}.bSuspended = 0\r\n                    UNION ALL\r\n                    SELECT tCore_Header{0}.iVoucherType, iCode[iMasterId],sVoucherNo,\r\n                    CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n                    CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit\r\n                    FROM tCore_Header{0} \r\n                    JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                    WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA = 0\r\n                    AND tCore_Data{0}.iAuthStatus  < 2 AND tCore_Header{0}.bSuspended = 0\r\n                )InnerTable\r\n\t            JOIN cCore_Vouchers{0} ON cCore_Vouchers{0}.iVoucherType = InnerTable.iVoucherType\r\n\t            GROUP BY sName, sAbbr+':'+sVoucherNo\r\n\t            HAVING SUM([Debit])+SUM([Credit])<>0", sSuffix);
			break;
		case DISCREPANCY_REASON.ACCOUNT_MISSING_IN_TREE:
			result = "SELECT sName, iMasterId[sValue] FROM fCore_GetAccountTreeSequence(0,0) where iMasterId NOT IN(select iMasterId from vmCore_Account where iTreeId=0)";
			break;
		case DISCREPANCY_REASON.GROUP_ACCOUNT_SET_AS_NODE:
			result = "SELECT m.sName, iMasterId[sValue] FROM vmCore_Account m WHERE m.iParentId IN (SELECT iMasterId FROM mCore_Account WHERE bGroup = 0) AND m.bGroup = 0";
			break;
		case DISCREPANCY_REASON.PARENT_ACCOUNT_MISSING:
			result = "SELECT a.sName, a.iMasterId[sValue]\r\n                    FROM vmCore_Account a \r\n                    LEFT OUTER JOIN mCore_Account b ON a.iParentId = b.iMasterId\r\n                    JOIN mCore_AccountTreeDetails t ON a.iMasterId = t.iMasterId\r\n                    LEFT OUTER JOIN mCore_Account n ON b.sName = n.sName AND n.iStatus<>5\r\n                    WHERE a.iStatus = 0 AND a.iParentId IN (SELECT iMasterId FROM mCore_Account WHERE iStatus = 5)";
			break;
		case DISCREPANCY_REASON.BALANCESHEET_ACCOUNTS_WITH_PNL_GROUP:
			result = "SELECT sName, iMasterId[sValue]\r\n                    FROM vmCore_Account \r\n                    WHERE iAccountType IN (1,2,5,6,7,8,9,17,21,23,24,25,26,28,30,31,32,33,35,36,37)\r\n                    AND iParentId IN (SELECT iMasterId FROM vmCore_Account WHERE iAccountType IN (4,10,11,12,13,14,15,16,18,19,20,22,27,29,34,38,3))";
			break;
		case DISCREPANCY_REASON.PNL_ACCOUNTS_WITH_BALANCESHEET_GROUP:
			result = "SELECT sName, iMasterId[sValue]\r\n                    FROM vmCore_Account \r\n                    WHERE iAccountType IN (4,10,11,12,13,14,15,16,18,19,20,22,27,29,34,38,3)\r\n                    AND iParentId IN (SELECT iMasterId FROM vmCore_Account WHERE iAccountType IN (1,2,5,6,7,8,9,17,21,23,24,25,26,28,30,31,32,33,35,36,37))";
			break;
		}
		return result;
	}

	public TranHomeRecentData[] LoadRdHomeRecentData(int iUserId, CalendarType objCalType, string strDateFormat, int iComp)
	{
		string text = null;
		IDataReader dataReader = null;
		List<TranHomeRecentData> list = null;
		RDConversion rDConversion = null;
		try
		{
			list = new List<TranHomeRecentData>();
			rDConversion = new RDConversion(objCalType);
			if (!string.IsNullOrEmpty(strDateFormat))
			{
				rDConversion.DateFormat = strDateFormat;
			}
			text = string.Format("SELECT iReportId, sReportName, iModule, iReportType, iSourceType, EUser.sUserName[sCreatedBy], MUser.sUserName[sModifiedBy],\r\n                cCore_Reports{0}.iCreatedDate, ISNULL(cCore_Reports{0}.iModifiedDate, 0)iModifiedDate\r\n                FROM cCore_Reports{0} \r\n                JOIN mSec_Users EUser ON EUser.iUserId = cCore_Reports{0}.iCreatedBy\r\n                JOIN mSec_Users MUser ON MUser.iUserId = cCore_Reports{0}.iModifiedBy\r\n                WHERE iReportId >= 70000 AND iReportType > 0 AND iReportType <> 4\r\n                ORDER BY CASE WHEN cCore_Reports{0}.iCreatedDate <> cCore_Reports{0}.iModifiedDate THEN cCore_Reports{0}.iModifiedDate \r\n                ELSE cCore_Reports{0}.iCreatedDate END DESC", FConvert.GetSuffix(iComp));
			dataReader = DatabaseWrapper.GetDatabase2(iComp).ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				list.Add(new TranHomeRecentData
				{
					HeaderId = Convert.ToInt32(dataReader["iReportId"]),
					DocNo = Convert.ToString(dataReader["sReportName"]),
					Date = rDConversion.SetDateFormat(StandardDataFormat.Default, Convert.ToInt32(dataReader["iCreatedDate"]), null),
					ModifiedDetail = string.Format("{0} {1}", Convert.ToString(dataReader["sModifiedBy"]), rDConversion.SetDateFormat(StandardDataFormat.Default, Convert.ToInt32(dataReader["iModifiedDate"]), null)),
					Suspend = (Convert.ToInt32(dataReader["iReportType"]) == 2),
					AuthStatus = Convert.ToInt32(dataReader["iSourceType"]),
					LinkStatus = string.Format("{0}", (Module)Convert.ToInt32(dataReader["iModule"]))
				});
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			list.Add(new TranHomeRecentData
			{
				HeaderId = -1,
				DocNo = ex.Message
			});
		}
		return list.ToArray();
	}

	public string SaveColumnOrder(int iReportId, _ColumnOrder[] arrColumnOrder, byte iLinkType, int iCompanyId)
	{
		string result = null;
		string text = null;
		string suffix = FConvert.GetSuffix(iCompanyId);
		DbCommand dbCommand = null;
		DbConnection dbConnection = null;
		DbTransaction dbTransaction = null;
		try
		{
			if (m_objDatabase == null)
			{
				m_objDatabase = DatabaseWrapper.GetDatabase2(iCompanyId, -1, bReplicationServer: true);
			}
			dbConnection = m_objDatabase.CreateConnection();
			using (dbConnection = m_objDatabase.CreateConnection())
			{
				dbConnection.Open();
				dbTransaction = dbConnection.BeginTransaction();
				text = $"DELETE FROM cCore_ReportColumnsOrder{suffix} WHERE iColumnId = {iReportId} AND iLinkType = {iLinkType}";
				dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				m_objDatabase.ExecuteNonQuery(dbCommand, dbTransaction);
				text = string.Empty;
				if (arrColumnOrder != null)
				{
					for (int i = 0; i < arrColumnOrder.Length; i++)
					{
						text += $"INSERT INTO cCore_ReportColumnsOrder{suffix}\r\n                        (iColumnId,bAscending,iOrderBy,iLinkType) VALUES({iReportId}, {(arrColumnOrder[i].IsAscending ? ((byte)1) : ((byte)0))}, {arrColumnOrder[i].OrderId}, {iLinkType}); \r\n                        ";
					}
					dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
					m_objDatabase.ExecuteNonQuery(dbCommand, dbTransaction);
				}
				dbTransaction.Commit();
			}
		}
		catch (Exception ex)
		{
			result = ex.Message;
		}
		return result;
	}
}
